INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Monsoft-Solutions/alluring-website-v1/page-cro', 'page-cro', 'Monsoft-Solutions', 'alluring-website-v1', 'community', 'page-cro Monsoft-Solutions alluring-website-v1 community The page-cro skill analyzes marketing pages and provides actionable recommendations to improve conversion rates, benefiting developers and marketers. It checks for product marketing context and identifies key page elements. Page-CRO 是一种通过分析营销页面并提供可行的建议来提高转化率的技术 Page-CRO は、マーケティングページを分析し、実行可能な提案を提供してコンバージョン率を向上させる技術です Page-CRO는 마케팅 페이지를 분석하고 실행 가능한 제안을 제공하여 전환률을 향상시키는 기술입니다 El skill page-cro analiza páginas de marketing y proporciona recomendaciones para mejorar la tasa de conversión Le skill page-cro analyse les pages de marketing et fournit des recommandations pour améliorer le taux de conversion Der Skill page-cro analysiert Marketingseiten und liefert Empfehlungen zur Verbesserung der Konversionsrate A ferramenta page-cro é uma solução de otimização de taxa de conversão de página que fornece recomendações para melhorar a eficácia da sua página ИИ Агент page-cro является инструментом оптимизации конверсии страницы, который предоставляет рекомендации для улучшения эффективности вашей страницы أداة page-cro هي حل لتحسين معدل تحويل الصفحة التي توفر توصيات لتحسين فعالية صفحتك how to use page-cro what is page-cro page-cro alternative page-cro vs conversion rate optimization tools page-cro install page-cro setup guide conversion rate optimization best practices marketing page analysis actionable recommendations for conversion rate improvement Page-CRO 转化率优化 页面分析 AI工具 产品营销上下文 页面元素优化 转化率分析报告 Checks for product marketing context in .claude/product-marketing-context.md Identifies key page elements for conversion rate optimization Provides actionable recommendations for improvement Analyzes marketing pages for conversion rate optimization opportunities Reads context from .claude/product-marketing-context.md before asking questions page-cro is a conversion rate optimization expert skill that analyzes marketing pages to provide actionable recommendations for improvement');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dmitryprg-ai/cursor-develop-autorules/backlog-to-rules', 'community', 'dmitryprg-ai', 'cursor-develop-autorules', 'dmitryprg-ai/cursor-develop-autorules', 'backlog-to-rules', 0, 0, 46, '2026-03-08T01:57:15.472Z', '2026-03-08T02:09:35.786Z', '3b288638de5f2d7ffda749a4a807624fb62b8d47eb2de4aefff5cd9a4f96cff2', '{"id":"dmitryprg-ai/cursor-develop-autorules/backlog-to-rules","name":"backlog-to-rules","description":{"en":"The backlog-to-rules skill is an AI agent that automates the process of transforming accumulated error fixes and improvements from a backlog file into formal, structured rules. It reads from a specified improvements-backlog.md file and outputs updated .mdc rule files, ensuring past mistakes are c...","zh":"Backlog-to-Rules AI Agent Skill 将错误积累转换为防御规则，减少重复错误","ja":"Backlog-to-Rules AIエージェントスキルは、エラーアキュムレーションを防御ルールに変換し、再発防止","ko":"Backlog-to-Rules AI 툴 스킬은 오류 누적으로 규칙으로 전환하여 반복 오류를 줄입니다","es":"Backlog-to-Rules es una habilidad que convierte la experiencia de errores en reglas concretas para prevenir errores. Se integra con archivos `.cursor/data/improvements-backlog.md` y actualiza `.cursor/rules/*.mdc`","fr":"Backlog-to-Rules est une compétence qui transforme l''expérience des erreurs en règles concrètes pour prévenir les erreurs. Elle s''intègre avec les fichiers `.cursor/data/improvements-backlog.md` et met à jour `.cursor/rules/*.mdc`","de":"Backlog-to-Rules ist eine Fähigkeit, die Erfahrungen aus Fehlern in konkrete Regeln umwandelt, um Fehler zu vermeiden. Sie integriert sich mit Dateien `.cursor/data/improvements-backlog.md` und aktualisiert `.cursor/rules/*.mdc`","pt":"O Backlog-to-Rules é uma habilidade que converte o backlog de melhorias em regras concretas para prevenir erros. Funciona com .cursor/data/improvements-backlog.md e atualiza .cursor/rules/*.mdc","ru":"Backlog-to-Rules - это навык, который преобразует накопленный опыт ошибок в конкретные правила для предотвращения повторений. Работает с .cursor/data/improvements-backlog.md и обновляет .cursor/rules/*.mdc с помощью ИИ Агентов","ar":"العميل الإلكتروني Backlog-to-Rules هو مهارة تقوم بتحويل قائمة الانتظار للتطورات إلى قواعد ملموسة لمنع الأخطاء. يعمل مع .cursor/data/improvements-backlog.md ويعمل على تحديث .cursor/rules/*.mdc"},"seo":{"title":{"en":"backlog-to-rules: Automate Improvement Rule Generation | ...","zh":"Backlog 到规则 Setup Guide：AIエージェント错误防御","ja":"バックログからルールへの移行 Best Practices：AIエージェント","ko":"백로그에서 규칙으로 Setup Guide：AI 툴 오류 예방","es":"Configuración de Backlog-to-Rules: Guía para implementar ...","fr":"Mise en place de Backlog-to-Rules : Guide pour implémente...","de":"Einrichtung von Backlog-to-Rules: Leitfaden für die Imple...","pt":"Guia de Configuração do Backlog-to-Rules para Desenvolved...","ru":"Настройка ИИ Агентов: Backlog-to-Rules для Разработчиков","ar":"دليل إعداد العميل الإلكتروني Backlog-to-Rules للعاملين في..."},"description":{"en":"Automate the conversion of backlogged error fixes into structured MDC rules. This AI agent skill processes improvements-backlog.md to generate & update .curs...","zh":"使用 Backlog-to-Rules AI AgentSkill 转换错误积累为防御规则，减少重复错误","ja":"Backlog-to-Rules AIエージェントスキルを使用して、エラーアキュムレーションを防御ルールに変換し、再発防止","ko":"Backlog-to-Rules AI 툴 스킬을 사용하여 오류 누적으로 규칙으로 전환하여 반복 오류 줄이기","es":"Aprende a configurar Backlog-to-Rules para convertir errores en reglas concretas y mejorar tus procesos con herramientas de inteligencia artificial","fr":"Découvrez comment configurer Backlog-to-Rules pour transformer les erreurs en règles concrètes et améliorer vos processus avec des outils d''intelligence arti...","de":"Erfahren Sie, wie Sie Backlog-to-Rules einrichten, um Fehler in konkrete Regeln umzuwandeln und Ihre Prozesse mit KI-Tools zu verbessern","pt":"Aprenda a configurar o Backlog-to-Rules para melhorar a eficiência do seu fluxo de trabalho com .cursor/data/improvements-backlog.md","ru":"Узнайте, как настроить Backlog-to-Rules для повышения эффективности вашего рабочего процесса с .cursor/data/improvements-backlog.md и ИИ Агентами","ar":"تعلم كيفية إعداد العميل الإلكتروني Backlog-to-Rules لتحسين كفاءة تدفق العمل الخاص بك مع .cursor/data/improvements-backlog.md"},"definition":{"en":"backlog-to-rules is an AI agent skill that processes a backlog of software improvements (.cursor/data/improvements-backlog.md) to automatically generate and update deterministic rule files (.cursor/rules/*.mdc), turning experiential knowledge into enforceable code standards.","zh":"Backlog-to-Rules 是一种 AI Agent Skill，用于将错误积累转换为防御规则","ja":"Backlog-to-Rules は、エラーアキュムレーションを防御ルールに変換する AIエージェントスキル","ko":"Backlog-to-Rules는 오류 누적으로 규칙으로 전환하는 AI 툴 스킬","es":"Backlog-to-Rules es una habilidad de inteligencia artificial que convierte errores en reglas concretas","fr":"Backlog-to-Rules est une compétence d''intelligence artificielle qui transforme les erreurs en règles concrètes","de":"Backlog-to-Rules ist eine KI-Fähigkeit, die Fehler in konkrete Regeln umwandelt","pt":"O que é Backlog-to-Rules? É uma habilidade que converte o backlog de melhorias em regras concretas","ru":"Что такое Backlog-to-Rules? Это навык, который преобразует накопленный опыт ошибок в конкретные правила","ar":"ما هو العميل الإلكتروني Backlog-to-Rules؟ هو مهارة تقوم بتحويل قائمة الانتظار للتطورات إلى قواعد ملموسة"},"features":{"en":["Processes improvements from a designated backlog Markdown file (.md)","Generates and updates rule files in the .mdc format","Automates the codification of error fixes into preventitive rules","Triggers based on backlog size (5+ items) or time-based conditions (weekly)"],"zh":["自动转换错误积累为防御规则","减少重复错误","支持 `.cursor/data/improvements-backlog.md` 输入","生成 `.cursor/rules/*.mdc` 输出","集成 skills 功能"],"ja":["エラーアキュムレーションを防御ルールに自動変換","再発防止",".cursor/data/improvements-backlog.md 形式の入力に対応",".cursor/rules/*.mdc 形式の出力を生成","skills 機能と統合"],"ko":["오류 누적으로 규칙으로 자동 전환","반복 오류 줄이기",".cursor/data/improvements-backlog.md 형식의 입력 지원",".cursor/rules/*.mdc 형식의 출력 생성","스킬 기능 통합"],"es":["Procesamiento de archivos `.cursor/data/improvements-backlog.md`","Actualización de reglas en `.cursor/rules/*.mdc`","Implementación de mejoras basadas en la experiencia de errores","Integración con herramientas de inteligencia artificial","Automatización de la creación de reglas para prevenir errores"],"fr":["Traitement de fichiers `.cursor/data/improvements-backlog.md`","Mise à jour de règles dans `.cursor/rules/*.mdc`","Implémentation d''améliorations basées sur l''expérience des erreurs","Intégration avec des outils d''intelligence artificielle","Automatisation de la création de règles pour prévenir les erreurs"],"de":["Verarbeitung von Dateien `.cursor/data/improvements-backlog.md`","Aktualisierung von Regeln in `.cursor/rules/*.mdc`","Implementierung von Verbesserungen basierend auf der Erfahrung von Fehlern","Integration mit KI-Tools","Automatisierung der Erstellung von Regeln zur Vermeidung von Fehlern"],"pt":["Converte o backlog de melhorias em regras concretas","Funciona com .cursor/data/improvements-backlog.md","Atualiza .cursor/rules/*.mdc","Previnir erros com regras personalizadas","Integração com habilidades de desenvolvimento"],"ru":["Преобразует накопленный опыт ошибок в конкретные правила","Работает с .cursor/data/improvements-backlog.md и ИИ Агентами","Обновляет .cursor/rules/*.mdc","Предотвращает ошибки с помощью персонализированных правил","Интеграция с навыками разработки"],"ar":["يتحول قائمة الانتظار للتطورات إلى قواعد ملموسة","يعمل مع .cursor/data/improvements-backlog.md","يعمل على تحديث .cursor/rules/*.mdc","الوقاية من الأخطاء مع قواعد مخصصة","التكامل مع مهارات التطوير"]},"keywords":{"en":["backlog-to-rules AI agent","how to use backlog-to-rules","automate .mdc rule generation","cursor editor improvements backlog","backlog-to-rules setup guide","prevent software errors with AI","what is backlog-to-rules","backlog-to-rules alternative"],"zh":["AI Agent Skill","Backlog-to-Rules","错误防御","规则生成","AIエージェント","错误积累","防御规则"],"ja":["AIエージェントスキル","Backlog-to-Rules","エラーアキュムレーション","防御ルール","AIエージェント","エラー防止","ルール生成"],"ko":["AI 툴 스킬","Backlog-to-Rules","오류 예방","규칙 생성","AI 툴","오류 누적","防御 규칙"],"es":["Backlog-to-Rules","inteligencia artificial","herramientas de IA","implementación de mejoras","prevención de errores","reglas concretas","archivos `.cursor/data/improvements-backlog.md`","actualización de reglas"],"fr":["Backlog-to-Rules","intelligence artificielle","outils d''IA","implémentation d''améliorations","prévention d''erreurs","règles concrètes","fichiers `.cursor/data/improvements-backlog.md`","mise à jour de règles"],"de":["Backlog-to-Rules","künstliche Intelligenz","KI-Tools","Implementierung von Verbesserungen","Vermeidung von Fehlern","konkrete Regeln","Dateien `.cursor/data/improvements-backlog.md`","Aktualisierung von Regeln"],"pt":["Backlog-to-Rules","desenvolvimento de software","melhorias de processo","regras de negócio","integração com .cursor","otimização de fluxo de trabalho","ferramentas de desenvolvimento","tecnologias de automação"],"ru":["Backlog-to-Rules","разработка программного обеспечения","улучшение процесса","правила бизнеса","интеграция с .cursor и ИИ Агентами","оптимизация рабочего процесса","инструменты разработки","технологии автоматизации"],"ar":["العميل الإلكتروني Backlog-to-Rules","تطوير البرمجيات","تحسين العملية","قواعد الأعمال","التكامل مع .cursor","تحسين تدفق العمل","أدوات التطوير","تقنيات التأتمة"]}},"owner":"dmitryprg-ai","repo":"cursor-develop-autorules","repoPath":"dmitryprg-ai/cursor-develop-autorules","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.472Z","topics":[],"category":"community","skillMd":{"name":"backlog-to-rules","description":"Внедрение накопленных улучшений из improvements-backlog в инструкции AI агента","version":"2.0","tags":["improvement","rules","learning"],"bodyPreview":"# Backlog to Rules: Внедрение улучшений\n\n> **Цель:** Превратить накопленный опыт ошибок в конкретные правила для предотвращения повторений\n> **Входные данные:** `.cursor/data/improvements-backlog.md`\n> **Выходные данные:** Обновлённые `.cursor/rules/*.mdc` и skills\n\n---\n\n## Когда запускать\n\n| Условие | Приоритет |\n|---------|-----------|\n| Накопилось 5+ улучшений в backlog | 🔴 Обязательно |\n| Прошла неделя с последнего внедрения | 🟡 Рекомендуется |\n| Есть 2+ High priority улучшения | 🔴 Обязат","body":"# Backlog to Rules: Внедрение улучшений\n\n> **Цель:** Превратить накопленный опыт ошибок в конкретные правила для предотвращения повторений\n> **Входные данные:** `.cursor/data/improvements-backlog.md`\n> **Выходные данные:** Обновлённые `.cursor/rules/*.mdc` и skills\n\n---\n\n## Когда запускать\n\n| Условие | Приоритет |\n|---------|-----------|\n| Накопилось 5+ улучшений в backlog | 🔴 Обязательно |\n| Прошла неделя с последнего внедрения | 🟡 Рекомендуется |\n| Есть 2+ High priority улучшения | 🔴 Обязательно |\n| Перед важным релизом | 🟡 Рекомендуется |\n| Одна ошибка повторилась 3+ раз | 🔴 Немедленно |\n\n---\n\n## Процесс (7 фаз)\n\n### Phase 1: ANALYZE\n\n1. Открыть `.cursor/data/improvements-backlog.md`\n2. Группировать улучшения по целевым файлам\n3. Собрать статистику (всего, high/medium/low priority)\n4. Выявить паттерны ошибок (объединить похожие)\n\n### Phase 2: RESEARCH\n\nДля каждого файла из группировки:\n1. Прочитать текущую структуру файла\n2. Определить куда добавить каждое улучшение (существующая/новая секция)\n3. Проверить конфликты с существующими правилами\n\n### Phase 3: PLAN\n\n1. Составить список изменений по файлам\n2. Определить критерии успеха\n3. Для сложных случаев — полный план (см. `references/templates.md`)\n\n### Phase 4: IMPLEMENT\n\nПравила внедрения:\n- Добавлять новые секции — НЕ заменять существующие\n- Каждое правило с конкретным примером кода/команды\n- Каждое правило с `> **WHY:**` (реальный случай ошибки)\n- Сохранять формат файла (tables, code blocks)\n- После каждого файла — прочитать целиком, проверить структуру\n\nШаблон секции — см. `references/templates.md`\n\n### Phase 5: VERIFY\n\n1. Все существующие секции сохранены\n2. Новые секции дополняют, не заменяют\n3. Формат соответствует стилю файла\n4. Связи с другими модулями не нарушены\n5. Cross-check: каждый файл открыт и проверен\n\n### Phase 6: UPDATE BACKLOG\n\n1. Обновить статусы в backlog: 📝 Backlog → ✅ Done\n2. Перенести в секцию \"✅ ВНЕДРЕНО\" в кратком формате\n3. Обновить статистику в шапке\n\n### Phase 7: SUMMARY\n\nОтчёт: сколько внедрено, какие файлы обновлены, какие паттерны предотвращены, уверенность.\n\n---\n\n## Quick Version (1-2 улучшения)\n\n```\n1. Открой backlog → найди улучшение\n2. Открой целевой файл инструкций\n3. Добавь секцию в конец соответствующего раздела\n4. Включи WHY с реальным случаем\n5. Обнови статус в backlog на ✅ Done\n```\n\n---\n\n## Quality Framework\n\nПри создании/улучшении инструкций — ключевые элементы:\n\n| Элемент | Что включить |\n|---------|--------------|\n| **Input** | Что триггерит правило |\n| **Output** | Что должно быть сделано |\n| **Success Metrics** | Как измерить успех |\n| **Guardrails** | Что запрещено, границы |\n| **WHY** | Реальный случай ошибки |\n\nМетрики качества — `standard-agent-quality.mdc`\n\n---\n\n## Связанные модули\n\n- `session-review` skill — создаёт записи в backlog\n- `error-learning.mdc` — записывает ошибки для анализа\n- `.cursor/data/improvements-backlog.md` — хранилище улучшений\n- `standard-agent-quality.mdc` — метрики и границы\n\n---\n\n**Версия:** 2.0\n"},"lastSynced":"2026-03-08T02:09:35.786Z","agentAnalysis":{"suitability":{"en":"Essential for Code Quality Agents that systematically convert accumulated error fixes into enforceable development rules.","zh":"对于系统地将累积的错误修复转换为可执行的开发规则的代码质量代理来说是必不可少的。","ja":"蓄積されたエラーフィックスを実行可能な開発ルールに体系的に変換するコード品質エージェントにとって不可欠です。","ko":"누적된 오류 수정을 시행 가능한 개발 규칙으로 체계적으로 변환하는 코드 품질 에이전트에 필수적입니다.","es":"Esencial para los Agentes de Calidad de Código que convierten sistemáticamente las correcciones de errores acumuladas en reglas de desarrollo ejecutables.","fr":"Essentiel pour les Agents de Qualité de Code qui convertissent systématiquement les corrections d''erreurs accumulées en règles de développement exécutoires.","de":"Wesentlich für Code-Qualitäts-Agents, die systematisch die angesammelten Fehlerkorrekturen in durchsetzbare Entwicklungsregeln umwandeln.","pt":"Essencial para Agentes de Qualidade de Código que convertem sistematicamente correções de erros acumuladas em regras de desenvolvimento aplicáveis.","ru":"Необходимо для агентов контроля качества кода, которые систематически преобразуют накопленные исправления ошибок в обязательные правила разработки.","ar":"ضروري لعميل جودة الكود الذي يحول بشكل منهجي عمليات исправة الأخطاء المتراكمة إلى قواعد تطوير قابلة للتنفيذ."},"recommendation":{"en":"Automates the transformation of unstructured improvements from an `improvements-backlog.md` file into formal, structured `.mdc` rule files, ensuring past mistakes are codified and prevented from recurring.","zh":"自动将来自 `improvements-backlog.md` 文件的非结构化改进转换为正式的结构化 `.mdc` 规则文件，确保过去的错误被编纂并防止再次发生。","ja":"「`improvements-backlog.md`」ファイルからの非構造化された改善を、正式な構造化された「`.mdc`」ルールファイルに自動変換し、過去のミスをコード化し、再発を防止します。","ko":"『improvements-backlog.md』 파일에서 비구조적 개선을 공식적인 구조적 『.mdc』 규칙 파일로 자동 변환하여 과거의 실수를 코드화하고 재발을 방지합니다.","es":"Automatiza la transformación de mejoras no estructuradas de un archivo `improvements-backlog.md` en archivos de reglas formales y estructurados `.mdc`, asegurando que los errores pasados se codifiquen y se prevengan de volver a ocurrir.","fr":"Automatise la transformation des améliorations non structurées d''un fichier `improvements-backlog.md` en fichiers de règles formels et structurés `.mdc`, en garantissant que les erreurs passées soient codifiées et prévenues de se reproduire.","de":"Automatisiert die Umwandlung unstrukturierter Verbesserungen aus einer Datei `improvements-backlog.md` in formale, strukturierte `.mdc`-Regeldateien, sicherstellend, dass vergangene Fehler kodifiziert und ein erneutes Auftreten verhindert wird.","pt":"Automatiza a transformação de melhorias não estruturadas de um arquivo `improvements-backlog.md` em arquivos de regras formais e estruturados `.mdc`, garantindo que erros passados sejam codificados e impedidos de ocorrer novamente.","ru":"Автоматизирует преобразование неструктурированных улучшений из файла `improvements-backlog.md` в формальные, структурированные файлы правил `.mdc`, гарантируя, что прошлые ошибки будут закодированы и предотвращены от повторения.","ar":"يتم Automatiza تحويل التحسينات غير المهيكلة من ملف `improvements-backlog.md` إلى ملفات قواعد رسمية ومنظمة `.mdc` ، مما يضمن أن الأخطاء السابقة يتم تحويلها إلى код وتمنع من التكرار."},"useCases":{"en":["Converting backlogged error fixes into enforceable coding standards","Automating rule file (.mdc) generation from historical improvement data","Systematizing the prevention of recurring development mistakes"],"zh":["将积压的错误修复转换为可执行的编码标准","从历史改进数据自动生成规则文件（.mdc）","系统化地防止反复出现的开发错误"],"ja":["バックログされたエラーフィックスを実行可能なコーディング標準に変換する","歴史的な改善データからルールファイル（.mdc）を自動生成する","再発する開発ミスを体系的に防止する"],"ko":["누적된 오류 수정을 시행 가능한 코딩 표준으로 변환","역사적 개선 데이터에서 규칙 파일(.mdc)을 자동 생성","반복되는 개발 오류를 체계적으로 방지"],"es":["Conversión de correcciones de errores acumuladas en estándares de codificación ejecutables","Automatización de la generación de archivos de reglas (.mdc) a partir de datos de mejora históricos","Sistematización de la prevención de errores de desarrollo recurrentes"],"fr":["Conversion des corrections d''erreurs accumulées en normes de codage exécutoires","Automatisation de la génération de fichiers de règles (.mdc) à partir de données d''amélioration historiques","Systématisation de la prévention des erreurs de développement récurrentes"],"de":["Umwandlung von angesammelten Fehlerkorrekturen in durchsetzbare Kodierstandards","Automatisierung der Generierung von Regeldateien (.mdc) aus historischen Verbesserungsdaten","Systematisierung der Verhinderung wiederkehrender Entwicklungsfehler"],"pt":["Converte correções de erros acumuladas em padrões de codificação aplicáveis","Automatiza a geração de arquivos de regras (.mdc) a partir de dados históricos de melhoria","Sistematiza a prevenção de erros de desenvolvimento recorrentes"],"ru":["Преобразует накопленные исправления ошибок в обязательные стандарты кодирования","Автоматизирует генерацию файлов правил (.mdc) из исторических данных улучшения","Систематизирует предотвращение повторяющихся ошибок разработки"],"ar":["يتحول عمليات исправة الأخطاء المتراكمة إلى معايير برمجة قابلة للتطبيق","يتم Automatiza توليد ملفات القواعد (.mdc) من بيانات التحسين التاريخية","يتم تحويل الأخطاء المتراكمة إلى قواعد قابلة للتنفيذ"]},"limitations":{"en":["Requires a pre-existing `improvements-backlog.md` file","Triggered only after accumulating 5+ improvements or specific priority conditions"],"zh":["需要预先存在的 `improvements-backlog.md` 文件","仅在累积 5+ 个改进或特定优先级条件后触发"],"ja":["事前に「`improvements-backlog.md`」ファイルが存在する必要がある","5 以上の改善または特定の優先度条件を蓄積した後のみトリガーされる"],"ko":["『improvements-backlog.md』 파일이事前に 존재해야 함","5개 이상의 개선 또는 특정 우선 순위 조건을 누적한 후에만 트리거됨"],"es":["Requiere un archivo `improvements-backlog.md` preexistente","Se activa solo después de acumular 5+ mejoras o condiciones de prioridad específicas"],"fr":["Nécessite un fichier `improvements-backlog.md` préexistant","Se déclenche uniquement après avoir accumulé 5+ améliorations ou des conditions de priorité spécifiques"],"de":["Benötigt eine vorherige Datei `improvements-backlog.md`","Wird nur nach Ansammlung von 5+ Verbesserungen oder spezifischen Prioritätsbedingungen ausgelöst"],"pt":["Exige a existência prévia de um arquivo `improvements-backlog.md`","É acionado apenas após acumular 5+ melhorias ou condições de prioridade específicas"],"ru":["Требует предварительного существования файла `improvements-backlog.md`","Срабатывает только после накопления 5+ улучшений или специфических условий приоритета"],"ar":["يتطلب وجود ملف `improvements-backlog.md` مسبق","يتم تشغيله فقط بعد تجميع 5+ تحسينات أو شروط أولوية محددة"]},"version":4},"contentHash":"3b288638de5f2d7ffda749a4a807624fb62b8d47eb2de4aefff5cd9a4f96cff2","qualityScore":46}');
