INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('infodungeon/keyforge/UI Performance Guard', 'UI Performance Guard', 'infodungeon', 'keyforge', 'community', 'UI Performance Guard infodungeon keyforge community UI Performance Guard enforces Vercel-standard performance optimizations for React and Next.js applications, benefiting developers seeking to improve their app''s performance. UI性能守护是一种AI工具，用于优化React和Next.js应用的性能，通过消除瀑布、合并和tree shaking等技术提高页面加载速度 UIパフォーマンスガードは、ReactとNext.jsアプリのパフォーマンスを最適化するAIエージェントです。ウォーターフォールを排除し、バンドルとツリーシェイキングを行うことでページロード速度を向上させます UI 성능 가드는 React 및 Next.js 애플리케이션의 성능을 최적화하는 AI 도구입니다. 워터폴을 제거하고 번들 및 트리シェ이킹을 통해 페이지 로드 속도를 개선합니다 UI Performance Guard es una herramienta que aplica las optimizaciones de rendimiento de Vercel para aplicaciones React y Next.js, mejorando el rendimiento de la interfaz de usuario UI Performance Guard est un outil qui applique les optimisations de performances Vercel pour les applications React et Next.js, améliorant les performances de l''interface utilisateur UI Performance Guard ist ein Tool, das die Vercel-Standardleistungsoptimierungen für React- und Next.js-Anwendungen anwendet, um die Leistung der Benutzeroberfläche zu verbessern O UI Performance Guard é uma ferramenta que ajuda a otimizar o desempenho da interface do usuário para aplicações React e Next.js ИИ Агент UI Performance Guard - это инструмент, помогающий оптимизировать производительность пользовательского интерфейса для приложений React и Next.js UI Performance Guard هو أداة تساعد على تحسين أداء واجهة المستخدم لتطبيقات React و Next.js how to use UI Performance Guard UI Performance Guard vs React optimization tools UI Performance Guard setup guide what is UI Performance Guard UI Performance Guard alternative optimizing React performance with UI Performance Guard UI Performance Guard install UI Performance Guard for Next.js UI性能优化 React性能优化 Next.js性能优化 AI工具 性能守护 瀑布优化 合并和tree shaking Eliminates waterfalls by deferring `await` until data is needed in the render tree Optimizes bundling by avoiding barrel file imports and using direct path imports Implements `Suspense` boundaries to unblock initial paint of the shell Utilizes `Promise.all()` for independent, concurrent data fetching Enforces Vercel-standard performance optimizations for React and Next.js applications UI Performance Guard is a skill that enforces performance optimizations for React and Next.js applications, ensuring faster render times and improved user experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('remote-123/v0-real-estate-landing-page/marketing-ideas', 'community', 'remote-123', 'v0-real-estate-landing-page', 'remote-123/v0-real-estate-landing-page', 'marketing-ideas', 0, 0, 46, '2026-03-07T05:37:16Z', '2026-03-08T02:17:11.224Z', 'f8f91a7409a5b7f3802e3de3ce70458ae77f701ec67995b9cd0df52f5244f19a', '{"id":"remote-123/v0-real-estate-landing-page/marketing-ideas","name":"marketing-ideas","description":{"en":"The marketing-ideas skill provides 139 proven marketing strategies for SaaS, helping users find the right approach for their specific situation, stage, and resources. It benefits marketing strategists and SaaS businesses.","zh":"Marketing Ideas是139个经过验证的营销策略，帮助用户找到适合特定情况、阶段和资源的营销策略。使用product-marketing-context.md文件中的上下文来获得更好的结果。","ja":"Marketing Ideasは139の検証済みマーケティング戦略であり、ユーザーが特定の状況、段階、リソースに適したマーケティング戦略を見つけるのに役立ちます。product-marketing-context.mdファイルのコンテキストを使用して、より良い結果を得ることができます。","ko":"Marketing Ideas는 139개의 검증된 마케팅 전략으로, 사용자가 특정 상황, 단계 및 자원에 적합한 마케팅 전략을 찾는 데 도움이 됩니다. product-marketing-context.md 파일의 컨텍스트를 사용하여 더 나은 결과를 얻을 수 있습니다.","es":"La habilidad de marketing-ideas ofrece 139 ideas de marketing probadas para ayudar a los usuarios a encontrar las estrategias de marketing adecuadas para su situación específica","fr":"La compétence marketing-ideas propose 139 idées de marketing éprouvées pour aider les utilisateurs à trouver les stratégies de marketing appropriées pour leur situation spécifique","de":"Die Fähigkeit marketing-ideas bietet 139 bewährte Marketingideen, um den Benutzern zu helfen, die richtigen Marketingstrategien für ihre spezifische Situation zu finden","pt":"O skill Marketing-Ideas fornece 139 ideias de marketing comprovadas para ajudar os desenvolvedores a encontrar as estratégias certas para o seu negócio","ru":"Навык Marketing-Ideas предоставляет 139 проверенных маркетинговых идей,