INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('adithya-s-k/manim_skill/manimce-best-practices', 'manimce-best-practices', 'adithya-s-k', 'manim_skill', 'community', 'manimce-best-practices adithya-s-k manim_skill community Manim最佳实践指南，用于创建3Blue1Brown风格的动画，帮助开发者掌握AI智能代理技术 3Blue1Brownスタイルのアニメーションを作成するためのManimのベストプラクティスガイド、AIエージェント技術をマスターする 3Blue1Brown 스타일의 애니메이션을 생성하기 위한 Manim의 최고의 관행 가이드, AI 에이전트 기술을 마스터하는 데 도움이 됩니다 Manimce es una herramienta para crear animaciones estilo 3Blue1Brown con Agentes de IA. Aprende a utilizarla con nuestras mejores prácticas Manimce est un outil pour créer des animations de style 3Blue1Brown avec des Outils de IA. Découvrez comment l''utiliser avec nos meilleures pratiques Manimce ist ein Tool zum Erstellen von Animationsvideos im Stil von 3Blue1Brown mit KI-Agents. Erfahren Sie, wie Sie es mit unseren Best Practices verwenden Manimce é uma habilidade de agente de IA para criar animações no estilo 3Blue1Brown. Aprenda a usar essas ferramentas para melhorar seu desenvolvimento. Manimce - это навык ИИ Агента для создания анимаций в стиле 3Blue1Brown. Узнайте, как использовать эти инструменты для улучшения своего разработки. منيمسي هي مهارة للوكيل الذكاء الاصطناعي لإنشاء رسومات متحركة بنمط 3Blue1Brown. تعلم كيفية استخدام هذه الأدوات لتحسين تطويرك. Agent skills for Manim to create 3Blue1Brown style animations. Manim最佳实践 AI智能代理 3Blue1Brown风格动画 动画创建指南 开发者工具 AI技术集成 跨平台兼容性 Agent skills for Manim to create 3Blue1Brown style animations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('notedit/happy-skills/video-producer', 'community', 'notedit', 'happy-skills', 'notedit/happy-skills', 'video-producer', 0, 0, 46, '2026-03-03T01:58:23.259Z', '2026-03-03T02:11:47.411Z', '2b6b0dfba44f70d198c9efa5151f2e86c44df3bdc5ddbbb5a00e3e8773b92575', '{"id":"notedit/happy-skills/video-producer","name":"video-producer","description":{"zh":"Video Producer是基于AI的智能视频制作工具，帮助开发者高效创建和编辑视频内容","ja":"Video ProducerはAIエージェントを活用した動画制作ツールで、開発者が動画を作成、編集することを支援","ko":"비디오 프로듀서는 AI 기반의 비디오 제작 도구로, 개발자가 비디오 콘텐츠를 효율적으로 생성하고 편집할 수 있도록 도와줍니다","es":"El agente de video producer es una herramienta de codificación feliz que utiliza agentes de IA para mejorar la experiencia del desarrollador","fr":"L''agent de vidéo producer est un outil de codage heureux qui utilise des agents d''IA pour améliorer l''expérience du développeur","de":"Der Video-Producer-Agent ist ein Codier-Tool, das KI-Agents verwendet, um die Erfahrung des Entwicklers zu verbessern","pt":"A ferramenta de vídeo-produção é uma solução inovadora para desenvolvedores que desejam criar vídeos personalizados com facilidade","ru":"Видео-производственная инструментка - это инновационное решение для разработчиков, которые хотят создавать персонализированные видео с легкостью","ar":"أداة إنتاج الفيديو هي حل مبتكر للمطورين الذين يرغبون في إنشاء فيديوهات مخصصة بسهولة","en":"happy coding  agent"},"seo":{"title":{"zh":"AI智能视频制作工具 - Video Producer","ja":"AIエージェントによる動画制作 - Video Producer","ko":"AI 비디오 프로듀서 - 비디오 제작 도구","es":"Herramientas de Video Producer con Agentes de IA","fr":"Outils de Vidéo Producer avec Agents d''IA","de":"Video Producer Tools mit KI-Agenten","pt":"Ferramentas de Vídeo Inteligentes - Agentes de IA","ru":"ИИ Агенты видео-производства","ar":"أدوات إنتاج الفيديو الذكية - وكلاء الذكاء الاصطناعي","en":"video-producer"},"description":{"zh":"Video Producer是基于AI的智能视频制作工具，帮助开发者高效创建和编辑视频内容","ja":"Video ProducerはAIエージェントを活用した動画制作ツールで、開発者が動画を作成、編集することを支援","ko":"비디오 프로듀서는 AI 기반의 비디오 제작 도구로, 개발자가 비디오 콘텐츠를 효율적으로 생성하고 편집할 수 있도록 도와줍니다","es":"El agente de video producer es una herramienta de codificación feliz que utiliza agentes de IA para mejorar la experiencia del desarrollador","fr":"L''agent de vidéo producer est un outil de codage heureux qui utilise des agents d''IA pour améliorer l''expérience du développeur","de":"Der Video-Producer-Agent ist ein Codier-Tool, das KI-Agents verwendet, um die Erfahrung des Entwicklers zu verbessern","pt":"A ferramenta de vídeo-produção é uma solução inovadora para desenvolvedores que desejam criar vídeos personalizados com facilidade","ru":"Видео-производственная инструментка - это инновационное решение для разработчиков, которые хотят создавать персонализированные видео с легкостью","ar":"أداة إنتاج الفيديو هي حل مبتكر للمطورين الذين يرغبون في إنشاء فيديوهات مخصصة بسهولة","en":"happy coding  agent"},"definition":{"en":"happy coding  agent"},"features":{"zh":["支持多种视频格式","AI驱动的视频编辑","高效的视频渲染","支持自定义视频模板","与React、Python、Node.js等开发框架集成"],"ja":["多種動画形式をサポート","AI駆動の動画編集","高効率の動画レンダリング","カスタム動画テンプレートをサポート","React、Python、Node.jsなどの開発フレームワークと連携"],"ko":["다양한 비디오 형식 지원","AI 기반 비디오 편집","고효율의 비디오 렌더링","사용자 정의 비디오 템플릿 지원","React, Python, Node.js 등의 개발 프레임워크와 통합"],"es":["Integración con herramientas de codificación como React y Node.js","Edición de video en tiempo real con agentes de IA","Compatibilidad con formatos de video como MP4 y AVI","Interfaz de usuario intuitiva para desarrolladores","Soporte para CLI y API para integración con otros herramientas"],"fr":["Intégration avec des outils de codage tels que React et Node.js","Édition de vidéo en temps réel avec des agents d''IA","Compatibilité avec des formats de vidéo tels que MP4 et AVI","Interface utilisateur intuitive pour les développeurs","Prise en charge de la CLI et de l''API pour l''intégration avec d''autres outils"],"de":["Integration mit Codier-Tools wie React und Node.js","Echtzeit-Video-Bearbeitung mit KI-Agenten","Unterstützung für Video-Formate wie MP4 und AVI","Benutzerfreundliche Oberfläche für Entwickler","Unterstützung für CLI und API für die Integration mit anderen Tools"],"pt":["Criação de vídeos personalizados com facilidade","Integração com tecnologias de IA para melhorar a qualidade do vídeo","Compatibilidade com várias plataformas de desenvolvimento","Fácil integração com bibliotecas de código aberto","Suporte a múltiplos formatos de vídeo"],"ru":["Создание персонализированных видео с легкостью","Интеграция с технологиями ИИ для улучшения качества видео","Совместимость с несколькими платформами разработки","Легкая интеграция с библиотеками с открытым исходным кодом","Поддержка нескольких форматов видео"],"ar":["إنشاء فيديوهات مخصصة بسهولة","التكامل مع تكنولوجيا الذكاء الاصطناعي لتحسين جودة الفيديو","التوافق مع منصات تطوير متعددة","التكامل السهل مع مكتبات الكود المفتوح","دعم صيغ فيديو متعددة"]},"keywords":{"zh":["如何使用Video Producer","什么是AI智能视频制作","Video Producer替代品","Video Producer与Adobe Premiere的比较","Video Producer安装教程","Video Producer设置指南"],"ja":["Video Producerの使い方","AIエージェントによる動画制作とは","Video Producerの代替","Video ProducerとAdobe Premiereの比較","Video Producerのインストール方法","Video Producerの設定ガイド"],"ko":["비디오 프로듀서 사용법","AI 비디오 제작이란","비디오 프로듀서 대체품","비디오 프로듀서와 Adobe Premiere 비교","비디오 프로듀서 설치 가이드","비디오 프로듀서 설정 방법"],"es":["cómo usar herramientas de video producer","qué es un agente de IA","alternativas a Adobe Premiere","instalación de herramientas de video producer","guía de configuración de agentes de IA","diferencias entre herramientas de video producer y editores de video","mejores prácticas para la edición de video con agentes de IA"],"fr":["comment utiliser des outils de vidéo producer","quoi est un agent d''IA","alternatives à Adobe Premiere","installation d''outils de vidéo producer","guide de configuration des agents d''IA","différences entre les outils de vidéo producer et les éditeurs de vidéo","meilleures pratiques pour l''édition de vidéo avec des agents d''IA"],"de":["wie man Video-Producer-Tools verwendet","was ist ein KI-Agent","Alternativen zu Adobe Premiere","Installation von Video-Producer-Tools","Konfigurationsanleitung für KI-Agents","Unterschiede zwischen Video-Producer-Tools und Video-Editoren","Best Practices für die Video-Bearbeitung mit KI-Agenten"],"pt":["como usar agentes de IA para vídeo","o que é agente de IA de vídeo","ferramentas de vídeo-produção","alternativas para vídeo-produção","vídeo-produção vs edição de vídeo","instalação de ferramentas de vídeo-produção","guia de configuração de vídeo-produção"],"ru":["как использовать ИИ Агенты для видео","что такое ИИ Агент видео","инструменты видео-производства","альтернативы для видео-производства","видео-производство vs видео-редактирование","установка инструментов видео-производства","руководство по настройке видео-производства"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي للفيديو","ما هو وكيل الذكاء الاصطناعي للفيديو","أدوات إنتاج الفيديو","بديلات لإنتاج الفيديو","إنتاج الفيديو مقابل تحرير الفيديو","تثبيت أدوات إنتاج الفيديو","دليل إعداد إنتاج الفيديو"]}},"owner":"notedit","repo":"happy-skills","repoPath":"notedit/happy-skills","stars":0,"forks":0,"updatedAt":"2026-03-03T01:58:23.259Z","topics":[],"category":"community","skillMd":{"name":"video-producer","description":">","bodyPreview":"## When to use\n\nUse this skill when the user provides a **video brief** — a description of a complete video with multiple scenes or a narrative arc.\n\n**Triggers:** \"create a promo video\", \"make a product demo\", \"I need a 30-second ad\", \"build a social media animation\", or any prompt describing a multi-scene video.\n\n**Do NOT use for:**\n- Single animation effects → use `gsap-animation`\n- Visual background components → use `react-animation`\n- Non-video tasks\n\n## Skill Relationships\n\n```\nvideo-produ","body":"## When to use\n\nUse this skill when the user provides a **video brief** — a description of a complete video with multiple scenes or a narrative arc.\n\n**Triggers:** \"create a promo video\", \"make a product demo\", \"I need a 30-second ad\", \"build a social media animation\", or any prompt describing a multi-scene video.\n\n**Do NOT use for:**\n- Single animation effects → use `gsap-animation`\n- Visual background components → use `react-animation`\n- Non-video tasks\n\n## Skill Relationships\n\n```\nvideo-producer (this skill)       ← orchestration: what story, which scenes\n├── gsap-animation                ← animation: text splits, SVG drawing, timeline orchestration\n├── spring-animation              ← physics: bouncy entrances, elastic trails, organic motion\n├── react-animation               ← visuals: Aurora, Silk, particles, grain\n└── Remotion                      ← engine: rendering, composition, sequences\n```\n\n## Workflow\n\nInitial request: $ARGUMENTS\n\n### Phase 1: Brief Intake\n\nExtract from the user''s request. Use AskUserQuestion for any missing **required** fields.\n\n| Field | Required | Default | Example |\n|-------|:--------:|---------|---------|\n| Product / brand name | Yes | — | \"Topview\" |\n| Video type | Yes | SaaS Promo | SaaS Promo / Typographic / Social Overlay |\n| Core messages (2-4) | Yes | — | \"AI-powered editing\", \"No coding required\" |\n| Emotional tone | Yes | — | Urgent / Reassuring / Exciting / Professional / Rebellious / Warm / Playful |\n| Memory anchor | Yes | — | \"The single image viewers will remember 30s later\" |\n| Target audience | No | General | \"Developers\", \"Marketers\" |\n| Duration | No | Template default | \"25 seconds\" |\n| Resolution | No | 1920x1080 | 1080x1080 for square |\n| FPS | No | 30 | 60 for social media |\n| Visual style | No | Apple Minimal | Apple Minimal / Bold Typography / Dark Tech / Warm Organic / Retro Pop / Editorial Mono |\n| CTA text | No | None | \"Start Creating →\" |\n| Color accent | No | From style preset | \"#FF7D00\" |\n\n**Emotional tone** drives animation technique selection, spring config, and pacing:\n- **Urgent** → `SPRING.stiff` + GSAP hard cuts, fast stagger (2-3 frames), `power3.out` for GSAP scenes\n- **Reassuring** → `SPRING.smooth` / `SPRING.gentle`, high damping, slow reveals, warm palette\n- **Exciting** → `SPRING.bouncy` / `SPRING.pop`, low damping, saturated colors, SpringTrail pop-ins\n- **Professional** → `SPRING.snappy` / `SPRING.smooth`, measured timing, clean motion, generous holds\n- **Rebellious** → `SPRING.stiff` + `SPRING.rubber` mix, GSAP glitch effects, irregular stagger\n- **Warm** → `SPRING.gentle` / `SPRING.molasses`, warm gradients, rounded shapes, slow stagger (6-8 frames)\n- **Playful** → `SPRING.wobbly` / `SPRING.rubber`, extreme overshoot, GridStagger center-out, bright accents\n\n**Memory anchor** — the ONE visual moment viewers will screenshot or recall. Every production decision should reinforce this anchor. Ask: \"If someone describes this video to a friend, what image do they describe?\"\n\n### Phase 2: Planning\n\n1. **Select narrative template** based on video type → see `rules/narrative-templates.md`\n2. **Select visual style** → see `rules/style-presets.md`\n3. **Map user''s messages to scene slots** in the selected template\n4. **Select animation pattern** for each scene → see `rules/scene-patterns.md`\n5. Present the plan as a table to the user:\n\n```\nScene | Duration | Pattern        | Content\n1     | 3s       | TitleCard      | \"Topview is powerful\"\n2     | 3s       | CardFlip3D     | CLI pain → AI solution\n...\n```\n\nWait for user confirmation before proceeding.\n\n### Phase 3: Project Scaffold\n\nGenerate the standard Remotion project structure → see `rules/project-scaffold.md`:\n\n1. `src/config.ts` — all parameters (colors, typography, scene frames)\n2. `src/Root.tsx` — composition registration\n3. `src/Composition.tsx` — TransitionSeries with all scenes\n4. `src/components/` — shared components (background, etc.)\n5. `src/scenes/` — one file per scene\n\n**Frame calculation:** `sceneFrames = Math.ceil(sceneDurationSeconds * fps)`\n\n### Phase 4: Scene Implementation + Evaluation\n\nImplement scenes in order. Each scene goes through a **build → verify → fix** loop before moving to the next. → see `rules/scene-evaluator.md` for the full scoring rubric and auto-fix rules.\n\nFor each scene:\n\n**Step 4a: Implement scene**\n\n1. Create `src/scenes/SceneN_Name.tsx`\n2. Select the right technique:\n   - Text splitting / SVG drawing / complex timelines → `useGSAPTimeline` or `useGSAPWithFonts` (from gsap-animation skill)\n   - Bouncy/elastic entrances / spring trails / overshoot effects → `spring()` + presets (from spring-animation skill)\n   - Simple fades / slides / linear counters → Remotion native `interpolate()`\n   - Visual backgrounds → react-animation components\n3. Apply the selected animation pattern from the plan\n4. Wire into `Composition.tsx` and register preview in `Root.tsx`\n\n**Step 4b: Render stills**\n\nCapture two key frames for visual inspection:\n\n```bash\n# Entry frame — catches early layout, initial positions\nnpx remotion still src/index.ts SceneN-Preview /tmp/sceneN_entry.png --frame={floor(SCENE_FRAMES.sceneN * 0.15)}\n\n# Peak frame — hero moment, all entrances settled\nnpx remotion still src/index.ts SceneN-Preview /tmp/sceneN_peak.png --frame={floor(SCENE_FRAMES.sceneN * 0.60)}\n```\n\n**Step 4c: Evaluate**\n\nRead the scene code + `config.ts` + rendered screenshots. Score across 7 weighted dimensions (anti-pattern compliance, typography, color & contrast, motion design, composition, narrative coherence, technical correctness).\n\n- **Score >= 7.0** and no instant-fails → **PASS**, proceed to next scene\n- **Score < 7.0** or instant-fail triggered → proceed to Step 4d\n\n**Step 4d: Auto-fix** (max 2 iterations)\n\nApply targeted fixes from the deduction → fix mapping table in `rules/scene-evaluator.md`. Each deduction maps to a concrete code change — not a vague suggestion. After fixing:\n\n- Return to **Step 4b** (re-render stills, re-score)\n- After **iteration 2**, if still below threshold: emit **WARNING** and proceed to next scene\n\n**Cross-scene tracking:** Maintain a running context of accent colors, spring presets, entrance directions, and techniques used per scene. At scene 3+, check for variety issues (same preset 3x in a row, same entrance direction, etc.).\n\n**After all scenes complete:** Output a full **Evaluation Summary Table** showing per-scene scores, iteration counts, and cross-scene notes before proceeding to Phase 5.\n\n**Pattern selection principle:** Use `spring()` for physics-driven motion with bounce/overshoot. Use GSAP for SplitText, DrawSVG, MorphSVG, and complex timeline orchestration. Use `interpolate()` for simple linear/eased motion.\n\n### Phase 5: Rendering\n\n```bash\n# Standard MP4\nnpx remotion render src/index.ts MainVideo --output out/video.mp4\n\n# High quality\nnpx remotion render src/index.ts MainVideo --codec h264 --crf 15\n\n# Transparent background (social overlays)\nnpx remotion render src/index.ts MainVideo --codec prores --prores-profile 4444\nnpx remotion render src/index.ts MainVideo --codec vp9 --output out/overlay.webm\n```\n\n| Format | Alpha | Use Case |\n|--------|:-----:|----------|\n| MP4 H.264 | No | Universal playback |\n| ProRes 4444 | Yes | Professional compositing |\n| WebM VP9 | Yes | Web overlays |\n\n## Complexity Calibration\n\nMatch implementation complexity to the emotional tone and visual style. The effort invested in animation must serve the creative vision — not exceed or undercut it.\n\n| Tone × Style | Pacing | Spring Preset | GSAP Usage | Hold Duration |\n|---|---|---|---|---|\n| Urgent + Bold Typography | Fast (1.5-2.5s scenes) | `stiff` (stagger: 2f) | charCascade, hard cut transitions | Short (0.5s) |\n| Exciting + Dark Tech | Medium-fast (2-3s) | `bouncy` / `pop` (stagger: 3f) | circleReveal transitions, DrawSVG | Medium (0.8s) |\n| Professional + Apple Minimal | Measured (3-4s) | `smooth` / `snappy` (stagger: 5f) | textReveal, SplitScreenComparison | Long (1.2s) |\n| Warm + Warm Organic | Slow (3-5s) | `gentle` / `molasses` (stagger: 8f) | Minimal GSAP, prefer spring-only | Long (1.5s) |\n| Rebellious + Retro Pop | Irregular | `stiff` + `rubber` alternating | ScrambleText, glitch effects | Variable |\n| Playful + any | Bouncy (2-3s) | `wobbly` / `pop` (stagger: 3f) | Minimal GSAP, SpringTrail + GridStagger | Medium (0.8s) |\n\n**Principle:** One signature transition executed perfectly creates more impact than six mediocre effects. Invest animation budget in the memory anchor moment.\n\n**Anti-bloat rule:** Each scene should use ONE dominant animation technique:\n- Spring-dominant: `spring()` + `interpolate()` for all motion (bouncy entrances, trails, counters)\n- GSAP-dominant: `useGSAPTimeline` for text splits, SVG operations, complex orchestration\n- Mixed: Spring for element entrances, GSAP for text splitting within that element (acceptable)\n- NEVER: GSAP timeline + spring physics + react-animation background + complex interpolations in one scene\n\n**Spring-first principle:** Default to `spring()` for all entrances, exits, and stagger animations. Only add GSAP when you specifically need SplitText, DrawSVG, MorphSVG, ScrambleText, or complex timeline labels. Spring is lighter, requires no additional dependency, and produces naturally organic motion.\n\n## Creative Direction Principles\n\n**Every video must have a point of view.** A \"clean, professional\" video without a strong aesthetic commitment is just a generic video. Commit to specific, bold choices:\n\n- A **color** that dominates (not 5 equally-weighted pastels)\n- A **font** that has character (not the first Google Font result)\n- A **motion signature** that repeats across scenes (the same easing curve, the same entrance direction, the same hold rhythm)\n- A **spatial rule** that breaks expectations (all text left-aligned at 20%, asymmetric panels, diagonal grid)\n\n**The Memorability Test:** Before finalizing the plan, ask: \"If I showed this next to 10 other AI-generated promo videos, would mine look distinctly different?\" If no, push the aesthetic further.\n\n## Quick Decision Reference\n\n| \"I need...\" | Use |\n|-------------|-----|\n| Bold text entrance (split chars) | gsap: charCascade / textReveal effect |\n| Bold text entrance (bouncy words) | spring: WordTrail / CharacterTrail |\n| Side-by-side comparison | gsap: SplitScreenComparison template |\n| Card flip reveal (smooth) | gsap: CardFlip3D template |\n| Card flip reveal (spring physics) | spring: SpringCardFlip |\n| Elements from both sides | gsap: PerspectiveEntrance template |\n| Word highlighting | gsap: TextHighlightBox pattern |\n| UI click simulation | gsap: CursorClick pattern |\n| Text swap animation | gsap: RotateXTextSwap pattern |\n| Flowing background | react-animation: Aurora / Silk |\n| Film grain overlay | react-animation: NoiseOverlay |\n| Simple fade / slide | Remotion: interpolate() |\n| Number counter (linear) | Remotion: interpolate() |\n| Number counter (overshoot) | spring: SpringCounter |\n| Bouncy scale entrance | spring: ScalePop |\n| Staggered list/grid reveal | spring: SpringTrail / GridStagger |\n| Enter + exit animation | spring: useSpringEnterExit |\n| Sequential orchestration | spring: useSpringChain |\n| Typing effect | Remotion: .slice() + interpolate() |\n| Scene transition (wipe/iris) | gsap: circleReveal / wipeIn effect |\n| Scene transition (spring slide) | spring: SpringSlide / SpringCrossfade |\n| Logo stroke draw | gsap: DrawSVG + drawIn effect |\n| Feature grid pop-in | spring: SpringFeatureGrid |\n\n---\n\n## Variability Enforcement\n\nNEVER produce the same aesthetic twice across different videos. Each production must feel like a unique creative work, not a template fill-in.\n\n- **Rotate fonts:** Never use the same display font in consecutive videos. If you used Space Grotesk last time, pick Clash Display or Cabinet Grotesk this time.\n- **Rotate color temperature:** Alternate between warm (orange/coral/gold) and cool (blue/violet/emerald) dominant palettes.\n- **Rotate spatial composition:** If the last video was center-aligned symmetrical, make this one left-anchored asymmetrical.\n- **Rotate motion signatures:** Vary between spring-heavy, linear-mechanical, and organic-fluid animation philosophies.\n- **Rotate background treatments:** Cycle through solid, gradient blob, aurora, grain texture, geometric pattern.\n\n**The Divergence Rule:** Before starting Phase 3, mentally compare the planned aesthetic to a \"default AI video\" — white background, centered Inter text, fade-in transitions, blue accent. If your plan shares more than ONE of these traits, push further from the default.\n\n---\n\n## Creative Ambition\n\nEvery video should make viewers want to screenshot a frame and share it. This is motion graphics as a craft — not template assembly.\n\nPush beyond \"functional\" toward \"remarkable.\" Use unexpected font pairings. Try color combinations that feel risky. Let one scene break the grid. Give the memory anchor moment 2x the animation investment of other scenes.\n\nThe gap between a forgettable promo and a memorable one is not technical complexity — it''s creative courage. Make bold choices and execute them with precision.\n"},"lastSynced":"2026-03-03T02:11:47.411Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing advanced video production capabilities with multi-scene narratives and animation support","zh":"非常适合需要高级视频制作能力的创意代理，包括多场景叙事和动画支持","ja":"クリエイティブエージェントが高度なビデオ制作機能を必要とする場合に最適で、マルチシーンの物語とアニメーションサポートを備えています","ko":"고급 비디오 제작 기능과 멀티 씬 내러티브 및 애니메이션 지원이 필요한 크리에이티브 에이전트에게 적합함","es":"Perfecto para Agentes Creativos que necesitan capacidades de producción de video avanzadas con narrativas de varias escenas y soporte de animación","fr":"Parfait pour les agents créatifs ayant besoin de capacités de production vidéo avancées avec des récits multi-scènes et un support d''animation","de":"Perfekt für kreative Agenten, die erweiterte Videoproduktionsfähigkeiten mit Multi-Szenen-Narrativen und Animationsunterstützung benötigen","pt":"Perfeito para Agentes Criativos que necessitam de capacidades avançadas de produção de vídeo com narrativas de multi-cena e suporte a animação","ru":"Идеально для Креативных Агентов, которым требуются продвинутые возможности видеопроизводства с мульти-сценарными нарративами и поддержкой анимации","ar":"مثالي لعميل الإبداع الذي يحتاج إلى إمكانيات إنتاج فيديو متقدمة مع سيناريوهات متعددة المشاهد ودعم الرسومات المتحركة"},"recommendation":{"en":"Empowers agents to generate high-quality video content using video briefs, supporting promo videos, product demos, and social media animations with precise scene control and narrative arcs, leveraging protocols like video encoding and file formats","zh":"赋予代理生成高质量视频内容的能力，使用视频简报，支持宣传视频、产品演示和社交媒体动画，具有精确的场景控制和叙事弧线，利用视频编码和文件格式等协议","ja":"ビデオブリーフを使用して、高品質のビデオコンテンツを生成するエージェントをEmpowersします。プロモーションビデオ、製品デモ、ソーシャルメディアアニメーションをサポートし、正確なシーンコントロールと物語のアークを提供し、ビデオエンコードやファイル形式などのプロトコルを活用します","ko":"비디오 브리핑을 사용하여 고화질 비디오 콘텐츠를 생성할 수 있는 에이전트를 강화하여, 프로모션 비디오, 제품 데모 및 소셜 미디어 애니메이션을 지원하며, 정교한 씬 컨트롤 및 내러티브 아크를 제공하고, 비디오 인코딩 및 파일 형식 등의 프로토콜을 활용함","es":"Habilita a los agentes a generar contenido de video de alta calidad utilizando descripciones de video, que admiten videos promocionales, demos de productos y animaciones de redes sociales con un control de escena preciso y arcos narrativos, aprovechando protocolos como la codificación de video y formatos de archivo","fr":"Permet aux agents de générer du contenu vidéo de haute qualité en utilisant des descriptifs vidéo, qui prennent en charge les vidéos promotionnelles, les démos de produits et les animations de réseaux sociaux avec un contrôle de scène précis et des arcs narratifs, en exploitant des protocoles tels que le codage vidéo et les formats de fichiers","de":"Ermächtigt Agenten, hochwertige Videoinhalte zu erstellen, indem sie Video-Beschreibungen verwenden, die Promo-Videos, Produkt-Demos und soziale Medien-Animationen mit präziser Szenensteuerung und Erzählbögen unterstützen, indem sie Protokolle wie Video-Codierung und Dateiformate nutzen","pt":"Habilita os agentes a gerar conteúdo de vídeo de alta qualidade usando briefs de vídeo, suportando vídeos promocionais, demonstrações de produtos e animações de mídia social com controle preciso de cena e arcos narrativos, utilizando protocolos como codificação de vídeo e formatos de arquivo","ru":"Наделяет агентов возможностью генерировать высококачественный видеоконтент с помощью видео-брифов, поддерживающих промо-видео, демонстрации продуктов и социальные анимации с точным контролем сцены и нарративными арками, используя протоколы, такие как видеокодирование и форматы файлов","ar":"يمنح الوكيل القدرة على生成 محتوى فيديو عالي الجودة باستخدام ملخصات الفيديو ، ودعم مقاطع الفيديو الترويجية وعروض المنتجات والرسومات المتحركة على وسائل الإعلام الاجتماعية مع التحكم الدقيق في المشهد والقصص السردية ، باستخدام بروتوكولات مثل ترميز الفيديو وتنسيقات الملفات"},"useCases":{"en":["Creating promo videos with complex scene transitions","Generating product demos with interactive animations","Building social media animations with custom narrative arcs"],"zh":["创建具有复杂场景过渡的宣传视频","生成具有交互式动画的产品演示","构建具有自定义叙事弧的社交媒体动画"],"ja":["複雑なシーン遷移を持つプロモーションビデオを作成する","インタラクティブアニメーションを持つ製品デモを生成する","カスタムな物語のアークを持つソーシャルメディアアニメーションを構築する"],"ko":["복잡한 씬 전환을 갖는 프로모션 비디오 생성","인터랙티브 애니메이션을 갖는 제품 데모 생성","사용자 정의 내러티브 아크를 갖는 소셜 미디어 애니메이션 구축"],"es":["Creación de videos promocionales con transiciones de escena complejas","Generación de demos de productos con animaciones interactivas","Creación de animaciones de redes sociales con arcos narrativos personalizados"],"fr":["Création de vidéos promotionnelles avec des transitions de scène complexes","Génération de démos de produits avec des animations interactives","Création d''animations de réseaux sociaux avec des arcs narratifs personnalisés"],"de":["Erstellung von Promo-Videos mit komplexen Szenenübergängen","Generierung von Produkt-Demos mit interaktiven Animationen","Erstellung von sozialen Medien-Animationen mit benutzerdefinierten Erzählbögen"],"pt":["Criar vídeos promocionais com transições de cena complexas","Gerar demonstrações de produtos com animações interativas","Construir animações de mídia social com arcos narrativos personalizados"],"ru":["Создание промо-видео с сложными переходами сцены","Генерация демонстраций продуктов с интерактивными анимациями","Построение социальных анимаций с настраиваемыми нарративными арками"],"ar":["إنشاء مقاطع فيديو ترويجية مع انتقالات مشهد معقدة","توليد عروض منتجات مع رسومات متحركة تفاعلية","بناء رسومات متحركة على وسائل الإعلام الاجتماعية مع قوس سردي مخصص"]},"limitations":{"en":["Requires detailed video briefs","Not suitable for single animation effects or visual background components","Limited to video production tasks"],"zh":["需要详细的视频简报","不适合单个动画效果或视觉背景组件","仅限视频制作任务"],"ja":["詳細なビデオブリーフが必要","単一のアニメーション効果または視覚的背景コンポーネントには適していない","ビデオ制作タスクに限定される"],"ko":["상세한 비디오 브리핑이 필요","단일 애니메이션 효과 또는 시각적 배경 구성 요소에는 적합하지 않음","비디오 제작 작업에만 제한됨"],"es":["Requiere descripciones de video detalladas","No es adecuado para efectos de animación individuales o componentes de fondo visual","Limitado a tareas de producción de video"],"fr":["Nécessite des descriptifs vidéo détaillés","N''est pas adapté aux effets d''animation individuels ou aux composants de fond visuel","Limité aux tâches de production vidéo"],"de":["Benötigt detaillierte Video-Beschreibungen","Nicht geeignet für einzelne Animationseffekte oder visuelle Hintergrundkomponenten","Begrenzt auf Videoproduktionsaufgaben"],"pt":["Exige briefs de vídeo detalhados","Não é adequado para efeitos de animação simples ou componentes de fundo visual","Limitado a tarefas de produção de vídeo"],"ru":["Требует подробных видео-брифов","Не подходит для простых эффектов анимации или визуальных фоновых компонентов","Ограничен задачами видеопроизводства"],"ar":["يتطلب ملخصات فيديو مفصلة","لا يصلح للأFFECTS البسيطة للرسومات المتحركة أو مكونات الخلفية البصرية","محدود بمهام إنتاج الفيديو"]},"version":3},"contentHash":"2b6b0dfba44f70d198c9efa5151f2e86c44df3bdc5ddbbb5a00e3e8773b92575","qualityScore":46}');
