INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('notedit/happy-skills/video-producer', 'video-producer', 'notedit', 'happy-skills', 'community', 'video-producer notedit happy-skills community Video Producer是基于AI的智能视频制作工具，帮助开发者高效创建和编辑视频内容 Video ProducerはAIエージェントを活用した動画制作ツールで、開発者が動画を作成、編集することを支援 비디오 프로듀서는 AI 기반의 비디오 제작 도구로, 개발자가 비디오 콘텐츠를 효율적으로 생성하고 편집할 수 있도록 도와줍니다 El agente de video producer es una herramienta de codificación feliz que utiliza agentes de IA para mejorar la experiencia del desarrollador L''agent de vidéo producer est un outil de codage heureux qui utilise des agents d''IA pour améliorer l''expérience du développeur Der Video-Producer-Agent ist ein Codier-Tool, das KI-Agents verwendet, um die Erfahrung des Entwicklers zu verbessern A ferramenta de vídeo-produção é uma solução inovadora para desenvolvedores que desejam criar vídeos personalizados com facilidade Видео-производственная инструментка - это инновационное решение для разработчиков, которые хотят создавать персонализированные видео с легкостью أداة إنتاج الفيديو هي حل مبتكر للمطورين الذين يرغبون في إنشاء فيديوهات مخصصة بسهولة happy coding agent 如何使用Video Producer 什么是AI智能视频制作 Video Producer替代品 Video Producer与Adobe Premiere的比较 Video Producer安装教程 Video Producer设置指南 happy coding agent');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/sentry-mcp/testing-guidelines', 'community', 'getsentry', 'sentry-mcp', 'getsentry/sentry-mcp', 'testing-guidelines', 575, 87, 45, '2026-02-28T20:56:08Z', '2026-03-06T06:27:41.008Z', '5261fda7fb4f3fc5e009725533ac6d6786ef066ad5de056f4903b09bbc9db5e7', '{"id":"getsentry/sentry-mcp/testing-guidelines","name":"testing-guidelines","description":{"en":"The testing-guidelines skill provides an MCP server for interacting with Sentry via LLMs, helping developers write tests that mock external services and use real fixtures. This skill benefits AI agent developers who need to ensure robust testing.","zh":"MCP服务器的测试指南，用于与Sentry进行交互。包含核心原则和最佳实践，帮助开发者进行高效的测试","ja":"SentryとのインタラクションにMCPサーバーを使用するためのテストガイドライン。コアプリンシプルとベストプラクティスを紹介","ko":"Sentry와 상호 작용하기 위한 MCP 서버의 테스트 가이드라인. 핵심 원칙과 모범 사례를 포함하여 개발자가 효율적으로 테스트할 수 있도록 도와줍니다","es":"El testing-guidelines es una guía para interactuar con Sentry a través de LLMs en un servidor MCP, proporcionando directrices para pruebas de integración y unidad","fr":"Les directives de test sont un guide pour interagir avec Sentry via les LLM sur un serveur MCP, offrant des directives pour les tests d''intégration et d''unité","de":"Die testing-guidelines sind ein Leitfaden für die Interaktion mit Sentry über LLMs auf einem MCP-Server, mit Richtlinien für Integrations- und Einheitstests","pt":"O MCP Server para interagir com o Sentry via LLMs oferece diretrizes de teste para garantir a integração perfeita. Siga nossas dicas para mockar serviços externos e usar fixtures reais.","ru":"MCP Server для взаимодействия с Sentry через LLMs предлагает руководство по тестированию для обеспечения идеальной интеграции. Следуйте нашим советам для模окирования внешних сервисов и использования реальных фикстур.","ar":"يقدم خادم MCP للتفاعل مع Sentry عبر LLMs إرشادات اختبار لضمان التكامل المثالي. اتبع نصائحنا لمحاكاة الخدمات الخارجية واستخدام الإعدادات الحقيقية."},"seo":{"title":{"en":"testing-guidelines: Best Practices for AI Agents | AI Age...","zh":"AI工具测试指南：MCP服务器集成测试最佳实践","ja":"AIエージェントのテストガイドライン：MCPサーバーによる統合テスト","ko":"AI 에이전트 테스트 가이드라인: MCP 서버 통합 테스트 설정","es":"Guía de Configuración de testing-guidelines para MCP Server","fr":"Paramétrer les Directives de Test pour le Serveur MCP","de":"Einrichtungsleitfaden für testing-guidelines auf MCP-Servern","pt":"Guia de Configuração de Diretrizes de Teste para MCP Server","ru":"Настройка Руководства по Тестированию для ИИ Агентов MCP ...","ar":"إعداد إرشادات الاختبار للخادم MCP"},"description":{"en":"Discover how to write effective tests with testing-guidelines. Learn to mock external services and prefer integration tests for robust AI agent development. ...","zh":"了解如何使用MCP服务器和LLMs与Sentry进行交互的测试指南，包括核心原则和最佳实践","ja":"SentryとのインタラクションにMCPサーバーとLLMsを使用するためのテストガイドライン。コアプリンシプルとベストプラクティスを紹介","ko":"Sentry와 상호 작용하기 위한 MCP 서버와 LLMs를 사용하는 테스트 가이드라인. 핵심 원칙과 모범 사례를 소개합니다","es":"Aprende a configurar testing-guidelines para MCP Server con nuestras mejores prácticas y directrices de prueba para Sentry y LLMs","fr":"Découvrez comment paramétrer les directives de test pour le serveur MCP avec nos meilleures pratiques pour Sentry et les LLM","de":"Erfahren Sie, wie Sie testing-guidelines auf MCP-Servern einrichten, mit unseren Best Practices und Testrichtlinien für Sentry und LLMs","pt":"Aprenda a configurar diretrizes de teste para o MCP Server com nossas melhores práticas e dicas para integração com Sentry via LLMs","ru":"Узнайте, как настроить руководство по тестированию для ИИ Агентов MCP Server с нашими лучшими практиками и советами для интеграции с Sentry через LLMs","ar":"تعلم كيفية إعداد إرشادات الاختبار للخادم MCP باستخدام أفضل الممارسات وأفكار التكامل مع Sentry عبر LLMs"},"definition":{"en":"testing-guidelines is a set of principles for writing tests that mock external services and use real fixtures, ensuring robust and reliable AI agent development.","zh":"测试指南是用于MCP服务器与Sentry交互的核心原则和最佳实践的集合","ja":"テストガイドラインは、SentryとのインタラクションにMCPサーバーを使用するためのコアプリンシプルとベストプラクティスの集合","ko":"테스트 가이드라인은 Sentry와 상호 작용하기 위한 MCP 서버의 핵심 원칙과 모범 사례의 집합입니다","es":"Un conjunto de directrices para pruebas de software que interactúan con Sentry a través de LLMs en un servidor MCP","fr":"Un ensemble de directives pour les tests de logiciels qui interagissent avec Sentry via les LLM sur un serveur MCP","de":"Ein Satz von Richtlinien für Softwaretests, die mit Sentry über LLMs auf einem MCP-Server interagieren","pt":"Diretrizes de teste para MCP Server são um conjunto de princípios para garantir a integração correta com o Sentry via LLMs","ru":"Руководство по тестированию для ИИ Агентов MCP Server - это набор принципов для обеспечения правильной интеграции с Sentry через LLMs","ar":"إرشادات الاختبار للخادم MCP هي مجموعة من المبادئ لضمان التكامل الصحيح مع Sentry عبر LLMs"},"features":{"en":["Mocks third-party network services for isolated testing","Uses fixtures based on real-world data for accurate testing","Preferes integration tests over unit tests for end-to-end testing","Captures real API responses and sanitizes them for secure testing","Never makes actual network calls in tests for efficient development"],"zh":["使用MCP服务器与Sentry进行交互","核心原则：模拟外部服务，使用真实的测试数据","优先使用集成测试而不是单元测试","使用基于真实世界数据的测试数据","捕获真实的API响应并对其进行清理"],"ja":["MCPサーバーを使用してSentryとのインタラクション","コアプリンシプル：外部サービスをモックし、実際のテストデータを使用","統合テストを単体テストよりも優先","実際のデータを使用したテストデータを使用","実際のAPIレスポンスをキャプチャして清理"],"ko":["MCP 서버를 사용하여 Sentry와 상호 작용","핵심 원칙: 외부 서비스를 모의하고 실제 테스트 데이터를 사용","통합 테스트를 단위 테스트보다 우선","실제 데이터를 사용한 테스트 데이터를 사용","실제 API 응답을 캡처하고 정리"],"es":["Mockear servicios externos con datos reales","Preferir pruebas de integración sobre pruebas de unidad","Uso de fixtures basados en datos del mundo real","Captura de respuestas de API reales y saneamiento","Evitar llamadas de red reales en pruebas"],"fr":["Mocker les services externes avec des données réelles","Préférer les tests d''intégration aux tests d''unité","Utilisation de fixtures basés sur des données du monde réel","Capture de réponses d''API réelles et assainissement","Éviter les appels de réseau réels dans les tests"],"de":["Mocken von externen Diensten mit echten Daten","Bevorzugung von Integrations-tests gegenüber Einheitstests","Verwendung von Fixtures basierend auf realen Welt-daten","Erfassung von echten API-Antworten und Säuberung","Vermeidung von echten Netzwerkanrufen in Tests"],"pt":["Mock de serviços externos","Uso de fixtures reais","Priorização de testes de integração sobre testes unitários","Captura de respostas de API reais","Sanitização de dados para evitar PII"],"ru":["Модокирование внешних сервисов","Использование реальных фикстур","Приоритет интеграционных тестов над юнит-тестами","Захват реальных ответов API","Санитизация данных для предотвращения PII"],"ar":["محاكاة الخدمات الخارجية","استخدام الإعدادات الحقيقية","أولوية الاختبارات التكاملية على الاختبارات الوحدوية","التقاط استجابات API الحقيقية","تنقية البيانات لمنع PII"]},"keywords":{"en":["how to use testing-guidelines","testing-guidelines setup guide","testing-guidelines vs Jest","what is testing-guidelines","testing-guidelines install","testing-guidelines best practices","testing-guidelines for AI agents","testing-guidelines alternative","testing-guidelines tutorial"],"zh":["AI工具测试","MCP服务器","Sentry","测试指南","核心原则","集成测试","单元测试","测试数据","API响应"],"ja":["AIエージェントのテスト","MCPサーバー","Sentry","テストガイドライン","コアプリンシプル","統合テスト","単体テスト","テストデータ","APIレスポンス"],"ko":["AI 에이전트 테스트","MCP 서버","Sentry","테스트 가이드라인","핵심 원칙","통합 테스트","단위 테스트","테스트 데이터","API 응답"],"es":["testing-guidelines","MCP Server","Sentry","LLMs","pruebas de integración","pruebas de unidad","mockear servicios externos","fixtures basados en datos reales"],"fr":["directives de test","Serveur MCP","Sentry","LLM","tests d''intégration","tests d''unité","mockage de services externes","fixtures basés sur des données réelles"],"de":["testing-guidelines","MCP-Server","Sentry","LLMs","Integrations-tests","Einheitstests","Mocken von externen Diensten","Fixtures basierend auf realen Welt-daten"],"pt":["diretrizes de teste","MCP Server","Sentry","LLMs","testes de integração","mock de serviços externos","fixtures reais","desenvolvimento de software"],"ru":["руководство по тестированию","ИИ Агенты","MCP Server","Sentry","LLMs","интеграционные тесты","модокирование внешних сервисов","реальные фикстуры","разработка программного обеспечения"],"ar":["إرشادات الاختبار","خادم MCP","Sentry","LLMs","اختبارات التكامل","محاكاة الخدمات الخارجية","الإعدادات الحقيقية","تطوير البرمجيات"]}},"owner":"getsentry","repo":"sentry-mcp","repoPath":"getsentry/sentry-mcp","stars":575,"forks":87,"updatedAt":"2026-02-28T20:56:08Z","topics":["mcp-server","tag-production"],"category":"community","skillMd":{"name":"testing-guidelines","description":"Guide for writing tests. Use when adding new functionality, fixing bugs, or when tests are needed. Emphasizes integration tests, real-world fixtures, and regression coverage.","bodyPreview":"# Testing Guidelines\n\nFollow these principles when writing tests.\n\n## Core Principles\n\n### 1. Mock External Services, Use Real Fixtures\n\n**ALWAYS** mock third-party network services. **ALWAYS** use fixtures based on real-world data.\n\n- Fixtures must be scrubbed of PII (use dummy data like `foo@example.com`, `user-123`)\n- Capture real API responses, then sanitize them\n- Never make actual network calls in tests\n\n### 2. Prefer Integration Tests Over Unit Tests\n\nFocus on **end-to-end style tests** t","body":"# Testing Guidelines\n\nFollow these principles when writing tests.\n\n## Core Principles\n\n### 1. Mock External Services, Use Real Fixtures\n\n**ALWAYS** mock third-party network services. **ALWAYS** use fixtures based on real-world data.\n\n- Fixtures must be scrubbed of PII (use dummy data like `foo@example.com`, `user-123`)\n- Capture real API responses, then sanitize them\n- Never make actual network calls in tests\n\n### 2. Prefer Integration Tests Over Unit Tests\n\nFocus on **end-to-end style tests** that validate inputs and outputs, not implementation details.\n\n- Test the public interface, not internal methods\n- Unit tests are valuable for edge cases in pure functions, but integration tests are the priority\n- If refactoring breaks tests but behavior is unchanged, the tests were too coupled to implementation\n\n### 3. Minimize Edge Case Testing\n\nDon''t test every variant of a problem.\n\n- Cover the **common path** thoroughly\n- Skip exhaustive input permutations\n- Skip unlikely edge cases that add maintenance burden without value\n- One representative test per category of input is usually sufficient\n\n### 4. Always Add Regression Tests for Bugs\n\nWhen a **bug** is identified, **ALWAYS** add a test that would have caught it.\n\n- The test should fail before the fix and pass after\n- Name it descriptively to document the bug\n- This prevents the same bug from recurring\n\n**Note:** Regression tests are for unintentional broken behavior (bugs), not intentional changes. Intentional feature removals, deprecations, or breaking changes do NOT need regression tests—these are design decisions, not defects.\n\n### 5. Cover Every User Entry Point\n\n**ALWAYS** have at least one basic test for each customer/user entry point.\n\n- CLI commands, API endpoints, public/exported functions\n- Test the common/happy path first\n- This proves the entry point works at all\n\n**Note:** \"Entry point\" means the public interface—exported functions, CLI commands, API routes. Internal/private functions are NOT entry points, even if they handle user-facing flags or options. Test entry points; internal functions get coverage through those tests.\n\n### 6. Tests Validate Before Manual QA\n\nTests are how we validate **ANY** functionality works before manual testing.\n\n- Write tests first or alongside code, not as an afterthought\n- If you can''t test it, reconsider the design\n- Passing tests should give confidence to ship\n\n## Technical Guidelines\n\n### File Organization\n\n- Co-locate tests with source files when possible\n- Use the project''s standard test file naming convention\n\n### Test Isolation\n\nEvery test must:\n- Run independently without affecting other tests\n- Use temporary directories for file operations\n- Clean up resources after completion\n\n### Pure Function Tests\n\nFor pure functions without side effects, no special setup is needed—just test inputs and outputs directly.\n\n## Checklist Before Submitting\n\n- [ ] New entry points have at least one happy-path test\n- [ ] Bug fixes (not intentional changes) include a regression test\n- [ ] External services are mocked with sanitized fixtures\n- [ ] Tests validate behavior, not implementation\n- [ ] No shared state between tests\n"},"lastSynced":"2026-03-06T06:27:41.008Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing robust testing capabilities with Sentry and LLMs","zh":"适合需要使用Sentry和LLMs进行强大的测试能力的AI代理开发人员","ja":"SentryとLLMsを使用した強力なテスト機能を必要とするAIエージェント開発者に最適","ko":"Sentry와 LLMs를 사용하여 강력한 테스트 기능이 필요한 AI 에이전트 개발자를 위한 최적의 선택","es":"Perfecto para desarrolladores de Agentes de IA que necesitan capacidades de prueba robustas con Sentry y LLMs","fr":"Parfait pour les développeurs d''Agents IA nécessitant des capacités de test robustes avec Sentry et LLMs","de":"Perfekt für AI-Agent-Entwickler, die robuste Testfunktionen mit Sentry und LLMs benötigen","pt":"Perfeito para Desenvolvedores de Agentes de IA que precisam de capacidades de teste robustas com Sentry e LLMs","ru":"Идеально для разработчиков агентов ИИ, которым необходимы мощные возможности тестирования с Sentry и LLMs","ar":"مثالي لمنطقي برنامج العميل الذكاء الاصطناعي الذين يحتاجون إلى إمكانيات اختبار قوية مع Sentry و LLMs"},"recommendation":{"en":"Empowers agents to write comprehensive tests that mock external services and utilize real fixtures, ensuring robustness and reliability by capturing real API responses and sanitizing them, while always avoiding actual network calls in tests","zh":"赋予代理编写全面测试的能力，模拟外部服务，利用真实的fixture，通过捕获真实的API响应并对其进行清理，确保强健性和可靠性，同时始终避免在测试中进行实际的网络调用","ja":"エージェントに外部サービスをモックし、実際のフィクスチャを利用して包括的なテストを記述する能力を付与し、実際のAPIレスポンスを捕捉してサニタイズし、常にテストでの実際のネットワーク呼び出しを回避することで、頑健性と信頼性を確保する","ko":"에이전트가 외부 서비스를 모의하고 실제 fixture를 사용하여 포괄적인 테스트를 작성할 수 있는 기능을 부여하여 실제 API 응답을 캡처하고 정리하고 테스트에서 실제 네트워크 호출을 항상 피함으로써 강건성과 신뢰성을 보장","es":"Habilita a los agentes a escribir pruebas exhaustivas que simulan servicios externos y utilizan fixtures reales, garantizando la robustez y la confiabilidad al capturar respuestas de API reales y sanitizarlas, mientras siempre evita llamadas de red reales en las pruebas","fr":"Permet aux agents d''écrire des tests complets qui simulent des services externes et utilisent des fixtures réelles, garantissant la robustesse et la fiabilité en capturant des réponses API réelles et en les sanitivant, tout en évitant toujours les appels réseau réels dans les tests","de":"Ermächtigt Agenten, umfassende Tests zu schreiben, die externe Dienste simulieren und reale Fixtures nutzen, wodurch Robustheit und Zuverlässigkeit durch die Erfassung realer API-Antworten und deren Sanitärversorgung gewährleistet werden, während immer tatsächliche Netzwerkanrufe in den Tests vermieden werden","pt":"Habilita os agentes a escrever testes abrangentes que simulam serviços externos e utilizam fixtures reais, garantindo robustez e confiabilidade ao capturar respostas de API reais e sanitizá-las, enquanto sempre evita chamadas de rede reais nos testes","ru":"Наделяет агентов возможностью писать комплексные тесты, которые имитируют внешние сервисы и используют реальные фикстуры, обеспечивая прочность и надежность путем захвата реальных ответов API и их санитарной обработки, при этом всегда избегая фактических сетевых вызовов в тестах","ar":"يمنح العميل القدرة على كتابة الاختبارات الشاملة التي ت模ь الخدمات الخارجية وتستخدم إعدادات حقيقية، مما يضمن متانتها وموثوقيتها من خلال التقاط استجابات واجهة برمجة التطبيقات الحقيقية وتنقيتها، مع تجنب دائم للاتصالات الشبكية الفعلية في الاختبارات"},"useCases":{"en":["Mocking third-party network services for secure testing","Generating tests with real-world data fixtures","Debugging issues with end-to-end style tests"],"zh":["为安全测试模拟第三方网络服务","使用实际数据fixture生成测试","使用端到端风格测试调试问题"],"ja":["セキュアなテストのためのサードパーティネットワークサービスのモッキング","実際のデータフィクスチャを使用したテストの生成","エンドツーエンドスタイルのテストを使用した問題のデバッグ"],"ko":["보안 테스트를 위한 제3자 네트워크 서비스 모의","실제 데이터 fixture를 사용한 테스트 생성","엔드 투 엔드 스타일 테스트를 사용한 문제 디버깅"],"es":["Simulación de servicios de red de terceros para pruebas seguras","Generación de pruebas con fixtures de datos del mundo real","Depuración de problemas con pruebas de estilo de extremo a extremo"],"fr":["Simulation de services réseau tiers pour des tests sécurisés","Génération de tests avec des fixtures de données du monde réel","Débogage de problèmes avec des tests de style de bout en bout"],"de":["Simulierung von Drittanbieter-Netzdiensten für sichere Tests","Erzeugung von Tests mit Echtwelt-Daten-Fixtures","Fehlerbehebung mit Tests im End-to-End-Stil"],"pt":["Simulação de serviços de rede de terceiros para testes seguros","Geração de testes com conjuntos de dados do mundo real","Depuração de problemas com testes de estilo de ponta a ponta"],"ru":["Мокинг внешних сетевых сервисов для безопасного тестирования","Генерация тестов с реальными данными фикстур","Отладка проблем с помощью тестов стиля конец-к-концу"],"ar":["模仿 خدمات الشبكة الخارجية للاختبارات الآمنة","توليد الاختبارات باستخدام مجموعات بيانات العالم الحقيقي","تصحيح الأخطاء باستخدام اختبارات النمط من النهاية إلى النهاية"]},"limitations":{"en":["Requires Sentry setup and configuration","Fixtures must be scrubbed of PII","Limited to testing scenarios with mockable external services"],"zh":["需要Sentry的设置和配置","fixture必须清除PII","仅限于具有模拟外部服务的测试场景"],"ja":["Sentryの設定と構成が必要","フィクスチャからPIIを消去する必要がある","モッキング可能な外部サービスを持つテストシナリオに限定される"],"ko":["Sentry 설정 및 구성이 필요","fixture에서 PII를 제거해야 함","mocking 가능한 외부 서비스를 갖는 테스트 시나리오에만 제한"],"es":["Requiere configuración y instalación de Sentry","Los fixtures deben ser limpiados de PII","Limitado a escenarios de prueba con servicios externos simulables"],"fr":["Nécessite une configuration et une installation de Sentry","Les fixtures doivent être nettoyés de PII","Limité aux scénarios de test avec des services externes simulables"],"de":["Benötigt Sentry-Einrichtung und -Konfiguration","Fixtures müssen von PII bereinigt werden","Begrenzt auf Testsszenarien mit simulierbaren externen Diensten"],"pt":["Requer configuração e setup do Sentry","Os fixtures devem ser limpos de PII","Limitado a cenários de teste com serviços externos simuláveis"],"ru":["Требуется настройка и конфигурация Sentry","Фикстуры должны быть очищены от PII","Ограничен тестированием сценариев с имитируемыми внешними сервисами"],"ar":["يتطلب إعداد وتكوين Sentry","يجب تنظيف الإعدادات من PII","محدود لسيناريوهات الاختبار مع خدمات خارجية يمكن محاكاتها"]},"version":4},"contentHash":"5261fda7fb4f3fc5e009725533ac6d6786ef066ad5de056f4903b09bbc9db5e7","qualityScore":45}');
