INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/sentry-mcp/testing-guidelines', 'testing-guidelines', 'getsentry', 'sentry-mcp', 'community', 'testing-guidelines getsentry sentry-mcp community mcp-server tag-production The testing-guidelines skill provides an MCP server for interacting with Sentry via LLMs, helping developers write tests that mock external services and use real fixtures. This skill benefits AI agent developers who need to ensure robust testing. MCP服务器的测试指南，用于与Sentry进行交互。包含核心原则和最佳实践，帮助开发者进行高效的测试 SentryとのインタラクションにMCPサーバーを使用するためのテストガイドライン。コアプリンシプルとベストプラクティスを紹介 Sentry와 상호 작용하기 위한 MCP 서버의 테스트 가이드라인. 핵심 원칙과 모범 사례를 포함하여 개발자가 효율적으로 테스트할 수 있도록 도와줍니다 El testing-guidelines es una guía para interactuar con Sentry a través de LLMs en un servidor MCP, proporcionando directrices para pruebas de integración y unidad Les directives de test sont un guide pour interagir avec Sentry via les LLM sur un serveur MCP, offrant des directives pour les tests d''intégration et d''unité Die testing-guidelines sind ein Leitfaden für die Interaktion mit Sentry über LLMs auf einem MCP-Server, mit Richtlinien für Integrations- und Einheitstests O MCP Server para interagir com o Sentry via LLMs oferece diretrizes de teste para garantir a integração perfeita. Siga nossas dicas para mockar serviços externos e usar fixtures reais. MCP Server для взаимодействия с Sentry через LLMs предлагает руководство по тестированию для обеспечения идеальной интеграции. Следуйте нашим советам для模окирования внешних сервисов и использования реальных фикстур. يقدم خادم MCP للتفاعل مع Sentry عبر LLMs إرشادات اختبار لضمان التكامل المثالي. اتبع نصائحنا لمحاكاة الخدمات الخارجية واستخدام الإعدادات الحقيقية. how to use testing-guidelines testing-guidelines setup guide testing-guidelines vs Jest what is testing-guidelines testing-guidelines install testing-guidelines best practices testing-guidelines for AI agents testing-guidelines alternative testing-guidelines tutorial AI工具测试 MCP服务器 Sentry 测试指南 核心原则 集成测试 单元测试 测试数据 API响应 Mocks third-party network services for isolated testing Uses fixtures based on real-world data for accurate testing Preferes integration tests over unit tests for end-to-end testing Captures real API responses and sanitizes them for secure testing Never makes actual network calls in tests for efficient development testing-guidelines is a set of principles for writing tests that mock external services and use real fixtures, ensuring robust and reliable AI agent development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('imbue-ai/mng/asciinema-demos', 'community', 'imbue-ai', 'mng', 'imbue-ai/mng', 'asciinema-demos', 11, 2, 45, '2026-03-04T00:30:16Z', '2026-03-06T06:46:12.683Z', '9047933f79a5bab80985a589b1f0ecab9ec1267c4bc08dd949732d8e27ae1e05', '{"id":"imbue-ai/mng/asciinema-demos","name":"asciinema-demos","description":{"en":"asciinema-demos is a CLI for managing agents that creates short, looping terminal demo recordings. It helps developers demonstrate completed work and facilitates quick review processes.","zh":"Asciinema Demos 提供创建短小的、循环的终端录制的指南，用于证明任务完成并帮助审查者快速理解更改","ja":"Asciinema Demos は、タスクの完了を証明し、レビュアーが変更を迅速に理解するのに役立つ短いループ型ターミナルレコーディングを作成するためのガイドラインを提供します","ko":"Asciinema Demos는 작업 완료를 증명하고 審查자가 변경 사항을 빠르게 이해하는 데 도움이 되는 짧고 반복되는 터미널 녹화를 생성하는 가이드를 제공합니다","es":"Asciinema-demos es una CLI para gestionar agentes de IA y crear demos de terminal","fr":"Asciinema-demos est une CLI pour gérer les outils d''IA et créer des démos de terminal","de":"Asciinema-demos ist eine CLI zur Verwaltung von KI-Agents und Erstellung von Terminal-Demos","pt":"O asciinema-demos é uma ferramenta para criar gravações de demo de terminal para Ferramentas de IA. Ele permite gravar e verificar sessões de demo com o CLI","ru":"Asciinema-demos - это инструмент для создания демонстрационных записей терминала для ИИ Агентов. Он позволяет записывать и проверять сессии демонстрации с помощью CLI","ar":"Asciinema-demos هو أداة لإنشاء تسجيلات عرض توضيحي للطرفية لأدوات الذكاء الاصطناعي. يسمح بتسجيل وفرض التحقق من جلسات العرض التوضيحي مع CLI"},"seo":{"title":{"en":"asciinema-demos: Creating Terminal Demo Recordings | AI A...","zh":"Asciinema Demos 设置指南：创建终端录制","ja":"Asciinema Demos セットアップガイド：ターミナルデモの作成","ko":"Asciinema Demos 설정 가이드: 터미널 녹화 생성","es":"Guía de configuración de asciinema-demos para agentes de IA","fr":"Guide de démarrage rapide pour asciinema-demos, outils d''IA","de":"Einrichtungsleitfaden für asciinema-demos, KI-Agents","pt":"Guia de Configuração do Asciinema-Demos para Ferramentas ...","ru":"Настройка Asciinema-Demos для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد Asciinema-Demos لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create short, looping terminal demos with asciinema-demos. Learn to visually demonstrate completed work and simplify review processes. Get st...","zh":"了解如何使用 Asciinema Demos 创建短小的、循环的终端录制，证明任务完成并帮助审查者快速理解更改","ja":"Asciinema Demos を使用して短いループ型ターミナルレコーディングを作成し、タスクの完了を証明し、レビュアーが変更を迅速に理解するのに役立てる方法について学びます","ko":"Asciinema Demos를 사용하여 짧고 반복되는 터미널 녹화를 생성하여 작업 완료를 증명하고審查자가 변경 사항을 빠르게 이해하는 데 도움이 되는 방법에 대해 알아보세요","es":"Aprende a crear demos de terminal con asciinema-demos para agentes de IA y mejora la comprensión de tus cambios","fr":"Découvrez comment créer des démos de terminal avec asciinema-demos pour les outils d''IA et améliorez la compréhension de vos modifications","de":"Erfahren Sie, wie Sie Terminal-Demos mit asciinema-demos für KI-Agents erstellen und das Verständnis Ihrer Änderungen verbessern","pt":"Aprenda a criar demos de terminal com asciinema para Ferramentas de IA. Descubra como gravar e verificar sessões de demo com o CLI","ru":"Создайте интерактивные демозаписи терминала с asciinema для ИИ Агентов. Узнайте, как записывать и проверять сессии демонстрации с помощью CLI","ar":"تعلم كيفية إنشاء عروض توضيحية للطرفية باستخدام asciinema لأدوات الذكاء الاصطناعي. اكتشف كيفية تسجيل وفرض التحقق من جلسات العرض التوضيحي مع CLI"},"definition":{"en":"asciinema-demos is a skill for creating terminal demo recordings that visually demonstrate completed work, producing 1-3 looping GIFs per session.","zh":"Asciinema Demos 是一种用于创建终端录制的工具，用于证明任务完成并帮助审查者快速理解更改","ja":"Asciinema Demos は、タスクの完了を証明し、レビュアーが変更を迅速に理解するためのターミナルレコーディングを作成するためのツールです","ko":"Asciinema Demos는 작업 완료를 증명하고 審查자가 변경 사항을 빠르게 이해하는 데 도움이 되는 터미널 녹화를 생성하는 도구입니다","es":"Asciinema-demos es una herramienta de línea de comandos para crear demos de terminal que demuestran el trabajo realizado","fr":"Asciinema-demos est un outil de ligne de commande pour créer des démos de terminal qui démontrent le travail effectué","de":"Asciinema-demos ist ein Kommandozeilen-Tool zum Erstellen von Terminal-Demos, die die durchgeführte Arbeit demonstrieren","pt":"Asciinema-demos é uma ferramenta de linha de comando para criar demos de terminal para Ferramentas de IA","ru":"Asciinema-demos - это инструмент командной строки для создания демонстрационных записей терминала для ИИ Агентов","ar":"Asciinema-demos هو أداة سطر أوامر لإنشاء عروض توضيحية للطرفية لأدوات الذكاء الاصطناعي"},"features":{"en":["Records terminal sessions with asciinema","Produces looping GIFs for demo purposes","Verifies recordings for accuracy and completeness","Iterates on demo sessions for refinement","Creates 1-3 recordings per session, each 5-20 seconds long","Utilizes demo and cleanup scripts for efficient workflow"],"zh":["创建短小的、循环的终端录制","使用 Asciinema 录制终端会话","生成 1-3 个录制文件，时长 5-20 秒","支持循环 GIF 格式","提供 demo 和 cleanup 脚本","支持录制验证和迭代"],"ja":["短いループ型ターミナルレコーディングを作成","Asciinema を使用してターミナルセッションをレコーディング","1-3 個のレコーディングファイルを生成、長さ 5-20 秒","ループ GIF 形式をサポート","デモとクリーンアップスクリプトを提供","レコーディングの検証とイテレーションをサポート"],"ko":["짧고 반복되는 터미널 녹화를 생성","Asciinema를 사용하여 터미널 세션 녹화","1-3개의 녹화 파일 생성, 길이 5-20초","반복 GIF 형식 지원","데모 및 클린업 스크립트 제공","녹화 검증 및 반복 지원"],"es":["Creación de demos de terminal con asciinema","Grabación de sesiones de demostración en formato GIF","Verificación y iteración de grabaciones","Planificación y escritura de scripts de demostración","Limpieza y preparación de la terminal para la grabación"],"fr":["Création de démos de terminal avec asciinema","Enregistrement de sessions de démonstration au format GIF","Vérification et itération d''enregistrements","Planification et écriture de scripts de démonstration","Nettoyage et préparation de la terminal pour l''enregistrement"],"de":["Erstellung von Terminal-Demos mit asciinema","Aufzeichnung von Demo-Sitzungen im GIF-Format","Überprüfung und Iteration von Aufzeichnungen","Planung und Erstellung von Demo-Skripten","Bereinigung und Vorbereitung der Terminal für die Aufzeichnung"],"pt":["Criação de gravações de demo de terminal com asciinema","Gravação e verificação de sessões de demo com o CLI","Suporte a 1-3 gravações por sessão de demo","Duração de gravação de 5-20 segundos por demo","Saída em formato GIF"],"ru":["Создание демонстрационных записей терминала с asciinema","Запись и проверка сессий демонстрации с помощью CLI","Поддержка 1-3 записей на одну сессию демонстрации","Продолжительность записи 5-20 секунд на одну демонстрацию","Вывод в формате GIF"],"ar":["إنشاء تسجيلات عرض توضيحي للطرفية باستخدام asciinema","تسجيل وفرض التحقق من جلسات العرض التوضيحي مع CLI","دعم 1-3 تسجيلات لكل جلسة عرض توضيحي","مدة التسجيل 5-20 ثانية لكل عرض توضيحي","الإخراج في تنسيق GIF"]},"keywords":{"en":["how to use asciinema-demos","asciinema-demos tutorial","creating terminal demos","asciinema-demos install guide","asciinema-demos vs terminal recorders","what is asciinema-demos","asciinema-demos setup","asciinema-demos alternative","asciinema-demos documentation"],"zh":["Asciinema Demos","终端录制","ターミナルレコーディング","CLI 工具","Asciinema","GIF 形式","demo 脚本","cleanup 脚本","录制验证","AIエージェント"],"ja":["Asciinema Demos","ターミナルレコーディング","CLI ツール","Asciinema","GIF 形式","デモスクリプト","クリーンアップスクリプト","レコーディングの検証","AIエージェント","ターミナルデモ"],"ko":["Asciinema Demos","터미널 녹화","CLI 도구","Asciinema","GIF 형식","데모 스크립트","클린업 스크립트","녹화 검증","AI 에이전트","터미널 데모"],"es":["asciinema-demos","agentes de IA","herramientas de IA","demos de terminal","grabación de terminal","CLI para agentes de IA","creación de demos","verificación de grabaciones"],"fr":["asciinema-demos","outils d''IA","agents d''IA","démos de terminal","enregistrement de terminal","CLI pour outils d''IA","création de démos","vérification d''enregistrements"],"de":["asciinema-demos","KI-Agents","KI-Tools","Terminal-Demos","Terminal-Aufzeichnung","CLI für KI-Agents","Erstellung von Demos","Überprüfung von Aufzeichnungen"],"pt":["asciinema-demos","Ferramentas de IA","demos de terminal","CLI","gravações de demo","verificação de sessões de demo","GIF","índice de desenvolvedores"],"ru":["asciinema-demos","ИИ Агенты","демонстрационные записи терминала","CLI","записи демонстрации","проверка сессий демонстрации","GIF","разработчиков"],"ar":["asciinema-demos","أدوات الذكاء الاصطناعي","تسجيلات عرض توضيحي للطرفية","CLI","تسجيلات عرض توضيحي","فرض التحقق من جلسات العرض التوضيحي","GIF","مطورين"]}},"owner":"imbue-ai","repo":"mng","repoPath":"imbue-ai/mng","stars":11,"forks":2,"updatedAt":"2026-03-04T00:30:16Z","topics":[],"category":"community","skillMd":{"name":"asciinema-demos","description":"Create 1-3 short asciinema demo recordings (5-20 seconds each) that demonstrate completed work. Use only when explicitly instructed to create demos.","bodyPreview":"# Creating Asciinema Demos\n\nThis skill provides guidelines for creating short, looping terminal demo recordings that visually demonstrate completed work. The demos serve as proof that a task was done correctly and help reviewers quickly understand what changed.\n\n## Overview\n\nEach demo session produces 1-3 recordings (each 5-20 seconds) as looping GIFs. The workflow is:\n\n1. Plan what to demo\n2. Write demo and cleanup scripts\n3. Record with asciinema\n4. Verify the recordings\n5. Iterate if needed\n6","body":"# Creating Asciinema Demos\n\nThis skill provides guidelines for creating short, looping terminal demo recordings that visually demonstrate completed work. The demos serve as proof that a task was done correctly and help reviewers quickly understand what changed.\n\n## Overview\n\nEach demo session produces 1-3 recordings (each 5-20 seconds) as looping GIFs. The workflow is:\n\n1. Plan what to demo\n2. Write demo and cleanup scripts\n3. Record with asciinema\n4. Verify the recordings\n5. Iterate if needed\n6. Convert to GIF and (optionally) upload to a PR\n\n## Prerequisites\n\nThe following tools must be available:\n\n- `asciinema` (terminal recorder) -- records .cast files\n- `agg` (asciinema gif generator) -- converts .cast to .gif\n- `python3` with `json` module (standard library) -- for .cast file verification\n\nIf they are not, simply make a note in the PR that the demos could not be generated, and which tools should be installed to enable them.\n\n## Step 1: Plan the Demos\n\nBefore recording anything, think carefully about what to demo. This is the most important step.\n\n**Ask yourself:**\n\n- What are the 1-3 most important things to show?\n- What would convince a reviewer that the task was completed correctly?\n- What is the shortest path to showing each thing?\n- How can I ensure that all resulting demo resources are always safely cleaned up by the demo script after each execution?\n\n**Common demo types:**\n\n| Scenario | What to show |\n|---|---|\n| New CLI command | Run the command with typical arguments, show the output |\n| Bug fix | Show the fixed behavior |\n| Data/config change | Show the data exists and has correct values (e.g., `cat`, `jq`, `grep`) and that the core dependent behavior works |\n| Performance improvement | Run a benchmark or timed command showing the improvement (and the necessary context to understand) |\n| New feature in existing command | Run the command exercising the new feature |\n| Refactor (no behavior change) | Show that the core dependent behavior(s) still work |\n\n**Guidelines:**\n\n- Each demo should be 5-20 seconds. Shorter is better.\n- Focus on the output that matters -- don''t show lengthy setup or irrelevant output.\n- If demonstrating data, use commands like `cat`, `head`, `jq`, `grep`, or `sqlite3` to show the relevant parts.\n- If the change is not directly visible in the CLI (e.g., internal refactor), demo the tests passing or show downstream effects.\n\n## Step 2: Write Demo and Cleanup Scripts\n\nFor each demo, create a bash script for that specific demo. Place them in a temporary location or in `.demos/scripts/`.\n\n**Template for a demo script:**\n\n```bash\n#!/usr/bin/env bash\n# Demo: Brief description of what this demonstrates\n\n# Optionally set up a clean prompt for the recording\nexport PS1=''$ ''\n\n# Add brief pauses between commands so the viewer can read the output\necho \"$ some-command --flag\"\nsome-command --flag\nsleep 1\n\necho \"\"\necho \"$ another-command\"\nanother-command\nsleep 1\n```\n\n**Important considerations for demo scripts:**\n\n### Handling commands that block or require input\n\nFor commands that would normally block waiting for input or run indefinitely:\n\n- Use `timeout` to limit execution time: `timeout 5 some-long-command`\n- Pipe input for interactive commands: `echo \"y\" | some-command`\n- Use `yes | head -1 |` for yes/no prompts\n- For commands that start background processes, run them and immediately show the result:\n  ```bash\n  some-command --background\n  sleep 2\n  show-status-command\n  ```\n\n### Simulating typed commands\n\nTo make the demo look natural (as if someone is typing), you can echo the command before running it:\n\n```bash\n# Show the command being \"typed\", then run it\necho ''$ mng list''\nmng list\nsleep 1\n```\n\nOr, for a more polished look, use a helper function that simulates typing:\n\n```bash\ntype_cmd() {\n    local cmd=\"$1\"\n    printf ''$ ''\n    for ((i=0; i<${#cmd}; i++)); do\n        printf ''%s'' \"${cmd:$i:1}\"\n        sleep 0.03\n    done\n    printf ''\\n''\n    eval \"$cmd\"\n}\n\ntype_cmd \"mng list\"\nsleep 1\n```\n\n### Keeping output clean\n\n- Set `export PS1=''$ ''` for a clean prompt\n- Redirect stderr if it would clutter the output: `command 2>/dev/null`\n- Use `head -n 20` or similar to truncate long output\n- Clear the screen between demos if needed: `clear`\n\n**Important considerations for cleanup scripts:**\n\n- The cleanup script *MUST* be run after running the demo\n- Be *very* careful with `rm` or any destructive commands! Always double-check that the script cannot accidentally delete important files or directories.\n- Name cleanup scripts like this: .demos/scripts/demo1_cleanup.sh\n\n## Step 3: Record\n\nUse the helper script `scripts/record_demo.sh` to record each demo:\n\n```bash\n./scripts/record_demo.sh <demo_script> <output_name> [options]\n```\n\n**Examples:**\n\n```bash\n# Basic recording\n./scripts/record_demo.sh .demos/scripts/demo1.sh feature-demo; .demos/scripts/demo1_cleanup.sh\n\n# Custom terminal size and speed\n./scripts/record_demo.sh .demos/scripts/demo1.sh feature-demo --cols 120 --rows 24 --speed 1.5; .demos/scripts/demo1_cleanup.sh\n\n# Recording without GIF conversion (for faster iteration)\n./scripts/record_demo.sh .demos/scripts/demo1.sh feature-demo --no-gif; .demos/scripts/demo1_cleanup.sh\n```\n\nThe script produces three files in `.demos/` (or the directory specified by `--out-dir`):\n\n- `<name>.cast` -- the asciinema recording\n- `<name>.gif` -- the GIF (unless `--no-gif`)\n- `<name>.txt` -- plain text dump of the recording output\n\n**Key options:**\n\n| Option | Default | Description |\n|---|---|---|\n| `--cols N` | 100 | Terminal width |\n| `--rows N` | 30 | Terminal height |\n| `--theme THEME` | monokai | GIF color theme |\n| `--font-size N` | 16 | Font size in pixels for GIF |\n| `--speed N` | 1 | Playback speed multiplier |\n| `--idle-limit N` | 2 | Max idle time between events (seconds) |\n| `--last-frame N` | 3 | How long the final frame displays (seconds) |\n| `--out-dir DIR` | .demos | Output directory |\n| `--no-gif` | | Skip GIF conversion (faster for iteration) |\n| `--no-loop` | | Disable GIF looping |\n\n## Step 4: Verify\n\nThis is critical. Since you cannot watch the GIF, you must verify the recording by reading the text dump.\n\n**Read the `.txt` file** to confirm:\n\n1. The expected commands appear in the output\n2. The expected output/results are visible\n3. There are no error messages or unexpected output\n4. The flow makes sense (commands appear in the right order)\n\n```bash\ncat .demos/feature-demo.txt\n```\n\nYou can also inspect the `.cast` file directly to check timing:\n\n```bash\n# Check the total duration (time of last event)\ntail -1 .demos/feature-demo.cast\n\n# Check all events\ncat .demos/feature-demo.cast\n```\n\n**Verification checklist:**\n\n- [ ] All expected commands are present in the output\n- [ ] All expected results/data are visible\n- [ ] No error messages or tracebacks\n- [ ] Recording duration is 5-20 seconds (check the timestamp of the last event in the .cast file)\n- [ ] Terminal size is appropriate for the content (no wrapping/truncation issues)\n\n## Step 5: Iterate\n\nIf the recording does not look right:\n\n1. Identify the problem from the `.txt` dump\n2. Fix the demo script\n3. Re-record (use `--no-gif` while iterating for speed)\n4. Verify again\n5. Once satisfied, do a final recording with GIF conversion\n\nCommon problems and fixes:\n\n| Problem | Fix |\n|---|---|\n| Output is truncated/wrapped | Increase `--cols` |\n| Recording is too long | Remove unnecessary `sleep` calls, use `--speed 2` |\n| Recording is too short | Add `sleep` calls between commands |\n| Command produced an error | Fix the demo script or the underlying issue |\n| Too much output | Use `head`, `tail`, or `grep` to filter |\n| Interactive command blocked | Use `timeout`, pipe input, or mock the interaction |\n\n## Step 6: Upload to PR\n\nIf the demos should be attached to a GitHub PR, you need to make the GIF accessible via URL.\n\n**NEVER try to commit files the demo files, especially not the GIFs**.\n\n**Instead, upload via GitHub''s attachment API**\n\nGitHub allows uploading images by posting them as assets. This avoids committing binary files to the repo. Use `gh` to create a release asset or attach to an issue/PR comment via the API.\n\n## Tips\n\n- **Start with `--no-gif`** while iterating on the demo script. Only convert to GIF once you are satisfied with the `.txt` output.\n- **Keep demos focused.** One concept per demo. If you need to show multiple things, make multiple short demos rather than one long one.\n- **Use `--speed 1.5` or `--speed 2`** if the demo has natural pauses that would make it feel slow.\n- **For data verification demos**, use colorized output when possible (e.g., `jq` with colors, `grep --color`). This makes the GIF more readable.\n- **Always run the cleanup script** after recording to ensure no leftover state could affect future runs or the user''s environment.\n- **Output directory**: The default `.demos/` directory is gitignored. **NEVER commit GIFs!**\n"},"lastSynced":"2026-03-06T06:46:12.683Z","agentAnalysis":{"suitability":{"en":"Perfect for CLI Agents needing advanced terminal demo recording capabilities.","zh":"适用于需要高级终端演示录制功能的CLI代理。","ja":"CLIエージェントが高度なターミナルデモレコーディング機能を必要とする場合に最適です。","ko":"고급 터미널 데모 녹화 기능이 필요한 CLI 에이전트에 적합합니다.","es":"Perfecto para agentes de CLI que necesitan capacidades de grabación de demostraciones de terminal avanzadas.","fr":"Parfait pour les agents CLI qui ont besoin de capacités de démo de terminal avancées.","de":"Perfekt für CLI-Agents, die erweiterte Terminal-Demo-Aufnahmefunktionen benötigen.","pt":"Perfeito para Agentes CLI que precisam de capacidades avançadas de gravação de demonstrações de terminal.","ru":"Идеально для агентов CLI, которым требуются расширенные возможности записи демонстраций терминала.","ar":"مثالي للوكلاء CLI الذين يحتاجون إلى إمكانيات تسجيل عروض توضيحية متقدمة عبر الطرفية."},"recommendation":{"en":"Empowers agents to create short, looping terminal demo recordings as GIFs using asciinema, facilitating quick review processes and demonstrating completed work through visual verification and cleanup scripts.","zh":"使代理能够使用asciinema创建短循环终端演示录制作为GIF，促进快速审查流程，并通过可视化验证和清理脚本展示已完成的工作。","ja":"エージェントがasciinemaを使用して短いループターミナルデモレコーディングを作成し、GIFとして保存できるようにし、迅速なレビュー処理と視覚的な検証およびクリーンアップスクリプトによる完了作業の実証を可能にします。","ko":"에이전트가 asciinema를 사용하여 짧은 루프 터미널 데모 녹화를 GIF로 생성할 수 있도록 하여 빠른 검토 프로세스를促進하고 시각적 확인 및 클린업 스크립트를 통해 완료된 작업을示します.","es":"Habilita a los agentes a crear grabaciones de demostraciones de terminal cortas y en bucle como GIF utilizando asciinema, lo que facilita los procesos de revisión rápida y demuestra el trabajo completado a través de verificación visual y scripts de limpieza.","fr":"Permet aux agents de créer des enregistrements de démo de terminal courts et en boucle sous forme de GIF à l''aide d''asciinema, ce qui facilite les processus de révision rapide et démontre le travail terminé par le biais d''une vérification visuelle et de scripts de nettoyage.","de":"Ermächtigt Agenten, kurze, sich wiederholende Terminal-Demo-Aufnahmen als GIFs mit asciinema zu erstellen, was schnelle Überprüfungsprozesse erleichtert und die abgeschlossene Arbeit durch visuelle Verifizierung und Bereinigungsskripte demonstriert.","pt":"Habilita os agentes a criar gravações de demonstrações de terminal curtas e em loop como GIFs usando asciinema, facilitando processos de revisão rápidos e demonstrando trabalho concluído por meio de verificação visual e scripts de limpeza.","ru":"Наделяет агентов возможностью создавать короткие, циклические записи демонстраций терминала в формате GIF с помощью asciinema, что облегчает быстрые процессы проверки и демонстрирует выполненную работу посредством визуальной верификации и очистки скриптов.","ar":"يمنح الوكلاء القدرة على إنشاء تسجيلات عرض توضيحي قصيرة ومكررة عبر الطرفية كملفات GIF باستخدام asciinema، مما يسهل عمليات المراجعة السريعة ويوضح العمل المكتمل من خلال التحقق المرئي وبرامج تنظيف النص البرمجي."},"useCases":{"en":["Creating terminal demo recordings for project showcases","Generating looping GIFs for code change reviews","Recording and verifying terminal-based workflows"],"zh":["为项目展示创建终端演示录制","为代码更改审查生成循环GIF","记录和验证基于终端的工作流"],"ja":["プロジェクトの紹介用にターミナルデモレコーディングを作成する","コード変更レビュー用にループGIFを生成する","ターミナルベースのワークフローを記録して検証する"],"ko":["프로젝트展示용 터미널 데모 녹화 생성","코드 변경 리뷰용 루프 GIF 생성","터미널 기반 워크플로우 기록 및 확인"],"es":["Creación de grabaciones de demostraciones de terminal para presentaciones de proyectos","Generación de GIF en bucle para revisiones de cambios de código","Grabación y verificación de flujos de trabajo basados en terminal"],"fr":["Création d''enregistrements de démo de terminal pour les présentations de projets","Génération de GIF en boucle pour les examens de modifications de code","Enregistrement et vérification des flux de travail basés sur le terminal"],"de":["Erstellung von Terminal-Demo-Aufnahmen für Projektpräsentationen","Erzeugung von sich wiederholenden GIFs für Code-Änderungs-Überprüfungen","Aufnahme und Überprüfung von terminalbasierten Workflows"],"pt":["Criação de gravações de demonstrações de terminal para mostras de projetos","Geração de GIFs em loop para revisões de alterações de código","Gravação e verificação de fluxos de trabalho baseados em terminal"],"ru":["Создание записей демонстраций терминала для показа проектов","Генерация циклических GIF для проверки изменений кода","Запись и верификация рабочих процессов на основе терминала"],"ar":["إنشاء تسجيلات عرض توضيحي عبر الطرفية لأمثلة المشاريع","توليد GIFs متكررة لمراجعة تغييرات الشفرة البرمجية","تسجيل وتحقق من سير العمل القائم على الطرفية"]},"limitations":{"en":["Requires asciinema installation","Limited to terminal-based demonstrations","Recording length limited to 5-20 seconds"],"zh":["需要安装asciinema","仅限终端演示","录制长度限制在5-20秒"],"ja":["asciinemaのインストールが必要","ターミナルベースのデモに限定される","レコーディングの長さが5〜20秒に制限される"],"ko":["asciinema 설치 필요","터미널 기반 데모에만 제한","녹화 길이 5〜20초로 제한"],"es":["Requiere la instalación de asciinema","Limitado a demostraciones basadas en terminal","La duración de la grabación está limitada a 5-20 segundos"],"fr":["Nécessite l''installation d''asciinema","Limité aux démonstrations basées sur le terminal","La durée de l''enregistrement est limitée à 5-20 secondes"],"de":["Erfordert die Installation von asciinema","Begrenzt auf terminalbasierte Demonstrationen","Die Aufnahmelänge ist auf 5-20 Sekunden begrenzt"],"pt":["Requer instalação do asciinema","Limitado a demonstrações baseadas em terminal","Duração da gravação limitada a 5-20 segundos"],"ru":["Требуется установка asciinema","Ограничен демонстрациями на основе терминала","Длительность записи ограничена 5-20 секундами"],"ar":["يتطلب تثبيت asciinema","محدود بالعروض التوضيحية القائمة على الطرفية","مدة التسجيل محدودة ب 5-20 ثانية"]},"version":4},"contentHash":"9047933f79a5bab80985a589b1f0ecab9ec1267c4bc08dd949732d8e27ae1e05","qualityScore":45}');
