INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('imbue-ai/mng/asciinema-demos', 'asciinema-demos', 'imbue-ai', 'mng', 'community', 'asciinema-demos imbue-ai mng community asciinema-demos is a CLI for managing agents that creates short, looping terminal demo recordings. It helps developers demonstrate completed work and facilitates quick review processes. Asciinema Demos 提供创建短小的、循环的终端录制的指南，用于证明任务完成并帮助审查者快速理解更改 Asciinema Demos は、タスクの完了を証明し、レビュアーが変更を迅速に理解するのに役立つ短いループ型ターミナルレコーディングを作成するためのガイドラインを提供します Asciinema Demos는 작업 완료를 증명하고 審查자가 변경 사항을 빠르게 이해하는 데 도움이 되는 짧고 반복되는 터미널 녹화를 생성하는 가이드를 제공합니다 Asciinema-demos es una CLI para gestionar agentes de IA y crear demos de terminal Asciinema-demos est une CLI pour gérer les outils d''IA et créer des démos de terminal Asciinema-demos ist eine CLI zur Verwaltung von KI-Agents und Erstellung von Terminal-Demos O asciinema-demos é uma ferramenta para criar gravações de demo de terminal para Ferramentas de IA. Ele permite gravar e verificar sessões de demo com o CLI Asciinema-demos - это инструмент для создания демонстрационных записей терминала для ИИ Агентов. Он позволяет записывать и проверять сессии демонстрации с помощью CLI Asciinema-demos هو أداة لإنشاء تسجيلات عرض توضيحي للطرفية لأدوات الذكاء الاصطناعي. يسمح بتسجيل وفرض التحقق من جلسات العرض التوضيحي مع CLI how to use asciinema-demos asciinema-demos tutorial creating terminal demos asciinema-demos install guide asciinema-demos vs terminal recorders what is asciinema-demos asciinema-demos setup asciinema-demos alternative asciinema-demos documentation Asciinema Demos 终端录制 ターミナルレコーディング CLI 工具 Asciinema GIF 形式 demo 脚本 cleanup 脚本 录制验证 AIエージェント Records terminal sessions with asciinema Produces looping GIFs for demo purposes Verifies recordings for accuracy and completeness Iterates on demo sessions for refinement Creates 1-3 recordings per session, each 5-20 seconds long Utilizes demo and cleanup scripts for efficient workflow asciinema-demos is a skill for creating terminal demo recordings that visually demonstrate completed work, producing 1-3 looping GIFs per session.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('orient-bot/orient/plan-executor', 'community', 'orient-bot', 'orient', 'orient-bot/orient', 'plan-executor', 8, 0, 45, '2026-02-11T20:29:58Z', '2026-03-06T06:50:14.234Z', '36415a9517621cc5bc89c07c66c8777348c01739b385eb16b49f065d2017d1e6', '{"id":"orient-bot/orient/plan-executor","name":"plan-executor","description":{"en":"The plan-executor skill automates implementation plans with two-stage review and verification. It benefits developers working with worktrees created with the --plan flag and multi-task implementations.","zh":"Plan Executor 是一个执行实施计划的 AI Agent，具有两阶段审查和批量检查点的能力","ja":"Plan Executor は、2ステージレビューとバッチチェックポイントを備えた実装計画の実行用 AI Agent です","ko":"Plan Executor는 2단계 검토 및 배치 체크포인트를 갖춘 구현 계획을 실행하는 AI 에이전트입니다","es":"El plan-executor es una habilidad que ejecuta planes de implementación con revisión y verificación en dos etapas, garantizando la calidad del código y la conformidad con las especificaciones","fr":"Le plan-executor est une compétence qui exécute des plans d''implémentation avec révision et vérification en deux étapes, garantissant la qualité du code et la conformité aux spécifications","de":"Der plan-executor ist eine Fähigkeit, die Implementierungspläne mit Überprüfung und Verifizierung in zwei Stufen ausführt, um die Codequalität und die Konformität mit den Spezifikationen sicherzustellen","pt":"O Plan Executor é uma ferramenta de AI que executa planos de implementação com revisão em duas etapas e verificação em batch","ru":"Плановый Executor - это инструмент ИИ, который выполняет планы реализации с двухэтапным обзором и пакетной проверкой","ar":"Plan Executor هو أداة ذكاء اصطناعي تقوم بتنفيذ خطط التنفيذ مع استعراض درجتين و_verification بالدفعة"},"seo":{"title":{"en":"plan-executor: Two-Stage Review Setup Guide | AI Agent Skill","zh":"Plan Executor 设置指南：两阶段审查和批量检查点","ja":"Plan Executor ベストプラクティス：2ステージレビューとバッチチェックポイント","ko":"Plan Executor 사용법: 2단계 검토 및 배치 체크포인트","es":"Guía de Configuración del plan-executor: Ejecución de Pla...","fr":"Guide de Configuration du plan-executor : Exécution de Pl...","de":"Konfigurationsleitfaden für plan-executor: Ausführung von...","pt":"Guia de Configuração do Plan Executor - Ferramentas de AI","ru":"Настройка Планового Executorа - ИИ Агенты","ar":"دليل إعداد Plan Executor - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how plan-executor streamlines implementation plans with automated verification and batch checkpoints. Learn how to apply this skill for efficient mu...","zh":"了解 Plan Executor 的核心原则，包括证据优先和两阶段审查，实现高效的实施计划执行","ja":"Plan Executor のコアプリンシプルを学び、効率的な実装計画の実行を実現する","ko":"Plan Executor의 핵심 원칙을 알아보고, 효율적인 구현 계획을 실행하는 방법을 배우세요","es":"Aprende a configurar y utilizar el plan-executor para ejecutar planes de implementación con revisión y verificación en dos etapas","fr":"Découvrez comment configurer et utiliser le plan-executor pour exécuter des plans d''implémentation avec révision et vérification en deux étapes","de":"Erfahren Sie, wie Sie den plan-executor konfigurieren und verwenden, um Implementierungspläne mit Überprüfung und Verifizierung in zwei Stufen auszuführen","pt":"Aprenda a configurar o Plan Executor para executar planos de implementação com revisão em duas etapas e verificação em batch","ru":"Узнайте, как настроить Планового Executorа для выполнения планов реализации с двухэтапным обзором и пакетной проверкой","ar":"تعرف على كيفية إعداد Plan Executor لتنفيذ خطط التنفيذ مع استعراض درجتين و_verification بالدفعة"},"definition":{"en":"plan-executor is a skill that executes implementation plans with two-stage review, verification, and batch checkpoints for efficient multi-task execution.","zh":"Plan Executor 是一种 AI Agent，用于执行实施计划，具有证据优先和两阶段审查的核心原则","ja":"Plan Executor は、実装計画を実行する AI Agent で、証拠優先と 2 ステージレビューのコアプリンシプルを備えています","ko":"Plan Executor는 구현 계획을 실행하는 AI 에이전트로, 증거 우선 및 2단계 검토의 핵심 원칙을 갖추고 있습니다","es":"El plan-executor es una habilidad de la plataforma Orient - AI Agent que ejecuta planes de implementación con revisión y verificación","fr":"Le plan-executor est une compétence de la plateforme Orient - AI Agent qui exécute des plans d''implémentation avec révision et vérification","de":"Der plan-executor ist eine Fähigkeit der Plattform Orient - AI Agent, die Implementierungspläne mit Überprüfung und Verifizierung ausführt","pt":"O Plan Executor é uma ferramenta de AI que executa planos de implementação com revisão em duas etapas","ru":"Плановый Executor - это инструмент ИИ, который выполняет планы реализации","ar":"Plan Executor هو أداة ذكاء اصطناعي تقوم بتنفيذ خطط التنفيذ"},"features":{"en":["Executes implementation plans with two-stage review and verification","Automatically applies to worktrees created with the --plan flag","Supports multi-task implementations with batch checkpoints","Verifies spec compliance before code quality review","Requires evidence before claiming completion"],"zh":["两阶段审查：规范合规性和代码质量","批量检查点：确保实施计划的完整性","证据优先：验证输出作为完成的依据","支持多任务实施：高效地执行复杂的实施计划"],"ja":["2ステージレビュー：仕様の準拠とコード品質","バッチチェックポイント：実装計画の完全性を確保","証拠優先：検証出力が完了の根拠となる","マルチタスク実装のサポート：複雑な実装計画を効率的に実行"],"ko":["2단계 검토: 규격 준수 및 코드 품질","배치 체크포인트: 구현 계획의 완전성을 보장","증거 우선: 검증 출력이 완료의 근거가 됨","다중 작업 구현 지원: 복잡한 구현 계획을 효율적으로 실행"],"es":["Ejecución de planes de implementación con revisión y verificación en dos etapas","Verificación de la conformidad con las especificaciones antes de la revisión del código","Utilización de la bandera --plan para crear un árbol de trabajo","Referencia a un archivo de plan en docs/plans/...","Ejecución de implementaciones multi-tarea","Garantía de calidad del código y conformidad con las especificaciones"],"fr":["Exécution de plans d''implémentation avec révision et vérification en deux étapes","Vérification de la conformité aux spécifications avant la révision du code","Utilisation du drapeau --plan pour créer un arbre de travail","Référence à un fichier de plan dans docs/plans/...","Exécution d''implémentations multi-tâches","Garantie de la qualité du code et de la conformité aux spécifications"],"de":["Ausführung von Implementierungsplänen mit Überprüfung und Verifizierung in zwei Stufen","Überprüfung der Konformität mit den Spezifikationen vor der Code-Überprüfung","Verwendung der Flagge --plan zum Erstellen eines Arbeitsverzeichnisses","Verweis auf eine Plan-Datei in docs/plans/...","Ausführung von Implementierungen mit mehreren Aufgaben","Sicherstellung der Codequalität und der Konformität mit den Spezifikationen"],"pt":["Revisão em duas etapas para garantir a conformidade com as especificações","Verificação em batch para garantir a qualidade do código","Suporte a implementações mult-tarefa","Integração com o CLI para execução de planos","Suporte a arquivos de plano no diretório docs/plans/"],"ru":["Двухэтапный обзор для обеспечения соответствия спецификациям","Пакетная проверка для обеспечения качества кода","Поддержка многозадачных реализаций","Интеграция с CLI для выполнения планов","Поддержка файлов планов в директории docs/plans/"],"ar":["استعراض درجتين لضمان مطابقة المواصفات","_verification بالدفعة لضمان جودة الكود","دعم التنفيذ متعدد المهام","التكامل مع CLI لتنفيذ الخطط","دعم ملفات الخطة في دليل docs/plans/"]},"keywords":{"en":["plan-executor setup guide","how to use plan-executor","what is plan-executor","plan-executor alternative","plan-executor vs implementation plans","plan-executor install","two-stage review process"],"zh":["AI Agent","实施计划","两阶段审查","批量检查点","证据优先","多任务实施","Plan Executor","AI工具"],"ja":["AIエージェント","実装計画","2ステージレビュー","バッチチェックポイント","証拠優先","マルチタスク実装","Plan Executor","AIツール"],"ko":["AI 에이전트","구현 계획","2단계 검토","배치 체크포인트","증거 우선","다중 작업 구현","Plan Executor","AI 도구"],"es":["plan-executor","Herramientas de AI","Agentes de AI","Ejecución de planes de implementación","Revisión y verificación de código","Conformidad con especificaciones","Implementaciones multi-tarea","Calidad del código","Desarrollo de software con AI"],"fr":["plan-executor","Outils d''IA","Agents d''IA","Exécution de plans d''implémentation","Révision et vérification de code","Conformité aux spécifications","Implémentations multi-tâches","Qualité du code","Développement de logiciels avec IA"],"de":["plan-executor","KI-Tools","KI-Agents","Ausführung von Implementierungsplänen","Überprüfung und Verifizierung von Code","Konformität mit Spezifikationen","Implementierungen mit mehreren Aufgaben","Codequalität","Software-Entwicklung mit KI"],"pt":["Plan Executor","Ferramentas de AI","Revisão em duas etapas","Verificação em batch","Implementações mult-tarefa","CLI","Arquivos de plano","docs/plans/","Desenvolvimento de software"],"ru":["Плановый Executor","ИИ Агенты","Двухэтапный обзор","Пакетная проверка","Многозадачные реализации","CLI","Файлы планов","docs/plans/","Разработка программного обеспечения"],"ar":["Plan Executor","أدوات الذكاء الاصطناعي","استعراض درجتين","_verification بالدفعة","تنفيذ متعدد المهام","CLI","ملفات الخطة","docs/plans/","تطوير البرمجيات"]}},"owner":"orient-bot","repo":"orient","repoPath":"orient-bot/orient","stars":8,"forks":0,"updatedAt":"2026-02-11T20:29:58Z","topics":[],"category":"community","skillMd":{"name":"plan-executor","description":"Execute implementation plans created by /discover. Use this skill when working in a worktree with a --plan flag, when you need to execute tasks from a docs/plans/*.md file, or when implementing a multi-task feature systematically.","bodyPreview":"# Plan Executor\n\nExecute implementation plans with two-stage review, verification, and batch checkpoints.\n\n## When This Skill Applies\n\nThis skill automatically applies when:\n\n- You''re in a worktree created with `--plan` flag\n- Your goal references a plan file at `docs/plans/...`\n- You''re executing a multi-task implementation\n\n## Core Principles\n\n1. **Evidence before claims** - Never claim completion without verification output\n2. **Two-stage review** - Spec compliance first, then code quality\n3.","body":"# Plan Executor\n\nExecute implementation plans with two-stage review, verification, and batch checkpoints.\n\n## When This Skill Applies\n\nThis skill automatically applies when:\n\n- You''re in a worktree created with `--plan` flag\n- Your goal references a plan file at `docs/plans/...`\n- You''re executing a multi-task implementation\n\n## Core Principles\n\n1. **Evidence before claims** - Never claim completion without verification output\n2. **Two-stage review** - Spec compliance first, then code quality\n3. **Batch execution** - Execute 3 tasks, checkpoint, continue\n4. **Fresh context per task** - For parallel execution, use separate subagents\n\n---\n\n## Execution Flow\n\n### Phase 1: Load and Review Plan\n\n```\n1. Read the plan file completely\n2. Extract all tasks with their:\n   - Files to create/modify\n   - Steps to follow\n   - Verification commands\n   - Dependencies\n3. Create mental model of dependency graph\n4. Identify independent vs dependent tasks\n5. If concerns about the plan, raise with user BEFORE starting\n```\n\n### Phase 2: Execute Tasks\n\n**For 1-3 tasks:** Execute sequentially yourself\n**For 4+ independent tasks:** Consider parallel subagents\n\n#### Per Task Execution\n\n```\n1. Mark task as in_progress (use TaskUpdate)\n2. Follow each step exactly as written\n3. Run verification commands, capture output\n4. Perform two-stage review (see below)\n5. Mark task as completed only with evidence\n6. Commit the work\n```\n\n### Phase 3: Batch Checkpoints\n\nAfter every 3 tasks (or all independent tasks):\n\n```\nReport to user:\n- Tasks completed with evidence\n- Issues encountered\n- \"Ready for feedback\"\n\nWait for user confirmation before continuing.\n```\n\n### Phase 4: Dependent Tasks\n\nAfter independent tasks complete:\n\n1. Identify newly unblocked tasks\n2. Execute next batch\n3. Repeat until all tasks done\n\n---\n\n## Two-Stage Review\n\n### Stage 1: Spec Compliance Review\n\n**Question:** Does the code match the plan exactly?\n\n```\nCheck:\n- [ ] All required files created at exact paths\n- [ ] All modifications match spec\n- [ ] Nothing missing from requirements\n- [ ] Nothing extra added (YAGNI)\n- [ ] Tests cover specified behaviors\n```\n\n**If issues found:**\n\n- Fix the gaps\n- Re-review\n- Don''t proceed until spec-compliant\n\n### Stage 2: Code Quality Review\n\n**Question:** Is the implementation well-built?\n\n```\nCheck:\n- [ ] Code follows project patterns\n- [ ] Tests are meaningful (not just coverage)\n- [ ] No obvious bugs or edge cases missed\n- [ ] Error handling appropriate\n- [ ] No code smells\n```\n\n**If issues found:**\n\n- Fix the issues\n- Re-review\n- Don''t proceed until quality approved\n\n---\n\n## Verification Before Completion\n\n### The Iron Law\n\n```\nNO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE\n```\n\n### Required Evidence\n\n| Claim            | Required Evidence                |\n| ---------------- | -------------------------------- |\n| \"Tests pass\"     | Actual test output: `X/Y pass`   |\n| \"Build succeeds\" | Build output: `exit code 0`      |\n| \"Linter clean\"   | Linter output: `0 errors`        |\n| \"Task complete\"  | All verification commands output |\n\n### Bad vs Good\n\n```\n❌ BAD: \"The tests should pass now\"\n❌ BAD: \"I believe this is working\"\n❌ BAD: \"Task completed successfully\"\n\n✅ GOOD: \"Tests pass (output: 12/12 pass, 0 failures)\"\n✅ GOOD: \"Build succeeded (exit code 0, no errors)\"\n✅ GOOD: \"Task complete. Evidence:\n         - Tests: 12/12 pass\n         - Lint: 0 errors\n         - Build: success\"\n```\n\n### When to Verify\n\n- Before claiming any task is done\n- Before moving to next task\n- Before reporting to user\n- Before committing\n\n---\n\n## Parallel Execution with Subagents\n\nWhen you have 4+ independent tasks, use parallel subagents:\n\n### Launching Subagents\n\n```javascript\n// Launch multiple Task tools in a SINGLE message\nTask({\n  description: ''Implement Task 1'',\n  prompt: `You are implementing Task 1 from the plan.\n\nTask details:\n${task1Content}\n\nRequirements:\n1. Follow each step exactly\n2. Run all verification commands\n3. Report actual output, not assumptions\n4. Commit when complete\n\nWhen done, report:\n- Files created/modified\n- Verification output (actual)\n- Any issues encountered`,\n  subagent_type: ''general-purpose'',\n});\n\n// In the SAME message, launch Task 2, 3, etc.\n```\n\n### Collecting Results\n\nAfter subagents complete:\n\n1. Review each result\n2. Verify the evidence provided\n3. If subagent claimed success without evidence, re-verify yourself\n4. Report consolidated results to user\n\n### Don''t Trust Blindly\n\n```\n❌ Subagent: \"Task completed successfully\"\n   You: \"Great, moving on\"\n\n✅ Subagent: \"Task completed. Tests: 5/5 pass\"\n   You: [Verify the claim by running tests yourself if suspicious]\n   You: \"Confirmed, Task 1 complete with 5/5 tests passing\"\n```\n\n---\n\n## When to Stop and Ask\n\n**STOP immediately when:**\n\n- Verification fails repeatedly\n- Plan has gaps or unclear instructions\n- Dependencies aren''t actually met\n- You''re unsure about an approach\n\n**Don''t:**\n\n- Guess when confused\n- Force through blockers\n- Skip verification\n- Proceed with failing tests\n\n---\n\n## Example Execution\n\n```\nAgent: I''m executing the plan at docs/plans/2026-02-01-webhooks.md\n\n[Reads plan, extracts 5 tasks]\n\nTask 1 (independent): WebhookConfig model\nTask 2 (independent): WebhookDelivery service\nTask 3 (independent): API endpoints\nTask 4 (depends on 1,2): Integration\nTask 5 (depends on 4): E2E tests\n\nStarting with independent tasks 1-3...\n\n---\n\nTask 1: WebhookConfig model\n[Following steps from plan]\n1. Writing failing test...\n2. Running: pnpm test packages/core --grep WebhookConfig\n   Output: FAIL - WebhookConfig is not defined\n3. Creating model...\n4. Running: pnpm test packages/core --grep WebhookConfig\n   Output: PASS - 3/3 tests pass\n\nSpec compliance review:\n✅ All files created at specified paths\n✅ Model matches spec\n✅ Tests cover required behaviors\n✅ Nothing extra added\n\nCode quality review:\n✅ Follows project patterns\n✅ Tests are meaningful\n✅ No obvious issues\n\nTask 1 complete.\nEvidence: Tests pass (3/3), files created at packages/core/src/models/webhook-config.ts\n[Commit: \"feat: add WebhookConfig model\"]\n\n---\n\n[Similar for Tasks 2, 3]\n\n---\n\nBatch checkpoint: Tasks 1-3 complete\n\nSummary:\n- Task 1: WebhookConfig model ✅ (3/3 tests)\n- Task 2: WebhookDelivery service ✅ (5/5 tests)\n- Task 3: API endpoints ✅ (4/4 tests)\n\nAll independent tasks verified and committed.\n\nReady for feedback. Should I proceed with Task 4 (Integration)?\n```\n\n---\n\n## Integration with Workflow\n\n```\n/discover (main branch)\n    │\n    ├── Creates plan at docs/plans/YYYY-MM-DD-feature.md\n    │\n    └── Creates worktree with --plan flag\n            │\n            └── plan-executor (this skill)\n                    │\n                    ├── Execute tasks with verification\n                    ├── Two-stage review\n                    ├── Batch checkpoints\n                    │\n                    └── Complete with evidence\n```\n\n---\n\n## Anti-Patterns\n\n**Don''t:**\n\n- Claim completion without running verification\n- Trust subagent \"success\" reports blindly\n- Skip spec compliance review\n- Move to next task with failing tests\n- Guess when plan is unclear\n- Add features not in the plan (YAGNI)\n\n**Do:**\n\n- Run every verification command\n- Capture and report actual output\n- Stop when blocked\n- Ask for clarification when needed\n- Follow the plan exactly\n"},"lastSynced":"2026-03-06T06:50:14.234Z","agentAnalysis":{"suitability":{"en":"Essential for Development Agents implementing complex multi-task plans with automated verification workflows.","zh":"适用于开发代理实现复杂的多任务计划，具有自动化验证工作流程的功能。","ja":"複雑なマルチタスクプランを実装し、自動化された検証ワークフローを使用する開発エージェントに不可欠です。","ko":"복잡한 멀티 태스크 계획을 구현하고 자동화된 검증 워크 플로를 사용하는 개발 에이전트에 필수적입니다.","es":"Esencial para los Agentes de Desarrollo que implementan planes de tarea múltiple complejos con flujos de trabajo de verificación automatizados.","fr":"Essentiel pour les Agents de Développement mettant en œuvre des plans de tâches multiples complexes avec des flux de travail de vérification automatisés.","de":"Wesentlich für Entwicklungssagenten, die komplexe Mehrfachaufgabenpläne mit automatisierten Überprüfungsworkflows implementieren.","pt":"Essencial para Agentes de Desenvolvimento que implementam planos de tarefas complexas com fluxos de trabalho de verificação automatizados.","ru":"Необходим для Разработчиков-агентов, реализующих сложные многоэтапные планы с автоматизированными рабочими процессами верификации.","ar":"ضروري للموكلين النموزجيين الذين ينفذون خطط عمل متعددة المهام مع تدفقات العمل الآلية للتحقق"},"recommendation":{"en":"Automates two-stage review and verification of implementation plans, ensuring evidence-based completion claims and batch checkpoint management for worktrees created with --plan flag.","zh":"自动执行两阶段审查和验证实施计划，确保基于证据的完成声明和为使用 --plan 标志创建的工作树批次检查点管理。","ja":"実装計画の2段階のレビューと検証を自動化し、証拠に基づく完了主張と、--plan フラグで作成されたワークツリーのバッチチェックポイント管理を保証します。","ko":"구현 계획의 2단계 검토 및 검증을 자동화하여 증거 기반 완료 주장 및 --plan 플래그로 생성 된 워크 트리의 배치 체크 포인트 관리를 보장합니다.","es":"Automatiza la revisión y verificación de dos etapas de los planes de implementación, garantizando la finalización de las reclamaciones basadas en la evidencia y la gestión de puntos de control por lotes para los worktrees creados con la bandera --plan.","fr":"Automatise la revue et la vérification en deux étapes des plans de mise en œuvre, garantissant l''achèvement des réclamations fondées sur des preuves et la gestion des points de contrôle par lots pour les worktrees créés avec le drapeau --plan.","de":"Automatisiert die zweistufige Überprüfung und Verifizierung von Implementierungsplänen, sicherstellend, dass die auf Beweisen basierenden Fertigstellungsansprüche und die Batch-Kontrollpunkte für mit der --plan-Flag erstellten Worktrees gemanagt werden.","pt":"Automatiza a revisão e verificação em duas etapas de planos de implementação, garantindo a conclusão com base em evidências e gerenciamento de pontos de verificação em lotes para worktrees criados com a flag --plan.","ru":"Автоматизирует двухэтапный обзор и верификацию планов реализации, обеспечивая завершение на основе доказательств и управление контрольными точками пакетов для worktrees, созданных с флагом --plan.","ar":"يعمل автоматиًا على استعراض ومراجعة خطط التنفيذ على مرحلتين، مما يضمن إكمالها استنادًا إلى الأدلة وإدارة نقاط التحقق المجمّعة لأشجار العمل التي تم إنشاؤها بالعلم --plan."},"useCases":{"en":["Executing multi-task implementation plans","Performing spec compliance verification","Conducting code quality reviews","Managing batch checkpoints in plan-based worktrees"],"zh":["执行多任务实施计划","执行规格符合性验证","进行代码质量审查","管理基于计划的工作树中的批次检查点"],"ja":["マルチタスク実装計画の実行","仕様の準拠検証の実行","コード品質レビューの実行","プランベースのワークツリーにおけるバッチチェックポイントの管理"],"ko":["멀티 태스크 구현 계획의 실행","사양 준수驗證의 수행","코드 품질 리뷰의 수행","계획 기반 워크 트리의 배치 체크 포인트 관리"],"es":["Ejecutar planes de implementación de varias tareas","Realizar verificación de cumplimiento de especificaciones","Realizar revisiones de calidad de código","Gestionar puntos de control por lotes en worktrees basados en planes"],"fr":["Exécuter des plans de mise en œuvre de plusieurs tâches","Effectuer une vérification de conformité aux spécifications","Effectuer des examens de qualité de code","Gérer les points de contrôle par lots dans les worktrees créés à partir de plans"],"de":["Ausführen von Implementierungsplänen mit mehreren Aufgaben","Durchführen von Spezifikationskonformitätsprüfungen","Durchführen von Codequalitätsprüfungen","Verwalten von Kontrollpunkten in Charge von Plänen"],"pt":["Executando planos de implementação de tarefas múltiplas","Realizando verificação de conformidade com especificações","Realizando revisões de qualidade de código","Gerenciando pontos de verificação em lotes em worktrees baseados em planos"],"ru":["Выполнение многоэтапных планов реализации","Проведение верификации соответствия спецификациям","Проведение обзоров качества кода","Управление контрольными точками пакетов в worktrees, созданных на основе планов"],"ar":["تنفيذ خطط العمل المتعددة المهام","إجراء التحقق من مطابقة المواصفات","إجراء استعراض جودة الشفرة","إدارة نقاط التحقق المجمّعة في أشجار العمل التي تعتمد على الخطة"]},"limitations":{"en":["Requires worktree created with --plan flag","Depends on plan file at docs/plans/ path","Only activates for multi-task implementations"],"zh":["需要使用 --plan 标志创建的工作树","依赖于 docs/plans/ 路径下的计划文件","仅激活多任务实现"],"ja":["--plan フラグで作成されたワークツリーが必要","docs/plans/ パスのプランファイルに依存","マルチタスク実装のみ有効"],"ko":["--plan 플래그로 생성 된 워크 트리가 필요","docs/plans/ 경로의 계획 파일에 의존","멀티 태스크 구현만 활성화"],"es":["Requiere worktree creado con la bandera --plan","Depende del archivo de plan en el camino docs/plans/","Solo se activa para implementaciones de varias tareas"],"fr":["Nécessite un worktree créé avec le drapeau --plan","Dépend du fichier de plan dans le chemin docs/plans/","Ne s''active que pour les mises en œuvre de plusieurs tâches"],"de":["Erfordert einen mit der --plan-Flag erstellten Worktree","Hängt von der Plan-Datei im Pfad docs/plans/ ab","Aktiviert sich nur für Mehrfachaufgaben-Implementierungen"],"pt":["Exige worktree criado com a flag --plan","Depende do arquivo de plano no caminho docs/plans/","Apenas ativa para implementações de tarefas múltiplas"],"ru":["Требует worktree, созданного с флагом --plan","Зависит от файла плана по пути docs/plans/","Активируется только для многоэтапных реализаций"],"ar":["يتطلب شجرة العمل التي تم إنشاؤها بالعلم --plan","يعتمد على ملف الخطة في المسار docs/plans/","تفعيله فقط لتنفيذ المهام المتعددة"]},"version":4},"contentHash":"36415a9517621cc5bc89c07c66c8777348c01739b385eb16b49f065d2017d1e6","qualityScore":45}');
