INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('orient-bot/orient/plan-executor', 'plan-executor', 'orient-bot', 'orient', 'community', 'plan-executor orient-bot orient community The plan-executor skill automates implementation plans with two-stage review and verification. It benefits developers working with worktrees created with the --plan flag and multi-task implementations. Plan Executor 是一个执行实施计划的 AI Agent，具有两阶段审查和批量检查点的能力 Plan Executor は、2ステージレビューとバッチチェックポイントを備えた実装計画の実行用 AI Agent です Plan Executor는 2단계 검토 및 배치 체크포인트를 갖춘 구현 계획을 실행하는 AI 에이전트입니다 El plan-executor es una habilidad que ejecuta planes de implementación con revisión y verificación en dos etapas, garantizando la calidad del código y la conformidad con las especificaciones Le plan-executor est une compétence qui exécute des plans d''implémentation avec révision et vérification en deux étapes, garantissant la qualité du code et la conformité aux spécifications Der plan-executor ist eine Fähigkeit, die Implementierungspläne mit Überprüfung und Verifizierung in zwei Stufen ausführt, um die Codequalität und die Konformität mit den Spezifikationen sicherzustellen O Plan Executor é uma ferramenta de AI que executa planos de implementação com revisão em duas etapas e verificação em batch Плановый Executor - это инструмент ИИ, который выполняет планы реализации с двухэтапным обзором и пакетной проверкой Plan Executor هو أداة ذكاء اصطناعي تقوم بتنفيذ خطط التنفيذ مع استعراض درجتين و_verification بالدفعة plan-executor setup guide how to use plan-executor what is plan-executor plan-executor alternative plan-executor vs implementation plans plan-executor install two-stage review process AI Agent 实施计划 两阶段审查 批量检查点 证据优先 多任务实施 Plan Executor AI工具 Executes implementation plans with two-stage review and verification Automatically applies to worktrees created with the --plan flag Supports multi-task implementations with batch checkpoints Verifies spec compliance before code quality review Requires evidence before claiming completion plan-executor is a skill that executes implementation plans with two-stage review, verification, and batch checkpoints for efficient multi-task execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('porkytheblack/glove/glove', 'community', 'porkytheblack', 'glove', 'porkytheblack/glove', 'glove', 5, 1, 45, '2026-02-24T09:13:24Z', '2026-03-06T06:54:24.666Z', '1a19179f4f769f0e9e49b9da9dcd9981673a41d024e3853f14002450a8fab04a', '{"id":"porkytheblack/glove/glove","name":"glove","description":{"en":"Glove is an open-source framework for building AI-powered applications, allowing users to describe tasks in conversation and invoking capabilities as needed. It benefits developers by handling the agent loop.","zh":"Glove 框架是一个开源的 TypeScript 框架，用于构建 AI 驱动的应用程序","ja":"Glove フレームワークは、AI を駆使したアプリケーションを開発するためのオープンソースの TypeScript フレームワークです","ko":"Glove 프레임워크는 AI 에이전트 애플리케이션을 개발하기 위한 오픈소스 TypeScript 프레임워크입니다","es":"Glove es un framework de TypeScript de código abierto para construir aplicaciones impulsadas por IA. Permite a los desarrolladores definir herramientas y renderizadores, mientras que Glove maneja el bucle del agente.","fr":"Glove est un framework TypeScript open-source pour construire des applications alimentées par l''IA. Il permet aux développeurs de définir des outils et des renderers, tandis que Glove gère la boucle de l''agent.","de":"Glove ist ein Open-Source-TypeScript-Framework für den Bau von KI-Anwendungen. Es ermöglicht Entwicklern, Tools und Renderer zu definieren, während Glove den Agenten-Loop verwaltet.","pt":"O Glove é um framework de código aberto em TypeScript para construir aplicações com AI. Ele permite que os desenvolvedores definam ferramentas e renderizadores, enquanto o Glove lida com o loop do agente.","ru":"Glove - открытая платформа на TypeScript для создания приложений с ИИ. Она позволяет разработчикам определять инструменты и рендереры, а Glove занимается агентским циклом.","ar":"Glove هو إطار عمل مفتوح المصدر باللغة TypeScript لبناء التطبيقات الذكية. يسمح للمطورين بتعريف الأدوات والمُحسّنات، بينما يتدبر Glove حلقة الوكيل."},"seo":{"title":{"en":"Glove: AI-Powered Application Framework Setup Guide | AI ...","zh":"Glove 框架：AI Agent 开发指南","ja":"Glove フレームワーク：AIエージェントのベストプラクティス","ko":"Glove 프레임워크: AI 에이전트 개발 가이드","es":"Guía de configuración de Glove para Agentes de Inteligenc...","fr":"Guide de mise en place de Glove pour les Agents d''Intelli...","de":"Einrichtungsleitfaden für Glove - Framework für KI-Agents","pt":"Guia de Configuração do Glove - Framework de AI em TypeSc...","ru":"Настройка Glove: Руководство по разработке ИИ Агентов","ar":"دليل إعداد Glove - إطار العمل للوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how Glove simplifies AI agent development with its open-source TypeScript framework. Explore the repository and docs site to get started with buildi...","zh":"了解 Glove 框架的优势和功能，打造强大的 AI Agent 应用","ja":"Glove フレームワークの特徴とメリットを知る、AIエージェントの開発を効率化","ko":"Glove 프레임워크의 기능과 장점을 알아보세요, 강력한 AI 에이전트 애플리케이션을 개발하세요","es":"Aprende a utilizar Glove, un framework de TypeScript de código abierto para construir aplicaciones impulsadas por IA. Descubre cómo funciona y cómo empezar.","fr":"Découvrez Glove, un framework TypeScript open-source pour construire des applications alimentées par l''IA. Comprenez comment cela fonctionne et comment comme...","de":"Erfahren Sie, wie Sie Glove, ein Open-Source-TypeScript-Framework für den Bau von KI-Anwendungen, verwenden können. Entdecken Sie, wie es funktioniert und wi...","pt":"Aprenda a configurar o Glove, um framework de código aberto em TypeScript para construir aplicações com AI. Descubra como criar ferramentas e renderizadores ...","ru":"Узнайте, как настроить Glove, открытую платформу на TypeScript для создания приложений с ИИ. Ознакомьтесь с возможностями создания инструментов и рендереров ...","ar":"تعلم كيفية إعداد Glove، إطار العمل مفتوح المصدر باللغة TypeScript لبناء التطبيقات الذكية. اكتشف كيفية إنشاء الأدوات والمُحسّنات مع Glove."},"definition":{"en":"Glove is an open-source TypeScript framework for building AI-powered applications, enabling users to interact with tools and renderers through conversation.","zh":"Glove 框架是一种开源的 AI Agent 框架，用于构建对话式应用程序","ja":"Glove フレームワークは、AIエージェントの開発を容易にするオープンソースのフレームワークです","ko":"Glove 프레임워크는 AI 에이전트 개발을 위한 오픈소스 프레임워크로, 대화식 애플리케이션을 구축하는 데 사용됩니다","es":"Glove es un framework de código abierto para construir aplicaciones impulsadas por IA, que permite a los desarrolladores definir herramientas y renderizadores.","fr":"Glove est un framework open-source pour construire des applications alimentées par l''IA, qui permet aux développeurs de définir des outils et des renderers.","de":"Glove ist ein Open-Source-Framework für den Bau von KI-Anwendungen, das es Entwicklern ermöglicht, Tools und Renderer zu definieren.","pt":"O Glove é um framework de AI em TypeScript que permite aos desenvolvedores criar aplicações com capacidades de inteligência artificial.","ru":"Glove - это платформа ИИ на TypeScript, которая позволяет разработчикам создавать приложения с возможностями искусственного интеллекта.","ar":"Glove هو إطار عمل للوكلاء الذكاء الاصطناعي باللغة TypeScript الذي يسمح للمطورين بإنشاء تطبيقات ذات قوى ذكاء اصطناعي."},"features":{"en":["Handles the agent loop for AI-powered applications","Supports definition of tools and renderers in TypeScript","Invokes capabilities based on user conversation input","Open-source framework available on GitHub repository","Documentation available on a dedicated docs site","Enables building of custom AI-powered applications"],"zh":["基于 TypeScript 开发","支持对话式应用程序开发","提供工具和渲染器定义","内置 AI 决策能力","开源和社区驱动"],"ja":["TypeScript を使用した開発","対話式アプリケーションの開発をサポート","ツールとレンダラーの定義を提供","AI の意思決定能力を内蔵","オープンソースとコミュニティ駆動"],"ko":["TypeScript 기반 개발","대화식 애플리케이션 개발 지원","도구와 렌더러 정의 제공","AI 의사결정 능력 내장","오픈소스 및 커뮤니티 주도"],"es":["Framework de TypeScript de código abierto","Permite a los desarrolladores definir herramientas y renderizadores","Glove maneja el bucle del agente","Integración con herramientas y tecnologías de IA","Repositorio en GitHub: https://github.com/porkytheblack/glove","Documentación en: https://"],"fr":["Framework TypeScript open-source","Permet aux développeurs de définir des outils et des renderers","Glove gère la boucle de l''agent","Intégration avec des outils et des technologies d''IA","Référentiel sur GitHub: https://github.com/porkytheblack/glove","Documentation sur: https://"],"de":["Open-Source-TypeScript-Framework","Ermöglicht Entwicklern, Tools und Renderer zu definieren","Glove verwaltet den Agenten-Loop","Integration mit KI-Tools und -Technologien","Repository auf GitHub: https://github.com/porkytheblack/glove","Dokumentation auf: https://"],"pt":["Desenvolvimento de aplicações com AI em TypeScript","Definição de ferramentas e renderizadores personalizados","Gerenciamento do loop do agente pelo Glove","Integração com diferentes capacidades de AI","Código aberto e comunitário"],"ru":["Разработка приложений с ИИ на TypeScript","Определение пользовательских инструментов и рендереров","Управление агентским циклом в Glove","Интеграция с различными возможностями ИИ","Открытый и общинный код"],"ar":["بناء التطبيقات الذكية باللغة TypeScript","تعريف الأدوات والمُحسّنات المخصصة","إدارة حلقة الوكيل بواسطة Glove","التكامل مع مختلف القدرات الذكاء الاصطناعي","الكود مفتوح والمجتمع"]},"keywords":{"en":["how to use glove","glove framework","glove alternative","glove vs other ai frameworks","glove install","glove setup guide","what is glove","glove documentation","glove github repository"],"zh":["Glove 框架","AI Agent 开发","TypeScript 开发","对话式应用程序","AI 驱动的应用程序","开源框架","AIエージェント"],"ja":["Glove フレームワーク","AIエージェントの開発","TypeScript の開発","対話式アプリケーション","AI ドライブのアプリケーション","オープンソースのフレームワーク","AIエージェント"],"ko":["Glove 프레임워크","AI 에이전트 개발","TypeScript 개발","대화식 애플리케이션","AI 에이전트 애플리케이션","오픈소스 프레임워크","AI 에이전트"],"es":["Glove framework","Agentes de Inteligencia Artificial","Aplicaciones impulsadas por IA","TypeScript","Framework de código abierto","Desarrollo de aplicaciones de IA","Herramientas de IA","Tecnologías de IA","Inteligencia Artificial"],"fr":["Glove framework","Agents d''Intelligence Artificielle","Applications alimentées par l''IA","TypeScript","Framework open-source","Développement d''applications d''IA","Outils d''IA","Technologies d''IA","Intelligence Artificielle"],"de":["Glove-Framework","KI-Agents","KI-Anwendungen","TypeScript","Open-Source-Framework","Entwicklung von KI-Anwendungen","KI-Tools","KI-Technologien","Künstliche Intelligenz"],"pt":["Glove framework","Desenvolvimento de AI","TypeScript","Ferramentas de AI","Renderizadores personalizados","Loop do agente","Inteligência artificial","Aplicações com AI"],"ru":["Glove платформа","Разработка ИИ","TypeScript","ИИ инструменты","Пользовательские рендереры","Агентский цикл","Искусственный интеллект","Приложения с ИИ"],"ar":["إطار Glove","بناء الوكلاء الذكاء الاصطناعي","TypeScript","أدوات الذكاء الاصطناعي","المُحسّنات المخصصة","حلقة الوكيل","الذكاء الاصطناعي","التطبيقات الذكية"]}},"owner":"porkytheblack","repo":"glove","repoPath":"porkytheblack/glove","stars":5,"forks":1,"updatedAt":"2026-02-24T09:13:24Z","topics":[],"category":"community","skillMd":{"name":"glove","description":"Expert guide for building AI-powered applications with the Glove framework. Use when working with glove-core, glove-react, glove-next, tools, display stack, model adapters, stores, or any Glove example project.","bodyPreview":"# Glove Framework — Development Guide\n\nYou are an expert on the Glove framework. Use this knowledge when writing, debugging, or reviewing Glove code.\n\n## What Glove Is\n\nGlove is an open-source TypeScript framework for building AI-powered applications. Users describe what they want in conversation, and an AI decides which capabilities (tools) to invoke. Developers define tools and renderers; Glove handles the agent loop.\n\n**Repository**: https://github.com/porkytheblack/glove\n**Docs site**: https","body":"# Glove Framework — Development Guide\n\nYou are an expert on the Glove framework. Use this knowledge when writing, debugging, or reviewing Glove code.\n\n## What Glove Is\n\nGlove is an open-source TypeScript framework for building AI-powered applications. Users describe what they want in conversation, and an AI decides which capabilities (tools) to invoke. Developers define tools and renderers; Glove handles the agent loop.\n\n**Repository**: https://github.com/porkytheblack/glove\n**Docs site**: https://glove.dterminal.net\n**License**: MIT (dterminal)\n\n## Package Overview\n\n| Package | Purpose | Install |\n|---------|---------|---------|\n| `glove-core` | Runtime engine: agent loop, tool execution, display manager, model adapters, stores | `pnpm add glove-core` |\n| `glove-react` | React hooks (`useGlove`), `GloveClient`, `GloveProvider`, `defineTool`, `<Render>`, `MemoryStore`, `ToolConfig` with colocated renderers | `pnpm add glove-react` |\n| `glove-next` | One-line Next.js API route handler (`createChatHandler`) for streaming SSE | `pnpm add glove-next` |\n\n**Most projects need just `glove-react` + `glove-next`.** `glove-core` is included as a dependency of `glove-react`.\n\n## Architecture at a Glance\n\n```\nUser message → Agent Loop → Model decides tool calls → Execute tools → Feed results back → Loop until done\n                                                          ↓\n                                                   Display Stack (pushAndWait / pushAndForget)\n                                                          ↓\n                                                   React renders UI slots\n```\n\n### Core Concepts\n\n- **Agent** — AI coordinator that replaces router/navigation logic. Reads tools, decides which to call.\n- **Tool** — A capability: name, description, inputSchema (Zod), `do` function, optional `render` + `renderResult`.\n- **Display Stack** — Stack of UI slots tools push onto. `pushAndWait` blocks tool; `pushAndForget` doesn''t.\n- **Display Strategy** — Controls slot visibility lifecycle: `\"stay\"`, `\"hide-on-complete\"`, `\"hide-on-new\"`.\n- **renderData** — Client-only data returned from `do()` that is NOT sent to the AI model. Used by `renderResult` for history rendering.\n- **Adapter** — Pluggable interfaces for Model, Store, DisplayManager, and Subscriber. Swap providers without changing app code.\n- **Context Compaction** — Auto-summarizes long conversations to stay within context window limits. The store preserves full message history (so frontends can display the entire chat), while `Context.getMessages()` splits at the last compaction summary so the model only sees post-compaction context. Summary messages are marked with `is_compaction: true`.\n\n## Quick Start (Next.js)\n\n### 1. Install\n\n```bash\npnpm add glove-core glove-react glove-next zod\n```\n\n### 2. Server route\n\n```typescript\n// app/api/chat/route.ts\nimport { createChatHandler } from \"glove-next\";\n\nexport const POST = createChatHandler({\n  provider: \"anthropic\",     // or \"openai\", \"openrouter\", \"gemini\", etc.\n  model: \"claude-sonnet-4-20250514\",\n});\n```\n\nSet `ANTHROPIC_API_KEY` (or `OPENAI_API_KEY`, etc.) in `.env.local`.\n\n### 3. Define tools with `defineTool`\n\n```tsx\n// lib/glove.tsx\nimport { GloveClient, defineTool } from \"glove-react\";\nimport type { ToolConfig } from \"glove-react\";\nimport { z } from \"zod\";\n\nconst inputSchema = z.object({\n  question: z.string().describe(\"The question to display\"),\n  options: z.array(z.object({\n    label: z.string().describe(\"Display text\"),\n    value: z.string().describe(\"Value returned when selected\"),\n  })),\n});\n\nconst askPreferenceTool = defineTool({\n  name: \"ask_preference\",\n  description: \"Present options for the user to choose from.\",\n  inputSchema,\n  displayPropsSchema: inputSchema,       // Zod schema for display props\n  resolveSchema: z.string(),             // Zod schema for resolve value\n  displayStrategy: \"hide-on-complete\",   // Hide slot after user responds\n  async do(input, display) {\n    const selected = await display.pushAndWait(input);  // typed!\n    return {\n      status: \"success\" as const,\n      data: `User selected: ${selected}`,         // sent to AI\n      renderData: { question: input.question, selected },  // client-only\n    };\n  },\n  render({ props, resolve }) {           // typed props, typed resolve\n    return (\n      <div>\n        <p>{props.question}</p>\n        {props.options.map(opt => (\n          <button key={opt.value} onClick={() => resolve(opt.value)}>\n            {opt.label}\n          </button>\n        ))}\n      </div>\n    );\n  },\n  renderResult({ data }) {               // renders from history\n    const { question, selected } = data as { question: string; selected: string };\n    return <div><p>{question}</p><span>Selected: {selected}</span></div>;\n  },\n});\n\n// Tools without display stay as raw ToolConfig\nconst getDateTool: ToolConfig = {\n  name: \"get_date\",\n  description: \"Get today''s date\",\n  inputSchema: z.object({}),\n  async do() { return { status: \"success\", data: new Date().toLocaleDateString() }; },\n};\n\nexport const gloveClient = new GloveClient({\n  endpoint: \"/api/chat\",\n  systemPrompt: \"You are a helpful assistant.\",\n  tools: [askPreferenceTool, getDateTool],\n});\n```\n\n### 4. Provider + Render\n\n```tsx\n// app/providers.tsx\n\"use client\";\nimport { GloveProvider } from \"glove-react\";\nimport { gloveClient } from \"@/lib/glove\";\n\nexport function Providers({ children }: { children: React.ReactNode }) {\n  return <GloveProvider client={gloveClient}>{children}</GloveProvider>;\n}\n```\n\n```tsx\n// app/page.tsx — using <Render> component\n\"use client\";\nimport { useGlove, Render } from \"glove-react\";\n\nexport default function Chat() {\n  const glove = useGlove();\n\n  return (\n    <Render\n      glove={glove}\n      strategy=\"interleaved\"\n      renderMessage={({ entry }) => (\n        <div><strong>{entry.kind === \"user\" ? \"You\" : \"AI\"}:</strong> {entry.text}</div>\n      )}\n      renderStreaming={({ text }) => <div style={{ opacity: 0.7 }}>{text}</div>}\n    />\n  );\n}\n```\n\nOr use `useGlove()` directly for full manual control:\n\n```tsx\n// app/page.tsx — manual rendering\n\"use client\";\nimport { useState } from \"react\";\nimport { useGlove } from \"glove-react\";\n\nexport default function Chat() {\n  const { timeline, streamingText, busy, slots, sendMessage, renderSlot, renderToolResult } = useGlove();\n  const [input, setInput] = useState(\"\");\n\n  return (\n    <div>\n      {timeline.map((entry, i) => (\n        <div key={i}>\n          {entry.kind === \"user\" && <p><strong>You:</strong> {entry.text}</p>}\n          {entry.kind === \"agent_text\" && <p><strong>AI:</strong> {entry.text}</p>}\n          {entry.kind === \"tool\" && (\n            <>\n              <p>Tool: {entry.name} — {entry.status}</p>\n              {entry.renderData !== undefined && renderToolResult(entry)}\n            </>\n          )}\n        </div>\n      ))}\n      {streamingText && <p style={{ opacity: 0.7 }}>{streamingText}</p>}\n      {slots.map(renderSlot)}\n      <form onSubmit={(e) => { e.preventDefault(); sendMessage(input.trim()); setInput(\"\"); }}>\n        <input value={input} onChange={(e) => setInput(e.target.value)} disabled={busy} />\n        <button type=\"submit\" disabled={busy}>Send</button>\n      </form>\n    </div>\n  );\n}\n```\n\n## Display Stack Patterns\n\n### pushAndForget — Show results (non-blocking)\n\n```tsx\nasync do(input, display) {\n  const data = await fetchData(input);\n  await display.pushAndForget({ input: data }); // Shows UI, tool continues\n  return { status: \"success\", data: \"Displayed results\", renderData: data };\n},\nrender({ data }) {\n  return <Card>{data.title}</Card>;\n},\nrenderResult({ data }) {\n  return <Card>{(data as any).title}</Card>;  // Same card from history\n},\n```\n\n### pushAndWait — Collect user input (blocking)\n\n```tsx\nasync do(input, display) {\n  const confirmed = await display.pushAndWait({ input }); // Pauses until user responds\n  return {\n    status: \"success\",\n    data: confirmed ? \"Confirmed\" : \"Cancelled\",\n    renderData: { confirmed },\n  };\n},\nrender({ data, resolve }) {\n  return (\n    <div>\n      <p>{data.message}</p>\n      <button onClick={() => resolve(true)}>Yes</button>\n      <button onClick={() => resolve(false)}>No</button>\n    </div>\n  );\n},\nrenderResult({ data }) {\n  const { confirmed } = data as { confirmed: boolean };\n  return <div>{confirmed ? \"Confirmed\" : \"Cancelled\"}</div>;\n},\n```\n\n### Display Strategies\n\n| Strategy | Behavior | Use for |\n|----------|----------|---------|\n| `\"stay\"` (default) | Slot always visible | Info cards, results |\n| `\"hide-on-complete\"` | Hidden when slot is resolved | Forms, confirmations, pickers |\n| `\"hide-on-new\"` | Hidden when newer slot from same tool appears | Cart summaries, status panels |\n\n### SlotRenderProps\n\n| Prop | Type | Description |\n|------|------|-------------|\n| `data` | `T` | Input passed to pushAndWait/pushAndForget |\n| `resolve` | `(value: unknown) => void` | Resolves the slot. For pushAndWait, the value returns to `do`. For pushAndForget, use `resolve()` or `removeSlot(id)` to dismiss. |\n| `reject` | `(reason?: string) => void` | Rejects the slot. For pushAndWait, this causes the promise to reject. Use for cancellation flows. |\n\n## Tool Definition\n\n### `defineTool` (recommended for tools with UI)\n\n```typescript\nimport { defineTool } from \"glove-react\";\n\nconst tool = defineTool({\n  name: string,\n  description: string,\n  inputSchema: z.ZodType,              // Zod schema for tool input\n  displayPropsSchema?: z.ZodType,      // Zod schema for display props (recommended for tools with UI)\n  resolveSchema?: z.ZodType,           // Zod schema for resolve value (omit for pushAndForget-only)\n  displayStrategy?: SlotDisplayStrategy,\n  requiresPermission?: boolean,\n  unAbortable?: boolean,                 // Tool runs to completion even if abort signal fires (e.g. voice barge-in)\n  do(input, display): Promise<ToolResultData>,  // display is TypedDisplay<D, R>\n  render?({ props, resolve, reject }): ReactNode,\n  renderResult?({ data, output, status }): ReactNode,\n});\n```\n\n**Key points:**\n- `do()` should return `{ status, data, renderData }` — `data` goes to model, `renderData` stays client-only\n- `render()` gets typed `props` (matching displayPropsSchema) and typed `resolve` (matching resolveSchema)\n- `renderResult()` receives `renderData` for showing read-only views from history\n- `displayPropsSchema` is optional but recommended — tools without display should use raw `ToolConfig`\n\n### `ToolConfig` (for tools without UI or manual control)\n\n```typescript\ninterface ToolConfig<I = any> {\n  name: string;\n  description: string;\n  inputSchema: z.ZodType<I>;\n  do: (input: I, display: ToolDisplay) => Promise<ToolResultData>;\n  render?: (props: SlotRenderProps) => ReactNode;\n  renderResult?: (props: ToolResultRenderProps) => ReactNode;\n  displayStrategy?: SlotDisplayStrategy;\n  requiresPermission?: boolean;\n  unAbortable?: boolean;\n}\n```\n\n### ToolResultData\n\n```typescript\ninterface ToolResultData {\n  status: \"success\" | \"error\";\n  data: unknown;          // Sent to the AI model\n  message?: string;       // Error message (for status: \"error\")\n  renderData?: unknown;   // Client-only — NOT sent to model, used by renderResult\n}\n```\n\n**Important:** Model adapters explicitly strip `renderData` before sending to the AI. This makes it safe to store sensitive client-only data (e.g., email addresses, UI state) in `renderData`.\n\n## `<Render>` Component\n\nHeadless render component that replaces manual timeline rendering:\n\n```tsx\nimport { Render } from \"glove-react\";\n\n<Render\n  glove={gloveHandle}           // return value of useGlove()\n  strategy=\"interleaved\"        // \"interleaved\" | \"slots-before\" | \"slots-after\" | \"slots-only\"\n  renderMessage={({ entry, index, isLast }) => ...}\n  renderToolStatus={({ entry, index, hasSlot }) => ...}\n  renderStreaming={({ text }) => ...}\n  renderInput={({ send, busy, abort }) => ...}\n  renderSlotContainer={({ slots, renderSlot }) => ...}\n  as=\"div\"                      // wrapper element\n  className=\"chat\"\n/>\n```\n\n**Features:**\n- Automatic slot visibility based on `displayStrategy`\n- Automatic `renderResult` rendering for completed tools with `renderData`\n- Interleaving: slots appear inline next to their tool call\n- Sensible defaults for all render props\n\n## `GloveHandle` Interface\n\nThe interface consumed by `<Render>`, returned by `useGlove()`:\n\n```typescript\ninterface GloveHandle {\n  timeline: TimelineEntry[];\n  streamingText: string;\n  busy: boolean;\n  slots: EnhancedSlot[];\n  sendMessage: (text: string, images?: { data: string; media_type: string }[]) => void;\n  abort: () => void;\n  renderSlot: (slot: EnhancedSlot) => ReactNode;\n  renderToolResult: (entry: ToolEntry) => ReactNode;\n  resolveSlot: (slotId: string, value: unknown) => void;\n  rejectSlot: (slotId: string, reason?: string) => void;\n}\n```\n\n## useGlove Hook Return\n\n| Property | Type | Description |\n|----------|------|-------------|\n| `timeline` | `TimelineEntry[]` | Messages + tool calls |\n| `streamingText` | `string` | Current streaming buffer |\n| `busy` | `boolean` | Agent is processing |\n| `isCompacting` | `boolean` | Context compaction in progress (driven by `compaction_start`/`compaction_end` events) |\n| `slots` | `EnhancedSlot[]` | Active display stack with metadata |\n| `tasks` | `Task[]` | Agent task list |\n| `stats` | `GloveStats` | `{ turns, tokens_in, tokens_out }` |\n| `sendMessage(text, images?)` | `void` | Send user message |\n| `abort()` | `void` | Cancel current request |\n| `renderSlot(slot)` | `ReactNode` | Render a display slot |\n| `renderToolResult(entry)` | `ReactNode` | Render a tool result from history |\n| `resolveSlot(id, value)` | `void` | Resolve a pushAndWait slot |\n| `rejectSlot(id, reason?)` | `void` | Reject a pushAndWait slot |\n\n## TimelineEntry\n\n```typescript\ntype TimelineEntry =\n  | { kind: \"user\"; text: string; images?: string[] }\n  | { kind: \"agent_text\"; text: string }\n  | { kind: \"tool\"; id: string; name: string; input: unknown; status: \"running\" | \"success\" | \"error\"; output?: string; renderData?: unknown };\n\ntype ToolEntry = Extract<TimelineEntry, { kind: \"tool\" }>;\n```\n\n## Supported Providers\n\n| Provider | Env Variable | Default Model | SDK Format |\n|----------|-------------|---------------|------------|\n| `openai` | `OPENAI_API_KEY` | `gpt-4.1` | openai |\n| `anthropic` | `ANTHROPIC_API_KEY` | `claude-sonnet-4-20250514` | anthropic |\n| `openrouter` | `OPENROUTER_API_KEY` | `anthropic/claude-sonnet-4` | openai |\n| `gemini` | `GEMINI_API_KEY` | `gemini-2.5-flash` | openai |\n| `minimax` | `MINIMAX_API_KEY` | `MiniMax-M2.5` | openai |\n| `kimi` | `MOONSHOT_API_KEY` | `kimi-k2.5` | openai |\n| `glm` | `ZHIPUAI_API_KEY` | `glm-4-plus` | openai |\n\n## Pre-built Tool Registry\n\nAvailable at https://glove.dterminal.net/tools — copy-paste into your project:\n\n- `confirm_action` — Yes/No confirmation dialog\n- `collect_form` — Multi-field form\n- `ask_preference` — Single-select preference picker\n- `text_input` — Free-text input\n- `show_info_card` — Info/success/warning card (pushAndForget)\n- `suggest_options` — Multiple-choice suggestions\n- `approve_plan` — Step-by-step plan approval\n\n## Voice Integration (`glove-voice`)\n\n### Package Overview\n\n| Package | Purpose | Install |\n|---------|---------|---------|\n| `glove-voice` | Voice pipeline: `GloveVoice`, adapters (STT/TTS/VAD), `AudioCapture`, `AudioPlayer` | `pnpm add glove-voice` |\n| `glove-react/voice` | React hook: `useGloveVoice` | Included in `glove-react` |\n| `glove-next` | Token handlers: `createVoiceTokenHandler` (already in `glove-next`, no separate import) | Included in `glove-next` |\n\n### Architecture\n\n```\nMic → VAD → STTAdapter → glove.processRequest() → TTSAdapter → Speaker\n```\n\n`GloveVoice` wraps a Glove instance with a full-duplex voice pipeline. Glove remains the intelligence layer — all tools, display stack, and context management work normally. STT and TTS are swappable adapters. Text tokens stream through a `SentenceBuffer` into TTS in real-time.\n\n### Quick Start (Next.js + ElevenLabs)\n\n**Step 1: Token routes** — server-side handlers that exchange your API key for short-lived tokens\n\n```typescript\n// app/api/voice/stt-token/route.ts\nimport { createVoiceTokenHandler } from \"glove-next\";\nexport const GET = createVoiceTokenHandler({ provider: \"elevenlabs\", type: \"stt\" });\n```\n\n```typescript\n// app/api/voice/tts-token/route.ts\nimport { createVoiceTokenHandler } from \"glove-next\";\nexport const GET = createVoiceTokenHandler({ provider: \"elevenlabs\", type: \"tts\" });\n```\n\nSet `ELEVENLABS_API_KEY` in `.env.local`.\n\n**Step 2: Client voice config**\n\n```typescript\n// app/lib/voice.ts\nimport { createElevenLabsAdapters } from \"glove-voice\";\n\nasync function fetchToken(path: string): Promise<string> {\n  const res = await fetch(path);\n  const data = await res.json();\n  return data.token;\n}\n\nexport const { stt, createTTS } = createElevenLabsAdapters({\n  getSTTToken: () => fetchToken(\"/api/voice/stt-token\"),\n  getTTSToken: () => fetchToken(\"/api/voice/tts-token\"),\n  voiceId: \"JBFqnCBsd6RMkjVDRZzb\",\n});\n```\n\n**Step 3: SileroVAD** — dynamic import for SSR safety\n\n```typescript\nexport async function createSileroVAD() {\n  const { SileroVADAdapter } = await import(\"glove-voice/silero-vad\");\n  const vad = new SileroVADAdapter({\n    positiveSpeechThreshold: 0.5,\n    negativeSpeechThreshold: 0.35,\n    wasm: { type: \"cdn\" },\n  });\n  await vad.init();\n  return vad;\n}\n```\n\n**Step 4: React hook**\n\n```tsx\nconst { runnable } = useGlove({ tools, sessionId });\nconst voice = useGloveVoice({ runnable, voice: { stt, createTTS, vad } });\n// voice.mode, voice.isActive, voice.isMuted, voice.error, voice.transcript\n// voice.start(), voice.stop(), voice.interrupt(), voice.commitTurn()\n// voice.mute(), voice.unmute()              — gate mic audio to STT/VAD\n// voice.narrate(\"text\")                     — speak text via TTS without model (returns Promise)\n```\n\n### Turn Modes\n\n| Mode | Behavior | Use for |\n|------|----------|---------|\n| `\"vad\"` (default) | Auto speech detection + barge-in | Hands-free, voice-first apps |\n| `\"manual\"` | Push-to-talk, explicit `commitTurn()` | Noisy environments, precise control |\n\n### Narration + Mic Control\n\n- **`voice.narrate(text)`** — Speak arbitrary text through TTS without the model. Resolves when audio finishes. Auto-mutes mic during narration. Abortable via `interrupt()`. Safe to call from `pushAndWait` tool handlers.\n- **`voice.mute()` / `voice.unmute()`** — Gate mic audio forwarding to STT/VAD. `audio_chunk` events still fire when muted (for visualization).\n- **`audio_chunk` event** — Raw `Int16Array` PCM from the mic, emitted even when muted. Use for waveform/level visualization.\n- **Compaction silence** — Voice automatically ignores `text_delta` during context compaction so the summary is never narrated.\n\n### Voice-First Tool Design\n\n- **Use `pushAndForget` instead of `pushAndWait`** — blocking tools that wait for clicks are unusable in voice mode\n- **Return descriptive text in `data`** — the LLM reads it to formulate spoken responses\n- **Add a voice-specific system prompt** — instruct the agent to narrate results concisely\n- **Use `narrate()` for slot narration** — read display content aloud from within tool handlers\n\n### Supported Voice Providers\n\n| Provider | Token Handler Config | Env Variable |\n|----------|---------------------|--------------|\n| ElevenLabs | `{ provider: \"elevenlabs\", type: \"stt\" \\| \"tts\" }` | `ELEVENLABS_API_KEY` |\n| Deepgram | `{ provider: \"deepgram\" }` | `DEEPGRAM_API_KEY` |\n| Cartesia | `{ provider: \"cartesia\" }` | `CARTESIA_API_KEY` |\n\n## Supporting Files\n\nFor detailed API reference, see [api-reference.md](api-reference.md).\nFor example patterns from real implementations, see [examples.md](examples.md).\n\n## Common Gotchas\n\n1. **model_response_complete vs model_response**: Streaming adapters emit `model_response_complete`, not `model_response`. Subscribers must handle both.\n2. **Closure capture in React hooks**: When re-keying sessions, use mutable `let currentKey = key` to avoid stale closures.\n3. **React useEffect timing**: State updates don''t take effect in the same render cycle — guard with early returns.\n4. **Browser-safe imports**: `glove-core` barrel exports include native deps (better-sqlite3). For browser code, import from subpaths: `glove-core/core`, `glove-core/glove`, `glove-core/display-manager`, `glove-core/tools/task-tool`.\n5. **`Displaymanager` casing**: The concrete class is `Displaymanager` (lowercase ''m''), not `DisplayManager`. Import it as: `import { Displaymanager } from \"glove-core/display-manager\"`.\n6. **`createAdapter` stream default**: `stream` defaults to `true`, not `false`. Pass `stream: false` explicitly if you want synchronous responses.\n7. **Tool return values**: The `do` function should return `ToolResultData` with `{ status, data, renderData? }`. `data` goes to the AI; `renderData` stays client-only.\n8. **Zod .describe()**: Always add `.describe()` to schema fields — the AI reads these descriptions to understand what to provide.\n9. **displayPropsSchema is optional but recommended**: `defineTool`''s `displayPropsSchema` is optional, but recommended for tools with display UI — tools without display should use raw `ToolConfig` instead.\n10. **renderData is stripped by model adapters**: Model adapters explicitly exclude `renderData` when formatting tool results for the AI, so it''s safe for client-only data.\n11. **SileroVAD must use dynamic import**: Never import `glove-voice/silero-vad` at module level in Next.js/SSR. Use `await import(\"glove-voice/silero-vad\")` to avoid pulling WASM into the server bundle.\n12. **Next.js transpilePackages**: Add `\"glove-voice\"` to `transpilePackages` in `next.config.ts` so Next.js processes the ES module.\n13. **createTTS must be a factory**: `GloveVoice` calls it once per turn to get a fresh TTS adapter. Pass `() => new ElevenLabsTTSAdapter(...)`, not a single instance.\n14. **Barge-in protection requires `unAbortable`**: A `pushAndWait` resolver suppresses voice barge-in at the trigger level (GloveVoice skips `interrupt()` when `resolverStore.size > 0`). But that alone doesn''t protect the tool — if `interrupt()` is called by other means, only `unAbortable: true` on the tool guarantees it runs to completion despite the abort signal. Use both together for mutation-critical tools like checkout. Use `pushAndForget` for voice-first tools.\n15. **Empty committed transcripts**: ElevenLabs Scribe may return empty committed transcripts for short utterances. The adapter auto-falls back to the last partial transcript.\n16. **TTS idle timeout**: ElevenLabs TTS WebSocket disconnects after ~20s idle. GloveVoice handles this by closing TTS after each model_response_complete and opening a fresh session on next text_delta.\n17. **onnxruntime-web build warnings**: `Critical dependency: require function is used in a way...` warnings from onnxruntime-web are expected and harmless.\n18. **Audio sample rate**: All adapters must agree on 16kHz mono PCM (the default). Don''t change unless your provider explicitly requires something different.\n19. **`narrate()` auto-mutes mic**: `voice.narrate()` automatically mutes the mic during playback to prevent TTS audio from feeding back into STT/VAD. It restores the previous mute state when done.\n20. **`narrate()` needs a started pipeline**: Calling `narrate()` before `voice.start()` throws. The TTS factory and AudioPlayer must be initialized.\n21. **Voice auto-silences during compaction**: When context compaction is triggered, the voice pipeline ignores all `text_delta` events between `compaction_start` and `compaction_end`. The compaction summary is never narrated.\n22. **`isCompacting` for React UI feedback**: `GloveState.isCompacting` is `true` while compaction is in progress. Use it to show a loading indicator or disable input during compaction.\n"},"lastSynced":"2026-03-06T06:54:24.666Z","agentAnalysis":{"suitability":{"en":"Perfect for Conversational AI Agents needing streamlined task invocation and agent loop handling.","zh":"非常适合需要简化任务调用和代理循环处理的对话式 AI 代理。","ja":"タスクの呼び出しとエージェント ループの処理を簡素化するために最適な会話型 AI エージェントです。","ko":"작업 호출 및 에이전트 루프 처리를 간소화해야 하는 대화형 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de inteligencia artificial conversacional que necesitan una invocación de tareas y un manejo de bucle de agente optimizados.","fr":"Parfait pour les agents d''IA conversationnels nécessitant une invocation de tâches et une gestion de boucle d''agent rationalisées.","de":"Perfekt für Conversation-AI-Agents, die eine optimierte Aufgabenaufruf- und Agenten-Schleifenverwaltung benötigen.","pt":"Perfeito para Agentes de Inteligência Artificial Conversacional que necessitam de invocação de tarefas e manipulação de loop de agente otimizados.","ru":"Идеально подходит для разговорных агентов ИИ, которым необходима оптимизированная вызов задач и обработка цикла агента.","ar":"مثالي لعميل الذكاء الاصطناعي المجاور الذي يحتاج إلى استدعاء مهمة ومعالجة حلقة الوكيل المتدفقة."},"recommendation":{"en":"Empowers agents to invoke capabilities as needed, leveraging the Glove framework''s open-source TypeScript architecture and agent loop management, while supporting tools and renderers definition through conversation-based interfaces and protocols.","zh":"赋予代理以按需调用能力的权力，利用 Glove 框架的开源 TypeScript 架构和代理循环管理，同时支持通过对话式接口和协议定义工具和渲染器。","ja":"Glove フレームワークのオープンソース TypeScript アーキテクチャとエージェント ループ管理を利用し、会話ベースのインターフェイスとプロトコルを通じてツールとレンダラーの定義をサポートすることで、エージェントに機能を必要に応じて呼び出す力を与えます。","ko":"Glove 프레임워크의 오픈소스 TypeScript 아키텍처와 에이전트 루프 관리를 활용하여 에이전트가 필요한 기능을 호출할 수 있도록 하고, 대화형 인터페이스와 프로토콜을 통해 도구와 렌더러를 정의할 수 있도록 지원합니다.","es":"Habilita a los agentes a invocar capacidades según sea necesario, aprovechando la arquitectura de TypeScript de código abierto del framework Glove y la gestión del bucle del agente, mientras que admite la definición de herramientas y renderizadores a través de interfaces y protocolos basados en conversación.","fr":"Permet aux agents d''invoker des capacités selon les besoins, en exploitant l''architecture TypeScript open-source du framework Glove et la gestion de la boucle d''agent, tout en supportant la définition d''outils et de renderers via des interfaces et des protocoles basés sur la conversation.","de":"Ermächtigt Agents, Fähigkeiten nach Bedarf aufzurufen, indem es die Open-Source-TypeScript-Architektur des Glove-Frameworks und die Agenten-Schleifenverwaltung nutzt, während es die Definition von Tools und Renderern über konversationsbasierte Schnittstellen und Protokolle unterstützt.","pt":"Habilita os agentes a invocar capacidades conforme necessário, aproveitando a arquitetura de código aberto do framework Glove em TypeScript e gerenciamento de loop de agente, enquanto suporta definição de ferramentas e renderizadores por meio de interfaces e protocolos baseados em conversa.","ru":"Наделяет агентов возможностью вызывать возможности по мере необходимости, используя открытую архитектуру фреймворка Glove на TypeScript и управление циклом агента, а также поддержку определения инструментов и рендереров через разговорные интерфейсы и протоколы.","ar":"يمنح الوكلاء القدرة على استدعاء القدرات حسب الحاجة ، باستخدام هندسة المصدر المفتوح لإطار Glove النصي النوعي و إدارة حلقة الوكيل ، مع دعم تعريف الأدوات والمُدرجين من خلال واجهات بروتوكول المحادثة."},"useCases":{"en":["Defining tools and renderers for AI-powered applications","Invoking capabilities through conversation-based interfaces","Handling agent loops for seamless task execution"],"zh":["为 AI 驱动的应用程序定义工具和渲染器","通过对话式接口调用功能","处理代理循环以实现无缝任务执行"],"ja":["会話ベースのインターフェイスを通じて機能を呼び出す","AI駆動型アプリケーションのためのツールとレンダラーの定義","エージェント ループを処理してシームレスなタスク実行を実現する"],"ko":["대화형 인터페이스를 통해 기능 호출","AI 구동 애플리케이션을 위한 도구 및 렌더러 정의","에이전트 루프 처리를 통해 무중단 작업 실행"],"es":["Definir herramientas y renderizadores para aplicaciones impulsadas por IA","Invocar capacidades a través de interfaces basadas en conversación","Controlar los bucles del agente para una ejecución de tareas sin problemas"],"fr":["Définir des outils et des renderers pour les applications alimentées par l''IA","Invoker des capacités via des interfaces basées sur la conversation","Gérer les boucles d''agent pour une exécution de tâches sans interruption"],"de":["Werkzeuge und Renderer für künstliche Intelligenz-basierte Anwendungen definieren","Fähigkeiten über konversationsbasierte Schnittstellen aufrufen","Agenten-Schleifen für eine reibungslose Aufgabenverarbeitung handhaben"],"pt":["Definindo ferramentas e renderizadores para aplicações impulsionadas por IA","Invocando capacidades por meio de interfaces baseadas em conversa","Manipulando loops de agente para execução de tarefas sem interrupção"],"ru":["Определение инструментов и рендереров для приложений, работающих на ИИ","Вызов возможностей через разговорные интерфейсы","Обработка циклов агентов для бесперебойного выполнения задач"],"ar":["تحديد الأدوات والمُدرجين للتطبيقات المُحسنة بالذكاء الاصطناعي","استدعاء القدرات من خلال واجهات المحادثة","معالجة حلقات الوكيل من أجل تنفيذ المهام دون انقطاع"]},"limitations":{"en":["Requires TypeScript knowledge","Dependent on GitHub repository updates"],"zh":["需要 TypeScript 知识","依赖于 GitHub 仓库更新"],"ja":["TypeScript の知識が必要","GitHub リポジトリの更新に依存"],"ko":["TypeScript 지식 필요","GitHub 리포지토리 업데이트에 의존"],"es":["Requiere conocimiento de TypeScript","Dependiente de las actualizaciones del repositorio de GitHub"],"fr":["Nécessite des connaissances en TypeScript","Dépend des mises à jour du référentiel GitHub"],"de":["Benötigt TypeScript-Kenntnisse","Abhängig von Updates des GitHub-Repositorys"],"pt":["Requer conhecimento de TypeScript","Dependente de atualizações do repositório GitHub"],"ru":["Требует знания TypeScript","Зависит от обновлений репозитория GitHub"],"ar":["يتطلب معرفة النص النوعي TypeScript","يعتمد على تحديثات مستودع GitHub"]},"version":4},"contentHash":"1a19179f4f769f0e9e49b9da9dcd9981673a41d024e3853f14002450a8fab04a","qualityScore":45}');
