INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('porkytheblack/glove/glove', 'glove', 'porkytheblack', 'glove', 'community', 'glove porkytheblack glove community Glove is an open-source framework for building AI-powered applications, allowing users to describe tasks in conversation and invoking capabilities as needed. It benefits developers by handling the agent loop. Glove 框架是一个开源的 TypeScript 框架，用于构建 AI 驱动的应用程序 Glove フレームワークは、AI を駆使したアプリケーションを開発するためのオープンソースの TypeScript フレームワークです Glove 프레임워크는 AI 에이전트 애플리케이션을 개발하기 위한 오픈소스 TypeScript 프레임워크입니다 Glove es un framework de TypeScript de código abierto para construir aplicaciones impulsadas por IA. Permite a los desarrolladores definir herramientas y renderizadores, mientras que Glove maneja el bucle del agente. Glove est un framework TypeScript open-source pour construire des applications alimentées par l''IA. Il permet aux développeurs de définir des outils et des renderers, tandis que Glove gère la boucle de l''agent. Glove ist ein Open-Source-TypeScript-Framework für den Bau von KI-Anwendungen. Es ermöglicht Entwicklern, Tools und Renderer zu definieren, während Glove den Agenten-Loop verwaltet. O Glove é um framework de código aberto em TypeScript para construir aplicações com AI. Ele permite que os desenvolvedores definam ferramentas e renderizadores, enquanto o Glove lida com o loop do agente. Glove - открытая платформа на TypeScript для создания приложений с ИИ. Она позволяет разработчикам определять инструменты и рендереры, а Glove занимается агентским циклом. Glove هو إطار عمل مفتوح المصدر باللغة TypeScript لبناء التطبيقات الذكية. يسمح للمطورين بتعريف الأدوات والمُحسّنات، بينما يتدبر Glove حلقة الوكيل. how to use glove glove framework glove alternative glove vs other ai frameworks glove install glove setup guide what is glove glove documentation glove github repository Glove 框架 AI Agent 开发 TypeScript 开发 对话式应用程序 AI 驱动的应用程序 开源框架 AIエージェント Handles the agent loop for AI-powered applications Supports definition of tools and renderers in TypeScript Invokes capabilities based on user conversation input Open-source framework available on GitHub repository Documentation available on a dedicated docs site Enables building of custom AI-powered applications Glove is an open-source TypeScript framework for building AI-powered applications, enabling users to interact with tools and renderers through conversation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fiftynotai/igris-ai/register', 'community', 'fiftynotai', 'igris-ai', 'fiftynotai/igris-ai', 'register', 5, 0, 45, '2026-02-24T08:03:51Z', '2026-03-06T06:54:47.222Z', '80558cb6b220cd17e05bf3151e3c1facc2798fc320dc799dc54fff769cc9814e', '{"id":"fiftynotai/igris-ai/register","name":"register","description":{"en":"The register skill allows developers to create new briefs for tracking bugs, features, migrations, or technical debt. It supports various types, including bug, feature, migration, and debt, with customizable prefixes.","zh":"使用/register命令创建新brief以跟踪bugs、features、migrations或技术债务，简化AI工程平台的工作流程","ja":"AIエージェントの/registerコマンドを使用して、バグ、機能、移行、または技術負債を追跡し、開発プロセスを最適化します","ko":"AI 도구의 등록 기능을 사용하여 버그, 기능, 마이그레이션, 기술 부채를 추적하고 개발 프로세스를 최적화합니다","es":"El registro permite crear nuevas solicitudes para seguimiento de errores, características y deudas técnicas","fr":"L''enregistrement permet de créer de nouvelles demandes pour suivre les bogues, les fonctionnalités et les dettes techniques","de":"Das Register ermöglicht die Erstellung neuer Anfragen für die Nachverfolgung von Fehlern, Funktionen und technischen Schulden","pt":"O register é uma habilidade que permite criar novos briefs para rastrear bugs, recursos, migrações ou dívidas técnicas. Utilize a plataforma de engenharia de IA para melhorar sua produtividade","ru":"Регистрация - это навык, который позволяет создавать новые брифы для отслеживания ошибок, функций, миграций или технического долга. Используйте платформу ИИ для повышения производительности","ar":"التسجيل هو مهارة تسمح بإنشاء Briefs جديدة لتعقب العلل والميزات والهجرات والدّين التقني. استفد من منصة الهندسة الإلكترونية للذكاء الاصطناعي لتحسين الإنتاجية"},"seo":{"title":{"en":"register: Setup Guide for AI Agents | AI Agent Skill","zh":"注册指南 - AI 工程平台简化跟踪","ja":"登録セットアップガイド - AIエージェントによるバグ管理","ko":"등록 설정