INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fiftynotai/igris-ai/register', 'register', 'fiftynotai', 'igris-ai', 'community', 'register fiftynotai igris-ai community The register skill allows developers to create new briefs for tracking bugs, features, migrations, or technical debt. It supports various types, including bug, feature, migration, and debt, with customizable prefixes. 使用/register命令创建新brief以跟踪bugs、features、migrations或技术债务，简化AI工程平台的工作流程 AIエージェントの/registerコマンドを使用して、バグ、機能、移行、または技術負債を追跡し、開発プロセスを最適化します AI 도구의 등록 기능을 사용하여 버그, 기능, 마이그레이션, 기술 부채를 추적하고 개발 프로세스를 최적화합니다 El registro permite crear nuevas solicitudes para seguimiento de errores, características y deudas técnicas L''enregistrement permet de créer de nouvelles demandes pour suivre les bogues, les fonctionnalités et les dettes techniques Das Register ermöglicht die Erstellung neuer Anfragen für die Nachverfolgung von Fehlern, Funktionen und technischen Schulden O register é uma habilidade que permite criar novos briefs para rastrear bugs, recursos, migrações ou dívidas técnicas. Utilize a plataforma de engenharia de IA para melhorar sua produtividade Регистрация - это навык, который позволяет создавать новые брифы для отслеживания ошибок, функций, миграций или технического долга. Используйте платформу ИИ для повышения производительности التسجيل هو مهارة تسمح بإنشاء Briefs جديدة لتعقب العلل والميزات والهجرات والدّين التقني. استفد من منصة الهندسة الإلكترونية للذكاء الاصطناعي لتحسين الإنتاجية how to use register register setup guide register alternative register vs Jira register install what is register register for AI agents register for software development register bug tracking register feature management AI工程平台 注册命令 brief创建 bugs跟踪 features跟踪 migrations跟踪 技术债务跟踪 AI工具 开发工作流程 Creates new briefs for tracking bugs, features, migrations, or technical debt Supports customizable prefixes, such as BR-XXX for bugs and features, and MG-XX for migrations Allows users to specify a title for the brief, with optional type specification Provides a prompt for users who don''t specify a type, ensuring flexibility and ease of use Uses a standardized format for arguments, with [type] "title" or just "title" options register is a skill that enables developers to create and track briefs for various software development tasks, using commands like /register bug or /register feature.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('omniaura/omniclaw/migrate-to-channels', 'community', 'omniaura', 'omniclaw', 'omniaura/omniclaw', 'migrate-to-channels', 4, 1, 45, '2026-02-28T18:12:17Z', '2026-03-06T06:58:34.556Z', 'ec5509bd7b14ee684578191a0d9f1452be60f69b6e16eff3d530146a07716af4', '{"id":"omniaura/omniclaw/migrate-to-channels","name":"migrate-to-channels","description":{"en":"The migrate-to-channels skill migrates existing OmniClaw setups to a new layered context architecture, benefiting developers and teams using group chats. It transforms the flat groups/ workspace model into a more organized structure.","zh":"Migrate to Channels 是一个总是在线的编码代理，帮助您将 OmniClaw 设置从平面 workspace 模型迁移到新层的上下文架构中","ja":"Migrate to Channels は、常にオンのコードエージェントであり、OmniClaw 設定を平面 workspace モデルから新しいレイヤードコンテキストアーキテクチャに移行するのに役立ちます","ko":"Migrate to Channels는 항상 온라인인 코드 에이전트로, OmniClaw 설정을 평면 workspace 모델에서 새로운 계층화된 컨텍스트 아키텍처로 마이그레이션하는 데 도움을줍니다","es":"El agente de código ''migrate-to-channels'' migra tu configuración de OmniClaw a la arquitectura de canales en capas","fr":"L''agent de code ''migrate-to-channels'' migre votre configuration OmniClaw vers l''architecture de canaux en couches","de":"Der Code-Agent ''migrate-to-channels'' migriert Ihre OmniClaw-Konfiguration auf die schichtbasierte Kanalarchitektur","pt":"O agente de codificação sempre-ativo migra sua configuração do OmniClaw para a nova arquitetura de canais em camadas","ru":"Всегда-включенный агент кодирования мигрирует вашу конфигурацию OmniClaw в новую многослойную архитектуру каналов","ar":"وكيل الترميز دائم التشغيل يهاجر إعدادات OmniClaw إلى هيكل قناة جديد معمّق"},"seo":{"title":{"en":"migrate-to-channels: Channel Architecture Migration Setup...","zh":"Migrate to Channels_SETUP GUIDE","ja":"Migrate to Channels_BEST PRACTICES","ko":"Migrate to Channels_SETUP TUTORIAL","es":"Guía de migración a Channels para agentes de código","fr":"Guide de migration vers Channels pour les agents de code","de":"Migrationsleitfaden zu Channels für Code-Agents","pt":"Guia de Migração para Arquitetura de Canais","ru":"ИИ Агенты: Руководство по миграции в Channel Architecture","ar":"دليل هجرة إلى قناة الهيكل"},"description":{"en":"Discover how to seamlessly migrate your OmniClaw setup to the new layered context architecture with migrate-to-channels. Get started now and optimize your gr...","zh":"Learn how to migrate your OmniClaw setup to the new layered context architecture with our always-on coding agent","ja":"OmniClawの設定を新しいレイヤードコンテキストアーキテクチャに移行する方法を学びましょう","ko":"OmniClaw 설정을 새로운 계층화된 컨텍스트 아키텍처로 마이그레이션하는 방법을 알아보세요","es":"Aprende a migrar tu configuración de OmniClaw a la arquitectura de canales en capas con nuestro agente de código siempre activo","fr":"Découvrez comment migrer votre configuration OmniClaw vers l''architecture de canaux en couches avec notre agent de code toujours actif","de":"Erfahren Sie, wie Sie Ihre OmniClaw-Konfiguration auf die schichtbasierte Kanalarchitektur mit unserem immer aktiven Code-Agenten migrieren","pt":"Migre sua configuração do OmniClaw para a nova arquitetura de canais em camadas com o agente de codificação sempre-ativo","ru":"Переместите свою конфигурацию OmniClaw в новую многослойную архитектуру каналов с помощью всегда-включенного агента кодирования","ar":"احصل على دليل للهجرة إلى هيكل قناة جديد مع وكيل الترميز دائم التشغيل"},"definition":{"en":"migrate-to-channels is a skill that migrates OmniClaw setups from a flat groups/ workspace model to a layered context architecture, organizing agents, servers, and channels","zh":"Migrate to Channels 是一种 AI 工具，用于将 OmniClaw 设置迁移到新的层级化上下文架构中","ja":"Migrate to Channels は、OmniClaw 設定を新しいレイヤードコンテキストアーキテクチャに移行するための AI エージェントです","ko":"Migrate to Channels는 OmniClaw 설정을 새로운 계층화된 컨텍스트 아키텍처로 마이그레이션하는 데 사용되는 AI 도구입니다","es":"Un agente de código que migra configuraciones de OmniClaw a la arquitectura de canales","fr":"Un agent de code qui migre des configurations OmniClaw vers l''architecture de canaux","de":"Ein Code-Agent, der OmniClaw-Konfigurationen auf die Kanalarchitektur migriert","pt":"O que é migração para canais? É um processo de atualização da arquitetura do OmniClaw para uma estrutura em camadas","ru":"Что такое миграция в каналы? Это процесс обновления архитектуры OmniClaw до многослойной структуры","ar":"ما هي هجرة إلى قناة؟ هي عملية تحديث هيكل OmniClaw إلى هيكل متعدّد الطبقات"},"features":{"en":["Migrates existing OmniClaw setups to a layered context architecture","Transforms flat groups/ workspace model to organized agents, servers, and channels","Supports agent identity shared across channels via CLAUDE.md files","Creates isolated channel notebooks within servers and categories","Handles non-server channels such as WhatsApp and Telegram"],"zh":["支持将 OmniClaw 设置从平面 workspace 模型迁移到新层的上下文架构中","提供 agents/{agentId}/CLAUDE.md 文件用于代理身份管理","支持 servers/{server}/{category}/ 目录用于分类团队 workspace 管理","支持 channels/{name}/ 目录用于非服务器频道管理"],"ja":["OmniClaw 設定を平面 workspace モデルから新しいレイヤードコンテキストアーキテクチャに移行する機能","エージェント ID 管理のための agents/{agentId}/CLAUDE.md ファイルを提供","サーバー/{サーバー}/{カテゴリ}/ ディレクトリを使用したカテゴリチーム workspace 管理のサポート","チャンネル/{名前}/ ディレクトリを使用した非サーバー チャンネル管理のサポート"],"ko":["OmniClaw 설정을 평면 workspace 모델에서 새로운 계층화된 컨텍스트 아키텍처로 마이그레이션하는 기능","에이전트 ID 관리를 위한 agents/{agentId}/CLAUDE.md 파일 제공","서버/{서버}/{카테고리}/ 디렉토리를 사용한 카테고리 팀 workspace 관리 지원","채널/{이름}/ 디렉토리를 사용한 비서버 채널 관리 지원"],"es":["Migración de la configuración de OmniClaw a la arquitectura de canales en capas","Soporte para agentes de código siempre activos","Compatibilidad con la arquitectura de grupos y servidores de OmniClaw","Migración de categorías y canales a la nueva arquitectura","Soporte para canales no servidores como WhatsApp y Telegram"],"fr":["Migration de la configuration OmniClaw vers l''architecture de canaux en couches","Prise en charge des agents de code toujours actifs","Compatibilité avec l''architecture de groupes et de serveurs OmniClaw","Migration des catégories et des canaux vers la nouvelle architecture","Prise en charge des canaux non serveurs tels que WhatsApp et Telegram"],"de":["Migration der OmniClaw-Konfiguration auf die schichtbasierte Kanalarchitektur","Unterstützung für immer aktive Code-Agents","Kompatibilität mit der Gruppen- und Server-Architektur von OmniClaw","Migration von Kategorien und Kanälen auf die neue Architektur","Unterstützung für nicht-serverbasierte Kanäle wie WhatsApp und Telegram"],"pt":["Suporte à arquitetura de canais em camadas","Migração da configuração do OmniClaw","Integração com servidores e categorias","Criação de canais isolados","Suporte a canais não-server (WhatsApp, Telegram)"],"ru":["Поддержка многослойной архитектуры каналов","Миграция конфигурации OmniClaw","Интеграция с серверами и категориями","Создание изолированных каналов","Поддержка каналов без сервера (WhatsApp, Telegram)"],"ar":["دعم هيكل متعدّد الطبقات","هجرة إعدادات OmniClaw","التكامل مع الخواديم والفئات","إنشاء قنوات معزولة","دعم القنوات غير الخوادم (WhatsApp, Telegram)"]},"keywords":{"en":["how to use migrate-to-channels","migrate-to-channels setup guide","OmniClaw migration tool","layered context architecture","migrate-to-channels vs OmniClaw","migrate-to-channels install","channel architecture migration","group chat optimization","what is migrate-to-channels"],"zh":["Migrate to Channels","OmniClaw","AI 工具","代码代理","层级化上下文架构","agents/{agentId}/CLAUDE.md","servers/{server}/{category}/","channels/{name}/"],"ja":["Migrate to Channels","OmniClaw","AI エージェント","コードエージェント","レイヤードコンテキストアーキテクチャ","agents/{agentId}/CLAUDE.md","servers/{server}/{category}/","channels/{name}/"],"ko":["Migrate to Channels","OmniClaw","AI 도구","코드 에이전트","계층화된 컨텍스트 아키텍처","agents/{agentId}/CLAUDE.md","servers/{server}/{category}/","channels/{name}/"],"es":["migrar a channels","agente de código siempre activo","arquitectura de canales en capas","omnichaw","migración de configuración","canal de whatsapp","canal de telegram"],"fr":["migration vers channels","agent de code toujours actif","architecture de canaux en couches","omnichaw","migration de configuration","canal whatsapp","canal telegram"],"de":["migration zu channels","code-agent immer aktiv","schichtbasierte kanalarchitektur","omnichaw","konfigurationsmigration","whatsapp-kanal","telegram-kanal"],"pt":["migração para canais","arquitetura de canais","OmniClaw","agente de codificação","always-on coding agent","migração de configuração"],"ru":["миграция в каналы","архитектура каналов","OmniClaw","агент кодирования","всегда-включенный агент кодирования","миграция конфигурации"],"ar":["هجرة إلى قناة","هيكل قناة","OmniClaw","وكيل الترميز","وكيل الترميز دائم التشغيل","هجرة الإعدادات"]}},"owner":"omniaura","repo":"omniclaw","repoPath":"omniaura/omniclaw","stars":4,"forks":1,"updatedAt":"2026-02-28T18:12:17Z","topics":[],"category":"community","skillMd":{"name":"migrate-to-channels","description":"Migrate existing multi-agent Discord/Slack setup to the new agent/server/category/channel context architecture. Restructures group workspaces into isolated per-channel notebooks with shared category and agent identity layers.","bodyPreview":"# Migrate to Channel Architecture\n\nThis skill migrates your existing OmniClaw setup from the flat `groups/` workspace model to the new layered context architecture:\n\n```\ngroups/\n  agents/{agentId}/CLAUDE.md     ← agent identity (shared across channels)\n  servers/{server}/{category}/    ← category team workspace\n  servers/{server}/{category}/{channel}/  ← isolated channel notebook\n  channels/{name}/               ← non-server channels (WhatsApp, Telegram)\n```\n\n## What This Skill Does\n\n1. **Inspec","body":"# Migrate to Channel Architecture\n\nThis skill migrates your existing OmniClaw setup from the flat `groups/` workspace model to the new layered context architecture:\n\n```\ngroups/\n  agents/{agentId}/CLAUDE.md     ← agent identity (shared across channels)\n  servers/{server}/{category}/    ← category team workspace\n  servers/{server}/{category}/{channel}/  ← isolated channel notebook\n  channels/{name}/               ← non-server channels (WhatsApp, Telegram)\n```\n\n## What This Skill Does\n\n1. **Inspects** the live database — reads all `channel_subscriptions`, `agents`, and their current workspace mappings\n2. **Consolidates** legacy agent entries that share the same persona\n3. **Proposes** a folder mapping for each channel (server → category → channel path)\n4. **Creates** new directories and CLAUDE.md stubs for missing layers\n5. **Updates** `channel_folder`, `category_folder`, `agent_context_folder` in the DB for each subscription/agent\n6. **Sets `is_primary`** correctly on each channel''s subscriptions\n7. **Verifies** agents without new fields still work (backward compat)\n\n---\n\n## Known Gotchas (from real migration)\n\n### 1. Consolidate legacy agent entries first\n\nIn older OmniClaw setups, each channel got its own agent entry (e.g., `landing-astro-discord`, `spec-discord`, `backend-discord`) even though they all share the same persona. These are **not separate agents** — they''re just channels.\n\n**Before migrating**, merge them: re-point their subscriptions to the canonical agent and delete the stubs.\n\n```sql\n-- Example: landing-astro-discord was just another PeytonOmni channel\n-- Move its subs to clayton-discord (if not already there)\nINSERT OR IGNORE INTO channel_subscriptions (channel_jid, agent_id, trigger_pattern, requires_trigger, priority, is_primary, discord_bot_id, discord_guild_id, created_at)\nSELECT channel_jid, ''clayton-discord'', trigger_pattern, requires_trigger, priority, is_primary, discord_bot_id, discord_guild_id, created_at\nFROM channel_subscriptions WHERE agent_id = ''landing-astro-discord'';\n\nDELETE FROM channel_subscriptions WHERE agent_id = ''landing-astro-discord'';\nDELETE FROM agents WHERE id = ''landing-astro-discord'';\nDELETE FROM registered_groups WHERE folder = ''landing-astro-discord'';\n```\n\n### 2. Set `agent_context_folder` — or identity breaks\n\nWithout `agent_context_folder`, the fallback identity injection fires using `agent.name` from the DB (e.g., \"Landing Astro\", \"Ditto Discord\") — **not** the persona name. The agent will say \"I am Landing Astro\" instead of \"I am PeytonOmni\".\n\nSet this immediately after adding the agent identity file:\n\n```sql\nUPDATE agents SET agent_context_folder = ''agents/peytonomi''\nWHERE id IN (''clayton-discord'', ''landing-astro-discord'');\n```\n\n### 3. Internal bot key vs Discord snowflake ID — never confuse them\n\nOmniClaw uses **two completely different identifiers** for Discord bots:\n\n| Identifier | Where it lives | Example | Used for |\n|---|---|---|---|\n| **Internal bot key** | `DISCORD_BOT_IDS` in `.env` | `PRIMARY`, `OCPEYTON` | OmniClaw routing |\n| **Discord snowflake ID** | Discord Developer Portal → App → General | `1476396931709276191` | Discord''s own API |\n\nThe `channel_subscriptions.discord_bot_id` column stores the **internal bot key** — the human-readable alias you defined in `DISCORD_BOT_IDS`. It must never contain a numeric Discord snowflake ID. If you accidentally write a numeric ID there, OmniClaw''s routing will silently fall back to `DISCORD_DEFAULT_BOT_ID` for every message and scheduled task.\n\nTo verify:\n```bash\n# These should match keys in DISCORD_BOT_IDS, not numeric IDs\nsqlite3 store/messages.db \"SELECT DISTINCT discord_bot_id FROM channel_subscriptions WHERE discord_bot_id IS NOT NULL\"\n```\n\nIf you see numeric IDs, fix them:\n```bash\nsqlite3 store/messages.db \"UPDATE channel_subscriptions SET discord_bot_id = ''OCPEYTON'' WHERE discord_bot_id = ''1476396931709276191''\"\n```\n\n**Separate issue:** When `agent_context_folder` is NULL, the injected identity block contains the bot key string (e.g., `OCPEYTON`, `PRIMARY`) not the persona name. This causes the agent to report conflicting identity info. The fix is always to set `agent_context_folder`.\n\n### 4. `is_primary` controls more than routing — it controls channel name resolution\n\n`is_primary` determines:\n- Which Discord bot handles the channel (sends messages, reactions)\n- Which agent''s name is used as the display name when building channel lists\n- Which subscriptions fire as a fallback when no trigger is explicitly matched\n\nIn a multi-agent channel (e.g., PeytonOmni + OCPeyton both in `#spec`), set `is_primary = 1` **only on the human-persona agent** (e.g., `clayton-discord`). The tool agent (`ocpeyton-discord`) should have `is_primary = 0` so it only responds to explicit `@OCPeyton` mentions and never fires via fallback.\n\nIf `is_primary` is wrong, you''ll see another agent''s name appear as a channel name in the multi-channel list (e.g., \"OCPeyton\" showing up as a channel name in PeytonOmni''s channel list).\n\n```sql\n-- Set primary correctly for each channel\nUPDATE channel_subscriptions SET is_primary = 1\nWHERE agent_id = ''clayton-discord'';  -- persona agent owns the channel\n\nUPDATE channel_subscriptions SET is_primary = 0\nWHERE agent_id = ''ocpeyton-discord'';  -- tool agent never owns\n```\n\n---\n\n## Steps\n\n### Step 1: Inspect current state\n\n```bash\nsqlite3 store/messages.db \"\nSELECT id, name, agent_context_folder FROM agents ORDER BY id;\nSELECT ''---'';\nSELECT channel_jid, agent_id, trigger_pattern, is_primary, channel_folder FROM channel_subscriptions ORDER BY channel_jid, agent_id;\n\"\n```\n\nLook for:\n- Multiple agent entries that are really the same persona (different channel, same trigger/bot)\n- Agents with `agent_context_folder` = NULL (identity will be wrong)\n- Channels where `is_primary` isn''t set correctly\n\n### Step 2: Consolidate legacy agent entries\n\nIdentify agents that are actually just channels for an existing persona. Re-point their subscriptions and delete the agent entry (see gotcha #1 above).\n\n### Step 3: Create agent identity files\n\nFor each distinct persona, create `groups/agents/{id}/CLAUDE.md`:\n\n```bash\nmkdir -p groups/agents/peytonomi\ncat > groups/agents/peytonomi/CLAUDE.md << ''EOF''\n# PeytonOmni Identity\nYou are **PeytonOmni** (@PeytonOmni), ...\nEOF\n```\n\nThen set `agent_context_folder` in the DB immediately (gotcha #2).\n\n### Step 4: Create category directories and CLAUDE.md stubs\n\n```bash\nmkdir -p groups/servers/{server}/{category}/{channel}\n```\n\nCreate a `CLAUDE.md` in each category folder documenting the project context shared across channels.\n\n### Step 5: Migrate legacy folder content to new channel dirs\n\nFor each old flat group folder (e.g., `spec-discord/`, `agentflow-discord/`), copy its contents into the new channel workspace. Use `cp` — never `mv` at this stage, so the original is preserved as a fallback.\n\n```bash\n# Copy all files except logs/ from old folder to new channel dir\nfind groups/spec-discord -maxdepth 1 -not -name ''logs'' -not -path ''groups/spec-discord'' \\\n  -exec cp -r {} groups/servers/omni-aura/ditto-assistant/spec/ \\;\n```\n\nRepeat for each old folder → new path mapping. After copying, verify the new dirs have the expected files.\n\n**If a channel has content in two legacy locations** (e.g., both `ocpeyton-discord/` and `landing-astro-discord/` map to the same new channel), merge them manually — copy one first, then copy the other, skipping any collisions.\n\n#### Offer to clean up old folders\n\nAfter all content is verified in the new locations, use `AskUserQuestion` to ask the user:\n\n> All legacy folder content has been copied to the new channel structure. Want to delete the old folders?\n>\n> - **Yes, delete them** — removes the duplicates, keeps `groups/` clean\n> - **No, keep them** — I''ll show you where everything lives so you can clean up manually later\n\n**If yes:** first check whether any containers are actively running — deleting a folder while a container has it virtiofs-mounted can break the mount mid-run (the host rename makes the path disappear inside the container).\n\n```bash\n# Check for running omniclaw containers\ncontainer list 2>/dev/null | grep omniclaw || echo \"No containers running\"\n```\n\nIf containers are running, use `AskUserQuestion` to ask:\n\n> Some agent containers are currently running. Deleting their workspace folders now could break an in-progress response. What would you like to do?\n>\n> - **Wait and check again** — I''ll re-check in a moment\n> - **Stop the service now** — safest option, agents will pick up again on next restart\n\n**If wait:** re-run the container list check and loop until clear, then delete without stopping the service:\n\n```bash\nrm -rf groups/spec-discord groups/agentflow-discord groups/clayton-discord # etc.\n```\n\n**If stop the service:** unload, delete, reload:\n\n```bash\nlaunchctl unload ~/Library/LaunchAgents/com.omniclaw.plist\nrm -rf groups/spec-discord groups/agentflow-discord groups/clayton-discord # etc.\nlaunchctl load ~/Library/LaunchAgents/com.omniclaw.plist\n```\n\n**If no containers running:** delete directly:\n\n```bash\nrm -rf groups/spec-discord groups/agentflow-discord groups/clayton-discord # etc.\n```\n\n**If no:** print a summary table of old → new paths so the user knows where to look:\n\n```\nLegacy folder                          → New location\ngroups/spec-discord/                   → groups/servers/omni-aura/ditto-assistant/spec/\ngroups/agentflow-discord/              → groups/servers/omni-aura/omniaura/agentflow/\ngroups/clayton-discord/                  → groups/servers/omni-aura/omniaura/agent-debug/\n...\n```\n\n#### Handle orphaned folders\n\nSome old folders may have no active DB entry (no `registered_groups` row, no `channel_subscriptions`). These are stale experiments. Show the user a list and ask if they want them deleted too. Safe to delete if they''re just a CLAUDE.md — worth reviewing first if they have real content.\n\n```bash\n# Find folders with no DB entry\nfor f in groups/*/; do\n  name=$(basename \"$f\")\n  count=$(sqlite3 store/messages.db \"SELECT COUNT(*) FROM registered_groups WHERE folder=''$name''\")\n  [ \"$count\" = \"0\" ] && echo \"Orphaned: $f ($(ls $f | grep -v logs | wc -l | tr -d '' '') files)\"\ndone\n```\n\n### Step 6: Update subscriptions with channel/category folders\n\n```sql\nUPDATE channel_subscriptions\nSET channel_folder = ''servers/omni-aura/ditto-assistant/spec'',\n    category_folder = ''servers/omni-aura/ditto-assistant''\nWHERE channel_jid = ''dc:...'' AND agent_id = ''clayton-discord'';\n```\n\n### Step 7: Set `is_primary` correctly\n\n```sql\n-- Persona agent owns all channels\nUPDATE channel_subscriptions SET is_primary = 1 WHERE agent_id = ''clayton-discord'';\n-- Tool agents never own\nUPDATE channel_subscriptions SET is_primary = 0 WHERE agent_id = ''ocpeyton-discord'';\n```\n\n### Step 8: Strip extra mounts from Discord agents\n\nDiscord agents should not have host filesystem mounts. They should clone repos into their own workspace rather than reading from the host. Legacy `additionalMounts` in `registered_groups.container_config` give Discord agents access to the host filesystem, which can cause confusion (agents following stale docs to wrong paths) and is unnecessary security surface.\n\n**Remove `container_config` from all Discord registered_groups:**\n\n```sql\n-- NULL out container_config for all Discord channels (dc: prefix)\nUPDATE registered_groups\nSET container_config = NULL\nWHERE jid LIKE ''dc:%'';\n```\n\nIf any channel genuinely needs custom mounts (e.g., a local dev agent), restore only that channel''s config explicitly:\n\n```sql\nUPDATE registered_groups\nSET container_config = ''{\"additionalMounts\":[...]}''\nWHERE folder = ''local-dev-agent'';\n```\n\n**Set `nonMainReadOnly: true` in the mount allowlist:**\n\nEdit `~/.config/omniclaw/mount-allowlist.json` and set:\n\n```json\n{\n  \"nonMainReadOnly\": true\n}\n```\n\nThis is belt-and-suspenders: even if `container_config` is accidentally set again, the allowlist prevents any non-main agent from getting write access to extra mounts. Discord agents that need to read/write code should clone the repo into `/workspace/group/` or `/workspace/extra/` and work from there.\n\n### Step 9: Restart and verify\n\n```bash\nlaunchctl unload ~/Library/LaunchAgents/com.omniclaw.plist\nlaunchctl load ~/Library/LaunchAgents/com.omniclaw.plist\n```\n\nAsk each agent: \"what are your debug info / loaded contexts?\" — verify:\n- Identity name matches the persona (not the DB agent name)\n- `/workspace/agent/CLAUDE.md` appears in loaded contexts\n- Channel list shows real channel names, not agent names\n\n---\n\n### Step 10: Remove any legacy heartbeat config\n\nThe heartbeat feature has been removed. Use scheduled tasks (`create_task`) instead — they''re more flexible and don''t silently re-create themselves on restart.\n\nIf any agents or groups had heartbeat configured, it will be automatically NULLed out on first startup (the migration runs in `createSchema()`). But you can also clean it up manually:\n\n```sql\nUPDATE registered_groups SET heartbeat = NULL WHERE heartbeat IS NOT NULL;\nUPDATE agents SET heartbeat = NULL WHERE heartbeat IS NOT NULL;\nDELETE FROM scheduled_tasks WHERE id LIKE ''heartbeat-%'';\n```\n\nAny `## Heartbeat` sections in existing `CLAUDE.md` files are now inert (the system no longer reads them). You can leave them as documentation or migrate the content to a regular scheduled task.\n\n---\n\n## Backward Compatibility\n\n- Agents without `agent_context_folder` → no `/workspace/agent/` mount, identity via `agentName` fallback (works but name may be wrong — see gotcha #2)\n- Subscriptions without `channel_folder` → workspace falls back to agent folder (unchanged behavior)\n- Subscriptions without `category_folder` → no `/workspace/category/` mount (unchanged behavior)\n"},"lastSynced":"2026-03-06T06:58:34.556Z","agentAnalysis":{"suitability":{"en":"Perfect for OmniClaw Agents needing to transition from flat group workspaces to layered context architectures.","zh":"非常适合需要从平面组工作空间转换为分层上下文架构的OmniClaw Agents。","ja":"OmniClaw Agentsが平面グループワークスペースから層化コンテキストアーキテクチャに移行する必要がある場合に最適です。","ko":"평면 그룹 워크스페이스에서 계층화된 컨텍스트 아키텍처로 전환해야 하는 OmniClaw 에이전트에게 적합합니다.","es":"Perfecto para agentes OmniClaw que necesitan transitar desde espacios de trabajo de grupo planos a arquitecturas de contexto en capas.","fr":"Parfait pour les agents OmniClaw qui ont besoin de passer d''espaces de travail de groupe plats à des architectures de contexte en couches.","de":"Perfekt für OmniClaw-Agents, die von flachen Gruppenarbeitsbereichen zu schichtbasierten Kontextarchitekturen wechseln müssen.","pt":"Perfeito para Agentes OmniClaw que precisam fazer a transição de ambientes de trabalho em grupo planos para arquiteturas de contexto em camadas.","ru":"Идеально подходит для агентов OmniClaw, которым необходимо перейти от плоских групповых рабочих пространств к архитектурам контекста с несколькими уровнями.","ar":"مثالي للوكلاء OmniClaw الذين يحتاجون إلى الانتقال من مساحات العمل الجماعي المسطحة إلى هياكل السياق المتدرجة."},"recommendation":{"en":"Empowers agents to transform existing setups into organized structures, utilizing layered context architecture with features like agent identity shared across channels, category team workspaces, and isolated channel notebooks, all while supporting file formats like .md and directory structures such as groups/, servers/, and channels/.","zh":"赋予代理人将现有设置转换为组织结构的能力，利用分层上下文架构，具有跨渠道共享的代理身份、类别团队工作空间和隔离的频道笔记本等功能，同时支持.md文件格式和groups/、servers/、channels/等目录结构。","ja":"エージェントに、既存のセットアップを組織構造に変換する能力を与え、層化コンテキストアーキテクチャを使用し、チャネル間で共有されるエージェントID、カテゴリチームワークスペース、隔離されたチャネルノートブックなどの機能を提供し、同時に.mdファイル形式やgroups/、servers/、channels/などのディレクトリ構造をサポートします。","ko":"기존 설정을 조직 구조로 변환할 수 있는 능력을 에이전트에게 부여하며, 계층화된 컨텍스트 아키텍처를 사용하고, 채널 간에 공유되는 에이전트 ID, 카테고리 팀 워크스페이스, 격리된 채널 노트북などの 기능을 제공하며,同時에 .md 파일 형식과 groups/、servers/、channels/ 등의 디렉토리 구조를 지원합니다.","es":"Habilita a los agentes a transformar las configuraciones existentes en estructuras organizadas, utilizando la arquitectura de contexto en capas con características como la identidad del agente compartida a través de canales, espacios de trabajo de equipo de categorías y cuadernos de canales aislados, todo mientras admite formatos de archivo como .md y estructuras de directorios como grupos/, servidores/ y canales/.","fr":"Permet aux agents de transformer les configurations existantes en structures organisées, en utilisant l''architecture de contexte en couches avec des fonctionnalités comme l''identité de l''agent partagée à travers les canaux, les espaces de travail d''équipe de catégories et les cahiers de canaux isolés, le tout en prenant en charge des formats de fichiers tels que .md et des structures de répertoire comme groups/, servers/ et channels/.","de":"Ermächtigt die Agents, bestehende Einrichtungen in organisierte Strukturen umzuwandeln, indem sie die schichtbasierte Kontextarchitektur mit Funktionen wie der über Kanäle hinweg gemeinsam genutzten Agentenidentität, Kategorie-Teamarbeitsbereichen und isolierten Kanal-Notizbüchern nutzen, und zwar unter gleichzeitiger Unterstützung von Dateiformaten wie .md und Verzeichnisstrukturen wie groups/, servers/ und channels/.","pt":"Habilita os agentes a transformar configurações existentes em estruturas organizadas, utilizando arquitetura de contexto em camadas com recursos como identidade de agente compartilhada em vários canais, espaços de trabalho de equipe de categoria e notebooks de canal isolados, tudo isso enquanto suporta formatos de arquivo como .md e estruturas de diretório como groups/, servers/ e channels/.","ru":"Позволяет агентам преобразовывать существующие настройки в организованные структуры, используя архитектуру контекста с несколькими уровнями с функциями, такими как общая идентичность агента на нескольких каналах, рабочие пространства команд категорий и изолированные канальные ноутбуки, все это при поддержке форматов файлов, таких как .md, и структур директорий, таких как groups/, servers/ и channels/.","ar":"تمكّن الوكلاء من تحويل الإعدادات الحالية إلى هياكل منظمة، مع استخدام هيكل السياق المتدريج مع ميزات مثل هوية الوكيل المشتركة عبر القنوات، وأماكن العمل الفريقية للفئة، ودفاتر القناة المعزولة، مع دعم صيغ الملفات مثل .md وهياكل الدليل مثل groups/ و servers/ و channels/."},"useCases":{"en":["Migrating flat groups to layered channel architectures","Organizing agent identities across multiple channels","Creating isolated channel notebooks for team collaborations"],"zh":["从平面组迁移到层次化频道架构","在多个频道中组织代理身份","为团队协作创建隔离的频道笔记本"],"ja":["平面グループから層化チャネルアーキテクチャへの移行","複数のチャネル間でエージェントIDを整理する","チームコラボレーションのために隔離されたチャネルノートブックを作成する"],"ko":["평면 그룹에서 계층화된 채널 아키텍처로의 마이그레이션","여러 채널에서 에이전트 ID를 조직화하는 것","팀 협업을 위한 격리된 채널 노트북 생성"],"es":["Migrar grupos planos a arquitecturas de canales en capas","Organizar identidades de agentes en múltiples canales","Crear cuadernos de canales aislados para colaboraciones de equipo"],"fr":["Migrer des groupes plats vers des architectures de canaux en couches","Organiser les identités d''agent sur plusieurs canaux","Créer des cahiers de canaux isolés pour des collaborations d''équipe"],"de":["Flache Gruppen in schichtbasierte Kanalarchitekturen migrieren","Agentenidentitäten über mehrere Kanäle hinweg organisieren","Isolierte Kanal-Notizbücher für Teamzusammenarbeiten erstellen"],"pt":["Migrar grupos planos para arquiteturas de canal em camadas","Organizar identidades de agente em vários canais","Criar notebooks de canal isolados para colaborações de equipe"],"ru":["Перемещение плоских групп в архитектуры каналов с несколькими уровнями","Организация идентичности агентов на нескольких каналах","Создание изолированных канальных ноутбуков для командной работы"],"ar":["نقل المجموعات المسطحة إلى هياكل القناة المتدرجة","تنظيم هويات الوكيل عبر القنوات المتعددة","إنشاء دفاتر قناة معزولة للتعاون الفريق"]},"limitations":{"en":["Requires existing OmniClaw setup","Only supports migration to layered context architecture","Directory structure needs to be compatible with groups/, servers/, and channels/ format"],"zh":["需要现有的OmniClaw设置","仅支持迁移到层次化上下文架构","目录结构需要与groups/、servers/、channels/格式兼容"],"ja":["既存のOmniClaw設定が必要","層化コンテキストアーキテクチャへの移行のみをサポート","ディレクトリ構造がgroups/、servers/、channels/形式と互換性がある必要がある"],"ko":["既存의 OmniClaw 설정이 필요합니다.","계층화된 컨텍스트 아키텍처로의 마이그레이션만을 지원합니다.","디렉토리 구조가 groups/、servers/、channels/ 형식과 호환되어야 합니다."],"es":["Requiere una configuración existente de OmniClaw","Solo admite la migración a la arquitectura de contexto en capas","La estructura de directorios debe ser compatible con el formato groups/, servers/ y channels/"],"fr":["Nécessite une configuration existante d''OmniClaw","Ne prend en charge que la migration vers l''architecture de contexte en couches","La structure de répertoire doit être compatible avec le format groups/, servers/ et channels/"],"de":["Benötigt eine bestehende OmniClaw-Konfiguration","Unterstützt nur die Migration zu schichtbasierter Kontextarchitektur","Das Verzeichnis muss mit dem Format groups/, servers/ und channels/ kompatibel sein"],"pt":["Requer configuração existente do OmniClaw","Apenas suporta migração para arquitetura de contexto em camadas","A estrutura de diretório precisa ser compatível com o formato groups/, servers/ e channels/"],"ru":["Требуется существующая настройка OmniClaw","Поддерживает только миграцию в архитектуру контекста с несколькими уровнями","Структура директорий должна быть совместима с форматом groups/, servers/ и channels/"],"ar":["يتطلب إعدادات OmniClaw الحالية","يدعم فقط نقل البيانات إلى هيكل السياق المتدريج","هيكل الدليل يحتاج إلى أن يكون متوافقًا مع صيغة groups/ و servers/ و channels/"]},"version":4},"contentHash":"ec5509bd7b14ee684578191a0d9f1452be60f69b6e16eff3d530146a07716af4","qualityScore":45}');
