INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('omniaura/omniclaw/migrate-to-channels', 'migrate-to-channels', 'omniaura', 'omniclaw', 'community', 'migrate-to-channels omniaura omniclaw community The migrate-to-channels skill migrates existing OmniClaw setups to a new layered context architecture, benefiting developers and teams using group chats. It transforms the flat groups/ workspace model into a more organized structure. Migrate to Channels 是一个总是在线的编码代理，帮助您将 OmniClaw 设置从平面 workspace 模型迁移到新层的上下文架构中 Migrate to Channels は、常にオンのコードエージェントであり、OmniClaw 設定を平面 workspace モデルから新しいレイヤードコンテキストアーキテクチャに移行するのに役立ちます Migrate to Channels는 항상 온라인인 코드 에이전트로, OmniClaw 설정을 평면 workspace 모델에서 새로운 계층화된 컨텍스트 아키텍처로 마이그레이션하는 데 도움을줍니다 El agente de código ''migrate-to-channels'' migra tu configuración de OmniClaw a la arquitectura de canales en capas L''agent de code ''migrate-to-channels'' migre votre configuration OmniClaw vers l''architecture de canaux en couches Der Code-Agent ''migrate-to-channels'' migriert Ihre OmniClaw-Konfiguration auf die schichtbasierte Kanalarchitektur O agente de codificação sempre-ativo migra sua configuração do OmniClaw para a nova arquitetura de canais em camadas Всегда-включенный агент кодирования мигрирует вашу конфигурацию OmniClaw в новую многослойную архитектуру каналов وكيل الترميز دائم التشغيل يهاجر إعدادات OmniClaw إلى هيكل قناة جديد معمّق how to use migrate-to-channels migrate-to-channels setup guide OmniClaw migration tool layered context architecture migrate-to-channels vs OmniClaw migrate-to-channels install channel architecture migration group chat optimization what is migrate-to-channels Migrate to Channels OmniClaw AI 工具 代码代理 层级化上下文架构 agents/{agentId}/CLAUDE.md servers/{server}/{category}/ channels/{name}/ Migrates existing OmniClaw setups to a layered context architecture Transforms flat groups/ workspace model to organized agents, servers, and channels Supports agent identity shared across channels via CLAUDE.md files Creates isolated channel notebooks within servers and categories Handles non-server channels such as WhatsApp and Telegram migrate-to-channels is a skill that migrates OmniClaw setups from a flat groups/ workspace model to a layered context architecture, organizing agents, servers, and channels');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Borda/.home/fix', 'community', 'Borda', '.home', 'Borda/.home', 'fix', 4, 1, 45, '2026-03-03T23:58:18Z', '2026-03-06T06:59:09.296Z', 'ba41b0067c68d42a7abe77ae801df68143b1d75c0d73dc56989b8b52c5b3d50a', '{"id":"Borda/.home/fix","name":"fix","description":{"en":"The fix skill is a collection of AI coding assistant configurations for Python and ML open-source development, helping developers fix software bugs with a reproduce-first workflow.","zh":"Fix 是一个用于 Python 和机器学习开发的 AI 代码错误修复工具，通过复现和测试，找到代码中的错误，并应用最小化修复","ja":"Fix は、Python と機械学習開発用の AI コードバグ修正ツールです。再現とテストを通じて、コードのエラーを特定し、最小限の修正を適用します","ko":"Fix 는 Python 및 머신러닝 개발을 위한 AI 코드 오류 수정 도구입니다. 재현과 테스트를 통해 코드의 오류를 찾고, 최소한의 수정을 적용합니다","es":"Fix es una colección de configuraciones de asistentes de codificación AI personalizados para Python y ML, que optimizan el flujo de trabajo de depuración con pruebas de regresión y verificación de calidad","fr":"Fix est une collection de configurations d''agents de codage IA personnalisés pour Python et ML, qui optimisent le flux de travail de débogage avec des tests de régression et de vérification de la qualité","de":"Fix ist eine Sammlung von Konfigurationen für personalisierte AI-Code-Assistenten für Python und ML, die den Fehlersuch-Workflow mit Regressions-Tests und Qualitätsprüfungen optimieren","pt":"O Fix é uma coleção de configurações de assistentes de codificação AI para corrigir erros de software em Python e ML","ru":"Fix - это коллекция конфигураций помощников кодирования ИИ для исправления ошибок программного обеспечения на Python и ML","ar":"Fix هو مجموعة من إعدادات مساعدي الترميز الذكاء الاصطناعي لتصحيح أخطاء البرمجيات في بيثون و ML"},"seo":{"title":{"en":"fix: Regression Test-Driven Bug Fixing for AI Agents | AI...","zh":"Fix AI 代码错误修复指南","ja":"Fix AI エージェントによるコードバグ修正方法","ko":"Fix AI 에이전트 코드 오류 수정 가이드","es":"Guía de configuración de Fix: Depuración de código Python...","fr":"Guide de configuration de Fix : Débogage de code Python e...","de":"Fix-Setup-Leitfaden: Fehlersuche in Python- und ML-Code","pt":"Guia de Configuração do Fix: Corrija Erros de Software co...","ru":"Настройка Fix: Исправление ошибок программного обеспечени...","ar":"دليل إعداد Fix: إصلاح أخطاء البرمجيات باستخدام وكلاء الذك..."},"description":{"en":"Streamline your Python and ML development with fix, a disciplined reproduce-first workflow. Learn how to setup and use fix to squash bugs for good.","zh":"使用 Fix AI 代码错误修复工具，通过复现和测试，找到代码中的错误，并应用最小化修复","ja":"Fix AI エージェントを使用して、コードのバグを修正します。再現とテストを通じて、エラーの根本原因を特定し、最小限の修正を適用します","ko":"Fix AI 에이전트를 사용하여 코드 오류를 수정합니다. 재현과 테스트를 통해 오류의根本 원인을 찾고, 최소한의 수정을 적용합니다","es":"Aprende a configurar Fix, un agente de código AI para Python y ML, y mejora tu flujo de trabajo de depuración con pruebas de regresión y verificación de calidad","fr":"Découvrez comment configurer Fix, un agent de code IA pour Python et ML, et améliorez votre flux de travail de débogage avec des tests de régression et de vé...","de":"Erfahren Sie, wie Sie Fix, einen AI-Code-Agenten für Python und ML, konfigurieren und Ihren Fehlersuch-Workflow mit Regressions-tests und Qualitätsprüfungen ...","pt":"Aprenda a usar o Fix, uma coleção de configurações de assistentes de codificação AI, para corrigir erros de software de forma eficiente","ru":"Узнайте, как использовать Fix, коллекцию конфигураций помощников кодирования ИИ, для исправления ошибок программного обеспечения","ar":"تعرف على كيفية استخدام Fix، مجموعة من إعدادات مساعدي الترميز الذكاء الاصطناعي، لتصحيح أخطاء البرمجيات بفعالية"},"definition":{"en":"fix is a set of AI agent configurations and automated workflows optimized for Python and ML development, focused on regression test-driven bug fixing.","zh":"Fix 是一个 AI 代码错误修复工具，用于帮助开发者找到代码中的错误并应用最小化修复","ja":"Fix は、コードのバグを修正する AI エージェントです。開発者がエラーを特定し、最小限の修正を適用するのに役立ちます","ko":"Fix 는 코드 오류를 수정하는 AI 에이전트입니다. 개발자가 오류를 찾고, 최소한의 수정을 적용하는 데 도움이 됩니다","es":"Fix es un agente de código AI que ayuda a los desarrolladores a depurar su código Python y ML mediante un flujo de trabajo disciplinado","fr":"Fix est un agent de code IA qui aide les développeurs à déboguer leur code Python et ML via un flux de travail discipliné","de":"Fix ist ein AI-Code-Agent, der Entwicklern hilft, ihren Python- und ML-Code durch einen disziplinierten Workflow zu debuggen","pt":"O Fix é uma ferramenta de correção de erros de software que utiliza AI Agents para identificar e corrigir problemas","ru":"Fix - это инструмент исправления ошибок программного обеспечения, использующий ИИ Агентов для выявления и исправления проблем","ar":"Fix هو أداة لتصحيح أخطاء البرمجيات التي تستخدم وكلاء الذكاء الاصطناعي لتحديد ومعالجة المشكلات"},"features":{"en":["Applies minimal fix after capturing bug in a regression test","Verifies all tests pass before finishing with linting and quality checks","Utilizes GitHub for bug description and issue tracking","Supports plain text input for bug descriptions","Creates regression tests to prevent re-introduction of bugs","Works with Codex and Claude agents for AI-powered coding assistance"],"zh":["支持 Python 和机器学习开发","通过复现和测试找到代码中的错误","应用最小化修复","使用 GitHub_issue 进行错误报告","支持 CLI 命令行工具"],"ja":["Python と機械学習開発をサポート","再現とテストを通じてコードのエラーを特定","最小限の修正を適用","GitHub_issue を使用したエラー報告","CLI コマンドラインツールをサポート"],"ko":["Python 및 머신러닝 개발을 지원","재현과 테스트를 통해 코드의 오류를 찾기","최소한의 수정을 적용","GitHub_issue 를 사용한 오류 보고","CLI 명령줄 도구를 지원"],"es":["Depuración de código Python y ML con pruebas de regresión","Verificación de calidad y linting","Flujo de trabajo disciplinado para la resolución de errores","Integración con GitHub","Compatibilidad con CLI"],"fr":["Débogage de code Python et ML avec des tests de régression","Vérification de la qualité et linting","Flux de travail discipliné pour la résolution d''erreurs","Intégration avec GitHub","Compatibilité avec CLI"],"de":["Fehlersuche in Python- und ML-Code mit Regressions-Tests","Qualitätsprüfung und Linting","Disziplinierter Workflow für die Fehlersuche","Integration mit GitHub","Kompatibilität mit CLI"],"pt":["Correção de erros de software com workflow de reprodução","Utilização de regression tests para capturar erros","Aplicação de correções mínimas e verificação de testes","Integração com GitHub para relatar erros","Suporte a Python e ML para desenvolvimento de software"],"ru":["Исправление ошибок программного обеспечения с помощью workflow воспроизведения","Использование regression tests для обнаружения ошибок","Применение минимальных исправлений и проверка тестов","Интеграция с GitHub для отчета об ошибках","Поддержка Python и ML для разработки программного обеспечения"],"ar":["تصحيح أخطاء البرمجيات باستخدام تدفق الإعادة","استخدام اختبارات الانحدار لالتقاط الأخطاء","تطبيق الإصلاحات الطفيفة وتحقق من الاختبارات","التكامل مع GitHub لتقديم تقارير عن الأخطاء","دعم بيثون و ML لتصميم البرمجيات"]},"keywords":{"en":["how to use fix for bug fixing","fix setup guide for Python developers","fix vs Codex for AI-powered coding","regression test-driven development with fix","fix install for ML open-source projects","what is fix and how it works","fix alternative for automated workflows","fix for GitHub issue tracking and management"],"zh":["AI 代码错误修复","Python 开发工具","机器学习开发工具","代码错误修复方法","Fix AI 代码错误修复","AI 代码测试工具"],"ja":["AI コードバグ修正","Python 開発ツール","機械学習開発ツール","コードバグ修正方法","Fix AI コードバグ修正","AI コードテストツール"],"ko":["AI 코드 오류 수정","Python 개발 도구","머신러닝 개발 도구","코드 오류 수정 방법","Fix AI 코드 오류 수정","AI 코드 테스트 도구"],"es":["agentes de código AI","herramientas de depuración de Python","herramientas de depuración de ML","pruebas de regresión","verificación de calidad","linting","flujo de trabajo de depuración","GitHub","CLI"],"fr":["agents de code IA","outils de débogage Python","outils de débogage ML","tests de régression","vérification de la qualité","linting","flux de travail de débogage","GitHub","CLI"],"de":["AI-Code-Agenten","Fehlersuch-Tools für Python","Fehlersuch-Tools für ML","Regressions-Tests","Qualitätsprüfung","Linting","Fehlersuch-Workflow","GitHub","CLI"],"pt":["AI Agents para correção de erros","Fix de software","Desenvolvimento de software em Python","ML para correção de erros","Regression tests","GitHub para relatar erros","Correção de erros de software com AI","Workflow de reprodução para correção de erros"],"ru":["ИИ Агенты для исправления ошибок","Исправление программного обеспечения","Разработка программного обеспечения на Python","ML для исправления ошибок","Regression tests","GitHub для отчета об ошибках","Исправление ошибок программного обеспечения с помощью ИИ","Workflow воспроизведения для исправления ошибок"],"ar":["وكلاء الذكاء الاصطناعي لتصحيح الأخطاء","تصحيح البرمجيات","تصميم البرمجيات باستخدام بيثون","ML لتصحيح الأخطاء","اختبارات الانحدار","GitHub لتقديم تقارير عن الأخطاء","تصحيح أخطاء البرمجيات باستخدام الذكاء الاصطناعي","تدفق الإعادة لتصحيح الأخطاء"]}},"owner":"Borda","repo":".home","repoPath":"Borda/.home","stars":4,"forks":1,"updatedAt":"2026-03-03T23:58:18Z","topics":["ai-agents","claude-agents","claude-code","claude-skills","codex","codex-agents","codex-cli"],"category":"community","skillMd":{"name":"fix","description":"Bug-fixing workflow — diagnose the problem, reproduce it with a regression test, apply a targeted fix, then verify with linting, quality checks, and optional optimization.","bodyPreview":"<objective>\n\nFix software bugs with a disciplined reproduce-first workflow. Before touching any code, understand the root cause and capture the bug in a regression test. Then apply the minimal fix, verify all tests pass, and finish with linting and quality checks. The regression test stays in the codebase to prevent re-introduction.\n\n</objective>\n\n<inputs>\n\n- **$ARGUMENTS**: required — one of:\n  - A bug description in plain text (e.g., `\"TypeError when passing None to transform()\"`)\n  - A GitHub","body":"<objective>\n\nFix software bugs with a disciplined reproduce-first workflow. Before touching any code, understand the root cause and capture the bug in a regression test. Then apply the minimal fix, verify all tests pass, and finish with linting and quality checks. The regression test stays in the codebase to prevent re-introduction.\n\n</objective>\n\n<inputs>\n\n- **$ARGUMENTS**: required — one of:\n  - A bug description in plain text (e.g., `\"TypeError when passing None to transform()\"`)\n  - A GitHub issue number (e.g., `123` — fetched via `gh issue view`)\n  - An error message or traceback snippet\n  - A failing test name (e.g., `tests/test_transforms.py::test_none_input`)\n\n</inputs>\n\n<workflow>\n\n**Task tracking**: per CLAUDE.md, create tasks (TaskCreate) for each major phase. Mark in_progress/completed throughout. On loop retry or scope change, create a new task.\n\n## Step 1: Understand the problem\n\nGather all available context about the bug:\n\n```bash\n# If issue number: fetch the full issue with comments\ngh issue view <number> --comments\n```\n\nIf an error message or pattern was provided: use the Grep tool (pattern `<error_pattern>`, path `.`) to search the codebase for the failing code path. Adjust to `src/`, `lib/`, or `app/` as appropriate for the project layout.\n\n```bash\n\n# If failing test: run it to capture the exact failure\npython -m pytest <test_path> -v --tb=long 2>&1 | tail -40\n```\n\nSpawn a **sw-engineer** agent to analyze the failing code path and identify:\n\n- The root cause (not just the symptom)\n- The minimal code surface that needs to change\n- Any related code that might be affected by the fix\n\n## Step 2: Reproduce the bug\n\nCreate or identify a test that demonstrates the failure:\n\n```bash\n# If a failing test already exists — run it to confirm it fails\npython -m pytest <test_file>::<test_name> -v --tb=short\n\n# If no test exists — write a regression test that captures the bug\n# Name it: test_<function>_<bug_description> (e.g., test_transform_none_input)\n```\n\nSpawn a **qa-specialist** agent to write the regression test if one doesn''t exist:\n\n- The test must **fail** against the current code (proving the bug exists)\n- Use `pytest.mark.parametrize` if the bug affects multiple input patterns\n- Keep the test minimal — exercise exactly the broken behavior\n- Add a brief comment linking to the issue if applicable (e.g., `# Regression test for #123`)\n\n**Gate**: the regression test must fail before proceeding. If it passes, the bug isn''t properly captured — revisit Step 1.\n\n## Step 3: Apply the fix\n\nMake the minimal change to fix the root cause:\n\n1. Edit only the code necessary to resolve the bug\n2. Run the regression test to confirm it now passes:\n   ```bash\n   python -m pytest <test_file>::<test_name> -v --tb=short\n   ```\n3. Run the full test suite for the affected module to check for regressions:\n   ```bash\n   # Step 3: regression gate — confirms fix does not break existing tests\n   python -m pytest <test_dir> -v --tb=short\n   ```\n4. If any existing tests break: the fix has side effects — reconsider the approach\n\n## Step 4: Linting and quality\n\nSpawn a **linting-expert** agent (or run directly) to ensure the fix meets code quality standards:\n\n```bash\n# Run ruff for linting and formatting\nruff check <changed_files> --fix\nruff format <changed_files>\n\n# Run mypy for type checking if configured\nmypy <changed_files> --no-error-summary 2>&1 | head -20\n\n# Step 4: final full-suite clean run before commit\npython -m pytest <test_dir> -v --tb=short\n```\n\n## Step 5: Verify and report\n\nOutput a structured report:\n\n```\n## Fix Report: <bug summary>\n\n### Root Cause\n[1-2 sentence explanation of what was wrong and why]\n\n### Regression Test\n- File: <test_file>\n- Test: <test_name>\n- Confirms: [what behavior the test locks in]\n\n### Changes Made\n| File | Change | Lines |\n|------|--------|-------|\n| path/to/file.py | description of fix | -N/+M |\n\n### Test Results\n- Regression test: PASS\n- Full suite: PASS (N tests)\n- Lint: clean\n\n### Follow-up\n- [any related issues or code that should be reviewed]\n\n## Confidence\n**Score**: [0.N]\n**Gaps**: [e.g., could not reproduce locally, partial traceback only, fix not runtime-tested]\n```\n\n## Team Mode (--team)\n\nUse when the bug has competing root-cause hypotheses or spans multiple modules. Skip for single-file bugs — use the default workflow above.\n\nWhen to trigger: root cause is unclear after Step 1, OR the bug manifests across 3+ modules.\n\n**Workflow with --team:**\n\n1. Lead spawns 2–3 **sw-engineer** teammates, each investigating a distinct hypothesis\n2. Broadcast current evidence to all teammates: `broadcast {bug: <description>, traceback: <key lines>}`\n3. Each teammate investigates independently — announces with `alpha PROTO:v2.0` and claims a hypothesis\n4. Teammates report findings via lead (hub-and-spoke); lead facilitates cross-challenge between competing analyses\n5. Lead synthesizes the consensus root cause, then proceeds with Steps 2–5 above (regression test, fix, lint, report) — all in lead context\n\n**Spawn prompt template:**\n\n```\nYou are a sw-engineer teammate debugging: [bug description].\nRead .claude/TEAM_PROTOCOL.md — use AgentSpeak v2 for inter-agent messages.\nYour hypothesis: [hypothesis N]. Investigate ONLY this root cause.\nReport findings to @lead using deltaT# or epsilonT# codes.\nCompact Instructions: preserve file paths, errors, line numbers. Discard verbose tool output.\n```\n\n</workflow>\n\n<notes>\n\n- **Reproduce first**: never fix a bug you can''t demonstrate with a test — the test is the proof\n- **Minimal fix**: change only what''s necessary to resolve the root cause — avoid incidental refactoring\n- The regression test is a permanent contribution — it prevents the bug from recurring\n- If the bug is in `.claude/` config files: run `self-mentor` audit + `/sync` after fixing\n- Related agents: `sw-engineer` (root cause analysis), `qa-specialist` (regression test), `linting-expert` (quality)\n- Follow-up chains:\n  - Fix involves structural improvements beyond the bug → `/refactor` for test-first code quality pass\n  - Fix touches non-trivial code paths → `/review` for full multi-agent quality validation\n  - Fix required consistent renames or annotation changes across many files → `/codex` to delegate the mechanical sweep\n\n</notes>\n"},"lastSynced":"2026-03-06T06:59:09.296Z","agentAnalysis":{"suitability":{"en":"Perfect for Debugging Agents needing a reproduce-first workflow for Python and ML open-source development.","zh":"非常适合需要为 Python 和 ML 开源开发提供重现优先工作流的调试代理。","ja":"Python と ML のオープンソース開発向けに再現優先のワークフローを必要とするデバッグ エージェントに最適。","ko":"Python 및 ML 오픈소스 개발을 위한 재현 우선 워크플로가 필요한 디버깅 에이전트에 적합합니다.","es":"Perfecto para Agentes de Depuración que necesitan un flujo de trabajo de reproducción primero para el desarrollo de código abierto de Python y ML.","fr":"Parfait pour les Agents de Débogage nécessitant un workflow de reproduction en premier pour le développement open-source Python et ML.","de":"Perfekt für Debugging-Agents, die einen reproduzierbaren Workflow für die Open-Source-Entwicklung von Python und ML benötigen.","pt":"Perfeito para Agentes de Depuração que necessitam de um fluxo de trabalho de reprodução em primeiro lugar para desenvolvimento de código aberto em Python e ML.","ru":"Идеально подходит для отладочных агентов, которым необходим рабочий процесс reproduce-first для открытого разработки Python и ML.","ar":"مثالي للوكلاء الذين يحتاجون إلى تدفق عمل إعادة الإنتاج أولاً لتطوير البرمجيات مفتوحة المصدر باستخدام Python و ML."},"recommendation":{"en":"Empowers agents to fix software bugs using a disciplined approach with regression tests, minimal fixes, and quality checks, leveraging Python and ML libraries for comprehensive debugging.","zh":"赋予代理使用严格的方法修复软件 bug 的能力，包括回归测试、最小修复和质量检查，利用 Python 和 ML 库进行全面调试。","ja":"回帰テスト、最小限の修正、品質チェックを使用した規律あるアプローチでソフトウェアのバグを修正するエージェントをEmpowerし、Python と ML ライブラリを使用して包括的なデバッグを行う。","ko":"회귀 테스트, 최소한의 수정 및 품질检查을 사용하여 규율적인 접근 방식을 사용하여 소프트웨어 버그를 수정하는 에이전트를 Empower하고 Python 및 ML 라이브러리를 사용하여 포괄적인 디버깅을 수행한다.","es":"Habilita a los agentes a solucionar errores de software utilizando un enfoque disciplinado con pruebas de regresión, soluciones mínimas y verificaciones de calidad, aprovechando las bibliotecas de Python y ML para una depuración integral.","fr":"Permet aux agents de corriger les bogues logiciels en utilisant une approche disciplinée avec des tests de régression, des corrections minimales et des vérifications de qualité, en exploitant les bibliothèques Python et ML pour un débogage complet.","de":"Ermächtigt Agenten, Softwarefehler mithilfe eines disziplinierten Ansatzes mit RegressionsTests, minimalen Korrekturen und Qualitätskontrollen zu beheben, indem Python- und ML-Bibliotheken für eine umfassende Fehlersuche genutzt werden.","pt":"Habilita os agentes a corrigir bugs de software usando uma abordagem disciplinada com testes de regressão, correções mínimas e verificações de qualidade, aproveitando as bibliotecas Python e ML para depuração abrangente.","ru":"Наделяет агентов возможностью исправлять программные ошибки, используя дисциплинированный подход с регрессионными тестами, минимальными исправлениями и проверками качества, используюя библиотеки Python и ML для всесторонней отладки.","ar":"تمكن الوكلاء من إصلاح أعطال البرمجيات باستخدام نهج منضبط مع اختبارات الانحدار والتصحيحات المعدلة والتحقق من الجودة، واستخدام مكتبات Python و ML للتصحيح الشامل."},"useCases":{"en":["Debugging TypeError exceptions in Python code","Generating regression tests for ML model bugs","Applying minimal fixes to software bugs with linting and quality checks"],"zh":["调试 Python 代码中的 TypeError 异常","为 ML 模型 bug 生成回归测试","使用 linting 和质量检查对软件 bug 应用最小修复"],"ja":["Python コード内の TypeError 例外のデバッグ","ML モデル バグの回帰テストの生成","linting と品質チェックを使用したソフトウェア バグへの最小限の修正の適用"],"ko":["Python 코드의 TypeError 예외 디버깅","ML 모델 버그에 대한 회귀 테스트 생성","린팅 및 품질 확인을 사용한 소프트웨어 버그에 대한 최소한의 수정 적용"],"es":["Depuración de excepciones TypeError en código Python","Generación de pruebas de regresión para errores de modelos ML","Aplicación de soluciones mínimas a errores de software con verificación de estilo y verificaciones de calidad"],"fr":["Débogage des exceptions TypeError dans le code Python","Génération de tests de régression pour les bogues de modèles ML","Application de corrections minimales aux bogues logiciels avec vérification de style et vérifications de qualité"],"de":["Fehlersuche für TypeError-Ausnahmen in Python-Code","Generierung von RegressionsTests für ML-Modellfehler","Anwendung von minimalen Korrekturen auf Softwarefehler mit Stilprüfung und Qualitätskontrollen"],"pt":["Depurar exceções TypeError no código Python","Gerar testes de regressão para bugs de modelo ML","Aplicar correções mínimas a bugs de software com linting e verificações de qualidade"],"ru":["Отладка исключений TypeError в коде Python","Генерация регрессионных тестов для ошибок модели ML","Применение минимальных исправлений к программным ошибкам с помощью linting и проверок качества"],"ar":["تصحيح استثناءات TypeError في رمز Python","توليد اختبارات انحدار لعيوب نموذج ML","تطبيق إصلاحات دقيقة على أعطال البرمجيات باستخدام linting والتحقق من الجودة"]},"limitations":{"en":["Requires Python and ML open-source development environment","Limited to GitHub issues or plain text bug descriptions as input"],"zh":["需要 Python 和 ML 开源开发环境","仅限于 GitHub 问题或纯文本 bug 描述作为输入"],"ja":["Python と ML のオープンソース開発環境が必要","入力として GitHub の問題またはプレーンテキストのバグ説明のみに限定"],"ko":["Python 및 ML 오픈소스 개발 환경이 필요","입력으로 GitHub 문제 또는 평문 버그 설명만으로 제한"],"es":["Requiere un entorno de desarrollo de código abierto de Python y ML","Limitado a problemas de GitHub o descripciones de errores de texto plano como entrada"],"fr":["Nécessite un environnement de développement open-source Python et ML","Limité aux problèmes GitHub ou aux descriptions d''erreurs de texte brut comme entrée"],"de":["Benötigt eine Open-Source-Entwicklungsumgebung für Python und ML","Begrenzt auf GitHub-Probleme oder Klartextfehlerbeschreibungen als Eingabe"],"pt":["Exige ambiente de desenvolvimento de código aberto em Python e ML","Limitado a problemas do GitHub ou descrições de bugs em texto simples como entrada"],"ru":["Требует среды разработки открытого кода Python и ML","Ограничен проблемами GitHub или описаниями ошибок в простом тексте в качестве входных данных"],"ar":["يتطلب بيئة تطوير برمجيات مفتوحة المصدر باستخدام Python و ML","محدود بمشاكل GitHub أو أوصاف الأعطال النصية البسيطة كمدخل"]},"version":4},"contentHash":"ba41b0067c68d42a7abe77ae801df68143b1d75c0d73dc56989b8b52c5b3d50a","qualityScore":45}');
