INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Borda/.home/fix', 'fix', 'Borda', '.home', 'community', 'fix Borda .home community ai-agents claude-agents claude-code claude-skills codex codex-agents codex-cli The fix skill is a collection of AI coding assistant configurations for Python and ML open-source development, helping developers fix software bugs with a reproduce-first workflow. Fix 是一个用于 Python 和机器学习开发的 AI 代码错误修复工具，通过复现和测试，找到代码中的错误，并应用最小化修复 Fix は、Python と機械学習開発用の AI コードバグ修正ツールです。再現とテストを通じて、コードのエラーを特定し、最小限の修正を適用します Fix 는 Python 및 머신러닝 개발을 위한 AI 코드 오류 수정 도구입니다. 재현과 테스트를 통해 코드의 오류를 찾고, 최소한의 수정을 적용합니다 Fix es una colección de configuraciones de asistentes de codificación AI personalizados para Python y ML, que optimizan el flujo de trabajo de depuración con pruebas de regresión y verificación de calidad Fix est une collection de configurations d''agents de codage IA personnalisés pour Python et ML, qui optimisent le flux de travail de débogage avec des tests de régression et de vérification de la qualité Fix ist eine Sammlung von Konfigurationen für personalisierte AI-Code-Assistenten für Python und ML, die den Fehlersuch-Workflow mit Regressions-Tests und Qualitätsprüfungen optimieren O Fix é uma coleção de configurações de assistentes de codificação AI para corrigir erros de software em Python e ML Fix - это коллекция конфигураций помощников кодирования ИИ для исправления ошибок программного обеспечения на Python и ML Fix هو مجموعة من إعدادات مساعدي الترميز الذكاء الاصطناعي لتصحيح أخطاء البرمجيات في بيثون و ML how to use fix for bug fixing fix setup guide for Python developers fix vs Codex for AI-powered coding regression test-driven development with fix fix install for ML open-source projects what is fix and how it works fix alternative for automated workflows fix for GitHub issue tracking and management AI 代码错误修复 Python 开发工具 机器学习开发工具 代码错误修复方法 Fix AI 代码错误修复 AI 代码测试工具 Applies minimal fix after capturing bug in a regression test Verifies all tests pass before finishing with linting and quality checks Utilizes GitHub for bug description and issue tracking Supports plain text input for bug descriptions Creates regression tests to prevent re-introduction of bugs Works with Codex and Claude agents for AI-powered coding assistance fix is a set of AI agent configurations and automated workflows optimized for Python and ML development, focused on regression test-driven bug fixing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('losfair/zeroserve/zeroserve-script-create', 'community', 'losfair', 'zeroserve', 'losfair/zeroserve', 'zeroserve-script-create', 4, 0, 45, '2026-02-07T07:29:48Z', '2026-03-06T06:59:45.474Z', '7b4e6614bd991cabf0ca2e0b446cf9a8aa7df556a8f7e9fd5b1c5564840e9131', '{"id":"losfair/zeroserve/zeroserve-script-create","name":"zeroserve-script-create","description":{"en":"The zeroserve-script-create skill generates a high-performance, scriptable HTTP server using io_uring and eBPF, serving static websites from tarballs with optional eBPF request scripts. It benefits developers seeking fast and efficient server setup.","zh":"Zeroserve 脚本创建工具是用于创建基于 io_uring 的 HTTPS 服务器的工具，支持 eBPF 和静态网站托管。它可以快速创建高性能的 HTTP 服务器","ja":"Zeroserve スクリプト作成ツールは、io_uring ベースの HTTPS サーバーを作成するためのツールです。eBPF と静的 Web サイトのホスティングをサポートしています","ko":"Zeroserve 스크립트 생성 도구는 io_uring 기반의 HTTPS 서버를 생성하는 도구입니다. eBPF 및 정적 웹 사이트 호스팅을 지원합니다","es":"Zeroserve Script Create es un servidor HTTP de alto rendimiento que utiliza io_uring y eBPF. Crea un script de solicitud en C para servir sitios web estáticos desde un tarball.","fr":"Zeroserve Script Create est un serveur HTTP haute performance qui utilise io_uring et eBPF. Il crée un script de requête en C pour servir des sites web statiques à partir d''un tarball.","de":"Zeroserve Script Create ist ein Hochleistungs-HTTP-Server, der io_uring und eBPF verwendet. Er erstellt ein Anfrage-Skript in C, um statische Websites aus einem Tarball zu servieren.","pt":"O Zeroserve-Script-Create é um servidor HTTPS de alta performance baseado em io_uring e eBPF, que serve sites estáticos a partir de um tarball e executa scripts de solicitação eBPF.","ru":"Zeroserve-Script-Create - это высокопроизводительный сервер HTTPS на основе io_uring и eBPF, который обслуживает статические сайты из tarball и запускает скрипты запросов eBPF.","ar":"Zeroserve-Script-Create هو خادم HTTPS سريع وآمن يستند إلى io_uring و eBPF، يقوم بخدمة مواقع إلكترونية ثابتة من tarball وتنفيذ scripts الطلب eBPF."},"seo":{"title":{"en":"zeroserve-script-create: Fast HTTPS Server Setup Guide | ...","zh":"Zeroserve 脚本创建指南 - 基于 io_uring 的 HTTPS 服务器","ja":"Zeroserve スクリプト作成ガイド - io_uring ベースの HTTPS サーバー","ko":"Zeroserve 스크립트 생성 가이드 - io_uring 기반 HTTPS 서버","es":"Configuración de Zeroserve Script Create: Guía de inicio ...","fr":"Mise en place de Zeroserve Script Create: Meilleures prat...","de":"Zeroserve Script Create Einrichtung: Leitfaden für Entwic...","pt":"Guia de Configuração do Zeroserve-Script-Create: Servidor...","ru":"Настройка Zeroserve-Script-Create: ИИ Агенты для Сервера ...","ar":"دليل إعداد Zeroserve-Script-Create: خادم HTTPS سريع وآمن"},"description":{"en":"Discover how zeroserve-script-create simplifies HTTPS server creation with io_uring and eBPF. Learn how to get started and optimize your workflow today!","zh":"使用 Zeroserve 脚本创建工具，快速创建基于 io_uring 的 HTTPS 服务器，支持 eBPF 和静态网站托管","ja":"Zeroserve スクリプト作成ツールを使用して、io_uring ベースの HTTPS サーバーを迅速に作成します。eBPF と静的 Web サイトのホスティングをサポートしています","ko":"Zeroserve 스크립트 생성 도구를 사용하여 io_uring 기반의 HTTPS 서버를 빠르게 생성합니다. eBPF 및 정적 웹 사이트 호스팅을 지원합니다","es":"Descubre cómo crear un servidor HTTPS de alto rendimiento con Zeroserve Script Create, utilizando io_uring y eBPF para desarrolladores","fr":"Découvrez comment créer un serveur HTTPS haute performance avec Zeroserve Script Create, en utilisant io_uring et eBPF pour les développeurs","de":"Erfahren Sie, wie Sie einen Hochleistungs-HTTPS-Server mit Zeroserve Script Create erstellen, unter Verwendung von io_uring und eBPF für Entwickler","pt":"Aprenda a configurar o Zeroserve-Script-Create, um servidor HTTPS de alta performance baseado em io_uring e eBPF, perfeito para desenvolvedores","ru":"Узнайте, как настроить Zeroserve-Script-Create, высокопроизводительный сервер HTTPS на основе io_uring и eBPF, идеальный для разработчиков","ar":"تعرف على كيفية إعداد Zeroserve-Script-Create، خادم HTTPS سريع وآمن يستند إلى io_uring و eBPF، مناسب للمطورين"},"definition":{"en":"zeroserve-script-create is a zero-config, fast io_uring-based HTTPS server skill that creates a Zeroserve request script in C from requirements.","zh":"Zeroserve 脚本创建工具是一种用于创建基于 io_uring 的 HTTPS 服务器的工具，用于生成高性能的 HTTP 服务器","ja":"Zeroserve スクリプト作成ツールは、io_uring ベースの HTTPS サーバーを作成するためのツールです","ko":"Zeroserve 스크립트 생성 도구는 io_uring 기반의 HTTPS 서버를 생성하는 도구입니다","es":"Zeroserve Script Create es una herramienta de AI que crea scripts de solicitud en C para servidores HTTP de alto rendimiento","fr":"Zeroserve Script Create est un outil d''IA qui crée des scripts de requête en C pour les serveurs HTTP haute performance","de":"Zeroserve Script Create ist ein AI-Tool, das Anfrage-Skripte in C für Hochleistungs-HTTP-Server erstellt","pt":"O que é Zeroserve-Script-Create? É um servidor HTTPS de alta performance que usa io_uring e eBPF para servir sites estáticos e executar scripts de solicitação.","ru":"Что такое Zeroserve-Script-Create? Это высокопроизводительный сервер HTTPS, который использует io_uring и eBPF для обслуживания статических сайтов и запуска скриптов запросов.","ar":"ما هو Zeroserve-Script-Create؟ هو خادم HTTPS سريع وآمن يستخدم io_uring و eBPF لخدمة مواقع إلكترونية ثابتة وتنفيذ scripts الطلب."},"features":{"en":["Uses io_uring for high-performance HTTPS serving","Supports eBPF request scripts for customizable server behavior","Serves static websites from tarballs","Optional hot reload for efficient development","Small templating pass for text responses","Opt-in reverse proxy from scripts"],"zh":["基于 io_uring 的 HTTPS 服务器","支持 eBPF","静态网站托管","热重载","小型模板传递文本响应","可选的反向代理"],"ja":["io_uring ベースの HTTPS サーバー","eBPF のサポート","静的 Web サイトのホスティング","ホットリロード","小型テンプレートパスによるテキスト応答","オプションのリバースプロキシ"],"ko":["io_uring 기반의 HTTPS 서버","eBPF 지원","정적 웹 사이트 호스팅","핫 리로드","소형 템플릿 전달 텍스트 응답","옵션의 리버스 프록시"],"es":["Utiliza io_uring para un rendimiento óptimo","Soporta HTTP y HTTPS","Incluye hot reload y templating para respuestas de texto","Permite proxy inverso desde scripts","Utiliza eBPF para scripts de solicitud personalizados"],"fr":["Utilise io_uring pour un rendement optimal","Prend en charge HTTP et HTTPS","Inclut hot reload et templating pour les réponses de texte","Permet un proxy inverse depuis les scripts","Utilise eBPF pour les scripts de requête personnalisés"],"de":["Verwendet io_uring für optimale Leistung","Unterstützt HTTP und HTTPS","Enthält Hot Reload und Templating für Textantworten","Ermöglicht Reverse-Proxy von Skripten aus","Verwendet eBPF für benutzerdefinierte Anfrage-Skripte"],"pt":["Suporte a HTTP e HTTPS","Uso de io_uring para alta performance","Suporte a eBPF para scripts de solicitação","Recarga quente para atualizações rápidas","Passagem de modelo de texto para respostas personalizadas"],"ru":["Поддержка HTTP и HTTPS","Использование io_uring для высокой производительности","Поддержка eBPF для скриптов запросов","Горячая перезагрузка для быстрых обновлений","Прохождение текстового шаблона для персонализированных ответов"],"ar":["دعم HTTP و HTTPS","استخدام io_uring لتحقيق الأداء العالي","دعم eBPF لتنفيذ scripts الطلب","إعادة تحميل ساخنة للتحديثات السريعة","مرور قالب النص للردود المخصصة"]},"keywords":{"en":["how to use zeroserve-script-create","zeroserve-script-create alternative","zeroserve-script-create setup guide","io_uring HTTPS server","eBPF request scripts","zeroserve-script-create vs nginx","install zeroserve-script-create","what is zeroserve-script-create","zeroserve-script-create tutorial"],"zh":["Zeroserve 脚本创建","io_uring","HTTPS 服务器","eBPF","静态网站托管","AIエージェント","脚本创建工具","高性能 HTTP 服务器"],"ja":["Zeroserve スクリプト作成","io_uring","HTTPS サーバー","eBPF","静的 Web サイトのホスティング","AIエージェント","スクリプト作成ツール","高性能 HTTP サーバー"],"ko":["Zeroserve 스크립트 생성","io_uring","HTTPS 서버","eBPF","정적 웹 사이트 호스팅","AI 에이전트","스크립트 생성 도구","고성능 HTTP 서버"],"es":["Zeroserve Script Create","servidor HTTP de alto rendimiento","io_uring","eBPF","desarrollo web","herramientas de AI para desarrolladores","creación de scripts de solicitud en C"],"fr":["Zeroserve Script Create","serveur HTTP haute performance","io_uring","eBPF","développement web","outils d''IA pour les développeurs","création de scripts de requête en C"],"de":["Zeroserve Script Create","Hochleistungs-HTTP-Server","io_uring","eBPF","Webentwicklung","AI-Tools für Entwickler","Erstellung von Anfrage-Skripten in C"],"pt":["Zeroserve-Script-Create","servidor HTTPS de alta performance","io_uring","eBPF","desenvolvimento web","servidor de sites estáticos","scripts de solicitação","recarga quente"],"ru":["Zeroserve-Script-Create","высокопроизводительный сервер HTTPS","io_uring","eBPF","веб-разработка","сервер статических сайтов","скрипты запросов","горячая перезагрузка"],"ar":["Zeroserve-Script-Create","خادم HTTPS سريع وآمن","io_uring","eBPF","تطوير الويب","خادم مواقع إلكترونية ثابتة","scripts الطلب","إعادة تحميل ساخنة"]}},"owner":"losfair","repo":"zeroserve","repoPath":"losfair/zeroserve","stars":4,"forks":0,"updatedAt":"2026-02-07T07:29:48Z","topics":[],"category":"community","skillMd":{"name":"zeroserve-script-create","description":"Create Zeroserve eBPF request-processing scripts in C for `.zeroserve/scripts` using the Zeroserve SDK (`zeroserve.h`). Use when you need to implement request inspection, header/query parsing, metadata templating, custom responses, or reverse-proxy behavior in a script.","bodyPreview":"# Zeroserve Script Create\n\n## Overview\n\nZeroserve is a high-performance, scriptable HTTP server that uses `io_uring` and eBPF. It\nserves a static website from a tarball, and optionally runs eBPF request scripts.\nIt supports HTTP, HTTPS, hot reload, a small templating pass for text responses, and\nan opt-in reverse proxy from scripts.\n\nThis skill creates a Zeroserve request script in C from requirements, using the SDK helpers\nand eBPF constraints. Output is a single `.c` file ready to place under","body":"# Zeroserve Script Create\n\n## Overview\n\nZeroserve is a high-performance, scriptable HTTP server that uses `io_uring` and eBPF. It\nserves a static website from a tarball, and optionally runs eBPF request scripts.\nIt supports HTTP, HTTPS, hot reload, a small templating pass for text responses, and\nan opt-in reverse proxy from scripts.\n\nThis skill creates a Zeroserve request script in C from requirements, using the SDK helpers\nand eBPF constraints. Output is a single `.c` file ready to place under `.zeroserve/scripts/`.\nIt includes JSON helper usage for parsing structured inputs from headers or params.\n\n## Basic zeroserve usage\n\nServe a prebuilt tarball:\n\n```bash\nzeroserve --addr 0.0.0.0:8080 site.tar\n```\n\nPackage a directory into a tarball and serve it:\n\n```bash\n# Create a tarball from the current directory\nzeroserve --pack . > site.tar\n\n# Serve it\nzeroserve --addr 0.0.0.0:8080 site.tar\n```\n\nPackaging a site: Zeroserve expects a tarball whose root corresponds to the site root.\nUse `--pack` to build one from a directory:\n\n```bash\nzeroserve --pack ./public > site.tar\n```\n\nPackaging notes:\n- All regular files under the directory are added to the tarball.\n- Request scripts live under `.zeroserve/scripts/`.\n- Any `.c` file in `.zeroserve/scripts/` is compiled to an `.o` eBPF object.\n  The resulting `.o` is included in the tarball and the `.c` is omitted.\n- If a `.c` and `.o` share the same name, the `.o` is skipped in favor of recompiling.\n- Script compilation requires `clang` and `llc` on your `PATH`.\n\nIf you want the SDK header without packing:\n\n```bash\nzeroserve --dump-sdk > zeroserve.h\n```\n\n## Workflow\n\n1. Gather requirements\n   - Trigger: path, method, header, query param, peer, or scheme.\n   - Action: log, mutate URI/headers, set metadata, respond, or reverse proxy.\n   - Short-circuit: confirm if the script should terminate the chain with `zs_respond` or `zs_reverse_proxy`.\n2. Choose a base\n   - Start from `assets/script_template.c` for a new script.\n   - Keep the entry signature and `ZS_ENTRY` section if editing an existing script.\n3. Implement logic\n   - Read request data with `zs_req_*` helpers into fixed buffers; clamp lengths before use.\n   - Use `ZS_STR(\"literal\")` for helper calls needing `(ptr, len)` for string literals.\n   - For JSON parsing, use `zs_json_parse`/`zs_json_get`/`zs_json_array_get` and\n     `zs_json_read_*`, then free handles with `zs_object_free` (handle table is limited).\n   - To parse the request body as JSON, use `zs_req_body_json()` which returns a handle\n     (-1 on empty body, body > 256KB, or invalid JSON). The body is read lazily and cached.\n   - To build JSON dynamically, use `zs_json_new_object`/`zs_json_new_array` and modify\n     with `zs_json_set`, `zs_json_array_push`, `zs_json_set_string`, `zs_json_set_i64`, etc.\n   - To send a JSON response, use `zs_json_respond(status, handle)` which auto-sets Content-Type.\n   - To parse a static JSON file from the tarball, call `zs_load_static_json(path, path_len)`\n     and treat the returned handle like any other JSON handle.\n   - To read tarball entry metadata as JSON, call `zs_load_file_metadata(path, path_len)`\n     and access `size`, `etag`, and `mtime`.\n   - For response headers, set metadata keys `zs.response.header.<name>`.\n   - To rate limit, use `zs_rate_limit(key, key_len, per_second, per_minute, per_hour)`;\n     it returns a result code indicating allowed or which limit was exceeded.\n   - Call `zs_respond`, `zs_json_respond`, or `zs_reverse_proxy` to stop later scripts.\n4. Validate eBPF constraints\n   - Avoid unbounded loops and recursion.\n   - Keep stack usage small (BPF stack is limited).\n5. Deliver result\n   - Provide the `.c` file and note it should live under `.zeroserve/scripts/`.\n   - Remind that `zeroserve --pack` compiles `.c` to `.o` automatically.\n   - If needed, dump the SDK header with `zeroserve --dump-sdk` to inspect the full API.\n\n## References\n\n- `references/sdk_api.md` for the SDK helper list and notes.\n- `references/scripting_behavior.md` for execution order, short-circuit rules, and packaging.\n- `references/examples.md` for common patterns (logging, health response, reverse proxy, templating).\n- `assets/script_template.c` for a starter skeleton.\n"},"lastSynced":"2026-03-06T06:59:45.474Z","agentAnalysis":{"suitability":{"en":"Perfect for Performance-Oriented Agents needing high-performance, scriptable HTTP server capabilities with io_uring and eBPF.","zh":"非常适合需要高性能、可脚本化的 HTTP 服务器功能的性能导向型代理，支持 io_uring 和 eBPF。","ja":"パフォーマンス指向のエージェントが高性能でスクリプト可能なHTTPサーバーキャパシティを必要とする場合に最適です。io_uringとeBPFをサポートしています。","ko":"성능 지향 에이전트가 높은 성능 및 스크립트 가능한 HTTP 서버 기능을 필요로 하는 경우에 적합합니다. io_uring 및 eBPF를 지원합니다.","es":"Perfecto para agentes orientados al rendimiento que necesitan capacidades de servidor HTTP de alto rendimiento y scriptable con io_uring y eBPF.","fr":"Parfait pour les agents axés sur les performances nécessitant des capacités de serveur HTTP de haute performance et scriptables avec io_uring et eBPF.","de":"Perfekt für leistungsfähige Agenten, die hochleistungs- und skriptfähige HTTP-Server-Funktionen mit io_uring und eBPF benötigen.","pt":"Perfeito para Agentes com foco em Desempenho que necessitam de capacidades de servidor HTTP de alta performance e scriptáveis com io_uring e eBPF.","ru":"Идеально подходит для агентов, ориентированных на производительность, которым необходимы возможности высокопроизводительного, скриптового сервера HTTP с io_uring и eBPF.","ar":"مثالي لعميل معني بالاداء يحتاج إلى возможности خادم HTTP عالية الأداء وقابلة للبرمجة باستخدام io_uring و eBPF."},"recommendation":{"en":"Empowers agents to generate high-performance, scriptable HTTP servers using io_uring and eBPF, serving static websites from tarballs with optional eBPF request scripts, and supporting HTTP, HTTPS, hot reload, and reverse proxy from scripts.","zh":"赋予代理生成高性能、可脚本化的 HTTP 服务器的能力，使用 io_uring 和 eBPF，从 tarballs 提供静态网站，具有可选的 eBPF 请求脚本，并支持 HTTP、HTTPS、热重载和脚本反向代理。","ja":"エージェントがio_uringとeBPFを使用して、高性能でスクリプト可能なHTTPサーバーを生成できるようにします。tarballsから静的Webサイトを提供し、オプションのeBPFリクエストスクリプトを備え、HTTP、HTTPS、ホットリロード、スクリプトによるリバースプロキシをサポートします。","ko":"에이전트가 io_uring 및 eBPF를 사용하여 높은 성능 및 스크립트 가능한 HTTP 서버를 생성할 수 있도록 합니다. tarballs에서 정적 웹사이트를 제공하고, 선택적인 eBPF 요청 스크립트를 지원하며, HTTP, HTTPS, 핫 리로드 및 스크립트를 통한 리버스 프록시를 지원합니다.","es":"Habilita a los agentes a generar servidores HTTP de alto rendimiento y scriptables utilizando io_uring y eBPF, sirviendo sitios web estáticos desde tarballs con scripts de solicitud eBPF opcionales y soportando HTTP, HTTPS, recarga en caliente y proxy inverso desde scripts.","fr":"Permet aux agents de générer des serveurs HTTP de haute performance et scriptables en utilisant io_uring et eBPF, servant des sites Web statiques à partir de tarballs avec des scripts de requête eBPF optionnels et prenant en charge HTTP, HTTPS, rechargement à chaud et proxy inversé à partir de scripts.","de":"Ermächtigt Agenten, hochleistungs- und skriptfähige HTTP-Server mit io_uring und eBPF zu generieren, statische Websites aus Tarballs mit optionalen eBPF-Anfrage-Skripten bereitzustellen und HTTP, HTTPS, Heißneustart und Reverse-Proxy von Skripten aus zu unterstützen.","pt":"Habilita os agentes a gerar servidores HTTP de alta performance e scriptáveis usando io_uring e eBPF, servindo sites estáticos a partir de tarballs com scripts de solicitação eBPF opcionais e suportando HTTP, HTTPS, recarregamento quente e proxy reverso a partir de scripts.","ru":"Позволяет агентам создавать высокопроизводительные, скриптовые серверы HTTP с использованием io_uring и eBPF, обслуживающие статические сайты из tarballs с опциональными скриптами запросов eBPF и поддерживающие HTTP, HTTPS, горячую перезагрузку и обратный прокси из скриптов.","ar":"يمكن للعميل إنشاء خوادم HTTP عالية الأداء وقابلة للبرمجة باستخدام io_uring و eBPF، وتقديم مواقع إلكترونية ساكنة من tarballs مع سكريبتات طلب eBPF اختيارية ودعم HTTP و HTTPS و إعادة تحميل ساخنة ووكيل عكسي من السكريبتات."},"useCases":{"en":["Creating high-performance static website servers from tarballs","Generating eBPF request scripts for custom HTTP server logic","Setting up efficient HTTP servers with hot reload and reverse proxy capabilities"],"zh":["从 tarballs 创建高性能的静态网站服务器","为自定义 HTTP 服务器逻辑生成 eBPF 请求脚本","设置具有热重载和反向代理功能的高效 HTTP 服务器"],"ja":["tarballsから高性能の静的Webサイトサーバーを作成する","カスタムHTTPサーバーロジックのためのeBPFリクエストスクリプトを生成する","ホットリロードとリバースプロキシ機能を備えた効率的なHTTPサーバーを設定する"],"ko":["tarballs에서 높은 성능의 정적 웹사이트 서버를 생성하는 것","사용자 지정 HTTP 서버 논리용 eBPF 요청 스크립트를 생성하는 것","핫 리로드 및 리버스 프록시 기능을 갖춘 효율적인 HTTP 서버를 설정하는 것"],"es":["Crear servidores de sitios web estáticos de alto rendimiento a partir de tarballs","Generar scripts de solicitud eBPF para lógica de servidor HTTP personalizada","Configurar servidores HTTP eficientes con capacidades de recarga en caliente y proxy inverso"],"fr":["Créer des serveurs de sites Web statiques de haute performance à partir de tarballs","Générer des scripts de requête eBPF pour une logique de serveur HTTP personnalisée","Configurer des serveurs HTTP efficaces avec des capacités de rechargement à chaud et de proxy inversé"],"de":["Erstellen von Hochleistungs-Servern für statische Websites aus Tarballs","Generieren von eBPF-Anfrage-Skripten für benutzerdefinierte HTTP-Server-Logik","Einrichten von effizienten HTTP-Servern mit Heißneustart- und Reverse-Proxy-Funktionen"],"pt":["Criação de servidores de sites estáticos de alta performance a partir de tarballs","Geração de scripts de solicitação eBPF para lógica de servidor HTTP personalizada","Configuração de servidores HTTP eficientes com capacidades de recarregamento quente e proxy reverso"],"ru":["Создание высокопроизводительных статических веб-серверов из tarballs","Генерация скриптов запросов eBPF для пользовательской логики сервера HTTP","Настройка эффективных серверов HTTP с возможностями горячей перезагрузки и обратного прокси"],"ar":["إنشاء خوادم مواقع إلكترونية ساكنة عالية الأداء من tarballs","إنشاء سكريبتات طلب eBPF للمنطق المخصص لخادم HTTP","تكوين خوادم HTTP فعالة مع إمكانيات إعادة تحميل ساخنة ووكيل عكسي"]},"limitations":{"en":["Requires C programming language compatibility","Limited to serving static websites from tarballs","Dependent on io_uring and eBPF support"],"zh":["需要 C 语言兼容性","仅限从 tarballs 提供静态网站","依赖 io_uring 和 eBPF 支持"],"ja":["C言語の互換性が必要","tarballsからの静的Webサイト提供のみ","io_uringとeBPFのサポートに依存する"],"ko":["C 언어 호환성이 필요함","tarballs에서 정적 웹사이트를 제공하는 것만 가능","io_uring 및 eBPF 지원에 의존"],"es":["Requiere compatibilidad con el lenguaje de programación C","Limitado a servir sitios web estáticos desde tarballs","Dependiente del soporte de io_uring y eBPF"],"fr":["Nécessite la compatibilité avec le langage de programmation C","Limité à servir des sites Web statiques à partir de tarballs","Dépendant du support de io_uring et eBPF"],"de":["Benötigt Kompatibilität mit der Programmiersprache C","Begrenzt auf die Bereitstellung statischer Websites aus Tarballs","Abhängig von der Unterstützung von io_uring und eBPF"],"pt":["Exige compatibilidade com a linguagem de programação C","Limitado a servir sites estáticos a partir de tarballs","Dependente do suporte a io_uring e eBPF"],"ru":["Требует совместимости с языком программирования C","Ограничен обслуживанием статических сайтов из tarballs","Зависит от поддержки io_uring и eBPF"],"ar":["يتطلب توافقًا مع لغة البرمجة C","محدود بتقديم مواقع إلكترونية ساكنة من tarballs","يعتمد على دعم io_uring و eBPF"]},"version":4},"contentHash":"7b4e6614bd991cabf0ca2e0b446cf9a8aa7df556a8f7e9fd5b1c5564840e9131","qualityScore":45}');
DELETE FROM skills_fts WHERE id = 'losfair/zeroserve/zeroserve-script-create';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('losfair/zeroserve/zeroserve-script-create', 'zeroserve-script-create', 'losfair', 'zeroserve', 'community', 'zeroserve-script-create losfair zeroserve community The zeroserve-script-create skill generates a high-performance, scriptable HTTP server using io_uring and eBPF, serving static websites from tarballs with optional eBPF request scripts. It benefits developers seeking fast and efficient server setup. Zeroserve 脚本创建工具是用于创建基于 io_uring 的 HTTPS 服务器的工具，支持 eBPF 和静态网站托管。它可以快速创建高性能的 HTTP 服务器 Zeroserve スクリプト作成ツールは、io_uring ベースの HTTPS サーバーを作成するためのツールです。eBPF と静的 Web サイトのホスティングをサポートしています Zeroserve 스크립트 생성 도구는 io_uring 기반의 HTTPS 서버를 생성하는 도구입니다. eBPF 및 정적 웹 사이트 호스팅을 지원합니다 Zeroserve Script Create es un servidor HTTP de alto rendimiento que utiliza io_uring y eBPF. Crea un script de solicitud en C para servir sitios web estáticos desde un tarball. Zeroserve Script Create est un serveur HTTP haute performance qui utilise io_uring et eBPF. Il crée un script de requête en C pour servir des sites web statiques à partir d''un tarball. Zeroserve Script Create ist ein Hochleistungs-HTTP-Server, der io_uring und eBPF verwendet. Er erstellt ein Anfrage-Skript in C, um statische Websites aus einem Tarball zu servieren. O Zeroserve-Script-Create é um servidor HTTPS de alta performance baseado em io_uring e eBPF, que serve sites estáticos a partir de um tarball e executa scripts de solicitação eBPF. Zeroserve-Script-Create - это высокопроизводительный сервер HTTPS на основе io_uring и eBPF, который обслуживает статические сайты из tarball и запускает скрипты запросов eBPF. Zeroserve-Script-Create هو خادم HTTPS سريع وآمن يستند إلى io_uring و eBPF، يقوم بخدمة مواقع إلكترونية ثابتة من tarball وتنفيذ scripts الطلب eBPF. how to use zeroserve-script-create zeroserve-script-create alternative zeroserve-script-create setup guide io_uring HTTPS server eBPF request scripts zeroserve-script-create vs nginx install zeroserve-script-create what is zeroserve-script-create zeroserve-script-create tutorial Zeroserve 脚本创建 io_uring HTTPS 服务器 eBPF 静态网站托管 AIエージェント 脚本创建工具 高性能 HTTP 服务器 Uses io_uring for high-performance HTTPS serving Supports eBPF request scripts for customizable server behavior Serves static websites from tarballs Optional hot reload for efficient development Small templating pass for text responses Opt-in reverse proxy from scripts zeroserve-script-create is a zero-config, fast io_uring-based HTTPS server skill that creates a Zeroserve request script in C from requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('djouallah/dbt/dbt-fabric-notebook', 'community', 'djouallah', 'dbt', 'djouallah/dbt', 'dbt-fabric-notebook', 3, 0, 45, '2026-03-06T01:12:16Z', '2026-03-06T07:03:54.931Z', '569f24f3351d9b18c3d05198e1bcbc3f7f3e6179d443d098fc62a7ae988ba766', '{"id":"djouallah/dbt/dbt-fabric-notebook","name":"dbt-fabric-notebook","description":{"en":"The dbt-fabric-notebook skill allows developers to run full dbt pipelines inside Microsoft Fabric Python notebooks using DuckDB and DuckLake. This skill benefits data engineers and analysts working with dbt and Microsoft Fabric.","zh":"dbt-fabric-notebook Skill 使您能够在 Microsoft Fabric 中运行 dbt.pipeline，利用 DuckDB 和 DuckLake 实现高效数据处理","ja":"dbt-fabric-notebook スキルを使用すると、Microsoft Fabric で dbt パイプラインを実行できます。DuckDB と DuckLake を使用して効率的なデータ処理を行います","ko":"dbt-fabric-notebook 스킬을 사용하면 Microsoft Fabric에서 dbt 파이프라인을 실행할 수 있으며, DuckDB 및 DuckLake를 사용하여 효율적인 데이터 처리를 수행할 수 있습니다","es":"El skill dbt-fabric-notebook permite ejecutar un pipeline de dbt completo dentro de un cuaderno de Python de Microsoft Fabric","fr":"Le skill dbt-fabric-notebook permet d''exécuter un pipeline dbt complet à l''intérieur d''un cahier Python Microsoft Fabric","de":"Der dbt-fabric-notebook-Skill ermöglicht die Ausführung einer vollständigen dbt-Pipeline innerhalb eines Microsoft Fabric Python-Notebooks","pt":"O dbt-fabric-notebook permite executar um pipeline dbt completo dentro de um notebook Python do Microsoft Fabric","ru":"dbt-fabric-notebook позволяет запускать полный пайплайн dbt внутри ноутбука Python от Microsoft Fabric","ar":"dbt-fabric-notebook يسمح بتشغيل pipeline dbt كامل داخل notebook Python من Microsoft Fabric"},"seo":{"title":{"en":"dbt-fabric-notebook: Setup Guide for AI Agents | AI Agent...","zh":"dbt-fabric-notebook 集成指南：在 Microsoft Fabric 中运行 dbt","ja":"dbt-fabric-notebook のセットアップガイド: Microsoft Fabri