INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AutumnsGrove/Lattice/elephant-build', 'elephant-build', 'AutumnsGrove', 'Lattice', 'community', 'elephant-build AutumnsGrove Lattice community blogging cloudflare indie-web nature-themed queer solarpunk sveltekit elephant-build is a set of writing and community tools for a quieter corner of the internet, utilizing SvelteKit and Cloudflare. It benefits developers who need to create complex systems and features. elephant-build是一种集成工具，用于构建和部署复杂的系统，支持前端到后端的无缝集成 elephant-buildは、複雑なシステムを構築およびデプロイするための統合ツールであり、フロントエンドからバックエンドまでのシームレスな統合をサポートします elephant-build는 복잡한 시스템을 구축하고 배포하는 통합 도구로, 프런트엔드에서 백엔드까지의 無縫な統合을 지원합니다 Elephant-build es una herramienta de blogging y comunidad que utiliza SvelteKit y Cloudflare para crear un espacio en línea más tranquilo Elephant-build est un outil de blogging et de communauté qui utilise SvelteKit et Cloudflare pour créer un espace en ligne plus calme Elephant-build ist ein Blogging- und Community-Tool, das SvelteKit und Cloudflare nutzt, um einen ruhigeren Online-Raum zu schaffen O Elephant Build é uma ferramenta de desenvolvimento que permite criar soluções personalizadas para a Indie-Web, com foco em tecnologias como SvelteKit e Cloudflare ИИ Агент Elephant Build - это инструмент разработки, который позволяет создавать индивидуальные решения для Indie-Web, используя технологии SvelteKit и Cloudflare Elephant Build هو أداة تطوير تمكن من إنشاء حلول مخصصة للويب المستقلة، مع التركيز على تكنولوجيا SvelteKit و Cloudflare how to use elephant-build what is elephant-build elephant-build alternative elephant-build vs SvelteKit elephant-build install elephant-build setup guide SvelteKit and Cloudflare integration indie-web development tools solarpunk and queer-friendly tech elephant-build AI工具 前端到后端集成 SvelteKit Cloudflare Indie-web Solarpunk API 数据库 Creates complex systems file by file, system by system Carries features through from frontend to backend, API to database Utilizes SvelteKit for building and deploying applications Leverages Cloudflare for scalable and secure infrastructure Supports indie-web and solarpunk principles for a quieter corner of the internet Enables queer-friendly and inclusive community tools elephant-build is a nature-themed, indie-web skill for building and deploying applications with SvelteKit and Cloudflare.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('WynterJones/OpenPaw/production', 'community', 'WynterJones', 'OpenPaw', 'WynterJones/OpenPaw', 'production', 2, 0, 45, '2026-02-25T09:41:26Z', '2026-03-06T07:05:05.164Z', '8ab7d742dc765faca4b395f046ebf0b6c52167a0bc26aeaa7bdec571225d3775', '{"id":"WynterJones/OpenPaw/production","name":"production","description":{"en":"The production skill enables AI agents to build, manage, and orchestrate custom tools and dashboards, ensuring production readiness and strategy alignment.","zh":"生产环境下的Agentic AI部署，实现高效生产和策略对齐","ja":"AIエージェントを使用して生産性を高めるための生产環境設定","ko":"Agentic AI를 사용하여 생산 환경을 설정하고 생산성과 전략을 최적화","es":"La habilidad de producción de Agentic AI permite la implementación y gestión de herramientas personalizadas para producción","fr":"La compétence de production d''Agentic AI permet l''implémentation et la gestion d''outils personnalisés pour la production","de":"Die Produktionsfähigkeit von Agentic AI ermöglicht die Implementierung und Verwaltung von benutzerdefinierten Tools für die Produktion","pt":"O skill de produção é usado para verificar o status de implementação e alinhar a estratégia antes do deploy de produção","ru":"Навык производства используется для проверки статуса реализации и выравнивания стратегии перед развертыванием в производство","ar":"يستخدم مهارة الإنتاج للتحقق من حالة التنفيذ وتنسيق الاستراتيجية قبل نشر الإنتاج"},"seo":{"title":{"en":"Production: Setup Guide for AI Agents | AI Agent Skill","zh":"生产环境部署指南 - 使用Agentic AI实现高效生产","ja":"Production Setup Guide - 生産性を高めるためのAIエージェントの活用","ko":"생산 환경 설정 가이드 - Agentic AI로 높은 생산성 달성","es":"Guía de configuración de producción con Agentic AI","fr":"Guide de mise en production avec Agentic AI","de":"Produktions-Setup-Leitfaden mit Agentic AI","pt":"Guia de Configuração de Produção com Agentic-AI","ru":"Настройка Сборки Производства с ИИ Агентами Agentic-