INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WynterJones/OpenPaw/production', 'production', 'WynterJones', 'OpenPaw', 'community', 'production WynterJones OpenPaw community agentic-ai agentic-framework openrouter The production skill enables AI agents to build, manage, and orchestrate custom tools and dashboards, ensuring production readiness and strategy alignment. 生产环境下的Agentic AI部署，实现高效生产和策略对齐 AIエージェントを使用して生産性を高めるための生产環境設定 Agentic AI를 사용하여 생산 환경을 설정하고 생산성과 전략을 최적화 La habilidad de producción de Agentic AI permite la implementación y gestión de herramientas personalizadas para producción La compétence de production d''Agentic AI permet l''implémentation et la gestion d''outils personnalisés pour la production Die Produktionsfähigkeit von Agentic AI ermöglicht die Implementierung und Verwaltung von benutzerdefinierten Tools für die Produktion O skill de produção é usado para verificar o status de implementação e alinhar a estratégia antes do deploy de produção Навык производства используется для проверки статуса реализации и выравнивания стратегии перед развертыванием в производство يستخدم مهارة الإنتاج للتحقق من حالة التنفيذ وتنسيق الاستراتيجية قبل نشر الإنتاج how to use production skill production setup guide for AI agents agentic ai framework production production vs openrouter production readiness check implementing production skill for custom tools Agentic AI 生产环境部署 高效生产 策略对齐 BROWNFIELD.md 代码库扫描 功能识别 路由检查 页面检查 Scans codebase and updates _OFFICE/BROWNFIELD.md Identifies implemented features via route and page checks Compares feature directories and user-facing components Performs documentation impact assessment Supports feature completion verification and strategy alignment checks Production is a skill that focuses on implementation status and strategy alignment for AI agents, ensuring seamless deployment and management of custom tools and dashboards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('T-rav/hyrda/skill-stocktake', 'community', 'T-rav', 'hyrda', 'T-rav/hyrda', 'skill-stocktake', 2, 0, 45, '2026-02-28T08:00:03Z', '2026-03-06T07:07:21.126Z', '2964e3b6a11b4d9d76b99a218a5d627c91da63ecc080feb686c895c2e52e37ab', '{"id":"T-rav/hyrda/skill-stocktake","name":"skill-stocktake","description":{"en":"The skill-stocktake audits Claude skills using a quality checklist and AI holistic judgment, benefiting developers with automated quality gates. It supports Quick Scan and Full Stocktake modes.","zh":"skill-stocktake是一个AIエージェント技能库存检查工具，支持Quick Scan和Full Stocktake两种模式，用于审计Claude技能和命令","ja":"skill-stocktakeはAIエージェントのスキルストックテイクツールであり、Quick ScanとFull Stocktakeの2つのモードをサポートし、Claudeのスキルとコマンドを監査します","ko":"skill-stocktake는 AI 에이전트의 스킬 재고 확인 도구로, Quick Scan과 Full Stocktake 두 가지 모드를 지원하여 Claude의 스킬과 명령어를 감사합니다","es":"Skill-stocktake es una herramienta de auditoría que utiliza un checklist de calidad y un juicio holístico de IA para evaluar las habilidades de Claude","fr":"Skill-stocktake est un outil d''audit qui utilise une checklist de qualité et un jugement holistique de l''IA pour évaluer les compétences de Claude","de":"Skill-stocktake ist ein Audit-Tool, das eine Qualität-Checkliste und ein holistisches Urteil der künstlichen Intelligenz verwendet, um die Fähigkeiten von Claude zu bewerten","pt":"O Skill-Stocktake é um comando que audita habilidades de Claude usando uma lista de verificação de qualidade e julgamento holístico de IA","ru":"Skill-Stocktake - это команда, которая проверяет навыки Claude с помощью списка контроля качества и целостной оценки ИИ","ar":"Skill-Stocktake هو أمر يتدقيق مهارات Claude باستخدام قائمة التحقق من الجودة والحكم الشامل للذكاء الاصطناعي"},"seo":{"title":{"en":"skill-stocktake: Audit and Quality Checklist for AI Agent...","zh":"skill-stocktake_SETUP GUIDE：AIエージェント技能库存检查","ja":"skill-stocktake セットアップガイド：AIエージェントのスキルストックテイク","ko":"skill-stocktake 설정 가이드: AI 에이전트 스킬 재고 확인","es":"Guía de configuración de skill-stocktake para agentic-dev...","fr":"Guide de mise en place de skill-stocktake pour le dévelop...","de":"Einrichtungsleitfaden für skill-stocktake in der agentic-...","pt":"Guia de Configuração do Skill-Stocktake: Auditoria de Hab...","ru":"Настройка Skill-Stocktake: Проверка Навыков Claude с ИИ А...","ar":"دليل إعداد Skill-Stocktake: تدقيق مهارات Claude مع أدوات ..."},"description":{"en":"Discover how to audit Claude skills with skill-stocktake. Learn to use the /skill-stocktake slash command for quality checks and AI-driven judgment. Get star...","zh":"了解skill-stocktake的功能和特点，如何使用AIエージェント技能库存检查工具优化您的开发流程","ja":"skill-stocktakeの機能と特徴をご紹介。AIエージェントのスキルストックテイクツールを使用して開発プロセスを最適化する方法","ko":"skill-stocktake의 기능 및 특징을 살펴보세요. AI 에이전트의 스킬 재고 확인 도구를 사용하여 개발 프로세스를 최적화하는 방법","es":"Descubre cómo utilizar skill-stocktake para auditar y mejorar tus habilidades de Claude con nuestra guía paso a paso","fr":"Découvrez comment utiliser skill-stocktake pour auditer et améliorer vos compétences Claude avec notre guide étape par étape","de":"Erfahren Sie, wie Sie skill-stocktake verwenden, um Ihre Claude-Fähigkeiten zu überprüfen und zu verbessern, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Skill-Stocktake para auditorias de habilidades de Claude com qualidade e julgamento holístico de IA","ru":"Узнайте, как настроить Skill-Stocktake для проверки навыков Claude с помощью ИИ Агентов и контроля качества","ar":"تعرف على كيفية إعداد Skill-Stocktake لتدقيق مهارات Claude باستخدام أدوات الذكاء الاصطناعي والتحكم في الجودة"},"definition":{"en":"skill-stocktake is a Slash command that audits all Claude skills and commands using a quality checklist and AI-driven judgment.","zh":"skill-stocktake是一种AIエージェント技能库存检查工具，用于审计和优化Claude技能和命令","ja":"skill-stocktakeはAIエージェントのスキルストックテイクツールであり、Claudeのスキルとコマンドを監査して最適化するために使用されます","ko":"skill-stocktake는 AI 에이전트의 스킬 재고 확인 도구로, Claude의 스킬과 명령어를 감사 및 최적화하는 데 사용됩니다","es":"Skill-stocktake es un comando de auditoría de habilidades de Claude que utiliza IA para evaluar y mejorar la calidad de las habilidades","fr":"Skill-stocktake est un commande d''audit de compétences de Claude qui utilise l''IA pour évaluer et améliorer la qualité des compétences","de":"Skill-stocktake ist ein Audit-Befehl für Claude-Fähigkeiten, der künstliche Intelligenz verwendet, um die Qualität der Fähigkeiten zu bewerten und zu verbessern","pt":"O que é Skill-Stocktake? É um comando que audita habilidades de Claude com qualidade e julgamento holístico de IA","ru":"Что такое Skill-Stocktake? Это команда, которая проверяет навыки Claude с помощью ИИ Агентов","ar":"ما هو Skill-Stocktake؟ هو أمر يتدقيق مهارات Claude باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Supports two modes: Quick Scan for recently changed skills and Full Stocktake for a complete review","Utilizes the /skill-stocktake slash command for auditing","Targets global skills in ~/.claude/skills/ and project-level skills in {cwd}/.claude/skills/","Enforces quality gates through a staged pipeline","Produces merged software changes using HydraFlow delivery kernel"],"zh":["支持Quick Scan和Full Stocktake两种模式","审计Claude技能和命令","使用AI判斷进行holistic judgment","支持全球技能和项目级技能","相对目录路径的命令调用"],"ja":["Quick ScanとFull Stocktakeの2つのモードをサポート","Claudeのスキルとコマンドを監査","AIのホリスティック・ジャッジメントを使用","グローバルスキルとプロジェクトレベルのスキルをサポート","相対ディレクトリパスのコマンド呼び出し"],"ko":["Quick Scan과 Full Stocktake 두 가지 모드를 지원","Claude의 스킬과 명령어를 감사","AI 홀리스틱 판단을 사용","전역 스킬과 프로젝트 수준의 스킬을 지원","상대 디렉토리 경로의 명령 호출"],"es":["Audit de habilidades de Claude utilizando un checklist de calidad","Juicio holístico de IA para evaluar la calidad de las habilidades","Soporte para dos modos: Quick Scan y Full Stocktake","Integración con el directorio de habilidades de Claude","Compatibilidad con proyectos de nivel global y de proyecto"],"fr":["Audit de compétences de Claude à l''aide d''une checklist de qualité","Jugement holistique de l''IA pour évaluer la qualité des compétences","Prise en charge de deux modes : Quick Scan et Full Stocktake","Intégration avec le répertoire de compétences de Claude","Compatibilité avec les projets de niveau global et de projet"],"de":["Audit von Claude-Fähigkeiten mithilfe einer Qualität-Checkliste","Holistisches Urteil der künstlichen Intelligenz zur Bewertung der Fähigkeiten","Unterstützung für zwei Modi: Quick Scan und Full Stocktake","Integration mit dem Verzeichnis der Claude-Fähigkeiten","Kompatibilität mit globalen und projektspezifischen Projekten"],"pt":["Auditoria de habilidades de Claude com qualidade e julgamento holístico de IA","Suporte a dois modos: Quick Scan e Full Stocktake","Alvo de caminhos relativos ao diretório onde é invocado","Verificação de habilidades globais e de projeto","Uso de lista de verificação de qualidade e julgamento holístico de IA"],"ru":["Проверка навыков Claude с помощью ИИ Агентов и контроля качества","Поддержка двух режимов: Quick Scan и Full Stocktake","Целевая проверка путей относительно директории, где она вызвана","Проверка глобальных и проектных навыков","Использование списка контроля качества и целостной оценки ИИ"],"ar":["تدقيق مهارات Claude باستخدام أدوات الذكاء الاصطناعي والتحكم في الجودة","دعم وضعين: Quick Scan و Full Stocktake","استهداف مسارات نسبية إلى الدليل حيث يتم استدعاؤها","تدقيق مهارات عالمية ومشروع","استخدام قائمة التحقق من الجودة والحكم الشامل للذكاء الاصطناعي"]},"keywords":{"en":["how to use skill-stocktake","what is skill-stocktake","skill-stocktake alternative","skill-stocktake setup guide","skill-stocktake install","HydraFlow delivery kernel","Claude skills audit","AI-driven quality judgment"],"zh":["AIエージェント","技能库存检查","Claude技能","Quick Scan","Full Stocktake","AI判斷","holistic judgment","agentic-development","agentic-workflow"],"ja":["AIエージェント","スキルストックテイク","Claudeスキル","Quick Scan","Full Stocktake","AIのホリスティック・ジャッジメント","agentic-development","agentic-workflow"],"ko":["AI 에이전트","스킬 재고 확인","Claude 스킬","Quick Scan","Full Stocktake","AI 홀리스틱 판단","agentic-development","agentic-workflow"],"es":["agentic development","agentic workflow","wishful programming","IA herramientas","audit de habilidades","mejora de la calidad","desarrollo de software","GitHub repositories"],"fr":["développement agentic","flux de travail agentic","programmation wishful","outils d''IA","audit de compétences","amélioration de la qualité","développement de logiciels","dépôts GitHub"],"de":["agentic Entwicklung","agentic Workflow","Wunschprogrammierung","KI-Tools","Fähigkeitsaudit","Qualitätsverbesserung","Softwareentwicklung","GitHub-Repositorys"],"pt":["Skill-Stocktake","Auditoria de habilidades de Claude","Julgamento holístico de IA","Controle de qualidade","Desenvolvimento de habilidades de Claude","Ferramentas de IA para desenvolvedores","Comandos de Claude","Habilidades de Claude"],"ru":["Skill-Stocktake","Проверка навыков Claude","Целостная оценка ИИ","Контроль качества","Разработка навыков Claude","ИИ Агенты для разработчиков","Команды Claude","Навыки Claude"],"ar":["Skill-Stocktake","تدقيق مهارات Claude","الحكم الشامل للذكاء الاصطناعي","التحكم في الجودة","تطوير مهارات Claude","أدوات الذكاء الاصطناعي للمطورين","أوامر Claude","مهارات Claude"]}},"owner":"T-rav","repo":"hyrda","repoPath":"T-rav/hyrda","stars":2,"forks":0,"updatedAt":"2026-02-28T08:00:03Z","topics":["agentic-development","agentic-workflow","wishful-programming"],"category":"community","skillMd":{"name":"skill-stocktake","description":"Use when auditing Claude skills and commands for quality. Supports Quick Scan (changed skills only) and Full Stocktake modes with sequential subagent batch evaluation.","bodyPreview":"# skill-stocktake\n\nSlash command (`/skill-stocktake`) that audits all Claude skills and commands using a quality checklist + AI holistic judgment. Supports two modes: Quick Scan for recently changed skills, and Full Stocktake for a complete review.\n\n## Scope\n\nThe command targets the following paths **relative to the directory where it is invoked**:\n\n| Path | Description |\n|------|-------------|\n| `~/.claude/skills/` | Global skills (all projects) |\n| `{cwd}/.claude/skills/` | Project-level skill","body":"# skill-stocktake\n\nSlash command (`/skill-stocktake`) that audits all Claude skills and commands using a quality checklist + AI holistic judgment. Supports two modes: Quick Scan for recently changed skills, and Full Stocktake for a complete review.\n\n## Scope\n\nThe command targets the following paths **relative to the directory where it is invoked**:\n\n| Path | Description |\n|------|-------------|\n| `~/.claude/skills/` | Global skills (all projects) |\n| `{cwd}/.claude/skills/` | Project-level skills (if the directory exists) |\n\n**At the start of Phase 1, the command explicitly lists which paths were found and scanned.**\n\n### Targeting a specific project\n\nTo include project-level skills, run from that project''s root directory:\n\n```bash\ncd ~/path/to/my-project\n/skill-stocktake\n```\n\nIf the project has no `.claude/skills/` directory, only global skills and commands are evaluated.\n\n## Modes\n\n| Mode | Trigger | Duration |\n|------|---------|---------|\n| Quick Scan | `results.json` exists (default) | 5–10 min |\n| Full Stocktake | `results.json` absent, or `/skill-stocktake full` | 20–30 min |\n\n**Results cache:** `~/.claude/skills/skill-stocktake/results.json`\n\n## Quick Scan Flow\n\nRe-evaluate only skills that have changed since the last run (5–10 min).\n\n1. Read `~/.claude/skills/skill-stocktake/results.json`\n2. Run: `bash ~/.claude/skills/skill-stocktake/scripts/quick-diff.sh \\\n         ~/.claude/skills/skill-stocktake/results.json`\n   (Project dir is auto-detected from `$PWD/.claude/skills`; pass it explicitly only if needed)\n3. If output is `[]`: report \"No changes since last run.\" and stop\n4. Re-evaluate only those changed files using the same Phase 2 criteria\n5. Carry forward unchanged skills from previous results\n6. Output only the diff\n7. Run: `bash ~/.claude/skills/skill-stocktake/scripts/save-results.sh \\\n         ~/.claude/skills/skill-stocktake/results.json <<< \"$EVAL_RESULTS\"`\n\n## Full Stocktake Flow\n\n### Phase 1 — Inventory\n\nRun: `bash ~/.claude/skills/skill-stocktake/scripts/scan.sh`\n\nThe script enumerates skill files, extracts frontmatter, and collects UTC mtimes.\nProject dir is auto-detected from `$PWD/.claude/skills`; pass it explicitly only if needed.\nPresent the scan summary and inventory table from the script output:\n\n```\nScanning:\n  ✓ ~/.claude/skills/         (17 files)\n  ✗ {cwd}/.claude/skills/    (not found — global skills only)\n```\n\n| Skill | 7d use | 30d use | Description |\n|-------|--------|---------|-------------|\n\n### Phase 2 — Quality Evaluation\n\nLaunch a Task tool subagent (**Explore agent, model: opus**) with the full inventory and checklist.\nThe subagent reads each skill, applies the checklist, and returns per-skill JSON:\n\n`{ \"verdict\": \"Keep\"|\"Improve\"|\"Update\"|\"Retire\"|\"Merge into [X]\", \"reason\": \"...\" }`\n\n**Chunk guidance:** Process ~20 skills per subagent invocation to keep context manageable. Save intermediate results to `results.json` (`status: \"in_progress\"`) after each chunk.\n\nAfter all skills are evaluated: set `status: \"completed\"`, proceed to Phase 3.\n\n**Resume detection:** If `status: \"in_progress\"` is found on startup, resume from the first unevaluated skill.\n\nEach skill is evaluated against this checklist:\n\n```\n- [ ] Content overlap with other skills checked\n- [ ] Overlap with MEMORY.md / CLAUDE.md checked\n- [ ] Freshness of technical references verified (use WebSearch if tool names / CLI flags / APIs are present)\n- [ ] Usage frequency considered\n```\n\nVerdict criteria:\n\n| Verdict | Meaning |\n|---------|---------|\n| Keep | Useful and current |\n| Improve | Worth keeping, but specific improvements needed |\n| Update | Referenced technology is outdated (verify with WebSearch) |\n| Retire | Low quality, stale, or cost-asymmetric |\n| Merge into [X] | Substantial overlap with another skill; name the merge target |\n\nEvaluation is **holistic AI judgment** — not a numeric rubric. Guiding dimensions:\n- **Actionability**: code examples, commands, or steps that let you act immediately\n- **Scope fit**: name, trigger, and content are aligned; not too broad or narrow\n- **Uniqueness**: value not replaceable by MEMORY.md / CLAUDE.md / another skill\n- **Currency**: technical references work in the current environment\n\n**Reason quality requirements** — the `reason` field must be self-contained and decision-enabling:\n- Do NOT write \"unchanged\" alone — always restate the core evidence\n- For **Retire**: state (1) what specific defect was found, (2) what covers the same need instead\n  - Bad: `\"Superseded\"`\n  - Good: `\"disable-model-invocation: true already set; superseded by continuous-learning-v2 which covers all the same patterns plus confidence scoring. No unique content remains.\"`\n- For **Merge**: name the target and describe what content to integrate\n  - Bad: `\"Overlaps with X\"`\n  - Good: `\"42-line thin content; Step 4 of chatlog-to-article already covers the same workflow. Integrate the ''article angle'' tip as a note in that skill.\"`\n- For **Improve**: describe the specific change needed (what section, what action, target size if relevant)\n  - Bad: `\"Too long\"`\n  - Good: `\"276 lines; Section ''Framework Comparison'' (L80–140) duplicates ai-era-architecture-principles; delete it to reach ~150 lines.\"`\n- For **Keep** (mtime-only change in Quick Scan): restate the original verdict rationale, do not write \"unchanged\"\n  - Bad: `\"Unchanged\"`\n  - Good: `\"mtime updated but content unchanged. Unique Python reference explicitly imported by rules/python/; no overlap found.\"`\n\n### Phase 3 — Summary Table\n\n| Skill | 7d use | Verdict | Reason |\n|-------|--------|---------|--------|\n\n### Phase 4 — Consolidation\n\n1. **Retire / Merge**: present detailed justification per file before confirming with user:\n   - What specific problem was found (overlap, staleness, broken references, etc.)\n   - What alternative covers the same functionality (for Retire: which existing skill/rule; for Merge: the target file and what content to integrate)\n   - Impact of removal (any dependent skills, MEMORY.md references, or workflows affected)\n2. **Improve**: present specific improvement suggestions with rationale:\n   - What to change and why (e.g., \"trim 430→200 lines because sections X/Y duplicate python-patterns\")\n   - User decides whether to act\n3. **Update**: present updated content with sources checked\n4. Check MEMORY.md line count; propose compression if >100 lines\n\n## Results File Schema\n\n`~/.claude/skills/skill-stocktake/results.json`:\n\n**`evaluated_at`**: Must be set to the actual UTC time of evaluation completion.\nObtain via Bash: `date -u +%Y-%m-%dT%H:%M:%SZ`. Never use a date-only approximation like `T00:00:00Z`.\n\n```json\n{\n  \"evaluated_at\": \"2026-02-21T10:00:00Z\",\n  \"mode\": \"full\",\n  \"batch_progress\": {\n    \"total\": 80,\n    \"evaluated\": 80,\n    \"status\": \"completed\"\n  },\n  \"skills\": {\n    \"skill-name\": {\n      \"path\": \"~/.claude/skills/skill-name/SKILL.md\",\n      \"verdict\": \"Keep\",\n      \"reason\": \"Concrete, actionable, unique value for X workflow\",\n      \"mtime\": \"2026-01-15T08:30:00Z\"\n    }\n  }\n}\n```\n\n## Notes\n\n- Evaluation is blind: the same checklist applies to all skills regardless of origin (ECC, self-authored, auto-extracted)\n- Archive / delete operations always require explicit user confirmation\n- No verdict branching by skill origin\n"},"lastSynced":"2026-03-06T07:07:21.126Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing automated quality gates for Claude skills and commands.","zh":"非常适合需要为 Claude 技能和命令自动化质量门槛的 AI Agent 开发人员。","ja":"Claude スキルとコマンドの自動化された品質ゲートが必要な AI エージェント開発者に最適です。","ko":"Claude 스킬 및 명령에 대한 자동화된 품질 게이트가 필요한 AI 에이전트 개발자를 위한 최적의 솔루션입니다.","es":"Ideal para desarrolladores de Agentes de IA que necesitan puertas de calidad automatizadas para habilidades y comandos de Claude.","fr":"Parfait pour les développeurs d''agents IA ayant besoin de portes de qualité automatisées pour les compétences et les commandes de Claude.","de":"Perfekt für AI-Agent-Entwickler, die automatisierte Qualitätsprüfungen für Claude-Fähigkeiten und -Befehle benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que precisam de portas de qualidade automatizadas para habilidades e comandos do Claude.","ru":"Идеально подходит для разработчиков агентов ИИ, которым необходимы автоматические ворота качества для навыков и команд Claude.","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى أبواب جودة أوتوماتيكية لمهارات وأوامر كلود"},"recommendation":{"en":"Empowers agents to audit Claude skills using a quality checklist and AI holistic judgment, supporting Quick Scan and Full Stocktake modes through the slash command `/skill-stocktake`, enabling automated quality control for global and project-level skills.","zh":"赋予代理人使用质量检查清单和 AI 全面判断来审计 Claude 技能的能力，支持通过斜杠命令 `/skill-stocktake` 的 Quick Scan 和 Full Stocktake 模式，实现全球和项目级别技能的自动化质量控制。","ja":"スラッシュコマンド `/skill-stocktake` を介した Quick Scan モードと Full Stocktake モードをサポートし、品質チェックリストと AI 全体的な判断を使用して Claude スキルを監査するエージェントの能力を提供し、グローバルおよびプロジェクトレベルのスキルに対する自動化された品質管理を可能にします。","ko":"슬래시 명령 `/skill-stocktake`을 통해 Quick Scan 모드와 Full Stocktake 모드를 지원하며, 품질 체크리스트와 AI 전반적인 판단을 사용하여 Claude 스킬을 감사할 수 있는 에이전트의 능력을 제공하여, 글로벌 및 프로젝트 수준의 스킬에 대한 자동화된 품질 제어를 가능하게 합니다.","es":"Habilita a los agentes a auditar habilidades de Claude utilizando una lista de verificación de calidad y juicio holístico de IA, compatible con los modos de análisis rápido y de inventario completo a través del comando `/skill-stocktake`, lo que permite el control de calidad automatizado para habilidades a nivel global y de proyecto.","fr":"Permet aux agents d''auditer les compétences de Claude en utilisant une liste de vérification de la qualité et un jugement holistique de l''IA, prenant en charge les modes d''analyse rapide et d''inventaire complet via la commande `/skill-stocktake`, permettant ainsi un contrôle de qualité automatisé pour les compétences au niveau mondial et de projet.","de":"Ermächtigt Agenten, Claude-Fähigkeiten mit einer Qualitätsprüfungsliste und holistischem IA-Urteil zu überprüfen, unterstützt Quick-Scan- und Full-Stocktake-Modi über den Befehl `/skill-stocktake`, ermöglicht so eine automatisierte Qualitätskontrolle für globale und projektspezifische Fähigkeiten.","pt":"Habilita os agentes a auditar habilidades do Claude usando uma lista de verificação de qualidade e julgamento holístico de IA, suportando os modos Quick Scan e Full Stocktake através do comando `/skill-stocktake`, permitindo controle de qualidade automatizado para habilidades globais e de nível de projeto.","ru":"Наделяет агентов возможностью аудита навыков Claude с помощью списка проверки качества и целостной оценки ИИ, поддерживая режимы быстрого сканирования и полного инвентаризации через команду `/skill-stocktake`, позволяя автоматизировать контроль качества для глобальных и проектных навыков.","ar":"تمكين الوكلاء من مراجعة مهارات كلود باستخدام قائمة فحص جودة وحكم شامل للذكاء الاصطناعي، داعمًا وضعين من المسح السريع والجرد الشامل عبر الأمر `/skill-stocktake`، وتمكين التحكم الآلي في الجودة للمهارات العالمية ومستوى المشروع"},"useCases":{"en":["Auditing recently changed skills with Quick Scan mode","Performing comprehensive reviews of all skills with Full Stocktake mode","Automating quality gates for Claude skills and commands"],"zh":["使用 Quick Scan 模式审计最近更改的技能","使用 Full Stocktake 模式对所有技能进行全面审查","自动化 Claude 技能和命令的质量门槛"],"ja":["最近変更されたスキルを Quick Scan モードで監査する","すべてのスキルに対して Full Stocktake モードで包括的なレビューを実行する","Claude スキルとコマンドの品質ゲートを自動化する"],"ko":["최근 변경된 스킬을 Quick Scan 모드로 감사하는 것","모든 스킬에 대한 종합적인 검토를 Full Stocktake 모드로 수행하는 것","Claude 스킬 및 명령의 품질 게이트를 자동화하는 것"],"es":["Auditar habilidades recientemente cambiadas con el modo de análisis rápido","Realizar revisiones exhaustivas de todas las habilidades con el modo de inventario completo","Automatizar puertas de calidad para habilidades y comandos de Claude"],"fr":["Auditer les compétences récemment modifiées avec le mode d''analyse rapide","Effectuer des examens complets de toutes les compétences avec le mode d''inventaire complet","Automatiser les portes de qualité pour les compétences et les commandes de Claude"],"de":["Kürzlich geänderte Fähigkeiten mit dem Quick-Scan-Modus überprüfen","Umfassende Überprüfungen aller Fähigkeiten im Full-Stocktake-Modus durchführen","Automatisieren von Qualitätsprüfungen für Claude-Fähigkeiten und -Befehle"],"pt":["Auditar habilidades recentemente alteradas com o modo Quick Scan","Realizar revisões abrangentes de todas as habilidades com o modo Full Stocktake","Automatizar portas de qualidade para habilidades e comandos do Claude"],"ru":["Просмотр измененных навыков в режиме быстрого сканирования","Проведение всесторонних обзоров всех навыков в режиме полного инвентаризации","Автоматизация ворот качества для навыков и команд Claude"],"ar":["مراجعة المهارات المعدلة مؤخرًا مع وضع المسح السريع","إجراء مراجعات شاملة لجميع المهارات مع وضع الجرد الشامل","تأتييم أبواب الجودة لأوامر ومهارات كلود أوتوماتيكيًا"]},"limitations":{"en":["Requires access to Claude skills directory","Limited to auditing skills in `~/.claude/skills/` and `{cwd}/.claude/skills/` paths"],"zh":["需要访问 Claude 技能目录","仅限于审计 `~/.claude/skills/` 和 `{cwd}/.claude/skills/` 路径中的技能"],"ja":["Claude スキルディレクトリへのアクセスが必要","`~/.claude/skills/` と `{cwd}/.claude/skills/` パスのスキルのみを監査可能"],"ko":["Claude 스킬 디렉토리에 대한 액세스가 필요함","`~/.claude/skills/` 및 `{cwd}/.claude/skills/` 경로의 스킬만 감사 가능"],"es":["Requiere acceso al directorio de habilidades de Claude","Limitado a la auditoría de habilidades en los caminos `~/.claude/skills/` y `{cwd}/.claude/skills/`"],"fr":["Nécessite l''accès au répertoire de compétences de Claude","Limité à l''audit des compétences dans les chemins `~/.claude/skills/` et `{cwd}/.claude/skills/`"],"de":["Erfordert Zugriff auf das Verzeichnis der Claude-Fähigkeiten","Begrenzt auf die Überprüfung von Fähigkeiten in den Pfaden `~/.claude/skills/` und `{cwd}/.claude/skills/`"],"pt":["Requer acesso ao diretório de habilidades do Claude","Limitado à auditoria de habilidades nos caminhos `~/.claude/skills/` e `{cwd}/.claude/skills/`"],"ru":["Требует доступа к каталогу навыков Claude","Ограничен аудитом навыков по путям `~/.claude/skills/` и `{cwd}/.claude/skills/`"],"ar":["يتطلب الوصول إلى دليل مهارات كلود","محدود بالتدقيق في المهارات في المسارات `~/.claude/skills/` و `{cwd}/.claude/skills/`"]},"version":4},"contentHash":"2964e3b6a11b4d9d76b99a218a5d627c91da63ecc080feb686c895c2e52e37ab","qualityScore":45}');
