INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('T-rav/hyrda/skill-stocktake', 'skill-stocktake', 'T-rav', 'hyrda', 'community', 'skill-stocktake T-rav hyrda community agentic-development agentic-workflow wishful-programming The skill-stocktake audits Claude skills using a quality checklist and AI holistic judgment, benefiting developers with automated quality gates. It supports Quick Scan and Full Stocktake modes. skill-stocktake是一个AIエージェント技能库存检查工具，支持Quick Scan和Full Stocktake两种模式，用于审计Claude技能和命令 skill-stocktakeはAIエージェントのスキルストックテイクツールであり、Quick ScanとFull Stocktakeの2つのモードをサポートし、Claudeのスキルとコマンドを監査します skill-stocktake는 AI 에이전트의 스킬 재고 확인 도구로, Quick Scan과 Full Stocktake 두 가지 모드를 지원하여 Claude의 스킬과 명령어를 감사합니다 Skill-stocktake es una herramienta de auditoría que utiliza un checklist de calidad y un juicio holístico de IA para evaluar las habilidades de Claude Skill-stocktake est un outil d''audit qui utilise une checklist de qualité et un jugement holistique de l''IA pour évaluer les compétences de Claude Skill-stocktake ist ein Audit-Tool, das eine Qualität-Checkliste und ein holistisches Urteil der künstlichen Intelligenz verwendet, um die Fähigkeiten von Claude zu bewerten O Skill-Stocktake é um comando que audita habilidades de Claude usando uma lista de verificação de qualidade e julgamento holístico de IA Skill-Stocktake - это команда, которая проверяет навыки Claude с помощью списка контроля качества и целостной оценки ИИ Skill-Stocktake هو أمر يتدقيق مهارات Claude باستخدام قائمة التحقق من الجودة والحكم الشامل للذكاء الاصطناعي how to use skill-stocktake what is skill-stocktake skill-stocktake alternative skill-stocktake setup guide skill-stocktake install HydraFlow delivery kernel Claude skills audit AI-driven quality judgment AIエージェント 技能库存检查 Claude技能 Quick Scan Full Stocktake AI判斷 holistic judgment agentic-development agentic-workflow Supports two modes: Quick Scan for recently changed skills and Full Stocktake for a complete review Utilizes the /skill-stocktake slash command for auditing Targets global skills in ~/.claude/skills/ and project-level skills in {cwd}/.claude/skills/ Enforces quality gates through a staged pipeline Produces merged software changes using HydraFlow delivery kernel skill-stocktake is a Slash command that audits all Claude skills and commands using a quality checklist and AI-driven judgment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryryo/dot-claude-dev/meta-skill-creator', 'community', 'ryryo', 'dot-claude-dev', 'ryryo/dot-claude-dev', 'meta-skill-creator', 2, 0, 45, '2026-02-28T07:18:44Z', '2026-03-06T07:08:35.976Z', 'e6c11714d4d3af4d64cb5210a221c3a9209450e599709ee0bb49b8d60bbea1f8', '{"id":"ryryo/dot-claude-dev/meta-skill-creator","name":"meta-skill-creator","description":{"en":"The meta-skill-creator skill enables developers to create and update AI agent skills using a story-driven development workflow, benefiting developers working with Claude Code. It supports collaborative and automated processing.","zh":"meta-skill-creator是一种Story-Driven Development工作流，为Claude Code提供Collaborative First、Script First和Progressive Disclosure功能","ja":"meta-skill-creatorは、Claude Code向けのStory-Driven Developmentワークフローであり、Collaborative First、Script First、Progressive Disclosureなどの機能を提供する","ko":"meta-skill-creator는 Claude Code를 위한 Story-Driven Development 워크플로우로 Collaborative First, Script First, Progressive Disclosure 등의 기능을 제공합니다","es":"meta-skill-creator es una herramienta de desarrollo de flujo de trabajo orientado a historias para Claude Code, que permite la creación y mejora de habilidades a través de la colaboración y la automatización","fr":"meta-skill-creator est un outil de workflow de développement basé sur des histoires pour Claude Code, qui permet la création et l''amélioration de compétences via la collaboration et l''automatisation","de":"meta-skill-creator ist ein Werkzeug für die Entwicklung von Story-Driven-Workflows für Claude Code, das die Erstellung und Verbesserung von Fähigkeiten durch Kollaboration und Automatisierung ermöglicht","pt":"O Meta-Skill-Creator é uma ferramenta para criar e melhorar fluxos de trabalho orientados por histórias com Claude Code, utilizando Collaborative First, Script First e Progressive Disclosure","ru":"Meta-Skill-Creator - это инструмент для создания и улучшения рабочих процессов, ориентированных на историю, с Claude Code, используя Collaborative First, Script First и Progressive Disclosure","ar":"Meta-Skill-Creator هو أداة لإنشاء وتحسين تدفقات العمل الموجهة بالسرد مع Claude Code، باستخدام Collaborative First و Script First و Progressive Disclosure"},"seo":{"title":{"en":"meta-skill-creator: Story-Driven Development Workflow Set...","zh":"meta-skill-creator Setup Guide: AIエージェント开发工作流","ja":"meta-skill-creator セットアップガイド: AIエージェント開発ワークフロー","ko":"meta-skill-creator 설정 가이드: AI 에이전트 개발 워크플로우","es":"Guía de configuración de meta-skill-creator para Agentes ...","fr":"Guide de mise en place de meta-skill-creator pour Outils ...","de":"Einrichtungsleitfaden für meta-skill-creator bei KI-Tools","pt":"Guia de Configuração do Meta-Skill-Creator para Ferrament...","ru":"Настройка Meta-Skill-Creator для ИИ Агентов: Руководство","ar":"دليل إعداد Meta-Skill-Creator لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient AI agent development with meta-skill-creator. Learn how to leverage Collaborative First, Script First, and Progressive Disclosure principles...","zh":"了解meta-skill-creator的功能和特点，掌握AIエージェント开发工作流，实现高效开发","ja":"meta-skill-creatorの機能と特徴を理解し、AIエージェント開発ワークフローをマスターして開発効率を向上させる","ko":"meta-skill-creator의 기능과 특징을 이해하고 AI 에이전트 개발 워크플로우를 마스터하여 개발 효율을 향상시키세요","es":"Aprende a crear y mejorar habilidades con meta-skill-creator, una herramienta de desarrollo de flujo de trabajo orientado a historias para Claude Code","fr":"Découvrez comment créer et améliorer des compétences avec meta-skill-creator, un outil de workflow de développement basé sur des histoires pour Claude Code","de":"Erfahren Sie, wie Sie Fähigkeiten mit meta-skill-creator erstellen und verbessern, einem Werkzeug für die Entwicklung von Story-Driven-Workflows für Claude Code","pt":"Aprenda a configurar o Meta-Skill-Creator para desenvolver fluxos de trabalho orientados por histórias com Claude Code e melhore a colaboração comusuários","ru":"Узнайте, как настроить Meta-Skill-Creator для разработки рабочих процессов, ориентированных на историю, с Claude Code и улучшить сотрудничество с пользователями","ar":"تعلم كيفية إعداد Meta-Skill-Creator لإنشاء تدفقات عمل مدفوعة بالسرد مع Claude Code وتحسين التعاون مع المستخدمين"},"definition":{"en":"meta-skill-creator is a meta-skill that facilitates the creation, update, and improvement of AI agent skills through collaborative and scripted workflows.","zh":"meta-skill-creator是一种AIエージェント开发工具，用于创建和更新AI模型","ja":"meta-skill-creatorは、AIエージェント開発ツールであり、AIモデルを作成および更新するために使用される","ko":"meta-skill-creator는 AI 에이전트 개발 도구로 AI 모델을 생성하고 업데이트하는 데 사용됩니다","es":"meta-skill-creator es una herramienta de desarrollo que permite crear y mejorar habilidades para Agentes de IA","fr":"meta-skill-creator est un outil de développement qui permet de créer et d''améliorer des compétences pour les Outils d''IA","de":"meta-skill-creator ist ein Entwicklungstool, das die Erstellung und Verbesserung von Fähigkeiten für KI-Tools ermöglicht","pt":"O Meta-Skill-Creator é uma ferramenta de desenvolvimento de fluxos de trabalho que combina colaboração, script e divulgação progressiva para melhorar a eficiência","ru":"Meta-Skill-Creator - это инструмент разработки рабочих процессов, который сочетает сотрудничество, скрипты и прогрессивное раскрытие для повышения эффективности","ar":"Meta-Skill-Creator هو أداة لتنمية تدفقات العمل التي تجمع بين التعاون والبرمجة والكشف التقدمي لتحسين الكفاءة"},"features":{"en":["Supports Collaborative First principle for user-driven requirement clarification","Utilizes Script First approach for deterministic processing with 100% precision","Employs Progressive Disclosure for efficient resource loading","Allows Custom Script Support for generating unique scripts beyond 24 types","Enables Self-Contained Skills with independent node_modules and dependencies"],"zh":["Collaborative First：用户与AIエージェント之间的协作","Script First：决定论性处理的自动化","Progressive Disclosure：按需加载资源","Custom Script Support：支持24种以上的自定义脚本","Self-Contained Skills：每个技能都有自己的node_modules和依赖关系"],"ja":["Collaborative First：ユーザーとAIエージェントの共同作業","Script First：決定論的処理の自動化","Progressive Disclosure：必要な時に必要なリソースのみ読み込み","Custom Script Support：24種類以上の独自スクリプトをサポート","Self-Contained Skills：各スキルは独自のnode_modulesと依存関係を持つ"],"ko":["Collaborative First: 사용자와 AI 에이전트 간의 협업","Script First: 결정론적 처리의 자동화","Progressive Disclosure: 필요한 리소스만 읽어들이는 기능","Custom Script Support: 24종 이상의 사용자 정의 스크립트 지원","Self-Contained Skills: 각 스킬이 독자적인 node_modules와 종속성을 가짐"],"es":["Colaboración en tiempo real con usuarios","Automatización de procesos deterministas con Script First","Carga progresiva de recursos con Progressive Disclosure","Soporte para scripts personalizados","Habilidades autocontenidas con node_modules y dependencias propias"],"fr":["Collaboration en temps réel avec les utilisateurs","Automatisation de processus déterministes avec Script First","Chargement progressif de ressources avec Progressive Disclosure","Prise en charge de scripts personnalisés","Compétences autocontenues avec node_modules et dépendances propres"],"de":["Echtzeit-Kollaboration mit Benutzern","Automatisierung von deterministischen Prozessen mit Script First","Schrittweises Laden von Ressourcen mit Progressive Disclosure","Unterstützung für benutzerdefinierte Skripte","Selbstständige Fähigkeiten mit node_modules und eigenen Abhängigkeiten"],"pt":["Colaboração em tempo real com usuários","Execução de scripts determinísticos com 100% de precisão","Divulgação progressiva de recursos necessários","Suporte a scripts personalizados","Habilidades autônomas com node_modules e dependências próprias"],"ru":["Взаимодействие с пользователями в режиме реального времени","Выполнение детерминированных скриптов с 100% точностью","Прогрессивное раскрытие необходимых ресурсов","Поддержка пользовательских скриптов","Самостоятельные навыки с собственными node_modules и зависимостями"],"ar":["التعاون في الوقت الفعلي مع المستخدمين","تنفيذ البرامج المحددة بدقة 100%","الكشف التقدمي للموارد اللازمة","دعم البرامج المخصصة","المهارات المستقلة مع node_modules والاعتماديات الخاصة بها"]},"keywords":{"en":["how to use meta-skill-creator","meta-skill-creator alternative","meta-skill-creator setup guide","what is meta-skill-creator","meta-skill-creator vs competitors","meta-skill-creator install","story-driven development workflow","Collaborative First principle","Script First approach"],"zh":["AIエージェント开发","Story-Driven Development","Collaborative First","Script First","Progressive Disclosure","meta-skill-creator","Claude Code","AI模型创建","AI模型更新"],"ja":["AIエージェント開発","Story-Driven Development","Collaborative First","Script First","Progressive Disclosure","meta-skill-creator","Claude Code","AIモデル作成","AIモデル更新"],"ko":["AI 에이전트 개발","Story-Driven Development","Collaborative First","Script First","Progressive Disclosure","meta-skill-creator","Claude Code","AI 모델 생성","AI 모델 업데이트"],"es":["meta-skill-creator","Agentes de IA","Desarrollo de habilidades","Colaboración en tiempo real","Automatización de procesos","Script First","Progressive Disclosure","node_modules","Claude Code"],"fr":["meta-skill-creator","Outils d''IA","Développement de compétences","Collaboration en temps réel","Automatisation de processus","Script First","Progressive Disclosure","node_modules","Claude Code"],"de":["meta-skill-creator","KI-Tools","Entwicklung von Fähigkeiten","Echtzeit-Kollaboration","Automatisierung von Prozessen","Script First","Progressive Disclosure","node_modules","Claude Code"],"pt":["Meta-Skill-Creator","Ferramentas de IA","Desenvolvimento de fluxos de trabalho","Colaboração em tempo real","Script determinístico","Divulgação progressiva","Claude Code","Desenvolvimento de software"],"ru":["Meta-Skill-Creator","ИИ Агенты","Разработка рабочих процессов","Сотрудничество в режиме реального времени","Детерминированный скрипт","Прогрессивное раскрытие","Claude Code","Разработка программного обеспечения"],"ar":["Meta-Skill-Creator","أدوات الذكاء الاصطناعي","تنمية تدفقات العمل","التعاون في الوقت الفعلي","البرمجة المحددة","الكشف التقدمي","Claude Code","تنمية البرمجيات"]}},"owner":"ryryo","repo":"dot-claude-dev","repoPath":"ryryo/dot-claude-dev","stars":2,"forks":0,"updatedAt":"2026-02-28T07:18:44Z","topics":[],"category":"community","skillMd":{"name":"meta-skill-creator","description":"|","bodyPreview":"# Skill Creator\n\n## 概要\n\nスキルを作成・更新・プロンプト改善するためのメタスキル。\n**Collaborative First**でユーザーと対話しながら共創、**Script First**で決定論的処理を自動化、**Progressive Disclosure**で必要なリソースのみを読み込む。\n\n## 設計原則\n\n| 原則 | 説明 |\n|------|------|\n| **Collaborative First** | ユーザーとの対話を通じて要件を明確化 |\n| Script First | 決定論的処理はスクリプトで実行（100%精度） |\n| Progressive Disclosure | 必要な時に必要なリソースのみ読み込み |\n| Custom Script Support | 24タイプに収まらない独自スクリプトも生成 |\n| Self-Contained Skills | 各スキルは独自のnode_modules・依存関係を持つ |\n\n## モード一覧\n\n| モード | 用途 | 開始方法 |\n|--------|------|-----","body":"# Skill Creator\n\n## 概要\n\nスキルを作成・更新・プロンプト改善するためのメタスキル。\n**Collaborative First**でユーザーと対話しながら共創、**Script First**で決定論的処理を自動化、**Progressive Disclosure**で必要なリソースのみを読み込む。\n\n## 設計原則\n\n| 原則 | 説明 |\n|------|------|\n| **Collaborative First** | ユーザーとの対話を通じて要件を明確化 |\n| Script First | 決定論的処理はスクリプトで実行（100%精度） |\n| Progressive Disclosure | 必要な時に必要なリソースのみ読み込み |\n| Custom Script Support | 24タイプに収まらない独自スクリプトも生成 |\n| Self-Contained Skills | 各スキルは独自のnode_modules・依存関係を持つ |\n\n## モード一覧\n\n| モード | 用途 | 開始方法 |\n|--------|------|----------|\n| **collaborative** | ユーザー対話型スキル共創（推奨） | AskUserQuestionでインタビュー開始 |\n| **orchestrate** | 実行エンジン選択（Claude/Codex/連携） | AskUserQuestionでヒアリング開始 |\n| create | 要件が明確な場合の新規作成 | `.claude/skills/meta-skill-creator/scripts/detect_mode.js --request \"新規スキル\"` |\n| update | 既存スキル更新 | `.claude/skills/meta-skill-creator/scripts/detect_mode.js --request \"更新\" --skill-path <path>` |\n| improve-prompt | プロンプト改善 | `.claude/skills/meta-skill-creator/scripts/analyze_prompt.js --skill-path <path>` |\n\n## 実行エンジン（orchestrateモード）\n\n| エンジン | 説明 | 適用場面 |\n|----------|------|----------|\n| **claude** | Claude Code単独実行 | ファイル編集、Git操作、コードベース深い理解 |\n| **codex** | Codex (GPT-5.2) 単独実行 | 独立したタスク、別視点での分析 |\n| **claude-to-codex** | Claude → Codex連携 | コンテキスト共有が必要な複合タスク |\n\n## 抽象度レベル\n\n| レベル | 説明 | 例 |\n|--------|------|-----|\n| **L1: Concept** | アイデア・課題レベル | 「開発効率を上げたい」 |\n| **L2: Capability** | 機能・能力レベル | 「PRを自動作成したい」 |\n| **L3: Implementation** | 実装・詳細レベル | 「GitHub APIでPR作成」 |\n\n**抽象度が高いほど、インタビューを通じて具体化する。**\n📖 詳細: [references/abstraction-levels.md](.claude/skills/meta-skill-creator/references/abstraction-levels.md)\n\n---\n\n# Part 0: Collaborative モード（推奨）\n\nユーザーと対話しながらスキルを共創するモード。\n\n## ワークフロー\n\n```\nPhase 0-1: 初期ヒアリング\n  Q1: 何を実現したいですか？ → 抽象度レベル判定\n  Q2: 対象は何ですか？ → コンテキスト特定\n  Q3: 頻度・規模は？ → 複雑さ判定\n      ↓\nPhase 0-2: 機能ヒアリング\n  Q4: 必要な機能は？\n  Q5: 外部連携は？\n  Q6: スクリプトは？\n      ↓\nPhase 0-3: 構成ヒアリング\n  Q7: 構成タイプは？（シンプル/標準/フル）\n  Q8: 優先事項は？\n      ↓\nPhase 0-4: 要件確認\n  → ユーザー確認後、Phase 1へ\n```\n\n📖 詳細: [agents/interview-user.md](.claude/skills/meta-skill-creator/agents/interview-user.md)\n\n---\n\n# Part 0.5: Orchestrate モード（実行エンジン選択）\n\n**スキル作成プロセス内**で、特定のサブタスクを最適な実行エンジンに委譲するモード。\n\n```\nskill-creator実行中 → 特定タスクでCodex使用 → Claude Code継続\n```\n\n## ワークフロー\n\n```\nPhase 1-2: ヒアリング\n  → .claude/skills/meta-skill-creator/agents/interview-execution-mode.md\n  タスク内容・コンテキスト判定 → モード推奨・選択\n      ↓\nPhase 3: 実行（モード別分岐）\n  claude: 直接実行\n  codex: .claude/skills/meta-skill-creator/scripts/assign_codex.js\n  claude-to-codex: コンテキスト収集 → Codex\n      ↓\nPhase 4: 結果確認・統合\n```\n\n📖 モード選択基準・詳細フローチャート: [references/execution-mode-guide.md](.claude/skills/meta-skill-creator/references/execution-mode-guide.md)\n\n## 関連リソース\n\n| リソース | 読み込み条件 |\n|----------|-------------|\n| [interview-execution-mode.md](.claude/skills/meta-skill-creator/agents/interview-execution-mode.md) | Phase 1-2 |\n| [delegate-to-codex.md](.claude/skills/meta-skill-creator/agents/delegate-to-codex.md) | Codex実行時 |\n| [execution-mode-guide.md](.claude/skills/meta-skill-creator/references/execution-mode-guide.md) | 判断に迷った時 |\n\n---\n\n# Part 1: スキル作成ワークフロー（createモード）\n\n```\nPhase 1: 分析（LLM）\n  .claude/skills/meta-skill-creator/agents/analyze-request.md\n  → .claude/skills/meta-skill-creator/agents/extract-purpose.md\n  → .claude/skills/meta-skill-creator/agents/define-boundary.md\n      ↓\nPhase 2: 設計（LLM + Script検証）\n  .claude/skills/meta-skill-creator/agents/select-anchors.md ─┐\n  .claude/skills/meta-skill-creator/agents/define-trigger.md ─┤\n      → .claude/skills/meta-skill-creator/agents/design-workflow.md\n      → .claude/skills/meta-skill-creator/scripts/validate_workflow.js\n      ↓\nPhase 3: 構造計画（LLM + Script検証）\n  .claude/skills/meta-skill-creator/agents/plan-structure.md\n  → .claude/skills/meta-skill-creator/scripts/validate_plan.js\n      ↓\nPhase 4: 生成（Script）\n  .claude/skills/meta-skill-creator/scripts/init_skill.js\n  → .claude/skills/meta-skill-creator/scripts/generate_skill_md.js\n  → .claude/skills/meta-skill-creator/scripts/generate_agent.js\n      ↓\nPhase 5: フィードバック機構生成（Script）\n  → LOGS.md, EVALS.json, references/patterns.md を生成\n      ↓\nPhase 6: 検証（Script）\n  .claude/skills/meta-skill-creator/scripts/validate_all.js\n  → .claude/skills/meta-skill-creator/scripts/log_usage.js\n```\n\n---\n\n# Part 2: スクリプト生成ワークフロー\n\n## 24種類のスクリプトタイプ\n\n| カテゴリ | タイプ |\n|----------|--------|\n| API関連 | api-client, webhook, scraper, notification |\n| データ処理 | parser, transformer, aggregator, file-processor |\n| ストレージ | database, cache, queue |\n| 開発ツール | git-ops, test-runner, linter, formatter, builder |\n| インフラ | deployer, docker, cloud, monitor |\n| 統合 | ai-tool, mcp-bridge, shell |\n| 汎用 | universal |\n\n📖 詳細: [references/script-types-catalog.md](.claude/skills/meta-skill-creator/references/script-types-catalog.md)\n\n## 生成ワークフロー\n\n```\nPhase 1: 要件分析（LLM）→ script-requirement.json\nPhase 2: ランタイム判定（Script）→ runtime-config.json\nPhase 3: 設計（LLM）→ script-design.json\nPhase 4: 変数設計（LLM）→ variables.json\nPhase 5: コード生成（LLM）→ script-template.{ext}\nPhase 6: コード展開（Script）→ 実行可能スクリプト\nPhase 7: 検証（Script）\n```\n\n📖 カスタムスクリプト: [agents/design-custom-script.md](.claude/skills/meta-skill-creator/agents/design-custom-script.md)\n\n---\n\n# Part 3: フィードバック＆自己改善ワークフロー\n\n## 3.1 毎回実行後（必須）\n\nスキル実行後は必ずフィードバックを記録する：\n\n```bash\n# 成功時\nnode .claude/skills/meta-skill-creator/scripts/log_usage.js --result success --phase \"Phase 4\" --notes \"完了\"\n\n# 失敗時\nnode .claude/skills/meta-skill-creator/scripts/log_usage.js --result failure --phase \"Phase 3\" --error \"ValidationError\" --notes \"理由\"\n```\n\n**記録先**:\n| ファイル | 更新内容 |\n|----------|----------|\n| LOGS.md | 実行ログ（日時、結果、フェーズ、メモ） |\n| EVALS.json | メトリクス（成功率、実行回数、平均時間） |\n\n## 3.2 パターン発見時\n\n成功/失敗パターンを発見したら記録する：\n\n```\n.claude/skills/meta-skill-creator/agents/analyze-feedback.md → パターン検出\n     ↓\n.claude/skills/meta-skill-creator/agents/save-patterns.md\n     → .claude/skills/meta-skill-creator/references/patterns.md 更新\n```\n\n**パターン形式**:\n- 成功パターン: 状況 → アプローチ → 結果 → 適用条件\n- 失敗パターン: 状況 → 問題 → 原因 → 教訓\n\n## 3.3 改善サイクル\n\n定期的（10回実行ごと、またはエラー率閾値超過時）に改善を検討：\n\n```\n.claude/skills/meta-skill-creator/scripts/collect_feedback.js → feedback-data.json出力\n     ↓\n.claude/skills/meta-skill-creator/agents/analyze-feedback.md → パターン分析・改善提案生成\n     ├─ patterns[] あり → .claude/skills/meta-skill-creator/agents/save-patterns.md\n     │                  → .claude/skills/meta-skill-creator/references/patterns.md更新\n     └─ suggestions[] あり → .claude/skills/meta-skill-creator/agents/design-self-improvement.md\n     ↓\n.claude/skills/meta-skill-creator/scripts/apply_self_improvement.js → 改善適用\n  --dry-run: 事前確認（推奨）\n  --backup: バックアップ作成\n  --auto-only: 自動適用可能なもののみ\n```\n\n📖 詳細: [references/self-improvement-cycle.md](.claude/skills/meta-skill-creator/references/self-improvement-cycle.md)\n\n## 3.4 フィードバック対象ファイル\n\n| ファイル | 用途 | 更新タイミング | スクリプト/エージェント |\n|----------|------|----------------|------------------------|\n| LOGS.md | 実行ログ | 毎回実行後 | [scripts/log_usage.js](.claude/skills/meta-skill-creator/scripts/log_usage.js) |\n| EVALS.json | メトリクス | 毎回実行後 | [scripts/log_usage.js](.claude/skills/meta-skill-creator/scripts/log_usage.js) |\n| references/patterns.md | 成功/失敗パターン | パターン発見時 | [agents/save-patterns.md](.claude/skills/meta-skill-creator/agents/save-patterns.md) |\n\n---\n\n# Part 4: ライブラリ管理（Self-Contained Skills）\n\nスキルは自己完結型。依存関係は**スキルディレクトリ内**で管理し、PNPMを使用する。\n\n## 4.1 設計思想\n\n| 原則 | 説明 |\n|------|------|\n| 自己完結 | 各スキルが独自のnode_modules・package.jsonを持つ |\n| 分離 | プロジェクト本体の依存関係と干渉しない |\n| 再現性 | pnpm-lock.yamlで依存関係を固定 |\n\n## 4.2 依存関係管理コマンド\n\n```bash\n# スキルの依存関係をインストール\nnode .claude/skills/meta-skill-creator/scripts/install_deps.js\n\n# パッケージを追加\nnode .claude/skills/meta-skill-creator/scripts/add_dependency.js axios\n\n# 開発依存関係として追加\nnode .claude/skills/meta-skill-creator/scripts/add_dependency.js typescript --dev\n\n# 他のスキルに対して実行\nnode .claude/skills/meta-skill-creator/scripts/install_deps.js --skill-path .claude/skills/my-skill\n```\n\n## 4.3 スキル構造（依存関係あり）\n\n```\n.claude/skills/my-skill/\n├── package.json       # 依存関係定義\n├── pnpm-lock.yaml     # 依存関係ロック（自動生成）\n├── node_modules/      # 依存関係（スキル内に配置）\n├── SKILL.md\n├── scripts/\n│   └── my-script.js   # import from ''axios'' 等が使用可能\n└── ...\n```\n\n📖 詳細: [references/library-management.md](.claude/skills/meta-skill-creator/references/library-management.md)\n\n---\n\n# Part 5: Progressive Disclosure リソースマップ\n\nリソースは**必要な時のみ**読み込む。詳細は [resource-map.md](.claude/skills/meta-skill-creator/references/resource-map.md) を参照。\n\n## リソース概要\n\n| カテゴリ | 数 | 主な読み込み条件 |\n|----------|-----|-----------------|\n| agents/ | 20 | モード・Phase別に必要時のみ |\n| references/ | 23 | 設計・判断・詳細確認時 |\n| scripts/ | 25 | 決定論的処理実行時（utils.js共通） |\n| assets/ | 17 | 生成・テンプレート展開時 |\n| schemas/ | 23 | JSON検証時 |\n\n## 主要リソース（高頻度）\n\n| リソース | 読み込み条件 |\n|----------|-------------|\n| [agents/interview-user.md](.claude/skills/meta-skill-creator/agents/interview-user.md) | collaborativeモード |\n| [agents/analyze-request.md](.claude/skills/meta-skill-creator/agents/analyze-request.md) | createモード |\n| [scripts/utils.js](.claude/skills/meta-skill-creator/scripts/utils.js) | 全スクリプト共通 |\n| [scripts/init_skill.js](.claude/skills/meta-skill-creator/scripts/init_skill.js) | スキル初期化 |\n| [scripts/log_usage.js](.claude/skills/meta-skill-creator/scripts/log_usage.js) | 毎回実行後 |\n| [references/script-commands.md](.claude/skills/meta-skill-creator/references/script-commands.md) | スクリプト実行時 |\n| [references/resource-map.md](.claude/skills/meta-skill-creator/references/resource-map.md) | 全リソース詳細 |\n\n📖 全リソース詳細: [references/resource-map.md](.claude/skills/meta-skill-creator/references/resource-map.md)\n\n---\n\n## ベストプラクティス\n\n| すべきこと | 避けるべきこと |\n|-----------|---------------|\n| Script優先（決定論的処理） | 全リソースを一度に読み込む |\n| LLMは判断・創造のみ | Script可能な処理をLLMに任せる |\n| Progressive Disclosure | 具体例をテンプレートに書く |\n| 中間出力は.tmp/に保存 | 中間ファイルを省略 |\n\n---\n\n## 変更履歴\n\n| Version | Date | Changes |\n|---------|------|---------|\n| **5.7.0** | **2026-01-21** | **SKILL.md最適化: Part 5をresource-map.mdに分離（485→375行、23%削減）、スクリプトutils.js統合完了** |\n| 5.6.1 | 2026-01-21 | DRYリファクタリング: utils.js共通モジュール作成、約270行の重複コード排除 |\n| 5.6.0 | 2026-01-21 | Self-Contained Skills: PNPM依存関係管理、package.json自動生成、install_deps.js/add_dependency.js追加 |\n| 5.5.2 | 2026-01-20 | 参照パス完全統一: ワークフロー図・コマンド例・テーブル内のすべての参照を完全パス化（105参照） |\n| 5.5.1 | 2026-01-20 | 参照パス統一: Markdownリンクをリポジトリルートからの相対パスに統一 |\n| 5.5.0 | 2026-01-20 | 最適化: SKILL.md 521→420行に削減、Part 0.5詳細をexecution-mode-guide.mdへ移動 |\n| 5.4.0 | 2026-01-20 | フィードバック機構強化: Part 3をフィードバック＆自己改善に拡張、save-patterns.mdエージェント追加 |\n| 5.3.0 | 2026-01-15 | Progressive Disclosure完全化: 全ファイル（19 refs, 23 schemas, 34 assets, 22 scripts）に読み込み条件追加 |\n| 5.2.1 | 2026-01-15 | Codex連携の目的明確化: スキル作成内サブタスク委譲用、Claude Code⇄Codexラウンドトリップパターン |\n| 5.2.0 | 2026-01-15 | Orchestrateモード追加: Codex連携機能、実行エンジン選択（claude/codex/claude-to-codex） |\n| 5.1.0 | 2026-01-15 | リファクタリング: SKILL.md簡素化、agents/フォーマット統一、workflow-patterns.md統合 |\n| 5.0.0 | 2026-01-15 | Collaborative First追加、抽象度レベル対応、カスタムスクリプト対応 |\n| 4.0.0 | 2026-01-13 | スクリプト生成ワークフロー追加、自己改善サイクル追加 |\n| 3.0.0 | 2026-01-06 | 3モード対応（create/update/improve-prompt） |\n"},"lastSynced":"2026-03-06T07:08:35.976Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code needing collaborative and automated skill development workflows with story-driven development and Custom Script Support","zh":"适合于 Claude Code 等 AI Agent，需要具有协作和自动化技能开发工作流的故事驱动开发和自定义脚本支持","ja":"Claude Code などの AI エージェントに適しています。協力的な自動化されたスキル開発ワークフローとストーリー駆動開発およびカスタムスクリプトサポートが必要です","ko":"Claude Code 와 같은 AI 에이전트에게 적합합니다. 협력적이고 자동화된 스킬 개발 워크플로 및 스토리 驱动 개발과 커스텀 스크립트 지원이 필요합니다","es":"Ideal para agentes de IA como Claude Code que necesitan flujos de trabajo de desarrollo de habilidades colaborativas y automatizadas con desarrollo impulsado por historias y soporte de script personalizado","fr":"Idéal pour les agents IA comme Claude Code nécessitant des flux de travail de développement de compétences collaboratifs et automatisés avec un développement piloté par l''histoire et un support de script personnalisé","de":"Ideal für KI-Agents wie Claude Code, die collaborative und automatisierte Fähigkeitsentwicklungs-Workflows mit storygetriebenem Entwickeln und benutzerdefiniertem Skriptunterstützung benötigen","pt":"Ideal para Agentes de IA como Claude Code que necessitam de fluxos de trabalho de desenvolvimento de habilidades colaborativas e automatizadas com desenvolvimento orientado a histórias e Suporte a Script Personalizado","ru":"Идеально для агентов ИИ, таких как Claude Code, требующих совместных и автоматизированных рабочих процессов разработки навыков с разработкой, ориентированной на историю, и поддержкой пользовательских скриптов","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude Code الذين يحتاجون إلى سير عمل تطوير المهارات التعاونية والآلية مع تطوير قائم على القصة ودعم البرامج النصية المخصصة"},"recommendation":{"en":"Empowers agents to create and update skills using Collaborative First, Script First, and Progressive Disclosure principles, supporting 24 types of custom scripts and self-contained skills with node_modules and dependencies","zh":"赋予代理创建和更新技能的能力，使用协作优先、脚本优先和渐进披露原则，支持 24 种自定义脚本和自包含技能，具有 node_modules 和依赖项","ja":"エージェントがスキルを作成および更新できるようにします。コラボレーションファースト、スクリプトファースト、プログレッシブディスクロージャーの原則を使用し、24 種類のカスタムスクリプトとセルフコンテイニングスキルをサポートし、node_modules と依存関係を備えています","ko":"에이전트가 협력 우선, 스크립트 우선, 점진적 공개 원칙을 사용하여 스킬을 생성하고 업데이트할 수 있도록 합니다. 24종의 커스텀 스크립트와 자체 포함 스킬을 지원하며 node_modules 및 종속 항목을 가집니다","es":"Habilita a los agentes a crear y actualizar habilidades utilizando los principios de Colaboración Primero, Script Primero y Divulgación Progresiva, y soporta 24 tipos de scripts personalizados y habilidades autocontenidas con node_modules y dependencias","fr":"Permet aux agents de créer et de mettre à jour des compétences en utilisant les principes de Collaboration First, Script First et de Divulgation progressive, et prend en charge 24 types de scripts personnalisés et des compétences autocontenues avec node_modules et des dépendances","de":"Ermächtigt Agents, Fähigkeiten zu erstellen und zu aktualisieren, indem sie die Prinzipien von Collaborative First, Script First und Progressiver Offenlegung verwenden, und unterstützt 24 Arten von benutzerdefinierten Skripten und selbstenthaltenen Fähigkeiten mit node_modules und Abhängigkeiten","pt":"Habilita os agentes a criar e atualizar habilidades usando os princípios Primeiro Colaborativo, Primeiro Script e Divulgação Progressiva, suportando 24 tipos de scripts personalizados e habilidades autocontidas com node_modules e dependências","ru":"Наделяет агентов возможностью создавать и обновлять навыки, используя принципы Совместное первым, Скрипт первым и Постепенное раскрытие, поддерживая 24 типа пользовательских скриптов и самодостаточные навыки с node_modules и зависимостями","ar":"تمكين الوكلاء من إنشاء وتحديث المهارات باستخدام مبدأ التعاون الأول وبرمجة النص الأول والإفصاح التدريجي ، ودعم 24 نوعًا من البرامج النصية المخصصة والمهارات المحتوية على node_modules والاعتماديات"},"useCases":{"en":["Automating skill updates with deterministic script execution","Generating new skills through collaborative user interactions","Optimizing skill development with progressive disclosure of necessary resources"],"zh":["使用确定性脚本执行自动化技能更新","通过协作用户交互生成新技能","使用渐进披露必要资源优化技能开发"],"ja":["決定性スクリプトの実行によるスキル更新の自動化","コラボレーションによるユーザーインタラクションを介した新しいスキルの生成","必要なリソースのプログレッシブディスクロージャによるスキル開発の最適化"],"ko":["결정적 스크립트 실행을 통한 스킬 업데이트 자동화","協力적 사용자 상호작용을 통해 새로운 스킬 생성","필요한 리소스의 점진적 공개를 통한 스킬 개발 최적화"],"es":["Automatizar las actualizaciones de habilidades con ejecución de scripts determinista","Generar nuevas habilidades a través de interacciones de usuario colaborativas","Optimizar el desarrollo de habilidades con divulgación progresiva de recursos necesarios"],"fr":["Automatiser les mises à jour de compétences avec une exécution de scripts déterministe","Générer de nouvelles compétences via des interactions utilisateur collaboratives","Optimiser le développement de compétences avec une divulgation progressive des ressources nécessaires"],"de":["Automatisieren von Fähigkeitsupdates mit deterministischer Skriptausführung","Erstellen neuer Fähigkeiten durch kollaborative Benutzerinteraktionen","Optimieren der Fähigkeitsentwicklung mit progressiver Offenlegung der erforderlichen Ressourcen"],"pt":["Automatizar atualizações de habilidades com execução de script determinística","Gerar novas habilidades por meio de interações colaborativas do usuário","Otimizar o desenvolvimento de habilidades com divulgação progressiva de recursos necessários"],"ru":["Автоматизировать обновления навыков с определенной исполнением скрипта","Генерировать новые навыки посредством совместных взаимодействий пользователей","Оптимизировать разработку навыков с постепенным раскрытием необходимых ресурсов"],"ar":["توفير تحديثات المهارات تلقائيًا باستخدام تنفيذ البرنامج النصي المتعين","توليد مهارات جديدة من خلال التفاعلات التعاونية للمستخدم","تحسين تطوير المهارات من خلال الإفصاح التدريجي عن الموارد الضرورية"]},"limitations":{"en":["Requires collaborative workflow setup","Limited to script-based automation","Dependent on node_modules and custom script compatibility"],"zh":["需要协作工作流设置","仅限脚本 기반自动化","依赖于 node_modules 和自定义脚本兼容性"],"ja":["コラボレーションワークフローの設定が必要","スクリプトベースの自動化のみ","node_modules とカスタムスクリプトの互換性に依存"],"ko":["협력 워크플로 설정 필요","스크립트 기반 자동화만 가능","node_modules 및 커스텀 스크립트 호환성에 의존"],"es":["Requiere configuración de flujo de trabajo colaborativo","Limitado a la automatización basada en scripts","Dependiente de la compatibilidad de node_modules y scripts personalizados"],"fr":["Nécessite une configuration de flux de travail collaboratif","Limité à l''automatisation basée sur les scripts","Dépendant de la compatibilité des node_modules et des scripts personnalisés"],"de":["Benötigt eine Konfiguration des kollaborativen Workflows","Begrenzt auf skriptbasierte Automatisierung","Abhängig von der Kompatibilität von node_modules und benutzerdefinierten Skripten"],"pt":["Requer configuração de fluxo de trabalho colaborativo","Limitado à automação baseada em script","Dependente da compatibilidade de node_modules e scripts personalizados"],"ru":["Требует настройки совместного рабочего процесса","Ограничен автоматизацией на основе скрипта","Зависит от совместимости node_modules и пользовательских скриптов"],"ar":["يتطلب إعداد سير عمل تعاوني","محدود بالتutomatisation القائمة على البرنامج النصي","يعتمد على توافق node_modules والبرامج النصية المخصصة"]},"version":4},"contentHash":"e6c11714d4d3af4d64cb5210a221c3a9209450e599709ee0bb49b8d60bbea1f8","qualityScore":45}');
