INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryryo/dot-claude-dev/meta-skill-creator', 'meta-skill-creator', 'ryryo', 'dot-claude-dev', 'community', 'meta-skill-creator ryryo dot-claude-dev community The meta-skill-creator skill enables developers to create and update AI agent skills using a story-driven development workflow, benefiting developers working with Claude Code. It supports collaborative and automated processing. meta-skill-creator是一种Story-Driven Development工作流，为Claude Code提供Collaborative First、Script First和Progressive Disclosure功能 meta-skill-creatorは、Claude Code向けのStory-Driven Developmentワークフローであり、Collaborative First、Script First、Progressive Disclosureなどの機能を提供する meta-skill-creator는 Claude Code를 위한 Story-Driven Development 워크플로우로 Collaborative First, Script First, Progressive Disclosure 등의 기능을 제공합니다 meta-skill-creator es una herramienta de desarrollo de flujo de trabajo orientado a historias para Claude Code, que permite la creación y mejora de habilidades a través de la colaboración y la automatización meta-skill-creator est un outil de workflow de développement basé sur des histoires pour Claude Code, qui permet la création et l''amélioration de compétences via la collaboration et l''automatisation meta-skill-creator ist ein Werkzeug für die Entwicklung von Story-Driven-Workflows für Claude Code, das die Erstellung und Verbesserung von Fähigkeiten durch Kollaboration und Automatisierung ermöglicht O Meta-Skill-Creator é uma ferramenta para criar e melhorar fluxos de trabalho orientados por histórias com Claude Code, utilizando Collaborative First, Script First e Progressive Disclosure Meta-Skill-Creator - это инструмент для создания и улучшения рабочих процессов, ориентированных на историю, с Claude Code, используя Collaborative First, Script First и Progressive Disclosure Meta-Skill-Creator هو أداة لإنشاء وتحسين تدفقات العمل الموجهة بالسرد مع Claude Code، باستخدام Collaborative First و Script First و Progressive Disclosure how to use meta-skill-creator meta-skill-creator alternative meta-skill-creator setup guide what is meta-skill-creator meta-skill-creator vs competitors meta-skill-creator install story-driven development workflow Collaborative First principle Script First approach AIエージェント开发 Story-Driven Development Collaborative First Script First Progressive Disclosure meta-skill-creator Claude Code AI模型创建 AI模型更新 Supports Collaborative First principle for user-driven requirement clarification Utilizes Script First approach for deterministic processing with 100% precision Employs Progressive Disclosure for efficient resource loading Allows Custom Script Support for generating unique scripts beyond 24 types Enables Self-Contained Skills with independent node_modules and dependencies meta-skill-creator is a meta-skill that facilitates the creation, update, and improvement of AI agent skills through collaborative and scripted workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mikemikula/AI-Coding-Summit-2026/nextjs-best-practices', 'community', 'mikemikula', 'AI-Coding-Summit-2026', 'mikemikula/AI-Coding-Summit-2026', 'nextjs-best-practices', 2, 2, 45, '2026-02-27T13:57:22Z', '2026-03-06T07:09:17.565Z', 'eeae8ebf60fe9a8f982c9228cccd9f8bce9a717ead6111dd3d99e036f2ec72bc', '{"id":"mikemikula/AI-Coding-Summit-2026/nextjs-best-practices","name":"nextjs-best-practices","description":{"en":"The nextjs-best-practices skill provides technical guidance on optimizing Next.js applications by leveraging Server and Client Components. It benefits developers seeking to improve their application''s performance and scalability.","zh":"Next.js 最佳实践包括默认使用服务器组件，仅在交互叶节点添加 ''use client''，优化应用性能","ja":"Next.js のベストプラクティスには、デフォルトでサーバーコンポーネントを使用し、交互作用する葉ノードのみで ''use client'' を追加することが含まれる、アプリケーションのパフォーマンスを最適化","ko":"Next.js 최상의 실천 방법에는 서버 컴포넌트를 기본으로 사용하고, 상호 작용하는 리프 노드에서만 ''use client''를 추가하는 것이 포함되어 애플리케이션의 성능을 최적화","es":"Las mejores prácticas de Next.js incluyen la utilización de componentes del servidor y del cliente de manera efectiva","fr":"Les meilleures pratiques Next.js incluent l''utilisation efficace des composants serveur et client","de":"Die besten Praktiken von Next.js umfassen die effektive Verwendung von Server- und Clientkomponenten","pt":"As melhores práticas do Next.js para criar aplicações web escaláveis e performáticas, incluindo arquitetura de servidor e componentes cliente","ru":"Лучшие практики Next.js для создания масштабируемых и производительных веб-приложений, включая архитектуру сервера и клиентских компонентов","ar":"أفضل ممارسات Next.js لإنشاء تطبيقات ويب قابلة للتوسيع وأداء عالية، بما في ذلك عمارة الخادم ومكونات العميل"},"seo":{"title":{"en":"nextjs-best-practices: Best Practices Setup Guide | AI Ag...","zh":"Next.js 最佳实践设置指南","ja":"Next.js ベストプラクティス設定ガイド","ko":"Next.js 최고의 실践 설정 가이드","es":"Mejores prácticas de Next.js: Guía de configuración","fr":"Meilleures pratiques Next.js: Guide de mise en place","de":"Next.js Best Practices: Einrichtungsleitfaden","pt":"Melhores Práticas do Next.js: Guia de Configuração","ru":"Лучшие практики Next.js: Настройка и оптимизация ИИ Агентов","ar":"أفضل ممارسات Next.js: دليل الإعداد والإستخدام"},"description":{"en":"Unlock optimal Next.js performance with our expert-backed best practices. Learn how to configure Server and Client Components for maximum efficiency.","zh":"了解 Next.js 16 最佳实践，优化您的应用性能，包括服务器组件和客户端组件的使用","ja":"Next.js 16 のベストプラクティスを学び、アプリケーションのパフォーマンスを最適化する、サーバーコンポーネントとクライアントコンポーネントの使用を含む","ko":"Next.js 16 최상의 실천 방법을 배우고 애플리케이션의 성능을 최적화 하세요, 서버 컴포넌트와 클라이언트 컴포넌트의 사용을 포함","es":"Aprende las mejores prácticas de Next.js para optimizar tu aplicación web con componentes del servidor y del cliente","fr":"Découvrez les meilleures pratiques Next.js pour optimiser votre application web avec des composants serveur et client","de":"Erfahren Sie die besten Praktiken von Next.js, um Ihre Webanwendung mit Server- und Clientkomponenten zu optimieren","pt":"Aprenda as melhores práticas do Next.js para criar aplicações web escaláveis e performáticas, incluindo arquitetura de servidor e componentes cliente","ru":"Узнайте лучшие практики Next.js для создания масштабируемых и производительных веб-приложений, включая архитектуру сервера и клиентских компонентов ИИ Агентов","ar":"تعلم أفضل ممارسات Next.js لإنشاء تطبيقات ويب قابلة للتوسيع وأداء عالية، بما في ذلك عمارة الخادم ومكونات العميل"},"definition":{"en":"nextjs-best-practices is a set of guidelines for optimizing Next.js applications, focusing on Server and Client Component architecture and data fetching strategies.","zh":"Next.js 最佳实践是指一系列优化 Next.js 应用的方法和技术","ja":"Next.js のベストプラクティスとは、Next.js アプリケーションを最適化する一連の方法と技術のこと","ko":"Next.js 최상의 실천 방법은 Next.js 애플리케이션을 최적화하는 일련의 방법과 기술을 말함","es":"Las mejores prácticas de Next.js son directrices para desarrollar aplicaciones web escalables y de alto rendimiento","fr":"Les meilleures pratiques Next.js sont des directives pour développer des applications web évolutives et hautes performances","de":"Die besten Praktiken von Next.js sind Richtlinien für die Entwicklung von skalierbaren und leistungsstarken Webanwendungen","pt":"As melhores práticas do Next.js são um conjunto de diretrizes para criar aplicações web escaláveis e performáticas","ru":"Лучшие практики Next.js - это набор рекомендаций для создания масштабируемых и производительных веб-приложений","ar":"أفضل ممارسات Next.js هي مجموعة من الإرشادات لإنشاء تطبيقات ويب قابلة للتوسيع وأداء عالية"},"features":{"en":["Defaulting to Server Components with optional ''use client'' directive","Minimizing client-side JavaScript by pushing ''use client'' deep in the component tree","Fetching data and accessing server resources exclusively in Server Components","Composing Server Components with Client Components for seamless data passing","Using async functions for server-side data fetching, such as in ProductPage components"],"zh":["默认使用服务器组件","仅在交互叶节点添加 ''use client''","优化应用性能","使用 ''use client'' 最小化客户端 JS","组合服务器组件和客户端组件"],"ja":["サーバーコンポーネントをデフォルトで使用","交互作用する葉ノードのみで ''use client'' を追加","アプリケーションのパフォーマンスを最適化","''use client'' を使用してクライアント JS を最小化","サーバーコンポーネントとクライアントコンポーネントを組み合わせ"],"ko":["서버 컴포넌트를 기본으로 사용","상호 작용하는 리프 노드에서만 ''use client''를 추가","애플리케이션의 성능을 최적화","''use client''를 사용하여 클라이언트 JS를 최소화","서버 컴포넌트와 클라이언트 컴포넌트를 결합"],"es":["Utilización de componentes del servidor por defecto","Uso de ''use client'' solo en nodos interactivos","Minimización de código JavaScript del cliente","Composición de componentes del servidor y del cliente","Acceso a recursos del servidor solo en componentes del servidor"],"fr":["Utilisation de composants serveur par défaut","Utilisation de ''use client'' uniquement sur les nœuds interactifs","Minimisation du code JavaScript client","Composition de composants serveur et client","Accès aux ressources serveur uniquement sur les composants serveur"],"de":["Verwendung von Serverkomponenten standardmäßig","Verwendung von ''use client'' nur in interaktiven Knoten","Minimierung von Client-JavaScript-Code","Zusammensetzung von Server- und Clientkomponenten","Zugriff auf Serverressourcen nur in Serverkomponenten"],"pt":["Utilizar componentes do servidor por padrão","Adicionar ''use client'' apenas em nós interativos de folha","Minimizar o JavaScript do lado do cliente","Nunca buscar dados ou acessar recursos do servidor em componentes do cliente","Compor: envolver componentes do cliente com a passagem de dados do componente do servidor"],"ru":["Использовать компоненты сервера по умолчанию","Добавлять ''use client'' только в интерактивных узлах листа","Минимизировать JavaScript на стороне клиента","Никогда не искать данные или доступ к ресурсам сервера в компонентах клиента","Составить: обернуть компоненты клиента с передачей данных компонента сервера ИИ Агентов"],"ar":["استخدام مكونات الخادم افتراضيا","إضافة ''use client'' فقط في العقد التفاعلية للورقة","تقليل الجافا سكريبت على جانب العميل","أبدا لا تحصل على بيانات أو الوصول إلى مصادر الخادم في مكونات العميل","التركيب: تغليف مكونات العميل مع تمرير بيانات مكون الخادم"]},"keywords":{"en":["how to use nextjs-best-practices","nextjs-best-practices setup guide","nextjs-best-practices vs create-react-app","what is nextjs-best-practices","nextjs-best-practices install","optimizing nextjs with server components","nextjs client component best practices","nextjs server component tutorial"],"zh":["Next.js 最佳实践","服务器组件","客户端组件","优化应用性能","use client","Next.js 16"],"ja":["Next.js ベストプラクティス","サーバーコンポーネント","クライアントコンポーネント","アプリケーションのパフォーマンスを最適化","use client","Next.js 16"],"ko":["Next.js 최상의 실천 방법","서버 컴포넌트","클라이언트 컴포넌트","애플리케이션의 성능을 최적화","use client","Next.js 16"],"es":["mejores prácticas nextjs","desarrollo web con nextjs","componentes del servidor y del cliente","optimización de aplicaciones web","nextjs para desarrolladores","herramientas de desarrollo web"],"fr":["meilleures pratiques nextjs","développement web avec nextjs","composants serveur et client","optimisation des applications web","nextjs pour développeurs","outils de développement web"],"de":["beste praktiken nextjs","webentwicklung mit nextjs","server- und clientkomponenten","optimierung von webanwendungen","nextjs für entwickler","webentwicklungstools"],"pt":["nextjs melhores práticas","arquitetura de servidor","componentes cliente","javascript","desenvolvimento web","aplicações web escaláveis","performática"],"ru":["nextjs лучшие практики","архитектура сервера","компоненты клиента","javascript","разработка веб-приложений","масштабируемые веб-приложения","производительные веб-приложения","ИИ Агенты"],"ar":["nextjs أفضل ممارسات","عمارة الخادم","مكونات العميل","جافا سكريبت","تطوير تطبيقات الويب","تطبيقات ويب قابلة للتوسيع","أداء عالية","أدوات الذكاء الاصطناعي"]}},"owner":"mikemikula","repo":"AI-Coding-Summit-2026","repoPath":"mikemikula/AI-Coding-Summit-2026","stars":2,"forks":2,"updatedAt":"2026-02-27T13:57:22Z","topics":[],"category":"community","skillMd":{"name":"nextjs-best-practices","description":"Enforces Next.js 16 best practices for App Router, React Server Components, caching, routing, TypeScript, and performance. Use when building, reviewing, or refactoring Next.js applications, creating pages/layouts/routes, configuring next.config.ts, handling data fetching, or working with server/client components.","bodyPreview":"# Next.js 16 Best Practices\n\n## Architecture: Server vs Client Components\n\n- Default to Server Components; add `''use client''` only at interactive leaf nodes\n- Push `''use client''` as deep in the tree as possible to minimize client JS\n- Never fetch data or access server resources in Client Components\n- Compose: wrap Client Components with Server Component data-passing, not the reverse\n\n```tsx\n// ✅ Server Component fetches, Client Component is interactive leaf\nasync function ProductPage({ id }: { i","body":"# Next.js 16 Best Practices\n\n## Architecture: Server vs Client Components\n\n- Default to Server Components; add `''use client''` only at interactive leaf nodes\n- Push `''use client''` as deep in the tree as possible to minimize client JS\n- Never fetch data or access server resources in Client Components\n- Compose: wrap Client Components with Server Component data-passing, not the reverse\n\n```tsx\n// ✅ Server Component fetches, Client Component is interactive leaf\nasync function ProductPage({ id }: { id: string }) {\n  const product = await fetchProduct(id);\n  return <AddToCartButton product={product} />;\n}\n\n// ✅ Client leaf\n''use client'';\nexport function AddToCartButton({ product }: { product: Product }) { ... }\n```\n\n## Caching: Opt-In with `\"use cache\"`\n\nCaching is **opt-in** in Next.js 16 — all code executes dynamically by default.\n\n```ts\n// next.config.ts\nconst nextConfig = { cacheComponents: true };\nexport default nextConfig;\n```\n\n```tsx\n// Cache a page, component, or function\n''use cache'';\nimport { cacheLife } from ''next/cache'';\n\nexport async function getProducts() {\n  cacheLife(''hours'');\n  return await db.products.findAll();\n}\n```\n\n### Cache Invalidation APIs\n\n| Scenario | API |\n|---|---|\n| Static content, eventual consistency | `revalidateTag(''tag'', ''max'')` |\n| User action, read-your-writes | `updateTag(''tag'')` in Server Action |\n| Uncached dynamic data refresh | `refresh()` in Server Action |\n\n```ts\n''use server'';\nimport { updateTag } from ''next/cache'';\n\nexport async function saveProfile(userId: string, data: Profile) {\n  await db.users.update(userId, data);\n  updateTag(`user-${userId}`); // User sees changes immediately\n}\n```\n\n## Routing & Navigation\n\n### File Conventions\n\n```\napp/\n├── layout.tsx          # Root layout (required)\n├── page.tsx            # Route segment\n├── loading.tsx         # Suspense fallback\n├── error.tsx           # Error boundary (''use client'' required)\n├── not-found.tsx       # 404 handler\n└── (group)/            # Route group (no URL segment)\n    └── page.tsx\n```\n\n### Async Params (Breaking Change in v16)\n\n```tsx\n// ✅ v16 — params and searchParams are async\nexport default async function Page({\n  params,\n  searchParams,\n}: {\n  params: Promise<{ slug: string }>;\n  searchParams: Promise<{ q?: string }>;\n}) {\n  const { slug } = await params;\n  const { q } = await searchParams;\n}\n```\n\n### Parallel Routes\n\nAll parallel route slots require an explicit `default.tsx`:\n\n```tsx\n// app/@modal/default.tsx\nexport default function Default() { return null; }\n```\n\n## Async APIs (Breaking Change in v16)\n\n```ts\n// ✅ All must be awaited\nimport { cookies, headers, draftMode } from ''next/headers'';\n\nconst cookieStore = await cookies();\nconst headersList = await headers();\nconst { isEnabled } = await draftMode();\n```\n\n## `proxy.ts` (replaces `middleware.ts`)\n\n```ts\n// proxy.ts (root of project)\nimport { NextRequest, NextResponse } from ''next/server'';\n\nexport default function proxy(request: NextRequest) {\n  if (!request.cookies.get(''token'')) {\n    return NextResponse.redirect(new URL(''/login'', request.url));\n  }\n}\n\nexport const config = { matcher: [''/dashboard/:path*''] };\n```\n\n> `middleware.ts` is deprecated — rename to `proxy.ts` and rename the export to `proxy`.\n\n## Performance\n\n### Streaming with Suspense\n\nData must be fetched **inside** the Suspense boundary for streaming to work.\nCreate an async loader component — never fetch above Suspense and pass data down:\n\n```tsx\n// ✅ Async loader fetches INSIDE Suspense — skeleton streams while data loads\nasync function DataLoader() {\n  const items = await getItems()\n  return <ItemList items={items} />\n}\n\nexport default function Page() {\n  return (\n    <>\n      <StaticHeader />\n      <Suspense fallback={<Skeleton />}>\n        <DataLoader />\n      </Suspense>\n    </>\n  )\n}\n\n// ❌ BAD — fetching ABOVE Suspense defeats streaming\nexport default async function Page() {\n  const items = await getItems() // blocks entire page\n  return (\n    <Suspense fallback={<Skeleton />}>\n      <ItemList items={items} /> {/* skeleton never shows */}\n    </Suspense>\n  )\n}\n```\n\n### Query Layer (`lib/queries/`)\n\nSeparate read queries into `lib/queries/` — never call the ORM directly in page components:\n\n```ts\n// lib/queries/todos.ts\nimport { prisma } from ''@/lib/prisma''\nimport type { Priority, Todo } from ''@/lib/types''\n\nexport async function getTodos(priorityFilter?: Priority): Promise<Todo[]> {\n  return prisma.todo.findMany({\n    where: priorityFilter ? { priority: priorityFilter } : undefined,\n    orderBy: { createdAt: ''desc'' },\n  })\n}\n```\n\nPages import from query functions; Server Actions handle mutations in `actions/`.\n\n### Constants-First\n\nNever hardcode enum values — derive from shared constants:\n\n```ts\n// ✅ Derive from single source of truth\nimport { PRIORITY_OPTIONS } from ''@/lib/constants/priorities''\nconst VALID_PRIORITIES = new Set(PRIORITY_OPTIONS.map((o) => o.value))\n\n// ❌ BAD — hardcoded, will drift from schema\nconst VALID_PRIORITIES = new Set([''LOW'', ''MEDIUM'', ''HIGH''])\n```\n\n### React Compiler (Stable)\n\nEnables automatic memoization — eliminates manual `useMemo`/`useCallback`:\n\n```ts\n// next.config.ts\nconst nextConfig = { reactCompiler: true };\n```\n\n```bash\npnpm add babel-plugin-react-compiler@latest\n```\n\n### Turbopack (Default)\n\nTurbopack is now the default bundler. Remove conflicting Webpack configs or opt out:\n\n```bash\nnext dev --webpack   # Opt out of Turbopack\n```\n\nEnable filesystem caching for large projects:\n\n```ts\nexperimental: { turbopackFileSystemCacheForDev: true }\n```\n\n## TypeScript\n\n- Target TypeScript 5.1+, Node.js 20.9+\n- Define explicit return types on all async functions\n- Use `Promise<PageProps>` types for params/searchParams\n- Use `next.config.ts` (TypeScript native config)\n\n```ts\n// ✅ Typed route handler\nexport async function GET(\n  request: Request,\n  { params }: { params: Promise<{ id: string }> }\n): Promise<Response> {\n  const { id } = await params;\n  const data = await fetchById(id);\n  return Response.json(data);\n}\n```\n\n## Image Optimization\n\n```tsx\nimport Image from ''next/image'';\n\n// Remote images require remotePatterns (not deprecated domains)\n// next.config.ts\nimages: {\n  remotePatterns: [{ protocol: ''https'', hostname: ''example.com'' }],\n}\n```\n\n## Server Actions\n\n```ts\n''use server'';\n\nexport async function createPost(formData: FormData): Promise<void> {\n  const title = formData.get(''title'') as string;\n  await db.posts.create({ title });\n  updateTag(''posts'');\n}\n```\n\n- Colocate with the component or in a dedicated `actions/` directory\n- Always validate and sanitize inputs\n- Use `updateTag` for read-your-writes after mutations\n\n## Environment & Config\n\n```ts\n// next.config.ts — use env vars, not deprecated serverRuntimeConfig/publicRuntimeConfig\nconst nextConfig = {\n  cacheComponents: true,\n  reactCompiler: true,\n  images: {\n    remotePatterns: [{ protocol: ''https'', hostname: ''cdn.example.com'' }],\n  },\n};\n\nexport default nextConfig;\n```\n\n\nFOR SSR BEST PRACTICES LOOK HERE:\n/.cursor/skills/nextjs-best-practices/ssr-best-practices\n\n\n## Breaking Changes Checklist (v15 → v16)\n\n- [ ] `params` / `searchParams` → `await params` / `await searchParams`\n- [ ] `cookies()` / `headers()` / `draftMode()` → add `await`\n- [ ] `middleware.ts` → rename to `proxy.ts`, export `proxy` function\n- [ ] `revalidateTag(''tag'')` → `revalidateTag(''tag'', ''max'')`\n- [ ] `experimental.dynamicIO` → `cacheComponents: true`\n- [ ] `experimental.ppr` → removed; use Cache Components\n- [ ] `images.domains` → `images.remotePatterns`\n- [ ] Parallel routes missing `default.tsx` → add for all slots\n- [ ] `serverRuntimeConfig` / `publicRuntimeConfig` → use `.env` files\n- [ ] Remove `next lint` from CI → use `eslint` or `biome` directly\n\n## Additional Resources\n\n- [Next.js 16 Release Notes](https://nextjs.org/blog/next-16)\n- [Upgrade Guide v16](https://nextjs.org/docs/app/guides/upgrading/version-16)\n- [Cache Components Docs](https://nextjs.org/docs/app/api-reference/config/next-config-js/cacheComponents)\n- [proxy.ts Docs](https://nextjs.org/docs/app/getting-started/proxy)\n- [DevTools MCP](https://nextjs.org/docs/app/guides/mcp)\n"},"lastSynced":"2026-03-06T07:09:17.565Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents seeking to optimize Next.js applications with Server and Client Components.","zh":"适合于寻求优化 Next.js 应用程序的全栈代理，使用 Server 和 Client Components。","ja":"Next.js アプリケーションを Server と Client Components で最適化しようとするフルスタックエージェントに最適です。","ko":"Next.js 애플리케이션을 서버 및 클라이언트 구성 요소를 사용하여 최적화하려는 풀 스택 에이전트에게 적합합니다.","es":"Ideal para Agentes de Full Stack que buscan optimizar aplicaciones Next.js con Componentes de Servidor y Cliente.","fr":"Idéal pour les agents Full Stack qui cherchent à optimiser les applications Next.js avec des composants serveur et client.","de":"Ideal für Full-Stack-Agenten, die Next.js-Anwendungen mit Server- und Clientkomponenten optimieren möchten.","pt":"Ideal para Agentes Full Stack que buscam otimizar aplicações Next.js com Componentes de Servidor e Cliente.","ru":"Идеально для полнофункциональных агентов, стремящихся оптимизировать приложения Next.js с помощью компонентов сервера и клиента.","ar":"مثالي لعمال العميل الكامل الذين يهدفون إلى تحسين تطبيقات Next.js مع مكونات الخادم والعميل."},"recommendation":{"en":"Empowers agents to leverage Server Components for data fetching and Client Components for interactive leaf nodes, minimizing client-side JavaScript and enhancing application performance with ''use client'' directive, while ensuring scalable architecture through composed data-passing.","zh":"赋予代理使用 Server Components 进行数据获取和 Client Components 进行交互式叶节点的能力，通过 ''use client'' 指令最小化客户端 JavaScript 并提高应用程序性能，同时通过组合数据传递确保可扩展的架构。","ja":"エージェントが Server Components を使用してデータを取得し、Client Components を使用してインタラクティブな葉ノードを作成する能力を提供し、''use client'' ディレクティブを使用してクライアント側の JavaScript を最小限に抑え、アプリケーションのパフォーマンスを向上させ、組み合わせたデータの受け渡しを通じてスケーラブルなアーキテクチャを確保します。","ko":"에이전트가 서버 구성 요소를 사용하여 데이터를 가져오고 클라이언트 구성 요소를 사용하여 상호 작용형 리프 노드를 만들 수 있는 기능을 제공하여 ''use client'' 지시문을 사용하여 클라이언트 측 JavaScript를 최소화하고 애플리케이션 성능을 향상시키고, 데이터 전달을 조합하여 확장 가능한 아키텍처를 보장합니다.","es":"Habilita a los agentes a aprovechar los Componentes de Servidor para la recuperación de datos y los Componentes de Cliente para nodos interactivos de hoja, minimizando el JavaScript del lado del cliente y mejorando el rendimiento de la aplicación con la directiva ''use client'', al mismo tiempo que garantiza una arquitectura escalable a través de la composición de paso de datos.","fr":"Permet aux agents d''utiliser les composants serveur pour la récupération de données et les composants client pour les nœuds interactifs de feuille, en minimisant le JavaScript côté client et en améliorant les performances de l''application avec la directive ''use client'', tout en garantissant une architecture scalable grâce à la composition de passage de données.","de":"Ermächtigt die Agenten, Serverkomponenten für Datenabruf und Clientkomponenten für interaktive Blattknoten zu nutzen, wodurch der Client-seitige JavaScript-Code minimiert und die Anwendungsleistung durch die ''use client''-Direktive verbessert wird, während gleichzeitig eine skalierbare Architektur durch die Zusammensetzung von Datenübertragung gewährleistet wird.","pt":"Permite que os agentes usem Componentes de Servidor para buscar dados e Componentes de Cliente para nós interativos de folha, minimizando o JavaScript do lado do cliente e melhorando o desempenho da aplicação com a diretiva ''use client'', garantindo ao mesmo tempo uma arquitetura escalável por meio da passagem de dados composta.","ru":"Позволяет агентам использовать компоненты сервера для извлечения данных и компоненты клиента для интерактивных листьев, минимизируя JavaScript на стороне клиента и повышая производительность приложения с помощью директивы ''use client'', обеспечивая при этом масштабируемую архитектуру за счет составной передачи данных.","ar":"تمكن الوكلاء من استخدام مكونات الخادم لاسترجاع البيانات ومكونات العميل للعقد التفاعلية، وتقليل جافا سكريبت جانب العميل وتحسين أداء التطبيق مع توجيه ''use client''، وضمان في الوقت نفسه هندسة قابلة للتوسيع من خلال تمرير البيانات المتركبة."},"useCases":{"en":["Optimizing Next.js application performance by leveraging Server Components","Minimizing client-side JavaScript with strategic ''use client'' placement","Composing scalable architectures with Server Component data-passing"],"zh":["通过利用 Server Components 优化 Next.js 应用程序性能","通过战略性地放置 ''use client'' 指令最小化客户端 JavaScript","通过 Server Component 数据传递组成可扩展的架构"],"ja":["Server Components を使用して Next.js アプリケーションのパフォーマンスを最適化する","''use client'' ディレクティブの戦略的な配置を使用してクライアント側の JavaScript を最小限に抑える","Server Component のデータ受け渡しを使用してスケーラブルなアーキテクチャを構成する"],"ko":["서버 구성 요소를 사용하여 Next.js 애플리케이션 성능 최적화","''use client'' 지시문을 전략적으로 배치하여 클라이언트 측 JavaScript 최소화","서버 구성 요소 데이터 전달을 사용하여 확장 가능한 아키텍처 구성"],"es":["Optimizar el rendimiento de la aplicación Next.js aprovechando los Componentes de Servidor","Minimizar el JavaScript del lado del cliente con una colocación estratégica de ''use client''","Componer arquitecturas escalables con el paso de datos de los Componentes de Servidor"],"fr":["Optimiser les performances de l''application Next.js en utilisant les composants serveur","Minimiser le JavaScript côté client avec un placement stratégique de ''use client''","Composer des architectures scalables avec le passage de données des composants serveur"],"de":["Optimieren des Next.js-Anwendungsleistungs durch die Nutzung von Serverkomponenten","Minimieren des Client-seitigen JavaScript-Codes durch eine strategische Platzierung von ''use client''","Zusammensetzen von skalierbaren Architekturen mit der Datenübertragung von Serverkomponenten"],"pt":["Otimizar o desempenho da aplicação Next.js, utilizando Componentes de Servidor","Minimizar o JavaScript do lado do cliente com colocação estratégica da diretiva ''use client''","Compor arquiteturas escaláveis com passagem de dados de Componentes de Servidor"],"ru":["Оптимизировать производительность приложения Next.js, используя компоненты сервера","Минимизировать JavaScript на стороне клиента с помощью стратегического размещения директивы ''use client''","Составлять масштабируемые архитектуры с помощью передачи данных компонентов сервера"],"ar":["تحسين أداء تطبيق Next.js باستخدام مكونات الخادم","تقليل جافا سكريبت جانب العميل مع وضع استراتيجي لتوجيه ''use client''","تركيب هندسة قابلة للتوسيع مع تمرير البيانات لمكونات الخادم"]},"limitations":{"en":["Requires understanding of Next.js Server and Client Components","Adherence to best practices for ''use client'' directive placement"],"zh":["需要了解 Next.js Server 和 Client Components","遵循 ''use client'' 指令放置的最佳实践"],"ja":["Next.js の Server と Client Components を理解する必要がある","''use client'' ディレクティブの配置に関するベストプラクティスに従う"],"ko":["Next.js의 서버 및 클라이언트 구성 요소를 이해해야 함","''use client'' 지시문의 배치에 대한 모범 사례를 따름"],"es":["Requiere comprensión de los Componentes de Servidor y Cliente de Next.js","Adhesión a las mejores prácticas para la colocación de la directiva ''use client''"],"fr":["Nécessite une compréhension des composants serveur et client de Next.js","Adhésion aux meilleures pratiques pour le placement de la directive ''use client''"],"de":["Benötigt ein Verständnis von Server- und Clientkomponenten von Next.js","Befolgung der besten Praktiken für die Platzierung der ''use client''-Direktive"],"pt":["Requer entendimento de Componentes de Servidor e Cliente do Next.js","Adesão às melhores práticas para colocação da diretiva ''use client''"],"ru":["Требует понимания компонентов сервера и клиента Next.js","Соблюдение лучших практик для размещения директивы ''use client''"],"ar":["يتطلب فهم مكونات الخادم والعميل في Next.js","الالتزام بأفضل الممارسات لوضع توجيه ''use client''"]},"version":4},"contentHash":"eeae8ebf60fe9a8f982c9228cccd9f8bce9a717ead6111dd3d99e036f2ec72bc","qualityScore":45}');
DELETE FROM skills_fts WHERE id = 'mikemikula/AI-Coding-Summit-2026/nextjs-best-practices';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mikemikula/AI-Coding-Summit-2026/nextjs-best-practices', 'nextjs-best-practices', 'mikemikula', 'AI-Coding-Summit-2026', 'community', 'nextjs-best-practices mikemikula AI-Coding-Summit-2026 community The nextjs-best-practices skill provides technical guidance on optimizing Next.js applications by leveraging Server and Client Components. It benefits developers seeking to improve their application''s performance and scalability. Next.js 最佳实践包括默认使用服务器组件，仅在交互叶节点添加 ''use client''，优化应用性能 Next.js のベストプラクティスには、デフォルトでサーバーコンポーネントを使用し、交互作用する葉ノードのみで ''use client'' を追加することが含まれる、アプリケーションのパフォーマンスを最適化 Next.js 최상의 실천 방법에는 서버 컴포넌트를 기본으로 사용하고, 상호 작용하는 리프 노드에서만 ''use client''를 추가하는 것이 포함되어 애플리케이션의 성능을 최적화 Las mejores prácticas de Next.js incluyen la utilización de componentes del servidor y del cliente de manera efectiva Les meilleures pratiques Next.js incluent l''utilisation efficace des composants serveur et client Die besten Praktiken von Next.js umfassen die effektive Verwendung von Server- und Clientkomponenten As melhores práticas do Next.js para criar aplicações web escaláveis e performáticas, incluindo arquitetura de servidor e componentes cliente Лучшие практики Next.js для создания масштабируемых и производительных веб-приложений, включая архитектуру сервера и клиентских компонентов أفضل ممارسات Next.js لإنشاء تطبيقات ويب قابلة للتوسيع وأداء عالية، بما في ذلك عمارة الخادم ومكونات العميل how to use nextjs-best-practices nextjs-best-practices setup guide nextjs-best-practices vs create-react-app what is nextjs-best-practices nextjs-best-practices install optimizing nextjs with server components nextjs client component best practices nextjs server component tutorial Next.js 最佳实践 服务器组件 客户端组件 优化应用性能 use client Next.js 16 Defaulting to Server Components with optional ''use client'' directive Minimizing client-side JavaScript by pushing ''use client'' deep in the component tree Fetching data and accessing server resources exclusively in Server Components Composing Server Components with Client Components for seamless data passing Using async functions for server-side data fetching, such as in ProductPage components nextjs-best-practices is a set of guidelines for optimizing Next.js applications, focusing on Server and Client Component architecture and data fetching strategies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kalepail/wispr-duck/release', 'community', 'kalepail', 'wispr-duck', 'kalepail/wispr-duck', 'release', 1, 0, 45, '2026-02-03T07:51:18Z', '2026-03-07T12:50:16.796Z', '2fc0ff0fd50993641e8aaa5e388872c34d7dec34fa8685be09dc0642ed252709', '{"id":"kalepail/wispr-duck/release","name":"release","description":{"en":"The Release skill automates the deployment of signed, notarized, and stapled macOS apps, benefiting developers who need to publish their apps on GitHub. It ensures a clean working tree and handles existing git tags and releases.","zh":"WisprDuck是一个macOS菜单栏实用工具，用于自动降低背景音量。了解如何发布和设置它","ja":"WisprDuckは、背景音量を自動で下げるmacOSメニューバー ユーティリティです。リリースと設定方法を学びましょう","ko":"WisprDuck는 자동으로 배경 음량을 낮추는 macOS 메뉴 바 유틸리티입니다.发布하고 설정하는 방법을 알아보세요","es":"La función de release de WisprDuck permite a los desarrolladores crear una versión firmada, notariada y etiquetada de su aplicación macOS","fr":"La fonction de release de WisprDuck permet aux développeurs de créer une version signée, notariée et étiquetée de leur application macOS","de":"Die Release-Funktion von WisprDuck ermöglicht es Entwicklern, eine signierte, notarierte und beschriftete Version ihrer macOS-App zu erstellen","pt":"O release do WisprDuck é uma utilidade de barra de menu macOS que controla automaticamente o volume de fundo quando o microfone está ativo.","ru":"Release WisprDuck - это утилита панели меню macOS, которая автоматически контролирует фоновой громкости при активном микрофоне.","ar":"الإصدار من WisprDuck هو أداة شريط قوائم macOS تسيطر تلقائيًا على صوت الخلفية عند تفعيل الميكروفون."},"seo":{"title":{"en":"Release: Automated macOS App Deployment for AI Agents | A...","zh":"Release WisprDuck Setup Guide: macOS菜单栏实用工具","ja":"Release WisprDuck 導入ガイド: macOSメニューバー ユーティリティ","ko":"Release WisprDuck 설정 가이드: macOS 메뉴 바 유틸리티","es":"Configuración de Release para Desarrolladores: Guía de Im...","fr":"Paramètres de Release pour Développeurs: Meilleures Prati...","de":"Release-Einrichtung für Entwickler: Leitfaden für macOS-Apps","pt":"Guia de Configuração do Release: Utilizando WisprDuck par...","ru":"Руководство по Настройке Release: Использование WisprDuck...","ar":"دليل إعداد الإصدار: استخدام WisprDuck للسيطرة على الصوت"},"description":{"en":"Discover how to automate your macOS app deployment with Release, a lightweight utility for AI agents. Learn how to setup and use it effectively.","zh":"了解如何发布和设置WisprDuck，一个轻量级的macOS菜单栏实用工具，用于自动降低背景音量","ja":"WisprDuckのリリースと設定方法を学びましょう。軽量のmacOSメニューバー ユーティリティで、背景音量を自動で下げます","ko":"WisprDuck를发布하고 설정하는 방법을 알아보세요. 경량 macOS 메뉴 바 유틸리티로 자동으로 배경 음량을 낮춥니다","es":"Aprende a configurar la función de release para tus proyectos de desarrollo con WisprDuck, una herramienta de audio de código abierto para macOS","fr":"Découvrez comment paramétrer la fonction de release pour vos projets de développement avec WisprDuck, un outil audio open-source pour macOS","de":"Erfahren Sie, wie Sie die Release-Funktion für Ihre Entwicklungsprojekte mit WisprDuck, einem Open-Source-Audio-Tool für macOS, einrichten","pt":"Aprenda a configurar o release do WisprDuck, uma utilidade de barra de menu macOS para controle de volume automático","ru":"Узнайте, как настроить release WisprDuck, утилиту панели меню macOS для автоматического контроля громкости","ar":"تعرف على كيفية إعداد الإصدار من WisprDuck، أداة شريط قوائم macOS للتحكم التلقائي في الصوت"},"definition":{"en":"Release is a lightweight macOS menu bar utility that automates the deployment of macOS apps, utilizing Swift and SwiftUI for development.","zh":"Release WisprDuck是一个用于发布和设置WisprDuck的过程，包括构建、签名和发布","ja":"Release WisprDuckは、WisprDuckのリリースと設定を行うプロセスで、ビルド、署名、公開が含まれます","ko":"Release WisprDuck는 WisprDuck를发布하고 설정하는 프로세스로, 빌드, 서명, 공개가 포함됩니다","es":"La función de release es una herramienta de línea de comandos que automatiza el proceso de creación de una versión de lanzamiento de una aplicación","fr":"La fonction de release est un outil en ligne de commande qui automatise le processus de création d''une version de lancement d''une application","de":"Die Release-Funktion ist ein Kommandozeilen-Tool, das den Prozess der Erstellung einer Veröffentlichungsversion einer Anwendung automatisiert","pt":"O que é release do WisprDuck? É uma utilidade macOS de código aberto que controla o volume de fundo.","ru":"Что такое release WisprDuck? Это открытая утилита macOS, которая контролирует фоновой громкости.","ar":"ما هو الإصدار من WisprDuck؟ إنه أداة مفتوحة المصدر لماكنتوش تسيطر على صوت الخلفية."},"features":{"en":["Automates the build of signed, notarized, and stapled .app files","Checks for uncommitted changes using git status","Handles existing git tags and GitHub releases","Supports re-release cleanup for overwritten versions","Utilizes Swift and SwiftUI for development"],"zh":["自动降低背景音量","支持macOS菜单栏","使用Swift和SwiftUI构建","开源和免费","支持GitHub发布","轻量级和易于使用"],"ja":["背景音量の自動下げ","macOSメニューバーのサポート","SwiftとSwiftUIで構築","オープンソースと無料","GitHubリリースのサポート","軽量で使いやすい"],"ko":["자동으로 배경 음량을 낮춘다","macOS 메뉴 바를 지원한다","Swift와 SwiftUI로構築","오픈소스이고 무료이다","GitHub发布를 지원한다","경량이고易于使用"],"es":["Creación de una versión firmada y notariada de la aplicación","Etiquetado automático de la versión en GitHub","Compatibilidad con Swift y SwiftUI","Control de volumen de audio en segundo plano","Soporte para macOS"],"fr":["Création d''une version signée et notariée de l''application","Étiquetage automatique de la version sur GitHub","Compatibilité avec Swift et SwiftUI","Contrôle du volume audio en arrière-plan","Prise en charge de macOS"],"de":["Erstellung einer signierten und notarierten Version der Anwendung","Automatisches Taggen der Version auf GitHub","Unterstützung für Swift und SwiftUI","Hintergrund-Audio-Lautstärkenkontrolle","Unterstützung für macOS"],"pt":["Controle de volume automático com Swift e SwiftUI","Integração com GitHub para publicação de releases","Verificação de árvore de trabalho limpa com git status","Suporte à re-publicação de releases existentes"],"ru":["Автоматический контроль громкости с помощью Swift и SwiftUI","Интеграция с GitHub для публикации релизов","Проверка чистоты рабочего дерева с помощью git status","Поддержка перепубликации существующих релизов"],"ar":["التحكم التلقائي في الصوت باستخدام Swift و SwiftUI","التكامل مع GitHub لنشر الإصدارات","التحقق من شجرة العمل النظيفة باستخدام git status","دعم إعادة نشر الإصدارات الحالية"]},"keywords":{"en":["how to use release for macOS app deployment","release alternative for automated deployment","release vs manual deployment","release setup guide for AI agents","what is release in macOS development","release install for GitHub publication"],"zh":["macOS菜单栏实用工具","自动降低背景音量","Swift和SwiftUI","开源和免费","GitHub发布","轻量级和易于使用","AIエージェント","Release WisprDuck"],"ja":["macOSメニューバー ユーティリティ","背景音量の自動下げ","SwiftとSwiftUI","オープンソースと無料","GitHubリリース","軽量で使いやすい","AIエージェント","Release WisprDuck"],"ko":["macOS 메뉴 바 유틸리티","자동으로 배경 음량을 낮춘다","Swift와 SwiftUI","오픈소스이고 무료이다","GitHub发布","경량이고易于使用","AI 에이전트","Release WisprDuck"],"es":["release de aplicaciones","herramientas de desarrollo de macOS","audio de código abierto","Swift","SwiftUI","control de volumen","GitHub","notarización de aplicaciones","firmado de aplicaciones"],"fr":["publication d''applications","outils de développement macOS","audio open-source","Swift","SwiftUI","contrôle du volume","GitHub","notarisation d''applications","signature d''applications"],"de":["Veröffentlichung von Anwendungen","Entwicklertools für macOS","Open-Source-Audio","Swift","SwiftUI","Lautstärkenkontrolle","GitHub","Notarisation von Anwendungen","Signierung von Anwendungen"],"pt":["release do WisprDuck","controle de volume automático","macOS","Swift","SwiftUI","GitHub","git status","re-publicação de releases"],"ru":["release WisprDuck","автоматический контроль громкости","macOS","Swift","SwiftUI","GitHub","git status","перепубликация релизов"],"ar":["الإصدار من WisprDuck","التحكم التلقائي في الصوت","ماكنتوش","Swift","SwiftUI","GitHub","git status","إعادة نشر الإصدارات"]}},"owner":"kalepail","repo":"wispr-duck","repoPath":"kalepail/wispr-duck","stars":1,"forks":0,"updatedAt":"2026-02-03T07:51:18Z","topics":["audio","core-audio","ducking","macos","macos-app","menu-bar","microphone","open-source","swift","swiftui","volume-control","wispr-flow"],"category":"community","skillMd":{"name":"release","description":"Build a signed, notarized macOS .app and publish a GitHub release. Use when cutting a new version of WisprDuck.","bodyPreview":"# Release WisprDuck\n\nBuild a signed, notarized, and stapled `.app`, then publish it as a GitHub release.\n\n**Target version:** $ARGUMENTS\n\n## Pre-flight\n\n1. Confirm the working tree is clean (`git status`). Abort if there are uncommitted changes.\n2. Check whether `$ARGUMENTS` already has a git tag or GitHub release.\n   - If it **does not exist**, proceed normally.\n   - If it **already exists** and the user explicitly asked to overwrite/re-release, run the re-release cleanup before continuing:","body":"# Release WisprDuck\n\nBuild a signed, notarized, and stapled `.app`, then publish it as a GitHub release.\n\n**Target version:** $ARGUMENTS\n\n## Pre-flight\n\n1. Confirm the working tree is clean (`git status`). Abort if there are uncommitted changes.\n2. Check whether `$ARGUMENTS` already has a git tag or GitHub release.\n   - If it **does not exist**, proceed normally.\n   - If it **already exists** and the user explicitly asked to overwrite/re-release, run the re-release cleanup before continuing:\n     ```bash\n     gh release delete v$ARGUMENTS --repo kalepail/wispr-duck --yes --cleanup-tag\n     git tag -d v$ARGUMENTS 2>/dev/null || true\n     ```\n   - If it already exists and the user did **not** ask to overwrite, abort and ask for confirmation.\n3. If not on `main`, merge the current branch into `main` and switch to it:\n   ```\n   git checkout main\n   git merge <branch> --no-edit\n   ```\n\n## Step 1 — Bump version numbers\n\nUpdate **all** of the following to `$ARGUMENTS`:\n\n| File | Field | Format |\n|------|-------|--------|\n| `WisprDuck.xcodeproj/project.pbxproj` | `MARKETING_VERSION` (both Debug and Release) | Short: `1.4` (no patch) |\n| `site/index.html` | `\"softwareVersion\"` in the Schema.org JSON-LD | Semver: `1.4.0` |\n| `site/package.json` | `\"version\"` | Semver: `1.4.0` |\n\n`MARKETING_VERSION` uses Xcode''s short version format (e.g., `1.4` not `1.4.0`). The other files use full semver.\n\nDo **not** touch `CURRENT_PROJECT_VERSION` (build number) — leave it as-is.\n\nAfter updating, verify with `grep` that no stale version strings remain in those files.\n\n## Step 2 — Commit and push\n\n```\ngit add WisprDuck.xcodeproj/project.pbxproj site/index.html site/package.json\ngit commit -m \"Bump version to $ARGUMENTS\"\ngit push origin main\n```\n\n## Step 3 — Archive\n\nRun as a **single line** (multiline backslash escaping can break in some shell environments):\n\n```bash\nxcodebuild archive -project WisprDuck.xcodeproj -scheme WisprDuck -configuration Release -archivePath /tmp/WisprDuck.xcarchive \"CODE_SIGN_IDENTITY=Developer ID Application: Tiny Anvil, LLC (T4GBHCYB7P)\" DEVELOPMENT_TEAM=T4GBHCYB7P CODE_SIGN_STYLE=Manual\n```\n\nNote: `CODE_SIGN_IDENTITY` must be quoted because the value contains spaces and a comma.\n\nConfirm output ends with `** ARCHIVE SUCCEEDED **`.\n\n## Step 4 — Export\n\nWrite this ExportOptions.plist to /tmp:\n\n```xml\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n  <key>method</key>\n  <string>developer-id</string>\n  <key>teamID</key>\n  <string>T4GBHCYB7P</string>\n  <key>signingStyle</key>\n  <string>manual</string>\n  <key>signingCertificate</key>\n  <string>Developer ID Application</string>\n</dict>\n</plist>\n```\n\nThen export:\n\n```bash\nxcodebuild -exportArchive -archivePath /tmp/WisprDuck.xcarchive -exportPath /tmp/WisprDuckExport -exportOptionsPlist /tmp/ExportOptions.plist\n```\n\nConfirm `** EXPORT SUCCEEDED **`.\n\n## Step 5 — Verify signing\n\n```bash\ncodesign -dv --verbose=2 /tmp/WisprDuckExport/WisprDuck.app\n```\n\nConfirm:\n- `Authority=Developer ID Application: Tiny Anvil, LLC (T4GBHCYB7P)`\n- `flags=0x10000(runtime)` (hardened runtime)\n\nIf signing is wrong, stop and diagnose.\n\n## Step 6 — Notarize\n\n```bash\nditto -c -k --keepParent /tmp/WisprDuckExport/WisprDuck.app /tmp/WisprDuck-$ARGUMENTS.zip\n\nxcrun notarytool submit /tmp/WisprDuck-$ARGUMENTS.zip --keychain-profile \"WisprDuck-Notarize\" --wait\n```\n\nIf the keychain profile is missing, ask the user to run:\n\n```\nxcrun notarytool store-credentials \"WisprDuck-Notarize\" --key ~/Desktop/wispr-duck-certs/AuthKey_4MM3YQXN45.p8 --key-id 4MM3YQXN45 --issuer 69a6de83-bf58-47e3-e053-5b8c7c11a4d1\n```\n\nThen retry. Confirm status is `Accepted`.\n\n## Step 7 — Staple\n\n```bash\nxcrun stapler staple /tmp/WisprDuckExport/WisprDuck.app\nxcrun stapler validate /tmp/WisprDuckExport/WisprDuck.app\n```\n\nConfirm `The staple and validate action worked!`.\n\nRe-create the zip with the stapled app:\n\n```bash\nrm /tmp/WisprDuck-$ARGUMENTS.zip\nditto -c -k --keepParent /tmp/WisprDuckExport/WisprDuck.app /tmp/WisprDuck-$ARGUMENTS.zip\n```\n\n## Step 8 — Draft release notes and create GitHub release\n\n**Do not use `--generate-notes`** — it only produces a bare changelog link with no useful content.\n\nInstead, draft proper release notes:\n\n1. Run `git log <previous-tag>..HEAD --oneline` to review all commits since the last release.\n2. Read the previous release''s notes (`gh release view <previous-tag> --repo kalepail/wispr-duck`) to match the established tone and format.\n3. Write a release body. **Scale the detail to the release size:**\n\n**Patch releases (x.y.Z)** — just categorized bullets, no intro paragraph:\n\n```markdown\n### <Category>\n\n- **Bold summary** — detail of each meaningful change.\n\n**Full Changelog**: https://github.com/kalepail/wispr-duck/compare/<previous-tag>...v$ARGUMENTS\n```\n\n**Minor/major releases (x.Y.0 / X.0.0)** — intro paragraph + categorized bullets:\n\n```markdown\n## What''s New in v$ARGUMENTS\n\n<1-2 sentence summary of the theme of this release.>\n\n### <Category> (e.g. Bug Fixes, UI, Audio, Internal)\n\n- **Bold summary** — detail of each meaningful change.\n\n**Full Changelog**: https://github.com/kalepail/wispr-duck/compare/<previous-tag>...v$ARGUMENTS\n```\n\n**Do not repeat boilerplate every release.** Installation instructions, system requirements, and signing info belong in the README and on wisprduck.com — not in release notes. Only mention these if something about them *changes* (e.g., certificate rotation, new OS requirement, changed install steps).\n\n4. Create the release, passing the body via a HEREDOC:\n\n```bash\ngh release create v$ARGUMENTS /tmp/WisprDuck-$ARGUMENTS.zip --repo kalepail/wispr-duck --title \"WisprDuck v$ARGUMENTS\" --notes \"$(cat <<''EOF''\n<drafted release notes here>\nEOF\n)\"\n```\n\nPrint the release URL when done.\n\n## Step 9 — Clean up\n\n```bash\nrm -rf /tmp/WisprDuck.xcarchive /tmp/WisprDuckExport /tmp/ExportOptions.plist /tmp/WisprDuck-$ARGUMENTS.zip\n```\n\n## Troubleshooting\n\n| Problem | Fix |\n|---------|-----|\n| `No Keychain password item found for profile: notarytool` | Re-run the `store-credentials` command from Step 6 |\n| `Developer ID Application` identity not found | Open Keychain Access and verify the cert is in the login keychain. Import from `~/Desktop/wispr-duck-certs/` if needed. |\n| Notarization status `Invalid` | Run `xcrun notarytool log <submission-id> --keychain-profile \"WisprDuck-Notarize\"` and fix the reported issues |\n| `ARCHIVE FAILED` with signing errors | Ensure `CODE_SIGN_STYLE=Manual` and the full identity string matches `security find-identity -v -p codesigning` output |\n| `Unknown build action ''''` from xcodebuild | Multiline backslash escaping broke — use single-line commands instead |\n| `No App Category is set` warning during archive | Non-blocking. Can be fixed by adding `LSApplicationCategoryType` to Info.plist if desired. |\n"},"lastSynced":"2026-03-07T12:50:16.796Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub-focused Agents needing automated deployment of signed, notarized, and stapled macOS apps.","zh":"适用于需要自动部署已签名、公证和打包的 macOS 应用的 GitHub 专注的 Agent。","ja":"GitHub に重点を置いたエージェントが署名済み、公証済み、スタップル済みの macOS アプリの自動デプロイを必要とする場合に最適です。","ko":"署명되고 공증 및 스테이플된 macOS 앱의 자동 배포가 필요한 GitHub에 중점을 둔 에이전트에게 적합합니다.","es":"Perfecto para agentes de GitHub que necesitan una implementación automática de aplicaciones de macOS firmadas, notarizadas y etiquetadas.","fr":"Parfait pour les agents GitHub nécessitant un déploiement automatisé d''applications macOS signées, notariées et étiquetées.","de":"Perfekt für GitHub-Agents, die eine automatisierte Bereitstellung von signierten, notarierten und gestempelten macOS-Apps benötigen.","pt":"Perfeito para Agentes focados no GitHub que necessitam de implantação automatizada de aplicativos macOS assinados, notarizados e anexados.","ru":"Идеально подходит для агентов, ориентированных на GitHub, которым требуется автоматическая развертка подписанных, нотариальных и прикрепленных приложений macOS.","ar":"مثالي للوكلاء المهتمين بجهاز GitHub الذين يحتاجون إلى نشر تطبيقات macOS موقعة ومرخصة وملحقة بشكل آلي."},"recommendation":{"en":"Empowers agents to publish macOS apps on GitHub, ensuring a clean working tree and handling existing git tags and releases, all while supporting automated deployment of `.app` files using git status and GitHub release protocols.","zh":"赋予代理发布 macOS 应用到 GitHub 的能力，确保干净的工作树，并处理现有的 git 标签和版本，同时支持使用 git 状态和 GitHub 版本协议自动部署 `.app` 文件。","ja":"エージェントが macOS アプリを GitHub に公開できるようにし、クリーンな作業ツリーを確保し、既存の git タグとリリースを処理し、git 状態と GitHub リリース プロトコルを使用して `.app` ファイルの自動デプロイをサポートします。","ko":"에이전트가 macOS 애플리케이션을 GitHub에 게시할 수 있도록 해주고, 깨끗한 작업 트리를 보장하며, 기존의 git 태그 및 릴리스를 처리하며, git 상태 및 GitHub 릴리스 프로토콜을 사용하여 `.app` 파일의 자동 배포를 지원합니다.","es":"Habilita a los agentes a publicar aplicaciones de macOS en GitHub, garantizando un árbol de trabajo limpio y gestionando las etiquetas y versiones de git existentes, todo mientras admite la implementación automática de archivos `.app` utilizando protocolos de estado de git y lanzamiento de GitHub.","fr":"Permet aux agents de publier des applications macOS sur GitHub, en garantissant un arbre de travail propre et en gérant les balises et versions git existantes, le tout en supportant le déploiement automatisé de fichiers `.app` à l''aide de protocoles d''état git et de publication GitHub.","de":"Ermächtigt Agents, macOS-Apps auf GitHub zu veröffentlichen, wodurch ein sauberer Arbeitsbereich sichergestellt und die vorhandenen git-Tags und -Versionen verwaltet werden, während die automatische Bereitstellung von `.app`-Dateien unter Verwendung von git-Status- und GitHub-Release-Protokollen unterstützt wird.","pt":"Habilita os agentes a publicar aplicativos macOS no GitHub, garantindo uma árvore de trabalho limpa e manipulando as tags e lançamentos git existentes, tudo isso enquanto suporta a implantação automatizada de arquivos `.app` usando o status do git e os protocolos de lançamento do GitHub.","ru":"Наделяет агентов возможностью публиковать приложения macOS на GitHub, обеспечивая чистую рабочую копию и обрабатывая существующие теги и релизы git, все это при поддержке автоматической развертки файлов `.app` с использованием статуса git и протоколов выпуска GitHub.","ar":"تمكّن الوكلاء من نشر تطبيقات macOS على جهاز GitHub، مع ضمان شجرة عمل نظيفة وتعامل مع العلامات والإصدارات الحالية لgit، مع دعم النشر الآلي لملفات `.app` باستخدام حالة git وبروتوكولات الإصدار على GitHub."},"useCases":{"en":["Automating deployment of macOS apps to GitHub","Handling existing git tags and releases for version management","Ensuring clean working trees before publishing apps"],"zh":["将 macOS 应用自动部署到 GitHub","处理现有的 git 标签和版本以进行版本管理","在发布应用之前确保干净的工作树"],"ja":["macOS アプリを GitHub に自動デプロイする","バージョン管理のために既存の git タグとリリースを処理する","アプリを公開する前にクリーンな作業ツリーを確保する"],"ko":["macOS 애플리케이션을 GitHub에 자동으로 배포하는 것","버전 관리를 위해 기존의 git 태그 및 릴리스를 처리하는 것","애플리케이션을 게시하기 전에 깨끗한 작업 트리를 보장하는 것"],"es":["Automatización de la implementación de aplicaciones de macOS en GitHub","Gestión de etiquetas y versiones de git existentes para la administración de versiones","Garantía de árboles de trabajo limpios antes de publicar aplicaciones"],"fr":["Automatisation du déploiement d''applications macOS sur GitHub","Gestion des balises et versions git existantes pour la gestion des versions","Garantie d''arbres de travail propres avant de publier des applications"],"de":["Automatisierung der Bereitstellung von macOS-Apps auf GitHub","Verwaltung von vorhandenen git-Tags und -Versionen für die Versionsverwaltung","Sicherstellung sauberer Arbeitsbereiche vor der Veröffentlichung von Apps"],"pt":["Automatizar a implantação de aplicativos macOS no GitHub","Manipular as tags e lançamentos git existentes para gerenciamento de versão","Garantir árvores de trabalho limpas antes de publicar aplicativos"],"ru":["Автоматизировать развертку приложений macOS на GitHub","Обрабатывать существующие теги и релизы git для управления версиями","Обеспечить чистые рабочие копии перед публикацией приложений"],"ar":["توفير نشر تطبيقات macOS على جهاز GitHub آليا","تعامل مع العلامات والإصدارات الحالية لgit لإدارة الإصدارات","ضمان شجرة عمل نظيفة قبل نشر التطبيقات"]},"limitations":{"en":["Requires clean working tree","GitHub access needed","macOS app development environment required"],"zh":["需要干净的工作树","需要 GitHub 访问权限","需要 macOS 应用开发环境"],"ja":["クリーンな作業ツリーが必要","GitHub へのアクセスが必要","macOS アプリ開発環境が必要"],"ko":["깨끗한 작업 트리가 필요함","GitHub 액세스가 필요함","macOS 애플리케이션 개발 환경이 필요함"],"es":["Se requiere un árbol de trabajo limpio","Se necesita acceso a GitHub","Se requiere un entorno de desarrollo de aplicaciones de macOS"],"fr":["Un arbre de travail propre est requis","L''accès à GitHub est nécessaire","Un environnement de développement d''applications macOS est requis"],"de":["Ein sauberer Arbeitsbereich wird benötigt","Zugriff auf GitHub wird benötigt","Eine Entwicklungsumgebung für macOS-Apps wird benötigt"],"pt":["Requer árvore de trabalho limpa","Acesso ao GitHub necessário","Ambiente de desenvolvimento de aplicativos macOS necessário"],"ru":["Требует чистой рабочей копии","Требуется доступ к GitHub","Необходимо окружение разработки приложений macOS"],"ar":["يتطلب شجرة عمل نظيفة","مطلوب الوصول إلى جهاز GitHub","مطلوب بيئة تطوير تطبيقات macOS"]},"version":4},"contentHash":"2fc0ff0fd50993641e8aaa5e388872c34d7dec34fa8685be09dc0642ed252709","qualityScore":45}');
