INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kalepail/wispr-duck/release', 'release', 'kalepail', 'wispr-duck', 'community', 'release kalepail wispr-duck community audio core-audio ducking macos macos-app menu-bar microphone open-source swift swiftui volume-control wispr-flow The Release skill automates the deployment of signed, notarized, and stapled macOS apps, benefiting developers who need to publish their apps on GitHub. It ensures a clean working tree and handles existing git tags and releases. WisprDuck是一个macOS菜单栏实用工具，用于自动降低背景音量。了解如何发布和设置它 WisprDuckは、背景音量を自動で下げるmacOSメニューバー ユーティリティです。リリースと設定方法を学びましょう WisprDuck는 자동으로 배경 음량을 낮추는 macOS 메뉴 바 유틸리티입니다.发布하고 설정하는 방법을 알아보세요 La función de release de WisprDuck permite a los desarrolladores crear una versión firmada, notariada y etiquetada de su aplicación macOS La fonction de release de WisprDuck permet aux développeurs de créer une version signée, notariée et étiquetée de leur application macOS Die Release-Funktion von WisprDuck ermöglicht es Entwicklern, eine signierte, notarierte und beschriftete Version ihrer macOS-App zu erstellen O release do WisprDuck é uma utilidade de barra de menu macOS que controla automaticamente o volume de fundo quando o microfone está ativo. Release WisprDuck - это утилита панели меню macOS, которая автоматически контролирует фоновой громкости при активном микрофоне. الإصدار من WisprDuck هو أداة شريط قوائم macOS تسيطر تلقائيًا على صوت الخلفية عند تفعيل الميكروفون. how to use release for macOS app deployment release alternative for automated deployment release vs manual deployment release setup guide for AI agents what is release in macOS development release install for GitHub publication macOS菜单栏实用工具 自动降低背景音量 Swift和SwiftUI 开源和免费 GitHub发布 轻量级和易于使用 AIエージェント Release WisprDuck Automates the build of signed, notarized, and stapled .app files Checks for uncommitted changes using git status Handles existing git tags and GitHub releases Supports re-release cleanup for overwritten versions Utilizes Swift and SwiftUI for development Release is a lightweight macOS menu bar utility that automates the deployment of macOS apps, utilizing Swift and SwiftUI for development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tacogips/QraftBox/supply-chain-secure-code', 'community', 'tacogips', 'QraftBox', 'tacogips/QraftBox', 'supply-chain-secure-code', 1, 0, 45, '2026-02-28T01:56:30Z', '2026-03-06T07:15:04.786Z', 'fb09b82a13ccc4fb328e75a500aced42007a381c80479af5197373b9a6a2a561', '{"id":"tacogips/QraftBox/supply-chain-secure-code","name":"supply-chain-secure-code","description":{"en":"This skill provides TypeScript coding patterns to defend against supply chain attacks at the application code level, benefiting developers who import and use third-party packages.","zh":"Supply Chain Secure Code 为您提供 TypeScript 编码模式，以防御应用代码级别的供应链攻击。该技能处理第三方包的导入和使用、代码中的凭据、令牌或 API 密钥的处理等","ja":"Supply Chain Secure Code は、TypeScript コーディング パターンを提供し、アプリケーション コード レベルのサプライ チェーン攻撃を防御します。第三パーティ パッケージのインポートと使用、コード内の資格情報、トークンまたは API キーの処理などを処理","ko":"Supply Chain Secure Code는 TypeScript 코딩 패턴을 제공하여 애플리케이션 코드 수준의 공급망 공격을 방어합니다. 第三자 파키지의 가져오기와 사용, 코드 내의 자격 증명, 토큰 또는 API 키의 처리 등","es":"El código seguro de cadena de suministro proporciona patrones de codificación de TypeScript para defenderse contra ataques de cadena de suministro a nivel de código de aplicación","fr":"Le code sécurisé de chaîne d''approvisionnement fournit des modèles de codage TypeScript pour se défendre contre les attaques de chaîne d''approvisionnement au niveau du code d''application","de":"Der sichere Lieferketten-Code bietet TypeScript-Coding-Muster, um sich gegen Lieferketten-Angriffe auf Anwendungscod-Ebene zu verteidigen","pt":"Este skill fornece padrões de codificação TypeScript para defender contra ataques de cadeia de suprimentos no nível do código do aplicativo","ru":"Этот навык предоставляет шаблоны кодирования TypeScript для защиты от атак на цепочку поставок на уровне кода приложения","ar":"هذا المهارة يوفر أنماط التشفير TypeScript لالدفاع ضد الهجمات على سلسلة التوريد على مست